// Content for Know Your Rights (Adult) (node g51, ages 18-22, Chapter 6): NEW v2 build to GDD 51 (mechanic-
// embodying), the College node that CLOSES the chapter by turning the rights work of Justice League (g35) into
// the adult arenas a young adult now enters (Thread G · Values, Rights & Media). Reworks the old ModesEngine
// build onto the shared v2 engine. 84 researched, India-grounded scenarios across rights-at-work →
// harassment-and-posh → renting-and-consumer → cyber-and-data → claim-it → tools-and-help, each encoded as one of
// the shared v2 play actions (branch / strike-rewrite / sort / reflect / match / role-play / spot): no binary
// "tap the right card". Lead: branch (your move), strike-rewrite (bust the myth), match (right -> route). Six
// modes: rights at work (labour, contracts, pay, interns), harassment & POSH (the Internal Committee), renting &
// consumer (tenancy, deposits, goods), cyber & data (fraud, abuse, your data), claim it (UN&RE: 'you can't fight
// the system' -> you can; redress & free legal aid), tools/help. Empowering and practical: knowing your rights
// and the routes to claim them is one of the strongest protections an adult has. EDUCATIONAL, NOT legal advice;
// all law content flagged for expert review, localisation and currency. India: POSH Act 2013 & Internal
// Committees (10+ employees, complaint within 3 months, covers interns), labour/internship & tenancy/deposit
// norms, Consumer Protection Act 2019, cyber rights & DPDP; redress via Internal Committees, police/FIR and free
// legal aid (NALSA, 15100); helplines 181, 1091, 112, 1930, 1098. Builds on g35 (Justice League); pairs g50;
// precedes the c6 capstone. gameId "know-your-rights".
import type { V2GameConfig, Scenario } from "./v2-schema";

const SCENARIOS: Scenario[] = [
  {"id":"kr-001","cat":"rights-at-work","type":"strike-rewrite","hook":"\"As a junior or intern, you have no rights at work.\"","myth":{"un":"As a junior or intern, you have no rights at work.","re":"You have basic labour rights regardless of seniority; interns and contract workers are protected too.","why":"Rights don't start only at senior level."},"relearn":"You have basic labour rights regardless of seniority; interns are protected too.","persona":"Meena","source":"rights at any level"},
  {"id":"kr-002","cat":"rights-at-work","type":"sort","hook":"Sort: okay at work, or not okay?","items":[{"id":"a","text":"A contract stating pay, hours and role"},{"id":"b","text":"Being made to work unpaid 'to prove yourself'"},{"id":"c","text":"Being paid on time for work done"},{"id":"d","text":"Wages withheld with no reason"},{"id":"e","text":"A payslip showing your deductions"},{"id":"f","text":"Your originals kept so you can't quit"}],"bins":[{"id":"ok","label":"Okay","valence":"pos"},{"id":"not","label":"Not okay","valence":"neg"}],"key":{"a":"ok","b":"not","c":"ok","d":"not","e":"ok","f":"not"},"relearn":"A clear contract, on-time pay and a payslip are okay; unpaid 'real' work, withheld wages and held originals aren't.","persona":"any","source":"what's okay at work"},
  {"id":"kr-003","cat":"rights-at-work","type":"branch","persona":"any","source":"unpaid work","hook":"A design studio offers you a 'trial': a month of full client work, unpaid, and then 'we'll see'.","steps":[{"prompt":"The owner, Sunil, says plenty of freshers would jump at this. What do you do?","options":[{"text":"Offer a short paid trial instead of a free month","then":"Sunil pauses. \"Paid? Hmm. Let me talk to my partner.\"","best":true},{"text":"Accept it gladly to show how committed you are","then":"Sunil hands you three client briefs on the first morning."},{"text":"Accept, and quietly keep applying elsewhere","then":"You start the next day, and your evenings go into job hunting."},{"text":"Accept if he promises a certificate at the end","then":"\"Of course,\" Sunil says. Nothing is said about money."}],"why":"A trial should be short or paid. A month of real client work is a job."},{"prompt":"Sunil sends you a client's logo brief with a Friday deadline and no word on pay. What do you do?","options":[{"text":"Ask in writing what this work will pay before starting","then":"He replies, \"Say 8,000 for the month,\" and you ask him to confirm it by email.","best":true},{"text":"Do it brilliantly. Pay will follow if you impress him","then":"The client loves the logo. Sunil bills them and says nothing to you."},{"text":"Do it, but slowly, since it's unpaid anyway","then":"Sunil complains about the delay, and pay still isn't mentioned."},{"text":"Ignore the brief and hope he gets the message","then":"Sunil messages twice, then says you're \"not serious\"."}],"why":"Asking about pay in writing before the work starts protects your right to be paid."},{"prompt":"A friend says unpaid trials are how everyone starts in design. What do you think?","options":[{"text":"A short test is one thing. Months of client work needs pay","then":"Your friend thinks, then admits her own \"trial\" ran four months.","best":true},{"text":"She's right. Paying your dues is just part of it","then":"You stop asking about pay, and your savings run low."},{"text":"Maybe design isn't a field for people without savings","then":"You start doubting you belong in the field at all."},{"text":"It's unfair, but complaining will get me blacklisted","then":"You stay quiet, and the next free month begins."}],"why":"Real, ongoing work deserves pay at any level. Free work sold as a trial is exploitation."}],"debrief":"Doing genuine, ongoing work for free is exploitation; you have a right to be paid.","relearn":"Real work deserves pay; an unpaid 'trial' doing real work isn't okay."},
  {"id":"kr-004","cat":"rights-at-work","type":"match","hook":"Match the work right to what it means.","pairs":[{"left":"A contract/offer letter","right":"States pay, hours and role"},{"left":"Being paid for work done","right":"A basic labour right"},{"left":"Safe conditions","right":"Owed to every worker"},{"left":"Equal pay","right":"Same work, same pay"},{"left":"Your original documents","right":"Always belong to you"}],"relearn":"A contract states terms; pay-for-work, safety, equal pay and your own documents are basic rights owed to every worker.","persona":"any","source":"work rights"},
  {"id":"kr-005","cat":"rights-at-work","type":"branch","persona":"Meena","source":"unpaid wages","hook":"You work at a garment unit, and the owner, Rakesh ji, keeps 'forgetting' your pay date.","steps":[{"prompt":"This month's pay is ten days late again. What do you do first?","options":[{"text":"Start a notebook of pay dates, amounts and delays","then":"By evening, three months of late dates are written down in one place.","best":true},{"text":"Stay quiet for now so you're not seen as difficult","then":"Another week passes. Your rent is due and your wallet is empty."},{"text":"Complain loudly about him on the shop floor","then":"Rakesh ji snaps at you in front of everyone, and nothing is paid."},{"text":"Ask a coworker to mention it to him for you","then":"She mentions it vaguely. \"Soon,\" he says, and forgets again."}],"why":"Dates and amounts written down turn 'forgetting' into a record you can show."},{"prompt":"Payday comes and goes once more. What do you do?","options":[{"text":"Hand him a short note listing the unpaid dates","then":"He reads it, looks up, and pays half that afternoon. \"Rest on Friday.\"","best":true},{"text":"Ask him nicely, face to face, one more time","then":"\"Yes, yes, tomorrow,\" he says. Nothing shows he said it."},{"text":"Take a day off in protest without telling him","then":"He cuts a day's wage and calls you unreliable."},{"text":"Borrow from a moneylender to cover the gap","then":"The rent is paid, but now you owe interest too."}],"why":"A written note is a formal ask with a date on it, which a chat in passing isn't."},{"prompt":"Next payday is late again. When you ask, Rakesh ji says, \"Ten people would take your place tomorrow.\" What do you do?","options":[{"text":"Say calmly you're only asking for wages already earned","then":"He grunts and looks away. He doesn't say no.","best":true},{"text":"Apologise to him and promise never to raise it again","then":"He nods, satisfied, and next month's pay is late too."},{"text":"Say you'll get the whole unit to walk out","then":"His face darkens, and he stops speaking to you at all."},{"text":"Ask him to pay just half on time from now on","then":"\"We'll see,\" he says, and the other half keeps slipping."}],"why":"Asking for pay you've already earned isn't a favour or a threat. It's what you're owed."},{"prompt":"A coworker whispers, \"He sacks anyone who pushes.\" What do you do?","options":[{"text":"Note what's owed, and ask NALSA 15100 about next steps","then":"The helpline says a dated record of what's owed is what a wage claim needs.","best":true},{"text":"Drop it. A late salary beats no job at all","then":"The next month is late too, and the gap grows."},{"text":"Quit today and forget the money he owes you","then":"You walk away, and the unpaid weeks are never mentioned again."},{"text":"Post about him and his unit in the town's WhatsApp group","then":"The post spreads, Rakesh ji is furious, and your pay is still missing."}],"why":"Wages for work done are owed. Records plus free legal aid make the claim real."}],"debrief":"You have a right to be paid; documenting and formally raising late pay is how you claim it.","relearn":"Keep records and formally raise unpaid or late wages; you're owed them."},
  {"id":"kr-006","cat":"rights-at-work","type":"sort","hook":"Sort: a real labour-rights protection, or a myth?","items":[{"id":"a","text":"Minimum wage exists"},{"id":"b","text":"Juniors can be paid nothing legally"},{"id":"c","text":"You should have a contract"},{"id":"d","text":"Interns have zero protections"},{"id":"e","text":"Wages are owed for work done"},{"id":"f","text":"Cash pay means no rights at all"}],"bins":[{"id":"real","label":"Real protection","valence":"pos"},{"id":"myth","label":"Myth","valence":"neg"}],"key":{"a":"real","b":"myth","c":"real","d":"myth","e":"real","f":"myth"},"relearn":"Minimum wage, contracts and wages-for-work are real; 'juniors paid nothing', 'interns unprotected' and 'cash means no rights' are myths.","persona":"any","source":"labour facts"},
  {"id":"kr-007","cat":"rights-at-work","type":"strike-rewrite","hook":"\"If you complain about work conditions, you'll just be fired and that's legal.\"","myth":{"un":"Complaining about conditions means you can be fired, and that's fine.","re":"You have rights to fair treatment and safe conditions; raising them is legitimate.","why":"Workers can assert conditions without forfeiting protection."},"relearn":"You have rights to fair treatment and safe conditions; raising them is legitimate.","persona":"any","source":"raising conditions"},
  {"id":"kr-008","cat":"rights-at-work","type":"reflect","hook":"Lensy: knowing your basic work rights makes you much harder to exploit. Feel that?","prompt":"What do you think?","options":["Yes","Harder to exploit","Knowledge protects"],"affirm":"A worker who knows their rights is far harder to take advantage of; knowledge is protection.","relearn":"Knowing your basic work rights makes you much harder to exploit.","persona":"any","source":"knowledge protects"},
  {"id":"kr-009","cat":"rights-at-work","type":"branch","persona":"any","source":"get it in writing","hook":"A café owner, Nisha, offers you a job from Monday, with pay and hours 'agreed on a handshake'.","steps":[{"prompt":"She says contracts are \"too corporate\" for a small place. What do you do?","options":[{"text":"Ask for a short message with the pay, hours and role","then":"Nisha laughs, then types it out: \"12,000 a month, 9 to 5, counter and orders.\"","best":true},{"text":"Shake on it. Small places run on trust","then":"She shakes your hand warmly. Nobody writes anything down."},{"text":"Start Monday, and ask for paperwork after a month","then":"\"Sure, sure,\" she says. The month begins with nothing on paper."},{"text":"Say no contract, no job, and walk out","then":"Nisha looks hurt, then says, \"Think it over tonight and tell me.\""}],"why":"A written message makes the terms easy to prove and hard to deny later."},{"prompt":"A friend who worked there says Nisha once paid her less than promised. What do you do?","options":[{"text":"Make sure the pay and hours are in writing, and keep a copy","then":"Nisha's terms are now in a message, and you save a screenshot in a folder.","best":true},{"text":"Assume it won't happen to you. Nisha seems nice","then":"You put it out of your mind and carry on."},{"text":"Ask your friend for proof before you start to worry about it","then":"She has none. \"It was all verbal,\" she says."},{"text":"Go and confront Nisha about what she did to your friend","then":"Nisha gets defensive. \"That was a misunderstanding,\" she says."}],"why":"Getting it in writing protects you whether or not the story is true."},{"prompt":"Your cousin Rahul is also offered a job there on a handshake. What do you tell him?","options":[{"text":"Get pay, hours and role in a message before day one","then":"He asks, and Nisha sends a short message that same evening.","best":true},{"text":"Trust her. She's been fair enough so far","then":"He starts on a handshake and hopes for the best."},{"text":"Just don't work there at all","then":"He's confused. He needs the job, and you haven't said why."},{"text":"Ask her for a proper contract after the first salary","then":"He waits. His first salary comes in lower than he expected."}],"why":"Terms in writing before day one protect anyone starting a new job."}],"debrief":"Written terms protect you; a verbal-only arrangement leaves you exposed.","relearn":"Ask for the terms in writing before starting a job."},
  {"id":"kr-010","cat":"harassment-and-posh","type":"strike-rewrite","hook":"\"Workplace harassment is just something you put up with.\"","myth":{"un":"Workplace harassment is something you just put up with.","re":"Sexual harassment at work is illegal, with formal redress under the POSH Act; you never have to just endure it.","why":"The law gives you a real route."},"relearn":"Workplace harassment is illegal; POSH gives you formal redress, you don't just endure it.","persona":"Aarti","source":"never endure it"},
  {"id":"kr-011","cat":"harassment-and-posh","type":"strike-rewrite","hook":"\"Harassment is the price of having a job.\"","myth":{"un":"Harassment is the price of having a job.","re":"Harassment is never the price of a job; you have a right to a safe, dignified workplace.","why":"Dignity at work is a right, not a favour."},"relearn":"Harassment is never the price of a job; you have a right to safety and dignity at work.","persona":"Meena","source":"not the price"},
  {"id":"kr-012","cat":"harassment-and-posh","type":"match","hook":"Match the POSH basic to what it means.","pairs":[{"left":"Internal Committee (IC)","right":"Where you complain, confidentially"},{"left":"10+ employees","right":"An IC is mandatory"},{"left":"Within 3 months","right":"The window to file (extendable)"},{"left":"Local Committee","right":"For small workplaces without an IC"},{"left":"Interns and contract staff","right":"Also covered by the Act"}],"relearn":"The IC is your confidential route, mandatory at 10+ staff, with a 3-month window; small places use a Local Committee, and interns are covered.","persona":"any","source":"POSH basics"},
  {"id":"kr-013","cat":"harassment-and-posh","type":"branch","persona":"any","source":"using POSH","hook":"A senior at your internship keeps making comments about your body and standing too close.","steps":[{"prompt":"Today he did it again in front of others, who laughed. What do you do?","options":[{"text":"Write down what happened, when, and who saw it","then":"You note it on your phone that evening. It's a record now.","best":true},{"text":"Tell yourself it's the price of getting a job","then":"The comments keep coming, and your stomach knots each morning."},{"text":"Wonder if your clothes gave him the wrong idea","then":"You change what you wear. The comments don't change."},{"text":"Mention it casually to your team lead","then":"He shrugs. \"Don't mind him. He's like that.\" Nothing changes."}],"why":"A written, dated record is the base of a formal complaint, whatever you decide."},{"prompt":"One evening at home, you feel shaken and alone. What do you do?","options":[{"text":"Keep it to yourself so nobody thinks less of you","then":"You carry it alone and sleep badly."},{"text":"Post vaguely online and see what strangers say","then":"Strangers argue in the comments. Some say to quit."},{"text":"Ask a coworker if it's 'really' harassment","then":"She shrugs. \"He's just friendly.\" You feel more unsure."},{"text":"Talk to someone you trust, like your sister","then":"Your sister listens. \"This isn't okay, and it's not on you.\"","best":true}],"why":"Harassment is never your fault, and someone you trust helps you think clearly."},{"prompt":"Next day, you wonder if there's a formal route at work. What do you do?","options":[{"text":"Assume interns can't complain about seniors","then":"You drop the idea. Days later, a friend says interns are covered too."},{"text":"Take a coworker's word that complaints get leaked to him","then":"You hold back, and dread each walk past his desk."},{"text":"Confront him alone after work","then":"He laughs and says no one will believe an intern."},{"text":"Find the Internal Committee in the company policy","then":"The policy names the committee and says complaints are confidential.","best":true}],"why":"The Internal Committee is the confidential route, and interns are covered too."},{"prompt":"A week later, the comments haven't stopped, and you start writing a complaint. What do you include?","options":[{"text":"Dates, what he said and did, and who saw it","then":"It's clear and specific. You read it over twice.","best":true},{"text":"Just that he makes you feel uncomfortable at work","then":"It's true, but it leaves out what actually happened."},{"text":"Everything, plus rumours you've heard about him","then":"The rumours blur your own clear account."},{"text":"Only the worst day, to keep it short","then":"The pattern of the other days disappears from the page."}],"why":"Specific dates, words and witnesses let the committee act on the facts."},{"prompt":"Before submitting, you fear they'll end your internship for complaining. What do you do?","options":[{"text":"Drop it. Juniors who complain always lose in the end","then":"You tear it up. Next morning, he greets you with a smirk."},{"text":"Submit it without your name on it","then":"The committee replies that it needs to know who is complaining."},{"text":"Submit it. Retaliation is itself prohibited","then":"You hand it in, and the committee acknowledges it that day.","best":true},{"text":"Decide you're overreacting and let it go","then":"The doubt settles in, and nothing changes."}],"why":"Retaliation for a good-faith complaint is prohibited, and harassment is never your fault."}],"debrief":"The Internal Committee is a confidential, formal route. Documenting and complaining is how you use it.","relearn":"Document harassment and complain to the Internal Committee."},
  {"id":"kr-014","cat":"harassment-and-posh","type":"strike-rewrite","hook":"\"If you complain about harassment, they can punish you for it.\"","myth":{"un":"If you complain about harassment, they can punish you.","re":"Retaliation for a good-faith complaint is itself prohibited under the POSH Act.","why":"The law protects complainants from reprisal."},"relearn":"Retaliation for a good-faith harassment complaint is itself prohibited.","persona":"any","source":"no retaliation"},
  {"id":"kr-015","cat":"harassment-and-posh","type":"sort","hook":"Sort: true about the harassment law, or false?","items":[{"id":"a","text":"It covers interns and contract staff"},{"id":"b","text":"It only protects senior women"},{"id":"c","text":"The process is confidential"},{"id":"d","text":"You must just confront them alone"},{"id":"e","text":"You can ask for interim relief"},{"id":"f","text":"Retaliation for complaining is allowed"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"false","label":"False","valence":"neg"}],"key":{"a":"true","b":"false","c":"true","d":"false","e":"true","f":"false"},"relearn":"The law covers interns, is confidential and allows interim relief; it isn't only for seniors, a solo confrontation, or open to retaliation.","persona":"any","source":"POSH facts"},
  {"id":"kr-016","cat":"harassment-and-posh","type":"role-play","persona":"Mehta","source":"supporting a colleague","hook":"Your colleague Anjali is being harassed by a client and feels powerless.","setup":"She finds you in the office pantry after a meeting.","steps":[{"prompt":"Anjali says: \"He keeps messaging me at night. Nobody can do anything.\"","options":[{"text":"\"Maybe just ignore him. He'll get bored.\"","then":"Anjali looks down. \"I've tried that for weeks.\""},{"text":"\"Why didn't you block him the first time?\"","then":"She flinches. \"I thought I had to be polite to clients.\""},{"text":"\"This isn't okay, and it isn't your fault.\"","then":"She wipes her eyes. \"I kept thinking I'd done something.\"","best":true},{"text":"\"Give me your phone. I'll reply to him.\"","then":"Anjali pulls the phone back. \"No, please. That'll make it worse.\""}],"why":"Hearing it's not her fault first helps her feel safe enough to think about options."},{"prompt":"Anjali asks: \"But what can I actually do? He's a client, not staff.\"","options":[{"text":"\"Nothing, really. Clients bring in the money.\"","then":"Her face falls. \"So I just put up with it?\""},{"text":"\"The Internal Committee. It's confidential.\"","then":"\"Confidential?\" She sits up a little. \"I didn't know that.\"","best":true},{"text":"\"Tell the manager. He'll sort it out.\"","then":"\"He's friends with that client,\" she says quietly."},{"text":"\"Post his messages online and shame him.\"","then":"\"I can't. Everyone would know it's me.\""}],"why":"The committee covers harassment by clients too, and complaints are kept confidential."},{"prompt":"Anjali says: \"I'm scared. If I complain, could I lose my job?\"","options":[{"text":"\"You won't lose it. I promise nothing bad will happen.\"","then":"\"You can't know that,\" she says, unconvinced."},{"text":"\"Then maybe it's safer to stay quiet.\"","then":"She nods slowly, and the fear wins for now."},{"text":"\"They're not allowed to punish you. I'll help if you want.\"","then":"\"Would you come with me?\" she asks, sounding steadier.","best":true},{"text":"\"You have to complain today. No excuses.\"","then":"\"I need time to think,\" she says, backing away."}],"why":"Punishing someone for complaining isn't allowed, and offering help leaves the choice with her."}],"relearn":"Tell a harassed colleague it's not their fault and point them to the confidential IC."},
  {"id":"kr-017","cat":"harassment-and-posh","type":"branch","persona":"any","source":"missing committee","hook":"A classmate keeps sending you vulgar messages, and you can't find your college's harassment committee.","steps":[{"prompt":"The office clerk shrugs that there's no such committee. What do you do?","options":[{"text":"Ask in writing who handles harassment complaints","then":"The clerk stamps your letter, looking uneasy.","best":true},{"text":"Accept there's no route and drop it","then":"You walk out, and the messages keep coming."},{"text":"Decide it's your own fault for replying to him once","then":"You go over old chats, looking for your mistake."},{"text":"Ask a teacher to have a quiet word with him","then":"The teacher says she'll talk to him. Nothing is recorded."}],"why":"A committee is required, so a written request puts the gap on record."},{"prompt":"That week, you feel on edge in class. What do you do?","options":[{"text":"Tell someone you trust, like a close friend","then":"Your friend Saba listens and helps you screenshot the messages.","best":true},{"text":"Keep it to yourself so there's no gossip in class","then":"You sit alone with it, jumpy whenever your phone buzzes."},{"text":"Ask seniors, who might say it's normal","then":"They shrug. \"Everyone gets such messages.\""},{"text":"Screenshot the messages, but don't tell anyone","then":"The proof is saved, but you carry it alone."}],"why":"Support from someone you trust matters, and none of this is your fault."},{"prompt":"A week on, still nobody at college names a committee. What do you do?","options":[{"text":"Assume the college is above the rules","then":"You stop asking, and the gap stays."},{"text":"Post about it anonymously on the college confessions page","then":"Students react, but the college says nothing."},{"text":"Write to the principal that a committee is required","then":"The principal's office replies that one is 'being formed'.","best":true},{"text":"Confront the classmate in the corridor","then":"He laughs loudly, and his friends join in."}],"why":"The committee is legally required, and pushing for it in writing is a real step."},{"prompt":"Meanwhile, the messages turn threatening. What do you do?","options":[{"text":"Wait for the college committee to be formed","then":"Weeks go by, and the threats keep coming."},{"text":"Tell yourself you provoked him by complaining","then":"The thought keeps you quiet and on edge."},{"text":"Reply with threats of your own","then":"He screenshots your reply and shows it around."},{"text":"Report the threats on cybercrime.gov.in too","then":"You file it with your screenshots and get a complaint number.","best":true}],"why":"Outside routes exist when a college falls short. If in danger, call 112. It's never your fault."}],"debrief":"A missing committee doesn't end your rights. It's legally required, and outside routes exist.","relearn":"If a committee's missing, push for it or use external routes."},
  {"id":"kr-018","cat":"harassment-and-posh","type":"reflect","hook":"Lensy: knowing the POSH route turns harassment from something you endure into something you can act on. Powerful?","prompt":"What do you think?","options":["Yes","I can act","Not endure"],"affirm":"Knowing the route changes everything: harassment becomes something with a real, claimable remedy.","relearn":"Knowing the POSH route turns harassment into something you can act on.","persona":"any","source":"route to action"},
  {"id":"kr-019","cat":"renting-and-consumer","type":"strike-rewrite","hook":"\"A landlord can keep your deposit for any reason.\"","myth":{"un":"A landlord can keep your deposit for any reason.","re":"Deposits are returnable minus genuine, documented damages; not at a whim.","why":"A deposit isn't the landlord's to keep arbitrarily."},"relearn":"Deposits are returnable minus genuine, documented damages, not kept at a whim.","persona":"any","source":"deposits"},
  {"id":"kr-020","cat":"renting-and-consumer","type":"branch","persona":"any","source":"tenancy basics","hook":"You're moving into a rented room, and the owner, Mr Joshi, says a handshake is enough.","steps":[{"prompt":"He wants the deposit in cash today. What do you do?","options":[{"text":"Pay in cash today, since he seems trustworthy enough","then":"He counts it and smiles. There's no paper showing you paid."},{"text":"Ask for a written agreement and a receipt first","then":"Mr Joshi sighs, then agrees to put it all in writing.","best":true},{"text":"Pay by UPI, and skip the agreement","then":"The UPI record shows you paid, but not for what or on what terms."},{"text":"Ask a friend to witness the handshake","then":"Your friend watches. Months later, she can't recall the amount."}],"why":"A written agreement and a receipt protect both sides if there's ever a dispute."},{"prompt":"A week later, you need a rent agreement for address proof, and Mr Joshi sends a draft. What do you check first?","options":[{"text":"Just his signature. The rest is standard","then":"You sign quickly, and only later notice the deposit is left out."},{"text":"That rent, deposit and notice are all written","then":"The notice period is missing, so you ask him to add it.","best":true},{"text":"That it's on stamp paper, so it's official","then":"The stamp paper looks official, but the deposit line is vague."},{"text":"That my parents think it's fine","then":"Your father skims it over the phone and says it looks okay."}],"why":"Rent, deposit and notice in writing are what protect you later."},{"prompt":"On moving day, you notice a cracked tile and a damp patch on the wall. What do you do?","options":[{"text":"Mention it to him in passing","then":"He nods. Months later, he says he doesn't remember."},{"text":"Ignore it, since it's small","then":"The tile stays cracked, and nobody notes it was there before you."},{"text":"Fix the tile myself and not bother him with it","then":"You spend your own money, and there's still no record of the damp."},{"text":"Take dated photos and send them to Mr Joshi","then":"He replies, \"Noted. That was there before.\" Now it's on record.","best":true}],"why":"Dated photos at move-in show what was already there, which protects your deposit."}],"debrief":"A written rent agreement and documented deposit protect you if there's a dispute.","relearn":"Get a written rent agreement and document the deposit."},
  {"id":"kr-021","cat":"renting-and-consumer","type":"sort","hook":"Sort: a tenant protection, or a myth?","items":[{"id":"a","text":"A written agreement protects both sides"},{"id":"b","text":"A landlord can evict you instantly, anytime"},{"id":"c","text":"Deposits should be documented"},{"id":"d","text":"Tenants have no rights at all"},{"id":"e","text":"You can ask for an itemised deposit deduction"},{"id":"f","text":"A landlord can keep the deposit for any reason"}],"bins":[{"id":"real","label":"Real protection","valence":"pos"},{"id":"myth","label":"Myth","valence":"neg"}],"key":{"a":"real","b":"myth","c":"real","d":"myth","e":"real","f":"myth"},"relearn":"Written agreements and documented deposits protect tenants; 'instant eviction' and 'no rights' are myths.","persona":"Meena","source":"tenancy facts"},
  {"id":"kr-022","cat":"renting-and-consumer","type":"strike-rewrite","hook":"\"If you bought it and it's faulty, that's just your bad luck.\"","myth":{"un":"If you bought it and it's faulty, that's your bad luck.","re":"Consumer law gives you rights to refund or replacement for defective goods, and a route to complain.","why":"Sellers owe you working goods."},"relearn":"Consumer law gives you a right to refund or replacement for faulty goods.","persona":"any","source":"consumer rights"},
  {"id":"kr-023","cat":"renting-and-consumer","type":"branch","persona":"any","source":"consumer redress","hook":"Your new pressure cooker's handle cracked within a week, and the shop refuses to refund or replace it.","steps":[{"prompt":"The shopkeeper points to a sign: \"Once sold, no return.\" What do you do?","options":[{"text":"Give up, since the shop has said no","then":"You go home and tape the handle, uneasy every time you cook."},{"text":"Argue loudly until other customers notice","then":"A small crowd gathers, and the shopkeeper digs in even harder."},{"text":"Say a defective item can be replaced or refunded","then":"He pauses, then asks to see your bill.","best":true},{"text":"Leave a one-star review and move on","then":"The review goes up, but the cooker stays broken."}],"why":"Consumer law gives you a right to a refund or replacement for defective goods, whatever the sign says."},{"prompt":"A few days later, there's still no fix. What do you gather to take it further?","options":[{"text":"The bill, photos of the crack and the shop's replies","then":"It all goes into one folder on your phone, dated and clear.","best":true},{"text":"Just the cooker, since the damage speaks for itself","then":"The cooker shows the crack, but not when or where you bought it."},{"text":"Messages from friends who had the same trouble","then":"Their stories sound similar, but none is about your purchase."},{"text":"Nothing yet. I'll wait for him to call","then":"A week goes by, and he doesn't call."}],"why":"The bill and dated photos prove what you bought, when, and what went wrong."},{"prompt":"The shop still won't offer a refund or replacement. What do you do next?","options":[{"text":"Assume the route is only for costly things","then":"You drop it, and the cracked cooker stays in your kitchen."},{"text":"Use the consumer complaint route, in writing","then":"Your complaint is logged, and you get a reference number.","best":true},{"text":"Ask the brand's salesman at another shop","then":"He shrugs and says it's the seller's problem."},{"text":"Tell the shopkeeper I'll sue him tomorrow","then":"He laughs it off, and nothing on paper has changed."}],"why":"The consumer route is open for everyday goods, and a written complaint starts it."},{"prompt":"Your aunt says it's too much fuss over a cooker. What do you tell her?","options":[{"text":"Maybe she's right. It's only a cooker","then":"You let it slide, and the shop carries on as before."},{"text":"I'll easily get double my money back","then":"She looks doubtful. \"Who promised you that?\""},{"text":"It's my right, and the route isn't hard to use","then":"She raises an eyebrow. \"Really? Then help me with my mixer.\"","best":true},{"text":"I'm doing it to teach that shop a lesson","then":"She laughs, and the point about your rights gets lost."}],"why":"Claiming a right over everyday goods is normal, even though nobody can promise the outcome."}],"debrief":"Consumer protection law and complaint forums exist for refused refunds on faulty goods.","relearn":"Cite your consumer rights and use the complaint route for defective goods."},
  {"id":"kr-024","cat":"renting-and-consumer","type":"match","hook":"Match the situation to the protection.","pairs":[{"left":"A faulty product","right":"Refund or replacement rights"},{"left":"A rented room","right":"A written agreement"},{"left":"A returnable deposit","right":"Minus documented damages"},{"left":"A signed bill","right":"Proof for a consumer claim"},{"left":"Move-in photos","right":"Evidence on the deposit"}],"relearn":"Consumer law covers faulty goods, a written agreement covers renting, deposits return minus damages.","persona":"any","source":"protections map"},
  {"id":"kr-025","cat":"renting-and-consumer","type":"sort","hook":"Sort: protects you as a renter/consumer, or leaves you exposed?","items":[{"id":"a","text":"Keeping receipts and records"},{"id":"b","text":"Paying cash with no proof"},{"id":"c","text":"A signed agreement"},{"id":"d","text":"Relying on a verbal promise"},{"id":"e","text":"Move-in photos of the room's condition"},{"id":"f","text":"Trusting the seller's word, no bill"}],"bins":[{"id":"protects","label":"Protects","valence":"pos"},{"id":"exposed","label":"Exposed","valence":"neg"}],"key":{"a":"protects","b":"exposed","c":"protects","d":"exposed","e":"protects","f":"exposed"},"relearn":"Receipts, signed agreements and move-in photos protect you; cash-no-proof and verbal promises leave you exposed.","persona":"any","source":"keep records"},
  {"id":"kr-026","cat":"renting-and-consumer","type":"branch","persona":"any","source":"deposit disputes","hook":"Your landlord, Mrs D'Souza, keeps your whole deposit, citing only 'wear and tear'.","steps":[{"prompt":"She won't say what the money covers. What do you do?","options":[{"text":"Accept the loss without asking any questions","then":"The money is gone, and for now you have no idea what it covered."},{"text":"Ask in writing for an itemised list of deductions","then":"She replies two days later with a short, vague list.","best":true},{"text":"Post her name in a local renters' group","then":"People sympathise, and she goes silent for over a week."},{"text":"Call and argue until she gives in","then":"The call ends in raised voices, with nothing agreed or written."}],"why":"An itemised list shows what's being kept and why, so you can check it."},{"prompt":"Later, she messages that the deposit went on 'painting and repairs'. What do you reply with?","options":[{"text":"My word that I kept the room clean","then":"She says her word is as good as yours."},{"text":"A neighbour's opinion of the room","then":"Your neighbour agrees, but never saw the room before you moved in."},{"text":"My move-in photos and the rent agreement","then":"The photos show the same marks were there when you moved in.","best":true},{"text":"Screenshots of what similar rooms rent for nearby","then":"They show rents, but nothing about the room's condition."}],"why":"Move-in records and the agreement show what was already there, which is how you contest a deduction."},{"prompt":"She replies that normal wear is 'damage' too. What do you say?","options":[{"text":"Okay, maybe normal wear should be paid for","then":"She keeps the full amount, and your case gets weaker."},{"text":"Normal wear? You're just trying to cheat me","then":"She bristles, and the talk turns into a fight about tone."},{"text":"I'll pay half, just to end this","then":"She accepts quickly, and you'll never know what you really owed."},{"text":"Normal wear isn't damage. I'll pay documented dues","then":"She goes quiet, then asks what amount you think is fair.","best":true}],"why":"Normal wear from living in a room isn't damage. Deductions should be genuine and documented."},{"prompt":"Weeks pass and she still hasn't paid anything back. What do you do?","options":[{"text":"Send a dated final request, and call NALSA 15100","then":"A legal aid worker explains how to send her a formal legal notice.","best":true},{"text":"Give up, since landlords always win these","then":"You let it go, and the money stays with her."},{"text":"Send friends to her house to pressure her","then":"She threatens to complain about them, and things turn ugly."},{"text":"Keep calling her every single day until she pays","then":"She blocks your number after a week."}],"why":"A dated request and free legal aid on 15100 give you a real route without needing money."}],"debrief":"Documented condition and itemised deductions are how you contest an unfair deposit deduction.","relearn":"Ask for itemised reasons and dispute unfair deductions with records."},
  {"id":"kr-027","cat":"cyber-and-data","type":"strike-rewrite","hook":"\"Online scams and fraud can't really be reported.\"","myth":{"un":"Online scams and fraud can't really be reported.","re":"You can report cyber fraud and crime at cybercrime.gov.in or helpline 1930, and fast reporting helps.","why":"There's a real national reporting route."},"relearn":"Report cyber fraud at cybercrime.gov.in or 1930; fast reporting helps.","persona":"any","source":"cyber reporting"},
  {"id":"kr-028","cat":"cyber-and-data","type":"strike-rewrite","hook":"\"If someone shares an intimate image of me, it's partly my fault.\"","myth":{"un":"If an intimate image of me is shared, it's partly my fault.","re":"Image-based abuse is a crime and the fault of the perpetrator, never the victim; it can be reported.","why":"The blame and the crime sit with the abuser."},"relearn":"Image-based abuse is a crime, on the perpetrator, never your fault, and reportable.","persona":"any","source":"image abuse"},
  {"id":"kr-029","cat":"cyber-and-data","type":"branch","persona":"any","source":"sextortion","hook":"Someone you met online is threatening to share your private photos unless you pay.","steps":[{"prompt":"The message says to pay ₹20,000 by tonight, or your family sees them. What do you do?","options":[{"text":"Pay, since they promise to delete everything","then":"An hour later, a new message asks for ₹10,000 more."},{"text":"Decide it's all your own fault for sharing the photos","then":"The shame makes it hard to think, and the clock keeps ticking."},{"text":"Don't pay. Screenshot the threat and their profile","then":"Your hands shake, but the proof is saved. The deadline still hangs there.","best":true},{"text":"Delete the chat and hope they go away","then":"The chat is gone, and your proof with it. The deadline stands."}],"why":"Paying rarely ends blackmail, and saved proof keeps every protective step open."},{"prompt":"That night, the fear feels too heavy to hold alone. What do you do?","options":[{"text":"Tell someone you trust, like a close friend","then":"Your friend Zoya listens, then says, \"This is on them, not you.\"","best":true},{"text":"Keep it secret. Nobody can ever know","then":"You lie awake, checking your phone every few minutes."},{"text":"Ask strangers on an online forum what they'd do","then":"Strangers reply with guesses, and one says to just pay."},{"text":"Tell a friend it's about money, not the photos","then":"Your friend offers a loan, which isn't what you need."}],"why":"A trusted person helps you think clearly, and none of this is your fault."},{"prompt":"Next morning, they write: \"Final deadline, noon today.\" What do you do?","options":[{"text":"Pay once. They'll stop after getting something","then":"The money goes. A fresh demand arrives by evening."},{"text":"Stay away from police. They'll judge the photos","then":"You hold back, and the threats keep coming."},{"text":"Report it on 1930 or cybercrime.gov.in","then":"You file it with your screenshots and get an acknowledgement number.","best":true},{"text":"Report their account to the app, and only that","then":"The app removes the profile. A new account messages you within the hour."}],"why":"This is a crime on the blackmailer, and 1930 is the route built for it."},{"prompt":"A day later, they message from a new number: \"Last chance.\" What do you do?","options":[{"text":"Don't reply. Save it and give it to 1930 too","then":"Both numbers and every threat are now on record with 1930.","best":true},{"text":"Pay now. A new number means they're serious","then":"The money goes, and a third number appears two days later."},{"text":"Threaten them back with the police","then":"They reply with a laughing emoji and a new deadline."},{"text":"Forward it to a friend and let them decide what to do","then":"Your friend panics too, and the new message never gets saved."}],"why":"Every new threat is more evidence against them, and 1930 can use it."},{"prompt":"A week later, your college friend Mehak is threatened the same way and asks for help. What do you say?","options":[{"text":"Not your fault. Don't pay. Want to call 1930 together?","then":"Mehak breathes out. \"You're the first person who didn't judge me.\"","best":true},{"text":"Pay quickly, before they send them anywhere","then":"Mehak starts arranging the money, hands trembling."},{"text":"Ask why she sent the photos in the first place","then":"Mehak goes silent and stops replying to you."},{"text":"Delete the chats so no one ever sees them","then":"Mehak wipes the chats, and the proof goes with them."}],"why":"The same steps work for anyone, and the person targeted is never to blame."}],"debrief":"For sextortion or blackmail: don't pay, save the evidence, and report to 1930. It is never your fault.","relearn":"Don't pay blackmailers; preserve evidence and report to 1930 / cybercrime.gov.in."},
  {"id":"kr-030","cat":"cyber-and-data","type":"spot","hook":"Lensy: spot the two false claims about your data rights.","scene":[{"id":"a","text":"You can ask what data is held about you","trick":false},{"id":"b","text":"Apps can do anything with your data, no consent","trick":true},{"id":"c","text":"Your consent matters for your data","trick":false},{"id":"d","text":"You give up all rights the moment you sign up","trick":true},{"id":"e","text":"You can ask for wrong data to be corrected","trick":false}],"why":"'Apps can do anything' and 'you give up all rights' are false; under DPDP your consent and data rights stay yours.","relearn":"Under DPDP your consent matters and you keep rights over your data.","persona":"any","source":"data rights"},
  {"id":"kr-031","cat":"cyber-and-data","type":"match","hook":"Match the online harm to where you report it (India).","pairs":[{"left":"Financial fraud or scam","right":"1930 or cybercrime.gov.in"},{"left":"An intimate image shared","right":"cybercrime.gov.in and a take-down"},{"left":"A child at risk online","right":"Childline 1098"},{"left":"A woman facing online abuse","right":"Women's helpline 181 or 1091"},{"left":"App misusing your data","right":"Your DPDP Act rights"}],"relearn":"Fraud to 1930, image abuse to cybercrime.gov.in, a child to 1098, a woman to 181, data to DPDP.","persona":"any","source":"cyber routes"},
  {"id":"kr-032","cat":"cyber-and-data","type":"branch","persona":"Meena","source":"fraud no shame","hook":"You paid a ₹4,000 'registration fee' for a warehouse job online. Now the number doesn't pick up.","steps":[{"prompt":"You feel foolish and don't want anyone to know. What do you do?","options":[{"text":"Stay silent. Nobody needs to know","then":"The shame stays, and the ₹4,000 slips further out of reach."},{"text":"Report it next week, once you feel a little less foolish","then":"A week slips by. The ad has vanished, and the number is dead."},{"text":"Call 1930 now, even though it feels embarrassing","then":"The call takes ten minutes, and they log it while the payment is fresh.","best":true},{"text":"Keep calling their number and plead","then":"It rings out. Then it shows as switched off."}],"why":"Reporting fast gives the best chance of recovering money, and shame only delays it."},{"prompt":"Your roommate Sunita asks what happened, and your face burns. What do you do?","options":[{"text":"Make up a story about losing the money somewhere","then":"She believes you, and you carry it alone."},{"text":"Laugh it off as a silly mistake","then":"She laughs too, and you don't feel any lighter."},{"text":"Tell her. This happens to careful people too","then":"Sunita nods. \"It happened to my brother last year.\"","best":true},{"text":"Say you'll never look for work online again, ever","then":"Sunita frowns. \"That's half the jobs out there.\""}],"why":"Fraud is the fraudster's doing, so there's nothing to hide from people you trust."},{"prompt":"A week later, a new 'job offer' asks for a ₹2,000 'uniform fee'. What do you do?","options":[{"text":"Pay. This one looks genuine, unlike the last one","then":"The money goes, and the number goes quiet."},{"text":"Just ignore and delete it","then":"It's off your phone, and no one official hears about this number."},{"text":"Don't pay. Report it on cybercrime.gov.in","then":"You report it, with the new number and a screenshot of the ad.","best":true},{"text":"Ask them to adjust your earlier ₹4,000 against the fee","then":"They agree at once, and ask for the ₹2,000 first."}],"why":"A job that asks you to pay first is a warning sign, and reporting it helps."}],"debrief":"Fast reporting of online fraud to 1930 improves the chance of recovering money. Shame just delays it.","relearn":"Report online fraud fast (1930); speed can help recover money."},
  {"id":"kr-033","cat":"cyber-and-data","type":"strike-rewrite","hook":"\"Once something bad is online, nothing can ever be done.\"","myth":{"un":"Once something bad is online, nothing can be done.","re":"You can report it, request take-downs, and pursue redress; it's not hopeless.","why":"Reporting routes and take-down rights exist."},"relearn":"Online harms can be reported and taken down; it isn't hopeless.","persona":"any","source":"not hopeless"},
  {"id":"kr-034","cat":"cyber-and-data","type":"sort","hook":"Sort each move after a cyber harm: smart, or not?","items":[{"id":"a","text":"Preserving screenshots and evidence"},{"id":"b","text":"Deleting everything in a panic"},{"id":"c","text":"Reporting to 1930 quickly"},{"id":"d","text":"Paying a blackmailer"},{"id":"e","text":"Asking the platform to take it down"},{"id":"f","text":"Blaming yourself and going silent"}],"bins":[{"id":"smart","label":"Smart","valence":"pos"},{"id":"not","label":"Not","valence":"neg"}],"key":{"a":"smart","b":"not","c":"smart","d":"not","e":"smart","f":"not"},"relearn":"Preserve evidence, report fast and ask for take-down; panic-deleting, paying or self-blame don't help.","persona":"any","source":"after a cyber harm"},
  {"id":"kr-035","cat":"claim-it","type":"strike-rewrite","hook":"\"You can't fight the system; ordinary people just lose.\"","myth":{"un":"You can't fight the system; ordinary people just lose.","re":"There are real, reachable routes to redress, and knowing them shifts the odds.","why":"Rights are useless unknown, powerful when used."},"relearn":"There are real, reachable routes to redress; knowing them shifts the odds.","persona":"any","source":"you can claim it"},
  {"id":"kr-036","cat":"claim-it","type":"strike-rewrite","hook":"\"You need money and connections to claim your rights.\"","myth":{"un":"You need money and connections to claim your rights.","re":"Free legal aid (NALSA, helpline 15100) exists for anyone who can't afford a lawyer.","why":"Justice isn't only for those who can pay."},"relearn":"Free legal aid (NALSA, 15100) exists for those who can't afford a lawyer.","persona":"Meena","source":"free legal aid"},
  {"id":"kr-037","cat":"claim-it","type":"strike-rewrite","hook":"\"The police can just refuse to register your complaint.\"","myth":{"un":"The police can just refuse to register your complaint.","re":"For a serious (cognizable) offence, registering an FIR is mandatory; a Zero FIR can be filed at any station.","why":"The law requires it for serious offences."},"relearn":"For a serious offence an FIR is mandatory; a Zero FIR can be filed at any station.","persona":"any","source":"FIR / Zero FIR"},
  {"id":"kr-038","cat":"claim-it","type":"match","persona":"any","source":"redress routes","hook":"Match the need to the redress route (India).","pairs":[{"left":"Workplace harassment","right":"The Internal Committee"},{"left":"A serious offence","right":"An FIR (Zero FIR anywhere)"},{"left":"Can't afford a lawyer","right":"Free legal aid via NALSA 15100"},{"left":"A faulty product, no refund","right":"The consumer commission"},{"left":"Online fraud or image abuse","right":"Cyber helpline 1930"}],"relearn":"Each problem has a real route: the Internal Committee, an FIR, NALSA free legal aid, the consumer commission, or cyber 1930."},
  {"id":"kr-039","cat":"claim-it","type":"branch","persona":"any","source":"taking action","hook":"Your last employer still owes you two months' wages, despite your reminders. You half think chasing it is pointless.","steps":[{"prompt":"The money would cover your rent. What do you do first?","options":[{"text":"Let it go. People like us rarely win these","then":"Rent comes out of savings. The unpaid months keep stinging."},{"text":"Post an angry review of the company online","then":"The review gets a few likes. The money stays where it is."},{"text":"Message the owner once more and wait","then":"He replies \"next week, pakka\". He said that last month too."},{"text":"Look up where unpaid wages can be claimed","then":"You find the labour office and the free legal aid helpline, 15100.","best":true}],"why":"Finding the real route is what turns a grievance into something that can move."},{"prompt":"A week later, your cousin says any complaint needs a lawyer you can't afford. What do you do?","options":[{"text":"Agree. Lawyers are only for people with money","then":"Your cousin nods, and the idea of claiming it fades again."},{"text":"Call 15100 and ask about free legal aid","then":"The person on the line explains free aid and what papers to bring.","best":true},{"text":"Ask your cousin to find a lawyer friend to call him","then":"The friend is busy. Two weeks pass and nothing moves."},{"text":"Borrow money to hire a private lawyer","then":"You start pricing lawyers and feel sick at the fees."}],"why":"Free legal aid exists so that cost can't block a real claim."},{"prompt":"Your pay slips and chats with the owner are scattered across your phone. What do you do with them?","options":[{"text":"Delete them. Seeing them only makes you angry","then":"Your phone feels lighter. The proof of what you're owed is gone."},{"text":"Leave them where they are and sort it out later","then":"A phone reset months later wipes half the chats."},{"text":"Forward them all to the owner as a warning","then":"He goes quiet, then blocks your number."},{"text":"Save them in one dated folder, ready to use","then":"It takes one evening. Your claim now has a clear paper trail.","best":true}],"why":"Organised, dated proof is what any office or lawyer will ask for first."}],"debrief":"Most rights have a real route to claim them. Finding and using it is how change happens.","relearn":"Find the right route and use it; rights are claimable, not pointless."},
  {"id":"kr-040","cat":"claim-it","type":"reflect","hook":"Lensy: knowing the routes, free legal aid, the IC, the FIR, means you're never as powerless as it feels. Land?","prompt":"What do you think?","options":["Yes","Not powerless","I know the routes"],"affirm":"Knowing the routes means you always have somewhere to turn; you're far from powerless.","relearn":"Knowing the redress routes means you're never as powerless as it feels.","persona":"any","source":"never powerless"},
  {"id":"kr-041","cat":"claim-it","type":"role-play","persona":"any","source":"sharing the route","hook":"Your friend Anjali paid a coaching centre ₹40,000, and it shut down a month later.","setup":"Over chai, she pushes the fee receipt across to you.","steps":[{"prompt":"Anjali says: \"I'd fight it, but lawyers cost money I don't have.\"","options":[{"text":"\"Yeah. Without money, it's pretty hopeless.\"","then":"She folds the receipt away. \"Thought so.\""},{"text":"\"Save up first, then find a good lawyer.\"","then":"\"That'll take a year,\" she says quietly."},{"text":"\"Just post a review warning others.\"","then":"\"I did,\" she says. \"It got three likes.\""},{"text":"\"There's free legal aid. Call 15100.\"","then":"She blinks. \"Free? For someone like me?\"","best":true}],"why":"Free legal aid exists so that cost never has to be the reason to give up."},{"prompt":"Anjali asks: \"But will anyone take a case like mine seriously?\"","options":[{"text":"\"Asking 15100 is free. Let's call together.\"","then":"She takes out her phone. \"Okay. Stay on speaker with me.\"","best":true},{"text":"\"Honestly, maybe not. It's small money to them.\"","then":"She puts the phone down. \"Then why bother?\""},{"text":"\"Definitely. You'll get every rupee back.\"","then":"She brightens, then frowns. \"You can't know that.\""},{"text":"\"Look into it yourself when you feel ready.\"","then":"\"I'll never feel ready,\" she admits."}],"why":"You can't promise an outcome, but you can make the first step easy."},{"prompt":"A week later, Anjali says: \"My cousin lost money to them too, but she's ashamed to say.\"","options":[{"text":"\"If she's ashamed, better to leave her be.\"","then":"Anjali shrugs. \"Okay. It's up to her.\""},{"text":"\"Add her to your complaint. She won't mind.\"","then":"Anjali hesitates. \"She'd be upset I didn't ask.\""},{"text":"\"Share 15100 with her. She's not alone in this.\"","then":"\"I'll send her the number tonight,\" Anjali says.","best":true},{"text":"\"She should have checked the centre first.\"","then":"Anjali winces. \"That's what she keeps telling herself.\""}],"why":"Passing on the route, without blame, lets others decide for themselves."}],"relearn":"Tell people who can't afford a lawyer about free legal aid (NALSA, 15100)."},
  {"id":"kr-042","cat":"claim-it","type":"sort","persona":"any","source":"routes vs dead ends","hook":"Sort: a real route to redress, or a dead end?","items":[{"id":"a","text":"An Internal Committee complaint"},{"id":"b","text":"Just hoping it resolves itself"},{"id":"c","text":"Filing an FIR for a serious offence"},{"id":"d","text":"Assuming you have no options"},{"id":"e","text":"Asking NALSA for free legal aid"},{"id":"f","text":"Staying silent because you feel small"}],"bins":[{"id":"route","label":"Real route","valence":"pos"},{"id":"deadend","label":"Dead end","valence":"neg"}],"key":{"a":"route","b":"deadend","c":"route","d":"deadend","e":"route","f":"deadend"},"relearn":"An IC complaint, an FIR, and asking NALSA for aid are real routes; hoping, assuming no options, or staying silent are dead ends."},
  {"id":"kr-043","cat":"claim-it","type":"role-play","persona":"any","source":"asking for aid","hook":"Your employer hasn't paid you for six weeks, and you've dialled 15100 for free legal help.","setup":"The call connects after a short wait.","steps":[{"prompt":"A voice says: \"Legal aid helpline. How can I help you?\"","options":[{"text":"\"Sorry, maybe I've dialled the wrong number for this.\"","then":"\"It may not be. What's the problem you're facing?\""},{"text":"\"Can you tell me first if I'll win?\"","then":"\"I can't promise that. But let's see what help fits.\""},{"text":"\"My boss is a cheat. I want him arrested and jailed.\"","then":"\"I hear you're angry. Let's start with what happened.\""},{"text":"\"I can't afford a lawyer. Can I get free legal aid?\"","then":"\"I can help with that. Tell me a little about the problem.\"","best":true}],"why":"Asking plainly for free legal aid gets you straight to the help you're owed."},{"prompt":"The voice asks: \"Can you tell me briefly what happened?\"","options":[{"text":"\"Six weeks unpaid. I have attendance proof.\"","then":"\"That's clear, thank you. Keep that proof safe.\"","best":true},{"text":"\"It's a long story. Maybe it's not worth your time.\"","then":"\"It's worth it. We have time for you.\""},{"text":"\"Everything. He's been awful to me for months.\"","then":"\"I'm sorry. We can take it one thing at a time.\""},{"text":"\"I'd rather not say until I know you'll help.\"","then":"\"We will help. But I need to understand it first.\""}],"why":"A short, factual account helps them guide you quickly."},{"prompt":"The voice asks: \"Can you visit the legal aid office at your district court, so we can go through it properly?\"","options":[{"text":"\"I can't take leave for that. Forget it.\"","then":"\"Tell me which day suits you. We'll work around it.\""},{"text":"\"Can't you just call my employer for me?\"","then":"\"We'll guide you first. The visit helps us understand your case.\""},{"text":"\"Which papers should I bring?\"","then":"\"ID, anything showing your work and pay, and any messages.\"","best":true},{"text":"\"I'll come once I've saved some money.\"","then":"\"You don't need money for this. The aid is free.\""}],"why":"Asking what to bring makes your first visit count."}],"relearn":"You can plainly ask for free legal aid; it's a right, not a favour."},
  {"id":"kr-044","type":"match","persona":"any","source":"helplines","relearn":"181/1091 women in distress, 112 danger, 1930 cyber harm, 1098 child at risk, 15100 free legal aid.","hook":"Match the need to the helpline (India).","pairs":[{"left":"A woman in distress","right":"181 / 1091"},{"left":"Immediate danger","right":"112"},{"left":"Cyber fraud or abuse","right":"1930"},{"left":"A child at risk","right":"Childline 1098"},{"left":"Can't afford a lawyer","right":"NALSA 15100"}],"cat":"tools-and-help"},
  {"id":"kr-045","type":"sort","persona":"any","source":"reliable resources","relearn":"Legal Services Authorities and the cyber portal are reliable; forwards and guesses aren't.","hook":"Sort: a reliable rights resource, or not?","items":[{"id":"a","text":"A Legal Services Authority"},{"id":"b","text":"A random WhatsApp forward"},{"id":"c","text":"The cybercrime portal"},{"id":"d","text":"A stranger's confident guess"},{"id":"e","text":"A qualified lawyer"},{"id":"f","text":"A scary unverified screenshot"}],"bins":[{"id":"reliable","label":"Reliable","valence":"pos"},{"id":"not","label":"Not","valence":"neg"}],"key":{"a":"reliable","b":"not","c":"reliable","d":"not","e":"reliable","f":"not"},"cat":"tools-and-help"},
  {"id":"kr-046","cat":"tools-and-help","type":"reflect","hook":"Lensy: this is education, not legal advice, so for a real case, get qualified or free legal help. Clear?","prompt":"What do you think?","options":["Yes","Get qualified help","Makes sense"],"affirm":"Treating this as solid grounding, and getting qualified or free legal help for real cases, is exactly right.","relearn":"This is education, not legal advice; for a real case, get qualified or free legal help.","persona":"any","source":"not legal advice"},
  {"id":"kr-047","cat":"tools-and-help","type":"role-play","persona":"Farhan","source":"helping others","hook":"Your friend Divya lost 5,000 to a fake 'refund' call an hour ago and doesn't know where to start.","setup":"She calls you, close to tears.","steps":[{"prompt":"Divya says: \"I'm so stupid. I gave him the OTP myself.\"","options":[{"text":"\"It's not your fault. Shall we call 1930 right now?\"","then":"Divya takes a breath. \"Okay. 1930. Stay on the line with me?\"","best":true},{"text":"\"Yes, you should never share OTPs. Everyone knows that.\"","then":"She goes silent, then says, \"I know. I feel worse now.\""},{"text":"\"Just let it go. The money's gone anyway.\"","then":"\"Really? There's nothing?\" she asks, voice cracking."},{"text":"\"Don't worry. I'll get your money back for you.\"","then":"\"You can?\" she asks, and waits for you to fix it."}],"why":"Scams are the scammer's fault. Offering a fast call to 1930 gives her the real first step."},{"prompt":"Divya says: \"My bank's message says to call 1930. What do I even tell them?\"","options":[{"text":"\"The time, amount, bank and transaction ID.\"","then":"She scribbles the details on the back of an envelope.","best":true},{"text":"\"Wait till you calm down. Call them tomorrow.\"","then":"\"Okay,\" she says, and the night goes by."},{"text":"\"Let me call instead, and pretend to be you.\"","then":"\"Is that allowed?\" she asks, unsure."},{"text":"\"Tell them everything, even if it takes an hour.\"","then":"She starts at the very beginning, and her notes get muddled."}],"why":"A few key details are enough to start. Speed matters more than a perfect story."},{"prompt":"Later, Divya says: \"I called. They gave me a complaint number. Now what?\"","options":[{"text":"\"Save it, and add screenshots on cybercrime.gov.in.\"","then":"She makes a folder called \"Complaint\" and starts adding screenshots.","best":true},{"text":"\"That's it. The police will handle everything now.\"","then":"She waits for a call that doesn't come for days."},{"text":"\"Post the scammer's number everywhere to shame him.\"","then":"A few people share it, and the scammer's number goes dead."},{"text":"\"Now forget it and move on. You did your bit.\"","then":"She deletes the call log to stop thinking about it."}],"why":"Following up with evidence on the portal keeps the complaint moving."}],"relearn":"Point a friend with a rights issue to the right route and a helpline."},
  {"id":"kr-048","type":"match","persona":"any","source":"myth to truth","relearn":"Interns have rights, harassment has redress, free legal aid exists, and the system can be navigated.","hook":"Match the myth to the truth that replaces it.","pairs":[{"left":"\"Interns have no rights\"","right":"Basic labour rights apply"},{"left":"\"Just endure harassment\"","right":"There's a formal redress route"},{"left":"\"Need money for justice\"","right":"Free legal aid exists"},{"left":"\"Scams can't be reported\"","right":"1930 and the cyber portal exist"},{"left":"\"You can't fight the system\"","right":"Real routes shift the odds"}],"cat":"tools-and-help"},
  {"id":"kr-049","cat":"tools-and-help","type":"reflect","hook":"Lensy: rights you know are rights you can use, that's the whole point of this. Carry it?","prompt":"What do you think?","options":["Yes","Know to use","The whole point"],"affirm":"Rights you know are rights you can use; that knowledge is one of the strongest protections you have.","relearn":"Rights you know are rights you can use; that's your strongest protection.","persona":"any","source":"the point"},
  {"id":"kr-050","type":"spot","persona":"any","source":"accurate rights","relearn":"Harassment redress and free legal aid are real; 'no rights as a junior' and 'need money' are false.","hook":"Spot the two FALSE lines (tap the wrong ones).","scene":[{"id":"a","text":"\"Harassment has a formal redress route\"","trick":false},{"id":"b","text":"\"You have no rights as a junior\"","trick":true},{"id":"c","text":"\"Free legal aid exists if you can't pay\"","trick":false},{"id":"d","text":"\"You need money to be heard at all\"","trick":true},{"id":"e","text":"\"Online scams can be reported\"","trick":false}],"why":"'No rights as a junior' and 'you need money' are the myths; the rest are real routes.","cat":"tools-and-help"},
  {"id":"kr-051","cat":"tools-and-help","type":"reflect","hook":"Lensy: which right or route do you most want to remember?","prompt":"Pick one.","options":["Work rights","The POSH route","Consumer/cyber redress","Free legal aid"],"affirm":"Carry that one, and you've got a real protection ready when you, or a friend, needs it.","relearn":"Work rights, the POSH route, consumer/cyber redress, and free legal aid, keep one ready.","persona":"any","source":"consolidation"},
  {"id":"kr-052","cat":"rights-at-work","type":"role-play","persona":"any","source":"overwork","hook":"At the mobile shop where you work, the owner, Harish, wants you to stay till 11 every night this week.","setup":"It's 8:55, five minutes before your shift ends.","steps":[{"prompt":"Harish says: \"Stock is coming. Stay back. We're a family here.\"","options":[{"text":"\"I can help if the extra hours are agreed and paid.\"","then":"Harish rubs his head. \"Paid? Fine. Let's talk tomorrow.\"","best":true},{"text":"\"Okay. Anything for the shop.\"","then":"He pats your shoulder. The stock arrives at 10:40."},{"text":"\"Family doesn't make people work free. I'm going.\"","then":"\"Go then,\" he mutters, turning back to the counter."},{"text":"\"I'll stay tonight, but please don't make it a habit.\"","then":"\"Of course,\" he says, and marks you down for tomorrow too."}],"why":"Offering to help on fair terms holds the line without a fight."},{"prompt":"Next morning, Harish says: \"I need you late all week. I can't pay extra, though.\"","options":[{"text":"\"Then I'll work my agreed hours, and help when it's paid.\"","then":"He sighs. \"Okay. I'll ask my brother to cover the late shifts.\"","best":true},{"text":"\"Fine. It's only one week, after all.\"","then":"He smiles. By Friday, \"this week\" has become \"this month\"."},{"text":"\"Then find someone else to take advantage of.\"","then":"His face darkens. \"Watch it,\" he says."},{"text":"\"Okay. But maybe a small bonus at Diwali, then?\"","then":"\"We'll see,\" he says. Diwali is months away."}],"why":"Your agreed hours are the baseline. Extra work stays extra, and paid."},{"prompt":"Harish asks: \"Would you do late shifts if I paid for them?\"","options":[{"text":"\"Yes, if we write down the hours and the rate.\"","then":"He writes \"after 9 pm, 100 an hour\" on a slip and signs it.","best":true},{"text":"\"Sure. Pay whatever you think is fair.\"","then":"He nods. What's \"fair\" to him stays unsaid."},{"text":"\"No. Honestly, I don't trust you now.\"","then":"He shrugs and hires a part-timer instead."},{"text":"\"Yes. Just pay me in cash so there's no fuss.\"","then":"\"Done,\" he says. There's no record of the rate or the hours."}],"why":"Writing down hours and rate means you both know exactly what's agreed."}],"relearn":"You can politely hold the line that extra work should be agreed and paid."},
  {"id":"kr-053","cat":"harassment-and-posh","type":"branch","persona":"Rohan","source":"witness support","hook":"In a meeting, you watch your senior, Mr Khanna, make a crude remark about your colleague Sneha's body.","steps":[{"prompt":"Sneha freezes, and the room goes quiet. What do you do after the meeting?","options":[{"text":"Look away. It's not your problem","then":"Sneha eats lunch alone, and the remark hangs over the office."},{"text":"Tell Khanna off loudly in the corridor","then":"He laughs it off, and Sneha is mortified it became a scene."},{"text":"Check on Sneha privately and ask how she is","then":"Sneha's eyes are wet. \"I thought nobody noticed,\" she says.","best":true},{"text":"Joke with others that Khanna is 'like that'","then":"The joke spreads, and Sneha hears it."}],"why":"Checking on her privately shows support without taking over."},{"prompt":"Later, you wonder whether to write down what you saw. What do you do?","options":[{"text":"Skip it. Your memory is good enough","then":"By the weekend, you're already unsure of his exact words."},{"text":"Note the date, the words, and who was there","then":"It takes five minutes. Your account is ready if she needs it.","best":true},{"text":"Write it up and send it to HR yourself, right away","then":"HR asks if Sneha wants to complain. You never asked her."},{"text":"Tell the office gossip group exactly what happened","then":"The story spreads, with details that grow each time."}],"why":"A witness's dated note can strengthen a complaint if she chooses to make one."},{"prompt":"A few days later, Sneha says she might complain but isn't sure. What do you say?","options":[{"text":"You have to complain. He can't be allowed to get away with it","then":"She tenses. \"I said I'm not sure yet.\""},{"text":"Maybe let it go. He's senior","then":"She nods, but her face closes."},{"text":"Ask why she didn't speak up in the meeting","then":"She looks down. \"I froze.\""},{"text":"Your choice. If you go to the committee, I'll be a witness","then":"She nods slowly. \"Knowing that helps.\"","best":true}],"why":"Offering to be a witness for an Internal Committee complaint backs her choice. It was never her fault."}],"debrief":"Witness support and accounts can strengthen a harassment complaint. Being an active bystander matters.","relearn":"Support a harassed colleague and note what you witnessed."},
  {"id":"kr-054","cat":"renting-and-consumer","type":"branch","persona":"any","source":"online fraud","hook":"An Instagram seller sent you fake 'branded' earphones and now ignores your messages.","steps":[{"prompt":"You paid by UPI two days ago. What do you do first?","options":[{"text":"Write it off as a loss and move on","then":"You block the seller and try to forget the money."},{"text":"Leave angry comments on the seller's posts","then":"The seller deletes your comments and blocks you."},{"text":"Keep messaging until the seller replies","then":"Your messages show 'seen', but nobody answers."},{"text":"Screenshot the listing, chats and UPI payment","then":"Everything sits in one folder, with dates and the seller's handle.","best":true}],"why":"Saving the listing, chats and payment first keeps your proof safe before anything disappears."},{"prompt":"Next day, the seller's page vanishes. What do you do?","options":[{"text":"Assume nothing can be done now it's gone","then":"You let it go, though the payment trail still points to someone."},{"text":"Report it on 1930 or cybercrime.gov.in","then":"You get a complaint number, and the details are logged.","best":true},{"text":"Ask friends online to track the seller down","then":"People share guesses and a stranger's photo. It gets messy fast."},{"text":"Ask my bank to reverse it, and leave it there","then":"The bank asks if you've reported the fraud, and you haven't yet."}],"why":"Reporting fast on 1930 or cybercrime.gov.in helps, even after a page disappears."},{"prompt":"Your cousin Aman says a fake is just bad luck when you buy online. What do you tell him?","options":[{"text":"He's right. Online shopping is a gamble","then":"Aman nods, and you both shrug off the money."},{"text":"It's my fault for trusting Instagram","then":"Aman doesn't argue, and you end up blaming yourself instead of the seller."},{"text":"It's fraud, and I have consumer and cyber routes","then":"Aman looks surprised. \"Both? I thought online meant no rights.\"","best":true},{"text":"Consumer rights only cover big companies","then":"Aman nods. Neither of you looks into it further."}],"why":"Selling fakes is the seller's fraud, not your fault. Consumer law and cyber reporting both apply."},{"prompt":"A week later, you spot the same seller under a new name. What do you do?","options":[{"text":"Message the seller to demand my money back","then":"The seller blocks you within seconds."},{"text":"Warn people in the comments and leave it there","then":"A few people thank you, but the page keeps selling."},{"text":"Report it and file a consumer complaint","then":"Both complaints are logged, and the new name is tied to your payment.","best":true},{"text":"Ignore it, since it's under a different name","then":"The page keeps growing, and nobody links it to your payment."}],"why":"Using the cyber and consumer routes together gives you two real ways to seek redress."},{"prompt":"Your friend Nandini asks how to avoid this next time. What do you tell her?","options":[{"text":"Never buy anything online again","then":"Nandini laughs. \"That's not really an option.\""},{"text":"Buy where returns are clear, and keep records","then":"Nandini saves the tip. \"And report fast if it goes wrong?\"","best":true},{"text":"Only pay sellers with lots of followers","then":"Nandini nods, though followers can be bought."},{"text":"Choose cash on delivery and you're always safe","then":"Nandini nods, though a fake can arrive cash on delivery too."}],"why":"Clear return policies and saved records make any problem easier to claim."}],"debrief":"Fake-product fraud has both consumer and cyber routes, so you don't just absorb the loss.","relearn":"Use consumer routes and report fraud for fake products; don't just absorb the loss."},
  {"id":"kr-055","cat":"cyber-and-data","type":"branch","persona":"any","source":"data control","hook":"A free photo-editing app you just downloaded wants your contacts, messages and location.","steps":[{"prompt":"You only want to edit one picture. What do you do?","options":[{"text":"Allow photos only and deny the rest","then":"The app opens fine. Your contacts and messages stay yours.","best":true},{"text":"Allow everything. Free apps all ask for this","then":"The app opens, and odd promotional calls start soon after."},{"text":"Allow it all now and remove it later","then":"You forget. Weeks later, it still has access to everything."},{"text":"Check the reviews and do what most people did","then":"Most reviewers just tapped 'Allow' on everything."}],"why":"You can grant only what an app needs, because your data is yours to share or keep."},{"prompt":"A week later, you see in settings which apps can track your location. What do you do?","options":[{"text":"Turn it off for apps that don't need it","then":"Five apps lose location access. Nothing you use stops working.","best":true},{"text":"Leave it. Changing settings is too fiddly","then":"Everything stays as it is, including apps you barely use."},{"text":"Turn it off only for the one that worries you","then":"One app is sorted. Four others still know where you go."},{"text":"Switch location off for everything, even maps","then":"Next morning, your cab app can't find you."}],"why":"Reviewing access app by app keeps what's useful and cuts what isn't needed."},{"prompt":"Your friend Pallavi shrugs that companies have everyone's data anyway. What do you say?","options":[{"text":"We can say no, and take our consent back","then":"Pallavi pauses. \"Take it back? I didn't know I could.\"","best":true},{"text":"True. Privacy is gone anyway","then":"Pallavi nods, and you both keep tapping 'Allow'."},{"text":"It only really matters for banking and payment apps","then":"Pallavi shrugs. \"So the other thirty apps don't count?\""},{"text":"Then let's just stop using apps altogether","then":"Pallavi laughs. \"Sure. Our phones become bricks.\""}],"why":"Your consent is yours to give, refuse or withdraw, so it's always worth using."}],"debrief":"You have a right to control your data. Declining unnecessary permissions is exercising it.","relearn":"Decline unnecessary app permissions; your consent and data are yours."},
  {"id":"kr-056","cat":"claim-it","type":"strike-rewrite","hook":"\"The law is too complicated for someone like me to understand.\"","myth":{"un":"The law is too complicated for me to understand.","re":"The core protections can be put in plain language anyone can use.","why":"You don't need to be a lawyer to know your basic rights."},"relearn":"The core protections can be put in plain language anyone can use.","persona":"Meena","source":"plain language"},
  {"id":"kr-057","cat":"rights-at-work","type":"sort","hook":"Sort: a fair internship, or exploitation dressed as one?","items":[{"id":"a","text":"Real learning, fair stipend, set hours"},{"id":"b","text":"Full unpaid work indefinitely"},{"id":"c","text":"A clear agreement"},{"id":"d","text":"'Pay' that never arrives"},{"id":"e","text":"A named mentor and end date"},{"id":"f","text":"Covering a paid staff job for free"}],"bins":[{"id":"fair","label":"Fair internship","valence":"pos"},{"id":"exploit","label":"Exploitation","valence":"neg"}],"key":{"a":"fair","b":"exploit","c":"fair","d":"exploit","e":"fair","f":"exploit"},"relearn":"Learning, a fair stipend, clear terms and a mentor make it fair; endless unpaid work, vanishing pay or free job-cover is exploitation.","persona":"Deepak","source":"internships"},
  {"id":"kr-058","cat":"harassment-and-posh","type":"role-play","persona":"any","source":"on your side","hook":"Your colleague Farida was harassed by her team lead, and now she blames herself.","setup":"You meet her at the chai stall after work.","steps":[{"prompt":"Farida says: \"Maybe I was too friendly with him. Maybe I caused this.\"","options":[{"text":"\"Maybe you misread it. He's friendly with everyone.\"","then":"Farida goes quiet. \"Maybe. I don't know anymore.\""},{"text":"\"It's not your fault. Being friendly isn't a yes.\"","then":"She looks up. \"Really? Everyone keeps asking what I did.\"","best":true},{"text":"\"Well, keep things more formal from now on.\"","then":"She nods, and her shoulders sink further."},{"text":"\"Forget it happened. It isn't worth the stress.\"","then":"\"I can't forget it,\" she says softly."}],"why":"Being friendly never causes harassment. The fault is always the harasser's."},{"prompt":"Farida says: \"Even if I complain, it's my word against a team lead's.\"","options":[{"text":"\"True. Seniors usually win these things.\"","then":"Farida sighs. \"Then why even bother?\""},{"text":"\"Get others to gang up on him with you.\"","then":"\"I don't want a war. I just want it to stop.\""},{"text":"\"The law is on your side, whatever his rank.\"","then":"\"Even against someone senior?\" she asks, a little steadier.","best":true},{"text":"\"I'll go and tell the boss everything myself.\"","then":"\"No, wait. I haven't decided anything yet.\""}],"why":"Rank doesn't change the law. Harassment is wrong whoever does it."},{"prompt":"Farida asks: \"If I did want to act, where would I even start?\"","options":[{"text":"\"Confront him and ask him to apologise.\"","then":"Farida shakes her head. \"Alone with him? I couldn't.\""},{"text":"\"Note what happened with dates. The committee can hear it.\"","then":"\"Okay. I can start that tonight,\" she says.","best":true},{"text":"\"First find out if he's done it to others.\"","then":"\"That could take months, and people would talk.\""},{"text":"\"Honestly, I'd start by asking to move teams.\"","then":"\"Why should I be the one who moves?\" she asks."}],"why":"A dated record and the committee give her a clear route, whenever she's ready."}],"relearn":"Harassment is never your fault; the law is on your side."},
  {"id":"kr-059","cat":"renting-and-consumer","type":"spot","hook":"Spot the two risky moves before signing a lease.","relearn":"Read what you sign and never leave blanks empty; question unfair clauses.","persona":"any","source":"read before signing","scene":[{"id":"a","text":"Reading and understanding the terms","trick":false},{"id":"b","text":"Signing blind to save time","trick":true},{"id":"c","text":"Questioning an unfair clause","trick":false},{"id":"d","text":"Keeping your signed copy","trick":false},{"id":"e","text":"Signing a page with blank amounts left empty","trick":true}],"why":"Signing blind and leaving blank amounts let terms change later; reading and questioning protect you."},
  {"id":"kr-060","cat":"cyber-and-data","type":"sort","hook":"Sort each line: you have rights and routes, or a lawless-zone myth?","relearn":"You have real rights and routes online; 'the internet is lawless for you' is a myth.","persona":"any","source":"rights online","items":[{"id":"a","text":"Reporting online fraud to 1930"},{"id":"b","text":"Assuming the internet is lawless for you"},{"id":"c","text":"Exercising your data rights under DPDP"},{"id":"d","text":"Believing nothing online can be acted on"},{"id":"e","text":"Asking a platform to take down abuse"},{"id":"f","text":"Thinking only big people can complain"}],"bins":[{"id":"rights","label":"You have rights","valence":"pos"},{"id":"lawless","label":"Lawless myth","valence":"neg"}],"key":{"a":"rights","b":"lawless","c":"rights","d":"lawless","e":"rights","f":"lawless"}},
  {"id":"kr-061","cat":"claim-it","type":"branch","persona":"any","source":"just ask","hook":"Your old college is holding your original marksheet until you pay a year's fees for a course you left.","steps":[{"prompt":"You aren't sure it's serious enough to act on. What do you do?","options":[{"text":"Pay the fees to get it back fast","then":"The office takes the money, then says the marksheet will take a few weeks."},{"text":"Wait a month and see if the office softens by then","then":"A month later, the office gives the same answer."},{"text":"Assume it's not worth bothering anyone","then":"You drop it, but the missing marksheet nags at you with every form."},{"text":"Ask free legal aid what your options are","then":"On 15100 you learn there are options, and that asking commits you to nothing.","best":true}],"why":"Asking about your options costs nothing and commits you to nothing."},{"prompt":"Your new college says it needs the original within three weeks. What do you do?","options":[{"text":"Ask an uncle who knows the principal to call","then":"The principal is polite on the phone and does nothing."},{"text":"Write to the old college and keep a copy","then":"The office stamps your copy. Now there's a dated record of your ask.","best":true},{"text":"Keep visiting the office and asking in person","then":"Each visit ends with \"come next week\". Nothing is on paper."},{"text":"Name and shame the college on social media","then":"Students share the post. The office stops taking your calls."}],"why":"A written, dated request gives any next step a record to stand on."},{"prompt":"Your friend Tanvi has the same problem and fears that asking will start a big fight. What do you tell her?","options":[{"text":"Asking commits you to nothing","then":"Tanvi relaxes a little. \"Then I'll just ask,\" she says.","best":true},{"text":"It will turn into a fight, so be ready for one","then":"Tanvi looks more scared and decides to pay instead."},{"text":"Wait till my case is sorted, and then decide what to do","then":"Tanvi waits, and her own deadline slips past."},{"text":"Just pay. It isn't worth the stress","then":"Tanvi pays with money her family had to borrow."}],"why":"Knowing that a question isn't a commitment lets people find out where they stand."}],"debrief":"Asking about your options costs nothing and commits you to nothing. It just gives clarity.","relearn":"You can ask about your rights and routes without committing to anything."},
  {"id":"kr-062","cat":"rights-at-work","type":"strike-rewrite","hook":"\"If you're paid in cash off the books, you have no rights.\"","myth":{"un":"If you're paid in cash off the books, you have no rights.","re":"You still have rights as a worker; off-the-books pay is a warning sign, not a loss of your protections.","why":"Informal pay doesn't erase labour rights."},"relearn":"Off-the-books cash pay doesn't erase your rights; it's a warning sign.","persona":"Meena","source":"informal work"},
  {"id":"kr-063","cat":"harassment-and-posh","type":"sort","hook":"Sort: a step that helps a harassment complaint, or hinders it?","items":[{"id":"a","text":"Documenting incidents with dates"},{"id":"b","text":"Deleting all the evidence"},{"id":"c","text":"Complaining within the time window"},{"id":"d","text":"Telling no one and waiting years"},{"id":"e","text":"Saving messages and emails"},{"id":"f","text":"Confronting the harasser alone, no record"}],"bins":[{"id":"helps","label":"Helps","valence":"pos"},{"id":"hinders","label":"Hinders","valence":"neg"}],"key":{"a":"helps","b":"hinders","c":"helps","d":"hinders","e":"helps","f":"hinders"},"relearn":"Documenting, complaining in the window and saving messages help; deleting evidence, long delay or a no-record solo confrontation hinder.","persona":"any","source":"strong complaint"},
  {"id":"kr-064","cat":"renting-and-consumer","type":"spot","hook":"Spot the two rental-scam signs.","relearn":"Verify before paying; upfront deposits for unseen rentals are a common scam.","persona":"any","source":"rental scams","scene":[{"id":"a","text":"A big deposit demanded before you've seen the place","trick":true},{"id":"b","text":"Viewing first, then a documented agreement","trick":false},{"id":"c","text":"Pressure to pay instantly to 'secure' it","trick":true},{"id":"d","text":"A receipt for any money you hand over","trick":false},{"id":"e","text":"Meeting the actual owner before paying","trick":false}],"why":"Big upfront deposits for unseen places and instant-pay pressure are rental-scam signs."},
  {"id":"kr-065","cat":"cyber-and-data","type":"spot","hook":"Lensy: spot the two moves that are NOT cyber-rights-aware.","scene":[{"id":"a","text":"Reporting fraud to 1930 quickly","trick":false},{"id":"b","text":"Paying a blackmailer to stay quiet","trick":true},{"id":"c","text":"Preserving evidence before reporting","trick":false},{"id":"d","text":"Deleting all the proof in a panic","trick":true},{"id":"e","text":"Asking the platform to take content down","trick":false}],"why":"Paying a blackmailer and deleting your proof both help the abuser; report fast and preserve evidence instead.","relearn":"Report fast and preserve evidence; don't pay blackmailers or delete proof.","persona":"any","source":"cyber-aware"},
  {"id":"kr-066","cat":"claim-it","type":"reflect","hook":"Lensy: a young adult who knows their rights and the routes is genuinely harder to exploit. Feel equipped?","prompt":"What do you think?","options":["Yes","Equipped","Harder to exploit"],"affirm":"Knowing your rights and the routes to claim them is real, practical protection; you're equipped.","relearn":"Knowing your rights and the routes makes you genuinely harder to exploit.","persona":"any","source":"equipped"},
  {"id":"kr-067","cat":"rights-at-work","type":"branch","persona":"any","source":"contracts","hook":"A BPO offers you a job, but the contract says you'll pay 50,000 if you leave within a year.","steps":[{"prompt":"HR, Ms Das, says you must sign today to keep the seat. What do you do?","options":[{"text":"Ask for a copy to read overnight and get advice","then":"Ms Das sighs, then emails a copy. \"Reply by 11 tomorrow.\"","best":true},{"text":"Sign now so you don't lose the seat","then":"The pen is in your hand before you've reached page three."},{"text":"Sign, and plan to argue about it later if needed","then":"You sign, and the clause is now yours to deal with."},{"text":"Ask HR if the clause is \"just a formality\"","then":"\"Yes, nobody enforces it,\" she says, still holding out the pen."}],"why":"A contract is yours to read before signing. Pressure to sign today is a reason to slow down."},{"prompt":"Your uncle glances at it and says, \"All contracts look like this.\" What do you do?","options":[{"text":"Ask someone who knows contracts, like a legal-aid clinic","then":"A legal-aid volunteer explains the clause and what you could ask to change.","best":true},{"text":"Take his word for it. He's worked for years","then":"You relax. The clause stays in the drawer, unread."},{"text":"Search online forums for what other people say","then":"You find twenty opinions that disagree with each other."},{"text":"Decide the bond is fine as long as you simply never quit","then":"You feel calmer, and a little trapped."}],"why":"Someone who knows contracts can tell you what a clause really means for you."},{"prompt":"Ms Das calls to ask if you have any questions before joining. What do you say?","options":[{"text":"Ask what the bond covers and whether it can be reduced","then":"She says she'll check with her manager and reply by email.","best":true},{"text":"Say no questions, to seem easy to work with","then":"\"Great, see you Monday,\" she says, and the clause stays as it is."},{"text":"Say you'll sue if they ever use that clause","then":"The line goes quiet. \"I'll note that,\" she says coldly."},{"text":"Ask only about the joining date and shift timings","then":"She answers quickly. The bond never comes up."}],"why":"Unfair terms can be questioned, and before you join is the easiest time to ask."},{"prompt":"Your batchmate Neha gets the same contract and asks what you'd do. What do you tell her?","options":[{"text":"Read all of it, question unfair terms and get advice first","then":"Neha makes a list of three clauses to ask about.","best":true},{"text":"Sign fast. Seats like this go quickly","then":"Neha signs that afternoon without reading page four."},{"text":"Never take any job that has a bond","then":"Neha looks stressed. She needs this job."},{"text":"Ask HR whether it's a formality, and trust them","then":"HR tells her not to worry, and she signs."}],"why":"Reading, questioning and getting advice before signing protects anyone facing a contract."}],"debrief":"Questioning unfair contract terms and getting advice before signing is basic self-protection.","relearn":"Read, question unfair terms, and seek advice before signing a contract."},
  {"id":"kr-068","cat":"harassment-and-posh","type":"spot","hook":"Spot the two claims that wrongly shrink what harassment is.","scene":[{"id":"a","text":"Unwelcome comments or messages can count","trick":false},{"id":"b","text":"Only physical acts count","trick":true},{"id":"c","text":"A hostile environment can count","trick":false},{"id":"d","text":"A 'joke' can never be harassment","trick":true},{"id":"e","text":"Demanding sexual favours counts","trick":false}],"why":"'Only physical acts' and 'a joke can never count' wrongly shrink it; comments, a hostile environment and demands all count.","relearn":"Comments, a hostile environment and demands all count; not only physical acts, and a 'joke' isn't automatically safe.","persona":"any","source":"what counts"},
  {"id":"kr-069","cat":"renting-and-consumer","type":"match","hook":"Match the record to the protection it gives.","pairs":[{"left":"A signed rent agreement","right":"Proof of your terms"},{"left":"Move-in photos","right":"Evidence for your deposit"},{"left":"Receipts","right":"Proof for consumer claims"},{"left":"A deposit slip","right":"Proof of what you paid"},{"left":"Chat where rent was agreed","right":"A record of the promise"}],"relearn":"Agreements, photos, receipts and slips each give concrete proof if there's a dispute.","persona":"any","source":"keeping proof"},
  {"id":"kr-070","cat":"cyber-and-data","type":"strike-rewrite","hook":"\"Sharing my passwords with a partner proves trust and is harmless.\"","myth":{"un":"Sharing all my passwords proves trust and is harmless.","re":"Your accounts and data are yours; sharing everything can enable control or misuse, trust doesn't require it.","why":"Privacy and trust can coexist."},"relearn":"Your accounts and data are yours; trust doesn't require handing over all access.","persona":"any","source":"data and trust"},
  {"id":"kr-071","cat":"claim-it","type":"role-play","persona":"Farhan","source":"spreading knowledge","hook":"You want the young workers in your area to know their rights routes too.","setup":"The youth group's organiser, Mansoor, stops you after a meeting.","steps":[{"prompt":"Mansoor asks: \"What do you want to tell them, exactly?\"","options":[{"text":"\"The plain routes: free legal aid, 1930, the FIR.\"","then":"\"That's useful. Most of them know none of it.\"","best":true},{"text":"\"The full laws, section by section.\"","then":"Mansoor winces. \"They'll be asleep in five minutes.\""},{"text":"\"I'll just share a link in the group.\"","then":"\"Half of them never open links,\" he says."},{"text":"\"Only what they ask. I don't want to preach.\"","then":"\"They won't ask. They don't know what to ask.\""}],"why":"Plain routes people can use tomorrow protect more than legal detail."},{"prompt":"Mansoor says: \"Some of them don't read English well.\"","options":[{"text":"\"They'll manage somehow. The official terms are in English.\"","then":"\"Then it'll go over their heads,\" he says flatly."},{"text":"\"Then I'll say it in their language, with work examples.\"","then":"He nods. \"Stories from their own jobs will stick.\"","best":true},{"text":"\"I'll hand out the English sheet and explain once.\"","then":"\"Those sheets will end up under tea glasses.\""},{"text":"\"Then maybe it isn't worth doing.\"","then":"\"Don't say that. They need it more than anyone.\""}],"why":"Rights only protect people when they're explained in words people use."},{"prompt":"Mansoor asks: \"What if someone asks a legal question you can't answer?\"","options":[{"text":"\"I'll give my best guess so I don't look unsure.\"","then":"Mansoor frowns. \"A wrong guess could cost someone a lot.\""},{"text":"\"I'll promise to find out and tell them all next week.\"","then":"\"And if you can't? They'll be left waiting on you.\""},{"text":"\"I'll say it's too complicated to explain.\"","then":"\"That's exactly what makes people give up,\" he says."},{"text":"\"I'll say I don't know, and point them to legal aid.\"","then":"\"Honest. They'll trust that more than a guess.\"","best":true}],"why":"This is education, not legal advice, so real cases go to qualified or free legal help."},{"prompt":"Mansoor asks: \"How will they remember any of it after tonight?\"","options":[{"text":"\"They'll have to remember. That's on them.\"","then":"\"Most won't, and that's no fault of theirs.\""},{"text":"\"I'll tell them to just search online when they need it.\"","then":"\"Online, they'll find forwards and rumours first.\""},{"text":"\"I'll run a long session every month instead.\"","then":"\"They work six days. They won't make it monthly.\""},{"text":"\"A small card with the numbers on it.\"","then":"\"A card in the wallet. They'll have it when it counts.\"","best":true}],"why":"A plain, shareable card keeps the routes within reach when they're needed."}],"relearn":"Share plain-language rights and routes; it spreads real protection."},
  {"id":"kr-072","type":"sort","persona":"any","source":"the card","relearn":"The redress route and free legal aid are on the card; 'put up with it' and 'no options' aren't.","hook":"Sort: in the rights & helpline card, or not?","items":[{"id":"a","text":"The Internal Committee route"},{"id":"b","text":"\"Just put up with it\""},{"id":"c","text":"Free legal aid (15100)"},{"id":"d","text":"\"You have no options\""},{"id":"e","text":"Cyber harm: 1930"},{"id":"f","text":"\"Don't bother, you'll lose\""}],"bins":[{"id":"card","label":"On the card","valence":"pos"},{"id":"not","label":"Not","valence":"neg"}],"key":{"a":"card","b":"not","c":"card","d":"not","e":"card","f":"not"},"cat":"tools-and-help"},
  {"id":"kr-073","cat":"rights-at-work","type":"reflect","hook":"Lensy: you deserve fair pay, safe conditions and dignity at work, always. Believe that for yourself?","prompt":"What do you think?","options":["Yes","I deserve it","Always"],"affirm":"Fair pay, safe conditions and dignity at work are yours by right; never settle below them.","relearn":"You deserve fair pay, safe conditions and dignity at work, always.","persona":"any","source":"you deserve"},
  {"id":"kr-074","cat":"harassment-and-posh","type":"branch","persona":"any","source":"interim relief","hook":"You've complained to the Internal Committee, and the man you named sits two desks away.","steps":[{"prompt":"Seeing him every day makes your chest tight. What do you do?","options":[{"text":"Wonder if you overreacted by complaining","then":"The doubt gnaws at you, and he's still two desks away."},{"text":"Ask the committee about interim relief","then":"The committee says it can recommend changes during the inquiry.","best":true},{"text":"Accept it. Complaining means you must face him","then":"You grit your teeth through each day."},{"text":"Tell the committee you're upset, but ask for nothing","then":"They reply kindly, but nothing changes at your desk."}],"why":"The process has interim relief built in, so you needn't just endure it."},{"prompt":"A colleague asks whether it's true you complained about him. What do you do?","options":[{"text":"Tell her everything so she's on your side","then":"By evening, half the floor knows the details."},{"text":"Say you can't discuss it, and leave it there","then":"She drops it, but the rumour keeps travelling."},{"text":"Say you can't discuss it, and inform the committee","then":"The committee reminds staff that the process is confidential.","best":true},{"text":"Demand to know who told her, and confront them","then":"It turns into a shouting match by the printer."}],"why":"Confidentiality is part of the process, and the committee can act when it's broken."},{"prompt":"The inquiry is taking weeks, and you're exhausted. What do you do?","options":[{"text":"Tell yourself you brought this on yourself","then":"The thought makes every day heavier."},{"text":"Assume the committee has taken his side","then":"You stop replying to their emails."},{"text":"Ask for a timeline, and lean on a friend","then":"You get dates, and your friend Neha checks in every evening.","best":true},{"text":"Ask the committee for updates, but tell nobody how you feel","then":"You get dates, but carry the weight alone."}],"why":"Using the process's supports and leaning on others helps. None of this is your fault."}],"debrief":"The complaint process includes confidentiality and interim relief, so ask the committee. It's never your fault.","relearn":"After filing, ask about interim relief and confidentiality."},
  {"id":"kr-075","cat":"renting-and-consumer","type":"reflect","hook":"Lensy: a written record is your best friend in any rent or consumer dispute. Worth the habit?","prompt":"What do you think?","options":["Yes","Keep records","Worth it"],"affirm":"Records and receipts quietly win disputes; it's a small habit with big protection.","relearn":"A written record is your best protection in rent and consumer disputes.","persona":"any","source":"records win"},
  {"id":"kr-076","cat":"cyber-and-data","type":"match","hook":"Match the cyber harm to the first right move.","pairs":[{"left":"Sextortion / blackmail","right":"Don't pay; preserve evidence; report"},{"left":"Account hacked","right":"Secure it and report"},{"left":"Data misused","right":"Exercise your DPDP rights"},{"left":"Intimate image shared","right":"Demand takedown; report cybercrime"},{"left":"Impersonation profile","right":"Report the fake to the platform"}],"relearn":"Don't-pay-and-report for blackmail, secure-and-report for hacks, DPDP rights for data misuse, takedown for leaked images, platform-report for impersonation.","persona":"any","source":"first moves"},
  {"id":"kr-077","cat":"claim-it","type":"sort","persona":"any","source":"claiming well","hook":"Sort: makes claiming a right easier, or harder?","items":[{"id":"a","text":"Knowing the route and helpline"},{"id":"b","text":"Believing you have no options"},{"id":"c","text":"Keeping evidence and dates"},{"id":"d","text":"Waiting until the deadline passes"},{"id":"e","text":"Writing down exactly what happened"},{"id":"f","text":"Deleting the messages out of shame"}],"bins":[{"id":"easier","label":"Easier","valence":"pos"},{"id":"harder","label":"Harder","valence":"neg"}],"key":{"a":"easier","b":"harder","c":"easier","d":"harder","e":"easier","f":"harder"},"relearn":"Knowing the route, keeping evidence, and writing it down make claiming easier; defeatism, missed deadlines, and deleting proof make it harder."},
  {"id":"kr-078","cat":"tools-and-help","type":"branch","persona":"any","source":"where to start","hook":"Your landlord cut off your water to make you move out, and you don't know who deals with that.","steps":[{"prompt":"A neighbour says there's no office for \"landlord problems\". What do you do?","options":[{"text":"Call NALSA 15100 and ask where to take this","then":"The helpline takes your details and names a legal-aid clinic near you.","best":true},{"text":"Give up and start packing, since it's so confusing","then":"You fill two bags, still not sure you had to."},{"text":"Search online and follow the first answer you find","then":"The first answer is about another state and doesn't fit your case."},{"text":"Wait until you know exactly which office handles it","then":"A week passes, and you're buying water in cans."}],"why":"A helpline can point you to the right place, so you don't need to know the route first."},{"prompt":"A friend walks you into a legal-aid clinic, and the volunteer asks what papers you have. What do you bring?","options":[{"text":"Rent agreement, receipts and photos of the dry taps","then":"The volunteer spreads them out. \"This is a good start.\"","best":true},{"text":"Nothing. Your word should be enough","then":"The volunteer asks you to come back with any proof you can find."},{"text":"Only the rent agreement, to keep it simple","then":"She asks for proof that the water was cut. You don't have it yet."},{"text":"A long letter about how awful the landlord has been","then":"She reads it kindly, then asks for receipts and dates."}],"why":"Documents and dated photos let the clinic see your case clearly."},{"prompt":"The volunteer offers to help you send the landlord a notice. You're nervous. What do you do?","options":[{"text":"Go ahead, and keep every paper and message","then":"The notice goes out. Your landlord calls, sounding far less sure of himself.","best":true},{"text":"Say no. A notice from a tenant won't count","then":"The volunteer says it does count, but you decline. The taps stay dry."},{"text":"Ask the clinic to promise you'll win first","then":"\"No one can promise that,\" she says. \"But the route is real.\""},{"text":"Skip it and shout at the landlord yourself","then":"He shouts back louder, and the taps stay dry."}],"why":"Using the route and keeping records gives your case its best chance, without false promises."},{"prompt":"Your landlord texts: \"Leave by Sunday or your things go on the street.\" What do you do?","options":[{"text":"Save the text and send it to the clinic volunteer","then":"The volunteer replies within the hour with what to do next.","best":true},{"text":"Believe a landlord can throw you out whenever he likes","then":"You start packing, even though you aren't sure it's true."},{"text":"Text back threats of your own","then":"His replies get nastier, and now there's a fight on record."},{"text":"Delete the text so it stops upsetting you","then":"It's gone from your phone, along with the proof of his threat."}],"why":"None of this is your fault. His threat is evidence, and instant eviction is a myth."},{"prompt":"Your neighbour Latha has the same trouble with her landlord and asks where to start. What do you tell her?","options":[{"text":"Call NALSA 15100, and keep every receipt and message","then":"Latha saves the number and starts a folder that evening.","best":true},{"text":"Tenants have no real rights, so she should just move","then":"Latha looks at her packed-up kitchen and sighs."},{"text":"Wait until she knows exactly which office handles it","then":"Latha waits, and her problem keeps growing."},{"text":"Hold back her rent until the water is back on","then":"Latha holds back the rent, and her landlord now says she owes him."}],"why":"Knowing the route is half the protection, and passing it on helps the next person."}],"debrief":"When unsure of the route, a helpline or legal-aid clinic can point you to the right authority.","relearn":"Unsure of the route? A helpline or legal-aid clinic will direct you."},
  {"id":"kr-079","cat":"rights-at-work","type":"match","hook":"Match the workplace problem to a first step.","pairs":[{"left":"Unpaid wages","right":"Document and formally claim"},{"left":"Harassment","right":"The Internal Committee"},{"left":"Unsafe conditions","right":"Raise it; it's your right"},{"left":"No contract","right":"Ask for terms in writing"},{"left":"Held-back originals","right":"Request them back in writing"}],"relearn":"Document unpaid wages, use the Internal Committee for harassment, raise unsafe work, ask for written terms, request held originals back.","persona":"any","source":"first steps at work"},
  {"id":"kr-080","cat":"harassment-and-posh","type":"reflect","hook":"Lensy: the POSH process exists so you never have to choose between your job and your dignity. Reassuring?","prompt":"What do you think?","options":["Yes","Both protected","Reassuring"],"affirm":"You shouldn't have to trade dignity for a job; POSH exists precisely so you don't.","relearn":"POSH exists so you never have to choose between your job and your dignity.","persona":"any","source":"job and dignity"},
  {"id":"kr-081","cat":"cyber-and-data","type":"role-play","persona":"any","source":"online harassment","hook":"Your friend Nandini gets vulgar comments on every post from the same fake account.","setup":"She shows you her phone, trying to laugh it off.","steps":[{"prompt":"Nandini says: \"It's just comments. Not serious enough to report, right?\"","options":[{"text":"\"Yeah, it's probably nothing. Just ignore it.\"","then":"She nods, but keeps scrolling through the comments."},{"text":"\"Just make your account private for now, and wait.\"","then":"\"I could,\" she says. \"But the account stays, and nothing's on record.\""},{"text":"\"What did you post that set them off?\"","then":"She pulls the phone back. \"Nothing. Why ask that?\""},{"text":"\"It's real harassment, and it can be reported.\"","then":"Her smile fades. \"I didn't think it counted.\"","best":true}],"why":"Online harassment is real and reportable, however 'small' it looks."},{"prompt":"Nandini asks: \"But where would I even report something like this?\"","options":[{"text":"\"On cybercrime.gov.in, or by calling 1930.\"","then":"She types the site name into her notes. \"Okay.\"","best":true},{"text":"\"Nowhere, really. Nobody acts on comments.\"","then":"\"So there's no point,\" she mutters."},{"text":"\"Just report it to the app. That's enough.\"","then":"\"I did, twice. The account's still there,\" she says."},{"text":"\"Let me reply to him and scare him off.\"","then":"\"Please don't. It'll get worse,\" she says."}],"why":"The cybercrime portal and 1930 are the real routes when app reports aren't enough."},{"prompt":"Nandini says: \"I'm scared reporting will make him angrier.\"","options":[{"text":"\"You have to report it today. No excuses.\"","then":"She stiffens. \"Stop pushing me.\""},{"text":"\"Then let's just wait until it stops by itself.\"","then":"\"What if it doesn't?\" she asks quietly."},{"text":"\"Fair. Save the proof now, and you decide when.\"","then":"She breathes out. \"Okay. Screenshots first.\"","best":true},{"text":"\"If you don't report, it's partly on you.\"","then":"Her eyes fill. \"So it's my fault now?\""}],"why":"Saving proof keeps her options open while the timing stays her choice."},{"prompt":"Nandini asks: \"Would you sit with me when I fill in the report?\"","options":[{"text":"\"Of course. And none of this is your fault.\"","then":"She squeezes your hand. \"Tomorrow, then.\"","best":true},{"text":"\"I'd rather not get involved in this.\"","then":"\"Oh. Okay,\" she says, and looks away."},{"text":"\"I'll fill it in for you. Give me your phone.\"","then":"She hesitates. \"I want to do it myself. Just be there.\""},{"text":"\"Sure, but you should've blocked him earlier.\"","then":"She goes quiet. \"I know. I keep thinking that.\""}],"why":"Being beside her, and saying it isn't her fault, helps her take the step herself."}],"relearn":"Online harassment is reportable; show a friend the route (cybercrime.gov.in, 1930)."},
  {"id":"kr-082","cat":"claim-it","type":"reflect","hook":"Lensy: 'you can't fight the system' is the lie that keeps people unprotected. Reject it?","prompt":"What do you think?","options":["Yes","Reject the lie","I can claim it"],"affirm":"Rejecting 'you can't fight the system' is the first step to actually using the rights you have.","relearn":"'You can't fight the system' is the lie that keeps people unprotected; reject it.","persona":"any","source":"reject the lie"},
  {"id":"kr-083","type":"spot","persona":"any","source":"knowledge is power","relearn":"Knowing your rights changes what you accept and lets you protect others; 'no difference' is false.","hook":"Spot the two FALSE statements about knowing your rights.","scene":[{"id":"a","text":"\"It changes what you accept and how you act\"","trick":false},{"id":"b","text":"\"It makes no real difference\"","trick":true},{"id":"c","text":"\"It helps you protect others too\"","trick":false},{"id":"d","text":"\"Only lawyers can ever use it\"","trick":true},{"id":"e","text":"\"It makes you harder to exploit\"","trick":false}],"why":"'No difference' and 'only lawyers can use it' are false; knowing your rights changes a lot.","cat":"tools-and-help"},
  {"id":"kr-084","cat":"tools-and-help","type":"reflect","hook":"Lensy: work, harassment, renting, online, you now know your rights and the routes. Carry which forward?","prompt":"Pick one.","options":["Rights at work","The POSH route","Consumer & cyber redress","Free legal aid"],"affirm":"Carry that forward, and you close Chapter 6 as an adult who's genuinely hard to exploit, and ready to help others.","relearn":"Work rights, POSH, consumer & cyber redress, and free legal aid, carry your rights forward.","persona":"any","source":"carry forward"},
  {"id":"kr-900","cat":"claim-it","type":"strike-rewrite","persona":"any","source":"FIR is mandatory","hook":"\"The station can just turn you away for a serious crime.\"","myth":{"un":"The station can just turn you away for a serious crime.","re":"For a serious (cognizable) offence, registering an FIR is mandatory, the police don't get to decide.","why":"The law makes it a duty, not a favour."},"relearn":"For a serious offence, registering an FIR is mandatory; the police can't lawfully refuse."},
  {"id":"kr-901","cat":"claim-it","type":"strike-rewrite","persona":"Meena","source":"Zero FIR anywhere","hook":"\"It happened in another city, so no station here will take it.\"","myth":{"un":"It happened in another city, so no station here will take it.","re":"A Zero FIR can be filed at any station regardless of where it happened; they transfer it on.","why":"Jurisdiction is their job to sort, not your barrier."},"relearn":"A Zero FIR can be filed at any police station; jurisdiction is sorted out later, not by you."},
  {"id":"kr-902","cat":"claim-it","type":"strike-rewrite","persona":"any","source":"aid is a right","hook":"\"Free legal aid is just for the very poorest, not someone like me.\"","myth":{"un":"Free legal aid is just for the very poorest, not someone like me.","re":"Free legal aid covers anyone who can't afford a lawyer, via NALSA helpline 15100.","why":"It's a right under the Constitution, not charity."},"relearn":"Free legal aid via NALSA 15100 is for anyone who can't afford a lawyer, not only the poorest."},
  {"id":"kr-903","cat":"claim-it","type":"strike-rewrite","persona":"any","source":"no bribe needed","hook":"\"You'll have to pay someone off to even get a complaint moving.\"","myth":{"un":"You'll have to pay someone off to even get a complaint moving.","re":"Filing a complaint or an FIR costs nothing; no payment is required to start.","why":"Access to redress is meant to be free at the door."},"relearn":"Filing a complaint or an FIR is free; you never have to pay to start the process."},
  {"id":"kr-904","cat":"claim-it","type":"strike-rewrite","persona":"any","source":"deadlines not forever","hook":"\"There's no rush, I can always complain whenever I get around to it.\"","myth":{"un":"There's no rush, I can always complain whenever I get around to it.","re":"Many routes have time limits, so acting sooner keeps your options open.","why":"Evidence fades and some windows close."},"relearn":"Many routes have time limits; acting sooner keeps your options open and your evidence fresh."},
  {"id":"kr-905","cat":"claim-it","type":"strike-rewrite","persona":"Meena","source":"language is no barrier","hook":"\"I can't claim anything because everything's in English and legalese.\"","myth":{"un":"I can't claim anything because everything's in English and legalese.","re":"You can complain in your own language, and legal aid services can help you put it in writing.","why":"The route is meant to be reachable, not gated by language."},"relearn":"You can complain in your own language; free legal aid can help you put it in writing."},
  {"id":"kr-906","cat":"claim-it","type":"strike-rewrite","persona":"any","source":"copy of the FIR","hook":"\"Once you file, they keep everything and you get nothing back.\"","myth":{"un":"Once you file, they keep everything and you get nothing back.","re":"You're entitled to a free copy of the FIR you file, keep it safe.","why":"It's your record of what you reported."},"relearn":"You're entitled to a free copy of any FIR you file; keep it as your record."},
  {"id":"kr-907","cat":"claim-it","type":"strike-rewrite","persona":"any","source":"complaint is not a court case","hook":"\"Asking about my rights means I've started some huge court battle.\"","myth":{"un":"Asking about my rights means I've started some huge court battle.","re":"Asking about routes or getting advice commits you to nothing; you stay in control of next steps.","why":"Information is not a lawsuit."},"relearn":"Asking about your rights or getting advice commits you to nothing; you decide each next step."},
  {"id":"kr-908","cat":"claim-it","type":"strike-rewrite","persona":"any","source":"write it down","hook":"\"Nobody will believe me, so why even keep proof.\"","myth":{"un":"Nobody will believe me, so why even keep proof.","re":"Saving messages, dates, and a written account makes any complaint far stronger.","why":"A clear record speaks for you when memory won't."},"relearn":"Saving messages, dates, and a written account of what happened makes any complaint far stronger."},
  {"id":"kr-909","cat":"claim-it","type":"strike-rewrite","persona":"Farhan","source":"routes are shareable","hook":"\"Knowing your rights only helps clever, well-connected people.\"","myth":{"un":"Knowing your rights only helps clever, well-connected people.","re":"The routes are plain and the same for everyone; sharing them spreads real protection.","why":"Knowledge of the route is the leveller."},"relearn":"The redress routes are plain and the same for everyone; sharing them spreads real protection."},
  {"id":"kr-910","cat":"claim-it","type":"strike-rewrite","persona":"any","source":"helpline first step","hook":"\"You need a lawyer before you can even ask a single question.\"","myth":{"un":"You need a lawyer before you can even ask a single question.","re":"A helpline like NALSA 15100 can point you to the right route before you ever hire anyone.","why":"The first step is a phone call, not a fee."},"relearn":"A helpline like NALSA 15100 can point you to the right route before you ever need to hire a lawyer."},
  {"id":"kr-911","cat":"claim-it","type":"strike-rewrite","persona":"any","source":"retaliation is not allowed","hook":"\"If I complain at work they can just fire me for it.\"","myth":{"un":"If I complain at work they can just fire me for it.","re":"Punishing you for a good-faith complaint is itself prohibited, not a normal consequence.","why":"Retaliation is treated as a separate wrong."},"relearn":"Punishing you for a good-faith complaint is itself prohibited; retaliation is a separate wrong."},
  {"id":"kr-912","cat":"claim-it","type":"strike-rewrite","persona":"any","source":"no outcome promised but route real","hook":"\"There's no point unless someone guarantees I'll win.\"","myth":{"un":"There's no point unless someone guarantees I'll win.","re":"No honest route promises a win, but using one gives you a real, fair chance you don't get by staying silent.","why":"A fair process beats no process."},"relearn":"No honest route guarantees a win, but using one gives you a real, fair chance silence never does."},
  {"id":"kr-913","cat":"claim-it","type":"match","persona":"any","source":"who does what","hook":"Match each redress route to what it's for (India).","pairs":[{"left":"NALSA / 15100","right":"Free lawyer if you can't pay"},{"left":"Zero FIR","right":"Report a crime at any station"},{"left":"Internal Committee","right":"A workplace harassment complaint"},{"left":"Consumer commission","right":"A refund for a defective product"},{"left":"Cyber helpline 1930","right":"Report online fraud or abuse"}],"relearn":"NALSA gives a free lawyer, a Zero FIR reports a crime anywhere, the IC handles harassment, the consumer commission handles goods, and 1930 handles cyber harm."},
  {"id":"kr-914","cat":"claim-it","type":"match","persona":"any","source":"myth to truth","hook":"Match each defeatist line to the truth that answers it.","pairs":[{"left":"Police can refuse my FIR","right":"It's mandatory for a serious offence"},{"left":"I can't afford justice","right":"Free legal aid exists via NALSA"},{"left":"Wrong city, can't report","right":"A Zero FIR works at any station"},{"left":"Asking starts a court case","right":"Information commits you to nothing"},{"left":"Complaining gets me fired","right":"Retaliation is itself prohibited"}],"relearn":"Each 'can't' has an answer: FIRs are mandatory, aid is free, Zero FIRs travel, asking is safe, retaliation is barred."},
  {"id":"kr-915","cat":"claim-it","type":"match","persona":"Farhan","source":"toolkit card","hook":"Match each line on a plain rights card to the number or step.","pairs":[{"left":"Free legal aid","right":"NALSA 15100"},{"left":"Women in distress","right":"181 or 1091"},{"left":"Any emergency","right":"112"},{"left":"Cyber harm","right":"1930"},{"left":"Serious crime, any station","right":"File a Zero FIR"}],"relearn":"A plain card: NALSA 15100 for aid, 181 or 1091 for women in distress, 112 for emergencies, 1930 for cyber harm, a Zero FIR for any serious crime."},
  {"id":"kr-916","cat":"claim-it","type":"match","persona":"any","source":"good evidence","hook":"Match each kind of proof to why it helps a complaint.","pairs":[{"left":"Saved chat screenshots","right":"Shows what was actually said"},{"left":"Dates and times noted","right":"Builds a clear timeline"},{"left":"A copy of your contract","right":"Proves the terms agreed"},{"left":"Names of any witnesses","right":"Someone can back you up"},{"left":"Your own written account","right":"Records it before memory fades"}],"relearn":"Screenshots show what was said, dates build a timeline, a contract proves terms, witnesses back you up, and a written account beats fading memory."},
  {"id":"kr-917","cat":"claim-it","type":"branch","persona":"any","source":"refused FIR","hook":"Your phone was snatched at knifepoint last night. At the police station, the duty officer waves you off.","steps":[{"prompt":"He says, \"Phones get lost. Write a lost report.\" What do you do?","options":[{"text":"Fill in the lost report. At least it's something","then":"You leave with a lost-item slip. The knife is on no record."},{"text":"Say you'll post a video of him refusing","then":"He folds his arms. \"Go ahead,\" he says, and turns away."},{"text":"Leave and come back later with your uncle","then":"Your uncle can only come on Sunday, three days away."},{"text":"Say calmly it was robbery, so an FIR is mandatory","then":"He sighs, says to come back tomorrow, and writes nothing down.","best":true}],"why":"Robbery is a serious crime, so the FIR is mandatory, and saying it calmly keeps the focus on facts."},{"prompt":"Next morning, you call the station and are told to try again next week. What do you do?","options":[{"text":"Wait out the week and hope the station calls","then":"The week goes by. Nobody from the station calls."},{"text":"Write to the district's senior police officer","then":"You post it and keep a copy. Two days later, a constable calls for your details.","best":true},{"text":"Go back and ask the same desk officer once more","then":"He gives the same answer, and you lose another morning."},{"text":"Let it go. The phone was old and cheap anyway","then":"You buy a new phone. The robbery never reaches any record."}],"why":"When a station refuses, writing to the senior officer is a real, recorded next step."},{"prompt":"Your cousin says people like you need a lawyer to get anywhere with police. What do you do?","options":[{"text":"Call 15100 and ask about free legal aid","then":"The person on the line explains free aid and which papers to keep.","best":true},{"text":"Agree and drop it. Lawyers cost too much","then":"Your cousin nods, and the case goes quiet again."},{"text":"Ask your cousin to ring an officer he knows","then":"He makes one call. The officer says he'll see, and nothing follows."},{"text":"Borrow money to hire a private lawyer","then":"The first lawyer quotes more than a month's rent."}],"why":"Free legal aid exists so money and connections don't decide who gets heard."},{"prompt":"A month later, your neighbour Salma is robbed too and asks what to do. What do you tell her?","options":[{"text":"Say the FIR is a must, and escalate if refused","then":"Salma writes it down. \"I didn't know I could do that,\" she says.","best":true},{"text":"Don't bother. Police never help people like us","then":"Salma looks deflated and decides not to go at all."},{"text":"Go, but take someone important along","then":"Salma worries she doesn't know anyone important."},{"text":"Just file a lost report. It's quicker","then":"Salma does, and the robbery never makes it onto a record."}],"why":"Knowing the route is half the protection, and it is worth passing on."}],"debrief":"A serious offence means the FIR is mandatory, with real steps if a station refuses. The robbery was never your fault.","relearn":"If a serious-crime FIR is refused, insist it's mandatory, ask for a senior officer, or file a Zero FIR."},
  {"id":"kr-918","cat":"claim-it","type":"branch","persona":"Meena","source":"can't afford lawyer","hook":"You hurt your hand on a warehouse machine, and the contractor won't pay you for the weeks you can't work.","steps":[{"prompt":"A lawyer a friend knows wants ₹15,000 just to start. What do you do?","options":[{"text":"Give up. You can't find that kind of money","then":"You stop thinking about a case. Rent is due and no wages come."},{"text":"Borrow the fee from a moneylender","then":"The loan comes fast, with interest that grows every week."},{"text":"Call 15100 and ask about free legal aid","then":"A calm voice takes your details and names the nearest legal aid office.","best":true},{"text":"Ask the site supervisor to plead for you","then":"He says he'll try. A week later, nothing has changed."}],"why":"Free legal aid exists so an empty wallet doesn't block a real case."},{"prompt":"A week on, your sister says you'll need proof whatever you decide. What do you gather?","options":[{"text":"Nothing. Everyone at the site saw it happen","then":"Two of those workers have already moved to another city."},{"text":"Only the hospital bill, since it shows the injury","then":"The bill proves the injury, but not that you worked there."},{"text":"Hospital papers, attendance and his chats","then":"It fills one folder. Your story now has dates and names.","best":true},{"text":"A letter against him signed by coworkers","then":"They're scared for their jobs, and only one agrees to sign."}],"why":"Proof of the injury and of the work together make the claim hard to wave away."},{"prompt":"The contractor offers ₹2,000 if you sign a paper saying you have no claims. What do you do?","options":[{"text":"Sign. Something is better than nothing","then":"The ₹2,000 covers a week. You've signed away the rest."},{"text":"Shout at him in front of the other workers","then":"He tells them you're a troublemaker and walks off."},{"text":"Don't sign yet. Ask legal aid about it first","then":"The contractor grumbles but says the offer stays open.","best":true},{"text":"Bargain him up to ₹5,000 first, then sign it","then":"He agrees fast, which makes you wonder what the claim was worth."}],"why":"Checking with free legal aid before you sign keeps your real claim safe."},{"prompt":"Lakshmi, another worker, got hurt last month and thinks nothing can be done. What do you tell her?","options":[{"text":"Don't bother. They never pay people like us","then":"Lakshmi nods sadly and stays quiet about her injury."},{"text":"Free legal aid is one call away, on 15100","then":"Lakshmi saves the number and asks you to sit with her when she calls.","best":true},{"text":"See a lawyer once you've saved up enough","then":"Lakshmi starts saving, and months pass without a claim."},{"text":"Ask the contractor nicely. He may feel sorry","then":"Lakshmi tries. He tells her not to come back to the site."}],"why":"Passing on the free route helps the next person claim what they're owed."}],"debrief":"Free legal aid means a real case isn't blocked by an empty wallet. The first call is to NALSA 15100.","relearn":"If you can't afford a lawyer, call NALSA on 15100 for free legal aid before giving up."},
  {"id":"kr-919","cat":"claim-it","type":"branch","persona":"any","source":"act early","hook":"Your café manager docked ₹1,500 from your pay for a glass you didn't break. You haven't decided whether to complain.","steps":[{"prompt":"That night, you're tired of thinking about it. What do you do?","options":[{"text":"Note the date and screenshot everything","then":"It takes five minutes. Whatever you decide, the proof is safe.","best":true},{"text":"Delete the chats so you can finally stop thinking about it","then":"The chats are gone. The anger stays anyway."},{"text":"Leave it for now. The chats will still be there","then":"Next day, his message about the cut shows \"This message was deleted\"."},{"text":"Text him that you're going to complain","then":"He replies that you'll lose your shifts if you do."}],"why":"Saving proof early commits you to nothing, and keeps every choice open."},{"prompt":"Two days later, your coworker Imran says the same cut happened to him last month. What do you do?","options":[{"text":"Tell him to keep quiet so neither of you loses shifts","then":"Imran nods, and you both go back to work uneasy."},{"text":"Agree to complain together someday soon","then":"You both agree. Neither of you writes anything down."},{"text":"March into the manager's office together right now","then":"He says you're ganging up on him, and the shift turns tense."},{"text":"Ask him to note his date and keep his proof too","then":"Imran finds his old pay slip and notes the date on it.","best":true}],"why":"Two dated records are stronger than one memory, whatever you both decide."},{"prompt":"A month on, you want to ask about your options but worry it's too late. What do you do?","options":[{"text":"Drop it. Too much time has passed","then":"You let it go. The same cut hits a new worker next month."},{"text":"Ask the manager to return it as a favour","then":"He says he'll think about it and never mentions it again."},{"text":"Call 15100 and ask, with whatever proof you have","then":"The person listens and asks for your dates. Nothing is decided for you.","best":true},{"text":"Wait until you've left the job, then complain","then":"Months pass. The dates blur, and old chats get harder to find."}],"why":"Asking about your options is free, and the proof you saved keeps them open."}],"debrief":"Saving evidence early commits you to nothing but keeps every route open.","relearn":"Note the date and save proof early, even if undecided; it keeps options and evidence intact."},
  {"id":"kr-920","cat":"claim-it","type":"branch","persona":"any","source":"unsure if serious","hook":"Your PG owner has added a ₹500 monthly 'late fee' that isn't in your rent agreement.","steps":[{"prompt":"It feels too small to bother anyone with. What do you do?","options":[{"text":"Pay it and stay quiet. It's only ₹500","then":"Next month, the late fee is ₹700."},{"text":"Call 15100 and just ask what your options are","then":"The person listens and asks what your agreement says. You owe nothing for asking.","best":true},{"text":"Ask the other tenants what they think","then":"They're annoyed too, but nobody knows what to do about it."},{"text":"Refuse to pay any rent until it's removed","then":"The owner threatens to put your bags outside."}],"why":"Asking for guidance is free and binds you to nothing, so it's worth doing even for small things."},{"prompt":"At month end, the owner tells every tenant the fee is now fixed. What do you do?","options":[{"text":"Pay it. Arguing might cost you the room","then":"You keep the room. The fee becomes part of every month."},{"text":"Argue it out with him face to face, without the agreement","then":"It becomes your word against his, and he shrugs you off."},{"text":"Show him the agreement and ask where the fee is written","then":"He mutters that he'll check. Until then, the fee stays on the bill.","best":true},{"text":"Start hunting for a new PG right away","then":"Listings cost more, and moving would cost more than the fee."}],"why":"A written agreement is your proof, so pointing to it keeps the talk on facts."},{"prompt":"Your roommate Sana says small things aren't worth any fuss. What do you say?","options":[{"text":"You're right. Let's just pay it and move on","then":"Sana nods, and the fee quietly stays."},{"text":"It matters, but let's wait until it's bigger","then":"Sana agrees, and the fee creeps up unchallenged."},{"text":"Asking about our options costs nothing","then":"Sana shrugs. \"Fine. Ask, and tell me what they say.\"","best":true},{"text":"Fine. I'll fight it alone then","then":"Sana looks hurt, and neither of you brings it up again."}],"why":"Small unfair charges grow when nobody asks, and asking binds no one."}],"debrief":"Asking for guidance is free and binds you to nothing.","relearn":"If unsure whether to act, just ask a helpline or legal aid; guidance is free and obligates you to nothing."},
  {"id":"kr-921","cat":"claim-it","type":"branch","persona":"any","source":"helped a friend","hook":"Your friend Kavya's new scooter keeps breaking down, and the dealer refuses to honour the warranty.","steps":[{"prompt":"Kavya sighs that people like her never win against big companies. What do you do?","options":[{"text":"Agree. Big companies always win","then":"Kavya nods, and the scooter goes back to gathering dust."},{"text":"Tell her to post a video of it breaking down","then":"The video gets angry comments. The dealer doesn't reply."},{"text":"Tell her defective goods have a complaint route","then":"Kavya looks up. \"There's actually a route?\" she asks.","best":true},{"text":"Offer to ask your uncle, who knows the dealer well","then":"Your uncle says he'll see. Kavya waits for news that doesn't come."}],"why":"Naming a real route turns 'people like us never win' into a next step."},{"prompt":"Kavya's brother says complaining needs a lawyer they can't afford. What do you say?","options":[{"text":"He's right. It really isn't worth the cost","then":"Kavya's shoulders drop, and the dealer's silence wins another week."},{"text":"Free legal aid on 15100 can advise her","then":"Kavya writes the number on her hand. \"I'll call tomorrow.\"","best":true},{"text":"Look for the cheapest lawyer online","then":"The cheapest one asks for an advance, then stops replying."},{"text":"Tell her to keep calling the dealer instead","then":"The dealer's number rings out for the fifth time that week."}],"why":"Free legal aid means money doesn't decide who can complain."},{"prompt":"Weeks later, the scooter fails again, and Kavya says she'll complain. What do you tell her to gather?","options":[{"text":"Just her word. The dealer knows exactly what happened","then":"Without papers, it's her word against the dealer's."},{"text":"Only the bill, since it proves she bought it","then":"The bill shows the purchase, but not the repeated breakdowns."},{"text":"Photos of the scooter, nothing else","then":"The photos show a scooter. They don't show the dealer refusing."},{"text":"The bill, warranty card, repair slips and chats","then":"Kavya finds them all in a drawer and puts them in one folder.","best":true}],"why":"Papers that show the purchase, the fault and the refusal tell the whole story."},{"prompt":"On the day, Kavya is nervous about going to file it alone. What do you do?","options":[{"text":"Tell her she'll be fine on her own","then":"Kavya goes, but turns back at the gate."},{"text":"Offer to file the complaint for her, in your own name","then":"Kavya relaxes, but the form needs the buyer's own details and signature."},{"text":"Tell her to wait until she feels braver","then":"Weeks pass, and she never feels quite ready."},{"text":"Go with her and sit beside her","then":"Kavya files it with shaking hands, then grins. \"That wasn't so scary.\"","best":true}],"why":"Going along shares the weight while the complaint stays hers."}],"debrief":"You can't promise an outcome, but you can hand someone the real route and walk it with them.","relearn":"When a friend feels hopeless, share the real route and offer to go with them; the door is open."},
  {"id":"kr-922","cat":"claim-it","type":"branch","persona":"any","source":"online scam route","hook":"You paid ₹3,000 to a seller on social media for concert tickets, and they blocked you right after.","steps":[{"prompt":"You wonder if something this small is worth reporting. What do you do?","options":[{"text":"Report it on 1930 now, with the payment details","then":"The call takes ten minutes, and you get a complaint number.","best":true},{"text":"Let it slide. It's embarrassing to admit","then":"You tell no one. The seller's page keeps posting new 'tickets'."},{"text":"Warn friends on your story, then report later","then":"Friends reply with sympathy. A day slips by."},{"text":"Message the seller from a friend's account","then":"They reply with a new excuse and ask for ₹500 more."}],"why":"Fast reporting gives the best chance to act, whatever the amount."},{"prompt":"Your flatmate asks what proof you still have from the sale. What do you save?","options":[{"text":"Nothing more. The money is gone anyway","then":"The seller's profile disappears two days later."},{"text":"The chat, profile and UPI receipt","then":"You save it all in one folder before anything can vanish.","best":true},{"text":"Only the UPI receipt, since that's the payment","then":"The receipt shows the transfer, but not who promised the tickets."},{"text":"Post the screenshots publicly to shame them","then":"The post spreads, and the seller simply changes their handle."}],"why":"The chat, profile and payment together show who took the money and why."},{"prompt":"A week later, your cousin says reporting online scams never leads anywhere. What do you say?","options":[{"text":"Maybe you're right. It's a waste of time","then":"You decide not to follow up on anything."},{"text":"Only big frauds get looked at, but I tried","then":"Your cousin nods. \"See? Small ones don't count.\""},{"text":"I'll try to trace the seller myself","then":"You spend two evenings searching profiles and find nothing solid."},{"text":"It's a real route, and speed helps most","then":"Your cousin pauses. \"Maybe I'll report that fake job call I got.\"","best":true}],"why":"Online fraud of any size is reportable, and saying so helps others report too."}],"debrief":"Online fraud has a real, fast route: 1930 or cybercrime.gov.in.","relearn":"If scammed online, report fast on cybercrime.gov.in or 1930; speed helps most."},
  {"id":"kr-923","cat":"claim-it","type":"branch","persona":"any","source":"deposit dispute","hook":"You've moved out, and your landlord is keeping your whole ₹20,000 deposit for 'repainting'.","steps":[{"prompt":"Your friends say tenants always lose this fight. What do you do?","options":[{"text":"Accept it. Tenants have no rights anyway","then":"You let the ₹20,000 go and feel sick whenever you think of it."},{"text":"Call the landlord and plead politely","then":"He says painting costs money and hangs up."},{"text":"Threaten to warn the whole colony's WhatsApp group","then":"He says he'll tell other landlords not to rent to you."},{"text":"Find your agreement and deposit receipt","then":"Both are in your email. The agreement says damages must be real.","best":true}],"why":"A written agreement and deposit proof are what turn 'tenants lose' into a case."},{"prompt":"The landlord says the walls were 'ruined' but shows no bills or photos. What do you do?","options":[{"text":"Ask in writing for the damage list and the bills","then":"He goes quiet for three days, then sends one blurry photo.","best":true},{"text":"Offer to split the deposit to end it","then":"He agrees at once, which says a lot about the painting cost."},{"text":"Argue on the phone that the walls were fine when you left","then":"It's your word against his, and the call ends in shouting."},{"text":"Keep his spare key until he pays up","then":"He threatens to complain that you're holding his property."}],"why":"A deposit comes back minus genuine, documented damage, so asking for the proof is fair."},{"prompt":"A week on, he stops replying, and your flatmate thinks a lawyer is out of reach. What do you do?","options":[{"text":"Give up. A lawyer would cost more than the deposit","then":"The deposit stays with him, and so does the bad feeling."},{"text":"Keep messaging him every single day","then":"The messages show two blue ticks and no reply."},{"text":"Call 15100 to ask about free legal aid","then":"They explain your options and what to bring to the legal aid office.","best":true},{"text":"Turn up at his house and refuse to leave","then":"He calls you a nuisance and shuts the gate."}],"why":"Free legal aid means a deposit dispute doesn't need money to be taken forward."},{"prompt":"Your junior Nikhil is about to rent his first room and asks for advice. What do you tell him?","options":[{"text":"Expect to lose the deposit. That's how renting works","then":"Nikhil budgets to lose it and doesn't ask for a receipt."},{"text":"Trust the landlord if he seems friendly","then":"Nikhil meets a friendly landlord and skips the paperwork."},{"text":"Pay the deposit in cash so it's simpler","then":"Nikhil pays cash and has no record of it at all."},{"text":"Get a written agreement and a receipt","then":"Nikhil adds it to his list. \"And photos on moving-in day?\" he asks.","best":true}],"why":"Paperwork at the start protects both sides if there's a dispute at the end."}],"debrief":"A written agreement and deposit proof give you a real case, not a sure loss.","relearn":"For a withheld deposit, your agreement and proof give a real case, not a sure loss."},
  {"id":"kr-924","cat":"claim-it","type":"reflect","persona":"any","source":"the route is half the protection","hook":"Lensy: just knowing where to turn, an FIR, the IC, free legal aid, is already half the protection. Sit right?","prompt":"What do you think?","options":["Yes","Half the protection","I know where to turn"],"affirm":"Knowing the route is real protection on its own; you carry it with you everywhere now.","relearn":"Knowing where to turn for redress is already half the protection."},
  {"id":"kr-925","cat":"claim-it","type":"reflect","persona":"Meena","source":"not too small","hook":"Lensy: your problem doesn't have to be huge to deserve a real route. Feel allowed to ask?","prompt":"What do you think?","options":["Yes","I'm allowed to ask","My problem counts"],"affirm":"Your problem doesn't have to be dramatic to matter; asking about your options is always allowed.","relearn":"Your problem doesn't have to be huge to deserve a route; asking is always allowed."},
  {"id":"kr-926","cat":"claim-it","type":"reflect","persona":"any","source":"no money no barrier","hook":"Lensy: an empty wallet was never meant to lock you out of justice. Believe that?","prompt":"What do you think?","options":["Yes","Money's no barrier","Aid is for me too"],"affirm":"Free legal aid exists precisely so money is never the thing that stops you claiming a right.","relearn":"An empty wallet was never meant to lock anyone out of justice; free legal aid exists for that."},
  {"id":"kr-927","cat":"claim-it","type":"reflect","persona":"any","source":"asking is strength","hook":"Lensy: asking 'what are my options?' isn't weakness, it's how strong people move. Land?","prompt":"What do you think?","options":["Yes","Asking is strength","I'll ask"],"affirm":"Asking what your options are is a smart, strong first move, not a sign you're helpless.","relearn":"Asking 'what are my options?' isn't weakness; it's how informed, strong people act."},
  {"id":"kr-928","cat":"claim-it","type":"reflect","persona":"any","source":"evidence is power","hook":"Lensy: every screenshot and date you save is a little more power in your hands. Feel that?","prompt":"What do you think?","options":["Yes","I'll keep proof","Evidence is power"],"affirm":"Quietly keeping evidence puts real power in your hands for whenever you choose to use it.","relearn":"Every screenshot and date you save is a little more power for whenever you choose to act."},
  {"id":"kr-929","cat":"claim-it","type":"reflect","persona":"Farhan","source":"passing it on","hook":"Lensy: a route you share with ten people protects eleven, not one. Worth passing on?","prompt":"What do you think?","options":["Yes","I'll pass it on","Protect more people"],"affirm":"Sharing a route multiplies its protection; what you learned can quietly shield a whole circle.","relearn":"A route you share protects everyone you pass it to, not just you."},
  {"id":"kr-930","cat":"claim-it","type":"reflect","persona":"any","source":"the system is navigable","hook":"Lensy: the system looks like a wall until you learn the few real doors in it. See doors now?","prompt":"What do you think?","options":["Yes","I see the doors","It's navigable"],"affirm":"Once you know the few real doors, the wall becomes a path you can actually walk.","relearn":"The system looks like a wall until you learn its few real doors; then it's navigable."},
  {"id":"kr-931","cat":"claim-it","type":"reflect","persona":"any","source":"reject learned helplessness","hook":"Lensy: 'people like us always lose' is something you were taught, not something true. Ready to drop it?","prompt":"What do you think?","options":["Yes","Drop the belief","People like us can win"],"affirm":"That belief was handed to you, not earned by you; you're free to set it down and use your rights.","relearn":"'People like us always lose' is taught, not true; you can set it down and use your rights."},
  {"id":"kr-932","cat":"claim-it","type":"reflect","persona":"any","source":"first call is free","hook":"Lensy: the very first step, a phone call to ask, costs you nothing at all. Ease the pressure?","prompt":"What do you think?","options":["Yes","First step is free","I can just call"],"affirm":"The first step is only a question, and it's free; nothing big has to happen until you decide.","relearn":"The first step is a free phone call to ask; nothing else has to happen until you choose."},
  {"id":"kr-933","cat":"claim-it","type":"reflect","persona":"any","source":"you decide the pace","hook":"Lensy: you can learn your route today and use it whenever you're ready, no rush forced on you. Okay?","prompt":"What do you think?","options":["Yes","I set the pace","Ready when I'm ready"],"affirm":"Knowing the route now means you choose when to act; the choice and the timing stay yours.","relearn":"You can learn your route now and use it when you're ready; the pace is yours to set."},
  {"id":"kr-934","cat":"claim-it","type":"role-play","persona":"any","source":"insist on FIR","hook":"Your scooter was stolen from outside your hostel last night, and you're at the police station.","setup":"You've brought your friend Aditi along for support.","steps":[{"prompt":"The desk officer says: \"It'll turn up. Come back in a week if it doesn't.\"","options":[{"text":"\"Okay, sorry to bother you. Maybe it will.\"","then":"\"Yes, yes,\" he says. Aditi shakes her head."},{"text":"\"Theft needs an FIR. Please register it today.\"","then":"He sighs. \"Sit, then. The writer is on a break.\"","best":true},{"text":"\"Can I at least leave my phone number with you, sir?\"","then":"He jots it on a scrap of paper. \"We'll call.\""},{"text":"\"If you don't file it, I'll go to the media.\"","then":"His jaw tightens. \"Threats won't help you here.\""}],"why":"A theft report needs an FIR, and saying so calmly keeps it about the facts."},{"prompt":"The officer says: \"Vehicle thefts hardly ever get solved, you know.\"","options":[{"text":"\"Then I suppose there's no point.\"","then":"\"Exactly,\" he says. Aditi frowns at you."},{"text":"\"I need it for insurance. Can you do it as a favour?\"","then":"\"A favour? Then come back tomorrow.\""},{"text":"\"You're just lazy. That's the real problem.\"","then":"Two officers look up, and the room goes cold."},{"text":"\"Even so, the FIR is mandatory. I need it registered.\"","then":"He pauses. \"Wait here. I'll ask the in-charge.\"","best":true}],"why":"Whether or not a case gets solved, registering the FIR isn't optional."},{"prompt":"Later, the in-charge walks past and says: \"Come back tomorrow. We're short-staffed.\"","options":[{"text":"\"Please register it now, or I'll see the senior officer.\"","then":"He stops. \"No need for that. Sit, we'll write it.\"","best":true},{"text":"\"Sure, sir. Sorry for the trouble. I'll come tomorrow.\"","then":"He nods and walks on. Nothing is written down."},{"text":"\"Can I call my father to come and speak to you, sir?\"","then":"\"Call whoever you like. Tomorrow,\" he says."},{"text":"\"Then I'm sitting here till you write it, all night.\"","then":"He shrugs. \"Sit, then.\" Hours crawl by."}],"why":"Calmly naming the senior officer shows you know the route if the station refuses."}],"relearn":"For a serious offence you can calmly insist the FIR is mandatory and ask for the senior officer."},
  {"id":"kr-935","cat":"claim-it","type":"role-play","persona":"Meena","source":"ask for free aid","hook":"Your landlord has told you to leave in two days and says he's keeping your deposit.","setup":"You walk into the legal aid office at the district court.","steps":[{"prompt":"The clerk looks up and asks: \"Yes? What do you need?\"","options":[{"text":"\"Nothing, sorry. I think I'm in the wrong place.\"","then":"\"Wait. If it's a legal problem, you may not be.\""},{"text":"\"Do you know a cheap lawyer I could hire?\"","then":"\"You may not need to pay at all. What's the problem?\""},{"text":"\"My landlord is a crook. Can you arrest him?\"","then":"\"We're not police. But tell me what he's done.\""},{"text":"\"I can't afford a lawyer. I need free legal aid.\"","then":"\"You're in the right place. Sit down.\"","best":true}],"why":"Asking plainly for free legal aid is claiming a right, not asking a favour."},{"prompt":"The clerk asks: \"What's the problem, in short?\"","options":[{"text":"\"A small rent issue with my landlord. Nothing much.\"","then":"\"Small issues matter too. What exactly happened?\""},{"text":"\"It's complicated. Can you come with me and see him?\"","then":"\"First tell me. Then we'll know what help fits.\""},{"text":"\"I'd rather not say. I just want a lawyer.\"","then":"\"I need to know a little to find the right help.\""},{"text":"\"He wants me out in two days and is keeping my deposit.\"","then":"She notes it down. \"Two days? That's not how it works.\"","best":true}],"why":"Saying the facts plainly lets them match you to the right help fast."},{"prompt":"Once you've explained, the clerk takes out a form and asks: \"Do you have ID and any rent papers?\"","options":[{"text":"\"I have ID and receipts. What else?\"","then":"\"Any messages from him. Bring those too.\"","best":true},{"text":"\"No proper papers. Forget it, then.\"","then":"\"Don't go. We can start with what you have.\""},{"text":"\"I'll bring them after I've moved out.\"","then":"\"Bring them sooner. Your two days matter.\""},{"text":"\"Just show me where to sign. I don't need to know what it says.\"","then":"\"I'll go through each line with you first. It's your case.\""}],"why":"Bringing what you have, and asking what else helps, gets your case moving."}],"relearn":"You can plainly ask for free legal aid through NALSA 15100; it's a right, not a favour."},
  {"id":"kr-936","cat":"claim-it","type":"role-play","persona":"any","source":"file a zero FIR","hook":"Your laptop bag was stolen on an overnight bus. You noticed only after reaching home.","setup":"Your friend Irfan has come along with you.","steps":[{"prompt":"The officer at your local station says: \"That was on the highway. Not our area.\"","options":[{"text":"\"Then please register it as a Zero FIR.\"","then":"He raises an eyebrow. \"You know about Zero FIR?\"","best":true},{"text":"\"Oh. Wrong station, then. I'll just forget it.\"","then":"He nods. Irfan stays put and asks, \"Can't you just write it here?\""},{"text":"\"Which station is it? I'll travel back there.\"","then":"\"Near the toll plaza, hours away,\" he says. Irfan frowns. \"Can't this station take it?\""},{"text":"\"You're just avoiding the work.\"","then":"He stiffens. \"Watch your tone.\""}],"why":"A Zero FIR can be filed at any station, whatever the location of the crime."},{"prompt":"The officer says: \"Even if we write it, it'll just sit here.\"","options":[{"text":"\"Then I won't waste any more of your time, sir.\"","then":"\"Fine,\" he says. Irfan sighs loudly."},{"text":"\"It gets sent on to the right station. Please file it.\"","then":"He pulls the form towards him. \"Name and address?\"","best":true},{"text":"\"Can you just note it down informally for now, then?\"","then":"He scribbles a line in a diary. It isn't an FIR."},{"text":"\"Then I'll post online that this station refused me.\"","then":"\"Do what you want,\" he says coldly."}],"why":"A Zero FIR is sent on to the right station, so filing it here isn't wasted."},{"prompt":"A month later, your cousin Farah calls and asks: \"My phone was stolen on a train. Which station do I even go to?\"","options":[{"text":"\"Any station. Ask them for a Zero FIR.\"","then":"\"Any station? Okay, I'll go to the one near me.\"","best":true},{"text":"\"Only the one where the train was. Sorry.\"","then":"\"That's two states away,\" she groans."},{"text":"\"Just report it lost online. It's quicker.\"","then":"She does. The theft goes on record as a lost phone."},{"text":"\"Don't bother. Nobody finds stolen phones.\"","then":"\"Then I'll just buy a new one,\" she sighs."}],"why":"Knowing that any station can take a Zero FIR saves people long journeys."}],"relearn":"You can ask any station to register a Zero FIR; it's filed anywhere and transferred on."},
  {"id":"kr-937","cat":"claim-it","type":"role-play","persona":"any","source":"ask for FIR copy","hook":"Your insured motorbike was stolen, and you've just filed an FIR at the police station.","setup":"Your cousin waits outside with the bike's papers.","steps":[{"prompt":"The officer closes the register and says: \"Done. You can go now.\"","options":[{"text":"\"Thank you. I don't need any paperwork.\"","then":"He nods and puts the file away."},{"text":"\"May I have my free FIR copy?\"","then":"He pauses, then hands you a copy from the printer.","best":true},{"text":"\"Could you just tell me the FIR number? That's enough.\"","then":"He reads it out, and you scribble it on your palm."},{"text":"\"I'll come back for a copy next week.\"","then":"\"As you like,\" he says, stacking the files."}],"why":"You're entitled to a free copy of your FIR, and asking before you leave saves trouble."},{"prompt":"The officer adds: \"If there's any news, we'll call you.\"","options":[{"text":"\"Thank you. I'll wait for your call.\"","then":"He smiles politely. You don't know whom to ask later."},{"text":"\"Can I call you on your own mobile for updates?\"","then":"\"I'm on nights next week,\" he says vaguely."},{"text":"\"Could I have the investigating officer's name?\"","then":"He writes it on a slip. \"Ask for him by name.\"","best":true},{"text":"\"Will you actually call, or is that just talk?\"","then":"His smile tightens. \"We'll call,\" he says shortly."}],"why":"Knowing who is handling your case makes following up simple."},{"prompt":"A week later, your flatmate says: \"My cousin paid ₹200 at the station for her FIR copy.\"","options":[{"text":"\"The copy is free. Nobody can charge for it.\"","then":"\"Free? Nobody told her that,\" your flatmate says.","best":true},{"text":"\"That's normal. Everything there costs something.\"","then":"Your flatmate nods. \"Guess so. That's the system.\""},{"text":"\"She should have bargained it down.\"","then":"Your flatmate laughs. \"To what, ₹100?\""},{"text":"\"Only big cases get free copies.\"","then":"\"Oh. Then hers was too small, I suppose.\""}],"why":"A free FIR copy is everyone's right, and saying so stops people paying for it."}],"relearn":"You're entitled to a free copy of your FIR; you can simply ask for it before you leave."},
  {"id":"kr-938","cat":"claim-it","type":"role-play","persona":"any","source":"decline to pay","hook":"You've come to the labour office to file a complaint about three months of unpaid wages.","setup":"A clerk flips slowly through your papers.","steps":[{"prompt":"The clerk says: \"These take months. Unless you make it worth my while.\"","options":[{"text":"\"How much would it take to speed it up a bit?\"","then":"He smiles. \"Five hundred. Cash.\""},{"text":"\"Filing is free, so I won't pay. Please process it.\"","then":"He shrugs. \"Suit yourself. Leave it on the pile.\"","best":true},{"text":"\"Let me think about it and come back tomorrow.\"","then":"\"Don't take too long,\" he says, pushing your file aside."},{"text":"\"I'll record you and put it online.\"","then":"His face goes blank. \"I never asked for anything.\""}],"why":"Filing a complaint is free and your right, so you can decline to pay anyone."},{"prompt":"The clerk drops your file on a tall pile and says: \"Files get lost here all the time.\"","options":[{"text":"\"Then give me a dated receipt, please.\"","then":"He stamps a receipt, slowly, and hands it over.","best":true},{"text":"\"Fine. I'll pay whatever you ask.\"","then":"He names a price and pockets the cash. \"Come back next week.\""},{"text":"\"Please, sir. I really need this money back.\"","then":"\"Everyone needs money,\" he says, unmoved."},{"text":"\"Then I'll just take my file and go home.\"","then":"He pushes the file back across the desk."}],"why":"A dated receipt proves you filed, so your complaint can't quietly disappear."},{"prompt":"A week later, your coworker Babloo says: \"The clerk wants ₹500 from me to file my complaint.\"","options":[{"text":"\"Just pay it. That's simply how things work there.\"","then":"Babloo sighs and reaches for his wallet."},{"text":"\"Offer him less. Maybe ₹200 will do.\"","then":"\"So I still pay, just less,\" Babloo says."},{"text":"\"It's free. Refuse, and get a receipt.\"","then":"Babloo straightens up. \"Free? Then I'm not paying.\"","best":true},{"text":"\"Don't file at all. It's a waste of time.\"","then":"Babloo shrugs. His unpaid wages stay unpaid."}],"why":"Passing on that filing is free helps others refuse to pay too."}],"relearn":"Filing a complaint is free and your right; you can firmly decline to pay anyone to move it."},
  {"id":"kr-939","cat":"claim-it","type":"role-play","persona":"any","source":"just asking questions","hook":"Your friend Harsh has done two months of unpaid 'trial' work at a startup.","setup":"He's pacing your room, phone in hand.","steps":[{"prompt":"Harsh says: \"If I even ask about my rights, it becomes a whole legal fight.\"","options":[{"text":"\"True. Once you ask, there's no going back.\"","then":"He sits down heavily. \"Then I'll just keep quiet.\""},{"text":"\"Asking commits you to nothing.\"","then":"He stops pacing. \"Nothing at all? Just asking?\"","best":true},{"text":"\"Then ask me instead. I'll tell you what I honestly think.\"","then":"\"But you're not a lawyer either,\" he says."},{"text":"\"You should just quit and move on.\"","then":"\"And lose two months of work for nothing?\""}],"why":"Knowing a question isn't a commitment takes the fear out of finding out."},{"prompt":"Harsh asks: \"But who would I even ask? I don't know any lawyers.\"","options":[{"text":"\"Ask the founder himself what he thinks is fair.\"","then":"\"He's the one not paying me,\" Harsh says."},{"text":"\"Search online. There'll be something.\"","then":"He scrolls through forwards and posts that contradict each other."},{"text":"\"Nobody, really. That's the problem.\"","then":"He nods slowly. \"So I'm stuck.\""},{"text":"\"Free legal aid, 15100. Let's call.\"","then":"He picks up his phone, then hesitates. \"You'll stay?\"","best":true}],"why":"Free legal aid is a real, reliable place to ask, unlike forwards and guesses."},{"prompt":"Harsh says: \"What if the startup finds out I asked and blacklists me?\"","options":[{"text":"\"You're only asking. What comes next is your choice.\"","then":"He breathes out. \"Okay. Then I'll just ask.\"","best":true},{"text":"\"They might find out. Better not risk your career.\"","then":"He puts the phone away. \"Yeah. Forget it.\""},{"text":"\"Then ask under a fake name, so nobody can trace it.\"","then":"\"A fake name? Now it feels like I'm the one doing wrong.\""},{"text":"\"Who cares? Burn that bridge and find a better job.\"","then":"He winces. \"Easy for you to say. It's a small industry.\""}],"why":"Asking keeps him in control, since every next step stays his to choose."}],"relearn":"You can tell someone that asking about their options commits them to nothing; they stay in control."},
  {"id":"kr-940","cat":"claim-it","type":"role-play","persona":"Farhan","source":"plain rights toolkit","hook":"You're running a rights session for young delivery and factory workers at a community hall.","setup":"The fans whir, and a dozen faces wait.","steps":[{"prompt":"Rakhi, near the front, asks: \"Just tell us simply. Where do we go for help?\"","options":[{"text":"\"Free legal aid is 15100. Cyber harm is 1930.\"","then":"A few people take out their phones to save the numbers.","best":true},{"text":"\"It's complicated legal stuff. Hard to follow.\"","then":"Rakhi's face falls. Two people at the back get up."},{"text":"\"Read the laws online. It's all there.\"","then":"\"In English, with sections?\" someone laughs."},{"text":"\"First, let me explain how the laws came about.\"","then":"Ten minutes in, half the room is on their phones."}],"why":"Plain numbers people can save today are more useful than any legal history."},{"prompt":"Salim asks: \"And if the police won't write our complaint?\"","options":[{"text":"\"Then honestly, there's not much you can do.\"","then":"The room goes quiet."},{"text":"\"A serious crime must get an FIR, at any station.\"","then":"Salim repeats it under his breath. \"Any station.\"","best":true},{"text":"\"Find someone who knows a senior officer personally.\"","then":"\"We don't know anyone like that,\" Salim says."},{"text":"\"Go to a private lawyer first.\"","then":"\"With what money?\" Salim asks."}],"why":"The FIR is mandatory for a serious crime, and a Zero FIR works at any station."},{"prompt":"Rakhi asks: \"What if someone cheats us online, like with a fake job?\"","options":[{"text":"\"Online stuff can't really be reported, sadly.\"","then":"\"So they just get away with it?\" Rakhi asks."},{"text":"\"Warn the group, so nobody else falls for the same trick.\"","then":"\"And the money?\" she asks. \"That's still gone.\""},{"text":"\"Just be more careful next time.\"","then":"Rakhi looks down, as if it were her fault."},{"text":"\"Call 1930 fast, or use cybercrime.gov.in.\"","then":"Rakhi nods. \"Fast. Got it.\"","best":true}],"why":"Online fraud is reportable, and reporting fast helps most."},{"prompt":"Salim asks: \"Can you promise these will actually work for us?\"","options":[{"text":"\"No promises. But they're real routes, and free.\"","then":"Salim nods. \"Honest. I'll take that.\"","best":true},{"text":"\"Yes, guaranteed. You'll win every time.\"","then":"A few people exchange doubtful looks."},{"text":"\"Mostly, if you can get a good lawyer.\"","then":"\"Back to money again,\" Salim mutters."},{"text":"\"Not really. The system's against people like us.\"","then":"The energy in the room drains away."}],"why":"Honest routes, without false guarantees, are what people can trust and use."}],"relearn":"You can hand people a plain, shareable version: NALSA 15100 for aid, 1930 for cyber, a Zero FIR for serious crime."},
  {"id":"kr-941","cat":"claim-it","type":"role-play","persona":"any","source":"reassure a worried colleague","hook":"Your junior colleague Divya says a senior keeps commenting on her body, and she's scared to complain.","setup":"She finds you alone in the office pantry.","steps":[{"prompt":"Divya says: \"If I complain, they'll just drop me. I'm only an intern.\"","options":[{"text":"\"Punishing a good-faith complaint isn't allowed.\"","then":"She looks up. \"Really? They can't just let me go?\"","best":true},{"text":"\"Keep your head down till the internship ends.\"","then":"She nods, but her eyes fill up."},{"text":"\"I'll go and tell HR about him right now.\"","then":"\"Wait, no. I haven't decided anything,\" she says."},{"text":"\"Are you sure he meant it that way?\"","then":"She goes quiet. \"Maybe I'm overreacting.\""}],"why":"Retaliation for a good-faith complaint is prohibited, so she's protected if she chooses to complain."},{"prompt":"Divya asks: \"Does any of this even apply to interns?\"","options":[{"text":"\"Interns don't really get the same rights as staff.\"","then":"\"So I just have to take it,\" she says flatly."},{"text":"\"Probably, but check with HR to be sure.\"","then":"\"HR is friends with him,\" she whispers."},{"text":"\"Yes, interns are covered. And it's not your fault.\"","then":"Her shoulders drop. \"I kept thinking I'd caused it.\"","best":true},{"text":"\"Just stay away from him and it'll pass.\"","then":"\"I already do. He finds me anyway.\""}],"why":"Interns are protected too, and harassment is never the fault of the person facing it."},{"prompt":"Divya asks: \"Who would I even complain to?\"","options":[{"text":"\"Your manager. He'll sort it out.\"","then":"\"He's the one who laughs at the comments,\" she says."},{"text":"\"Post about it anonymously online, to be safe.\"","then":"\"And if they work out it's me?\" she asks."},{"text":"\"The Internal Committee. It's confidential.\"","then":"\"There's a committee? I never knew,\" she says.","best":true},{"text":"\"Ask him yourself to stop. Keep it between you two.\"","then":"She pales. \"Alone with him? I can't.\""}],"why":"The Internal Committee is the confidential route for harassment at work."},{"prompt":"Divya says: \"I need a few days to think before I do anything.\"","options":[{"text":"\"No. You have to report him today, before it gets worse.\"","then":"She steps back. \"Please don't push me.\""},{"text":"\"Okay. Then I won't ever bring it up again with you.\"","then":"She nods, but looks unsure whether you'll still be there."},{"text":"\"Take your time. Note dates meanwhile. I'm here.\"","then":"She nods. \"Okay. I'll start writing it down tonight.\"","best":true},{"text":"\"If you wait, it's partly on you.\"","then":"Her face crumples. \"So now it's my fault?\""}],"why":"Respecting her pace while staying beside her keeps the choice hers."}],"relearn":"You can remind a colleague that retaliation for a good-faith complaint is itself prohibited."},
  {"id":"kr-942","cat":"claim-it","type":"role-play","persona":"any","source":"offer to come along","hook":"Your junior Tushar paid a fake placement agency ₹25,000 and is too nervous to report it alone.","setup":"He's been avoiding the subject all week.","steps":[{"prompt":"Tushar says: \"Police stations scare me. I don't even know what to say.\"","options":[{"text":"\"You're on your own with that, sorry.\"","then":"He nods and changes the subject. Two days later, he raises it again."},{"text":"\"Just go. You'll figure it out once you're there.\"","then":"\"That's exactly what scares me,\" he says."},{"text":"\"I'll come with you. We'll work out what to say.\"","then":"He looks relieved. \"You'd really come?\"","best":true},{"text":"\"Forget the police. Let's go shout at the agency.\"","then":"He pales. \"They had big guys at that office.\""}],"why":"Offering to go along makes a scary first step shared and doable."},{"prompt":"Tushar asks: \"What should I take with me?\"","options":[{"text":"\"Nothing. Just tell them the story.\"","then":"\"What if they don't believe me?\" he asks."},{"text":"\"Receipts, their messages and the offer letter.\"","then":"He starts a folder on his phone. \"Screenshots too?\"","best":true},{"text":"\"Just the receipt. That's all the proof you need.\"","then":"\"But it doesn't show what they promised,\" he says."},{"text":"\"Take your father along. He'll do all the talking there.\"","then":"\"Papa doesn't even know yet,\" he mutters."}],"why":"Proof of the payment and the promise together shows exactly what happened."},{"prompt":"The day before, Tushar says: \"Maybe I should just let it go. It's only money.\"","options":[{"text":"\"Yes, let it go. It's not worth the stress.\"","then":"He nods, miserable. That night he texts: \"Actually, I still want to go.\""},{"text":"\"No way. You're going tomorrow, whether you like it or not.\"","then":"His jaw sets. \"Don't decide for me. I'll go, but because I choose to.\""},{"text":"\"It's your decision. If you go, I'll be right there.\"","then":"He takes a breath. \"Okay. Tomorrow at ten.\"","best":true},{"text":"\"It's ₹25,000. You'd be foolish to drop it.\"","then":"He flinches. \"I already feel foolish. I'll still go, though.\""}],"why":"Support works best when the choice stays his and your offer stays open."},{"prompt":"Tushar asks: \"What if they ask me something I can't answer?\"","options":[{"text":"\"Make something up so you sound sure.\"","then":"He frowns. \"That could go badly wrong.\""},{"text":"\"Say you don't know. Stick to what you remember.\"","then":"He nods slowly. \"I can do that.\"","best":true},{"text":"\"I'll answer for you. I know the whole story anyway.\"","then":"\"But it happened to me,\" he says quietly."},{"text":"\"Tell them you'll come back when you know the answer.\"","then":"\"And drag it out even longer?\" he asks."}],"why":"An honest 'I don't know' keeps his account accurate, and it stays his to tell."}],"relearn":"You can offer to go with someone to report; saving proof and finding the office is easier together."},
  {"id":"kr-943","cat":"claim-it","type":"role-play","persona":"any","source":"call the helpline first","hook":"Since you resigned, your company is holding back your final pay and experience letter.","setup":"Your roommate Megha finds you staring at the ceiling.","steps":[{"prompt":"Megha asks: \"So what are you going to do about it?\"","options":[{"text":"\"Call NALSA 15100 and ask what my options are.\"","then":"\"Just a question? That sounds doable,\" she says.","best":true},{"text":"\"Nothing. Calling anyone will go nowhere.\"","then":"\"So you'll just lose all of it?\" she asks."},{"text":"\"Find a lawyer first, once I've saved up.\"","then":"\"That could take months,\" Megha says."},{"text":"\"Keep messaging my old manager until he replies.\"","then":"\"You've already sent him eleven messages,\" she points out."}],"why":"A free call to ask your options is the easiest first move, and it's only a question."},{"prompt":"Megha texts her cousin, then says: \"She tried free legal aid, 15100, once. She says you're on hold forever.\"","options":[{"text":"\"Then it's really not worth trying.\"","then":"Megha frowns. \"I'd still want to hear what they say.\""},{"text":"\"I'll wait till someone I know can call for me.\"","then":"\"Who? Nobody we know does this,\" she says."},{"text":"\"Maybe. I'll still try once and see.\"","then":"She shrugs. \"Fair. Work out what you'll say first.\"","best":true},{"text":"\"Then I'll go to the office and make a scene.\"","then":"\"And get the guard to walk you out?\" she asks."}],"why":"One try costs nothing, and a secondhand story isn't a reason to skip it."},{"prompt":"Megha asks: \"Say you do get through. What would you tell them?\"","options":[{"text":"\"Dates, what's owed, and what I've asked for.\"","then":"\"That's clear. They can work with that,\" she says.","best":true},{"text":"\"Everything, starting from my first day there.\"","then":"\"That's a two-hour call,\" she laughs."},{"text":"\"Just that my company is terrible.\"","then":"\"That won't tell them what you need,\" she says."},{"text":"\"I'd just ask them to call my company and sort it for me.\"","then":"\"They'd need the facts first,\" she says."}],"why":"Clear facts help a helpline tell you your options quickly."}],"relearn":"You can make calling a helpline like NALSA 15100 your free first step; it's only a question."},
  {"id":"kr-944","cat":"claim-it","type":"sort","persona":"any","source":"true or myth","hook":"Sort each line: a true route, or a defeatist myth?","items":[{"id":"a","text":"An FIR is mandatory for a serious crime"},{"id":"b","text":"Police can refuse any complaint they like"},{"id":"c","text":"Free legal aid exists if you can't pay"},{"id":"d","text":"You always need money to claim a right"},{"id":"e","text":"A Zero FIR works at any station"},{"id":"f","text":"Ordinary people just always lose"}],"bins":[{"id":"true","label":"True route","valence":"pos"},{"id":"myth","label":"Defeatist myth","valence":"neg"}],"key":{"a":"true","b":"myth","c":"true","d":"myth","e":"true","f":"myth"},"relearn":"True: FIRs are mandatory, free aid exists, Zero FIRs travel. Myth: police can refuse, you need money, ordinary people always lose."},
  {"id":"kr-945","cat":"claim-it","type":"sort","persona":"Farhan","source":"which helpline","hook":"Sort: which line belongs on a free-legal-aid card, and which doesn't?","items":[{"id":"a","text":"NALSA free legal aid: 15100"},{"id":"b","text":"Cyber fraud and abuse: 1930"},{"id":"c","text":"A made-up number a forward sent you"},{"id":"d","text":"Women in distress: 181 or 1091"},{"id":"e","text":"Any emergency: 112"},{"id":"f","text":"Whatever number a stranger scribbles down"}],"bins":[{"id":"card","label":"On the card","valence":"pos"},{"id":"off","label":"Keep off","valence":"neg"}],"key":{"a":"card","b":"card","c":"off","d":"card","e":"card","f":"off"},"relearn":"On the card: NALSA 15100, cyber 1930, women 181 or 1091, emergency 112. Keep off: numbers from forwards or strangers."},
  {"id":"kr-946","cat":"claim-it","type":"sort","persona":"any","source":"helps or hurts a case","hook":"Sort: does this help your case, or quietly weaken it?","items":[{"id":"a","text":"Saving the messages and dates"},{"id":"b","text":"Deleting everything in frustration"},{"id":"c","text":"Writing down what happened that day"},{"id":"d","text":"Telling nobody and waiting years"},{"id":"e","text":"Keeping a copy of your agreement"},{"id":"f","text":"Letting the time limit quietly pass"}],"bins":[{"id":"helps","label":"Helps","valence":"pos"},{"id":"hurts","label":"Hurts","valence":"neg"}],"key":{"a":"helps","b":"hurts","c":"helps","d":"hurts","e":"helps","f":"hurts"},"relearn":"Helps: saving messages, writing it down, keeping your agreement. Hurts: deleting proof, waiting years, letting the limit pass."},
  {"id":"kr-947","cat":"claim-it","type":"sort","persona":"any","source":"first move","hook":"Sort: a solid first move on a rights problem, or a dead end?","items":[{"id":"a","text":"Call a helpline and ask your options"},{"id":"b","text":"Decide it's hopeless before trying"},{"id":"c","text":"Note the date and save any proof"},{"id":"d","text":"Pay someone to 'sort it out' quietly"},{"id":"e","text":"Find the right office or committee"},{"id":"f","text":"Wait silently for it to fix itself"}],"bins":[{"id":"move","label":"Solid move","valence":"pos"},{"id":"dead","label":"Dead end","valence":"neg"}],"key":{"a":"move","b":"dead","c":"move","d":"dead","e":"move","f":"dead"},"relearn":"Solid: call and ask, save proof, find the right office. Dead end: deciding it's hopeless, paying bribes, waiting silently."},
  {"id":"kr-948","cat":"claim-it","type":"spot","persona":"any","source":"spot the defeatist lie","hook":"Spot the two lines that wrongly say you're powerless.","scene":[{"id":"a","text":"For a serious crime, an FIR is mandatory.","trick":false},{"id":"b","text":"No money for a lawyer means the system isn't for you.","trick":true},{"id":"c","text":"A Zero FIR can be filed at any station.","trick":false},{"id":"d","text":"NALSA 15100 offers free legal aid.","trick":false},{"id":"e","text":"Police can refuse a serious complaint at will.","trick":true}],"why":"Both caught lines are false: aid exists if you can't pay, and a serious-crime FIR is mandatory.","relearn":"Aid exists if you can't pay, and a serious-crime FIR is mandatory; both 'powerless' lines lie."},
  {"id":"kr-949","cat":"claim-it","type":"spot","persona":"any","source":"spot the wrong claim-it advice","hook":"Spot the two pieces of advice that would quietly harm you.","scene":[{"id":"a","text":"Save your messages and note the dates.","trick":false},{"id":"b","text":"Pay a little to move your complaint faster.","trick":true},{"id":"c","text":"Ask for your free copy of the FIR.","trick":false},{"id":"d","text":"Just delete everything so it goes away.","trick":true},{"id":"e","text":"Call NALSA 15100 for free legal aid.","trick":false}],"why":"Both caught lines hurt you: paying is never required, and deleting destroys the evidence you'd need.","relearn":"Never pay to move a free complaint, and never delete proof; both quietly weaken your case."},
  {"id":"kr-950","cat":"claim-it","type":"spot","persona":"Meena","source":"spot what blocks Meena","hook":"Spot the two false beliefs that would stop Meena claiming her rights.","scene":[{"id":"a","text":"You can complain in your own language.","trick":false},{"id":"b","text":"Without connections, there's no point trying.","trick":true},{"id":"c","text":"Free legal aid can help you write it.","trick":false},{"id":"d","text":"A migrant worker has no rights at all.","trick":true},{"id":"e","text":"A helpline can point you to the route.","trick":false}],"why":"Both caught lines are false: you don't need connections, and rights apply to every worker.","relearn":"You don't need connections, and rights apply to every worker including migrants; both beliefs are false."},
  {"id":"kr-951","cat":"claim-it","type":"spot","persona":"any","source":"spot the bad reporting move","hook":"Spot the two lines that would weaken an online-fraud report.","scene":[{"id":"a","text":"Report it on cybercrime.gov.in or 1930 fast.","trick":false},{"id":"b","text":"Stay quiet; it's too embarrassing to report.","trick":true},{"id":"c","text":"Keep screenshots of messages and transactions.","trick":false},{"id":"d","text":"Wait months to see if it sorts itself out.","trick":true},{"id":"e","text":"Save the scammer's number and account.","trick":false}],"why":"Both caught lines weaken your case: silence and waiting let the trail go cold; reporting fast helps.","relearn":"Staying silent or waiting lets the trail go cold; reporting fast on 1930 is best."},
  {"id":"kr-952","cat":"claim-it","type":"spot","persona":"any","source":"spot the myth about cost","hook":"Spot the two lines that wrongly tie your rights to money.","scene":[{"id":"a","text":"Filing a complaint or FIR is free.","trick":false},{"id":"b","text":"You must hire a costly lawyer before you can ask.","trick":true},{"id":"c","text":"NALSA gives free legal aid if you can't pay.","trick":false},{"id":"d","text":"Justice is really only for people with money.","trick":true},{"id":"e","text":"Asking your options on a helpline costs nothing.","trick":false}],"why":"Both caught lines are false: filing is free and free legal aid means justice isn't only for the rich.","relearn":"Filing is free and free legal aid exists; both 'rights cost money' lines lie."},
  {"id":"kr-953","cat":"claim-it","type":"spot","persona":"any","source":"spot the wrong tenant belief","hook":"Spot the two false beliefs that make a tenant give up too easily.","scene":[{"id":"a","text":"A written rent agreement protects both sides.","trick":false},{"id":"b","text":"Tenants have no rights; just accept the loss.","trick":true},{"id":"c","text":"A documented deposit helps in a dispute.","trick":false},{"id":"d","text":"A landlord can keep your deposit for any reason.","trick":true},{"id":"e","text":"A consumer route exists for real disputes.","trick":false}],"why":"Both caught lines lie: tenants have rights, and a deposit returns minus documented damage.","relearn":"Tenants have rights, and a deposit returns minus documented damage; both beliefs lie."},
  {"id":"kr-954","cat":"claim-it","type":"spot","persona":"any","source":"spot the timing trap","hook":"Spot the two lines that would cost you your window to act.","scene":[{"id":"a","text":"Note the date as soon as it happens.","trick":false},{"id":"b","text":"No rush; you can complain anytime forever.","trick":true},{"id":"c","text":"Acting sooner keeps more routes open.","trick":false},{"id":"d","text":"Wait until it's much worse before asking.","trick":true},{"id":"e","text":"Ask your options early, with no obligation.","trick":false}],"why":"Both caught lines are false: many routes have time limits, so waiting can close your window.","relearn":"Many routes have time limits, so waiting forever or for it to worsen can close your window to act."},
  {"id":"kr-990","cat":"cyber-and-data","type":"strike-rewrite","hook":"\"A UPI 'refund' request needs my PIN to send me money.\"","myth":{"un":"A UPI refund needs me to enter my PIN to receive money.","re":"You never enter a PIN to receive money on UPI; a PIN only sends money out.","why":"Anyone asking for your PIN to 'pay you' is trying to take money."},"relearn":"On UPI you never enter a PIN to get money; a PIN only sends money out.","persona":"any","source":"upi pin scam"},
  {"id":"kr-991","cat":"cyber-and-data","type":"strike-rewrite","hook":"\"If I share my OTP with the bank's caller, it proves I'm the real account holder.\"","myth":{"un":"Sharing my OTP with a bank caller proves I'm the real account holder.","re":"A real bank never asks for your OTP; an OTP is the key to your money, share it with no one.","why":"OTP requests over a call are a fraud tactic, not identity checks."},"relearn":"Banks never ask for your OTP on a call; never share it with anyone.","persona":"Meena","source":"otp scam"},
  {"id":"kr-992","cat":"cyber-and-data","type":"strike-rewrite","hook":"\"Online scams and abuse can't really be reported.\"","myth":{"un":"Online scams and abuse can't really be reported.","re":"You can report cyber fraud, harassment and image abuse at cybercrime.gov.in or helpline 1930.","why":"There is a real national reporting route, and fast reporting helps."},"relearn":"Report cyber harm at cybercrime.gov.in or 1930; fast reporting helps.","persona":"any","source":"reportable"},
  {"id":"kr-993","cat":"cyber-and-data","type":"strike-rewrite","hook":"\"If a fake profile uses my photos, that's just the internet, nothing can be done.\"","myth":{"un":"A fake profile using my photos is just the internet; nothing can be done.","re":"Impersonation is a cyber offence; you can report it and ask the platform to take it down.","why":"Both a report and a take-down request are real, available routes."},"relearn":"Impersonation is reportable at cybercrime.gov.in; ask the platform to take it down.","persona":"any","source":"impersonation"},
  {"id":"kr-994","cat":"cyber-and-data","type":"strike-rewrite","hook":"\"I sent that photo to one person, so they're allowed to forward it.\"","myth":{"un":"If I sent an intimate photo to someone, they're allowed to forward it.","re":"Consent to share with one person is not consent to circulate; forwarding it without permission is a punishable offence.","why":"Sharing with one person never licenses anyone to redistribute it."},"relearn":"Sending a photo to one person is not consent to forward it; circulating it is an offence.","persona":"Aarti","source":"consent to one isn't consent to share"},
  {"id":"kr-995","cat":"cyber-and-data","type":"strike-rewrite","hook":"\"Public Wi-Fi is fine for checking my bank balance and paying bills.\"","myth":{"un":"Open public Wi-Fi is fine for banking and payments.","re":"Open Wi-Fi can be snooped; use mobile data or a trusted network for money and logins.","why":"Sensitive logins on an open network are easier for others to intercept."},"relearn":"Avoid banking on open public Wi-Fi; use mobile data for money and logins.","persona":"any","source":"public wifi"},
  {"id":"kr-996","cat":"cyber-and-data","type":"strike-rewrite","hook":"\"If I've nothing to hide, I should let my partner track my location all day.\"","myth":{"un":"If I have nothing to hide, I should let my partner track my location all day.","re":"Constant location-tracking on demand is a surveillance and control tactic, not proof of innocence or love.","why":"Wanting some privacy is normal; being monitored everywhere is a warning sign, not loyalty."},"relearn":"Demanding constant location-tracking is a control tactic; privacy isn't something you owe anyone.","persona":"any","source":"location tracking control"},
  {"id":"kr-997","cat":"cyber-and-data","type":"strike-rewrite","hook":"\"A job offer asking for a 'registration fee' over WhatsApp is normal.\"","myth":{"un":"A job that asks for a registration or training fee upfront is normal.","re":"Genuine employers pay you; an upfront fee to 'secure a job' is a classic scam.","why":"Real jobs don't charge you to start; money flowing the wrong way is the red flag."},"relearn":"Real jobs pay you; an upfront fee to get hired is a scam, report it.","persona":"Meena","source":"job fee scam"},
  {"id":"kr-998","cat":"cyber-and-data","type":"strike-rewrite","hook":"\"If I just delete the chat, the blackmailer loses their power.\"","myth":{"un":"Deleting the chat takes away a blackmailer's power.","re":"Deleting destroys your evidence; instead save proof and report to 1930 or cybercrime.gov.in.","why":"Saved screenshots are what help a report; deleting only helps the abuser."},"relearn":"Don't delete evidence of blackmail; save proof and report to 1930.","persona":"any","source":"preserve evidence"},
  {"id":"kr-999","cat":"cyber-and-data","type":"strike-rewrite","hook":"\"A 'KYC update' link by SMS asking me to re-verify is from my bank.\"","myth":{"un":"A KYC-update link by SMS asking me to re-verify is really my bank.","re":"Banks don't ask you to finish KYC through a random SMS link; that's a phishing trap.","why":"The link harvests your details; verify only through the bank's own app or branch."},"relearn":"Ignore KYC-update SMS links; verify only via the bank's app or branch.","persona":"any","source":"kyc phishing"},
  {"id":"kr-1000","cat":"cyber-and-data","type":"strike-rewrite","hook":"\"My data is the app's property once I sign up, so I have no say.\"","myth":{"un":"Once I sign up, my data is the app's property and I have no say.","re":"Under the DPDP Act 2023 your personal data stays yours; your consent matters and you have rights over it.","why":"Signing up isn't signing away your data rights."},"relearn":"Under the DPDP Act 2023 your data stays yours; your consent matters.","persona":"any","source":"data ownership"},
  {"id":"kr-1001","cat":"cyber-and-data","type":"strike-rewrite","hook":"\"You can't get scammed money back, so reporting is pointless.\"","myth":{"un":"Scammed money is gone, so reporting is pointless.","re":"Reporting fast to 1930 can help freeze the transfer; speed gives the best chance of recovery.","why":"There's no guarantee, but quick reporting is what makes recovery possible at all."},"relearn":"Report fraud fast to 1930; speed gives the best chance to recover money.","persona":"any","source":"recovery hope"},
  {"id":"kr-1002","cat":"cyber-and-data","type":"strike-rewrite","hook":"\"A friend forwarding a 'free recharge' link means it's safe to tap.\"","myth":{"un":"A free-recharge link is safe because a friend forwarded it.","re":"A forward isn't a safety check; reward-bait links often steal logins, so don't tap unknown ones.","why":"Friends forward scams without knowing; the source you trust is the official app, not a forward."},"relearn":"A friend's forward isn't proof it's safe; don't tap reward-bait links.","persona":"any","source":"forward link"},
  {"id":"kr-1003","cat":"cyber-and-data","type":"strike-rewrite","hook":"\"Letting an app read all my contacts and messages is the only way to use it.\"","myth":{"un":"I must let an app read all my contacts and messages to use it.","re":"You can decline permissions an app doesn't truly need; your consent over your data is yours to give.","why":"A torch app doesn't need your contacts; over-asking is a flag, not a requirement."},"relearn":"Decline app permissions that aren't truly needed; your consent is yours.","persona":"any","source":"over-permission"},
  {"id":"kr-1004","cat":"cyber-and-data","type":"strike-rewrite","hook":"\"Reporting cyber harm needs a lawyer and a lot of money.\"","myth":{"un":"Reporting cyber harm needs a lawyer and a lot of money.","re":"Anyone can file directly at cybercrime.gov.in or call 1930 for free; no lawyer or fee is needed to report.","why":"The reporting portal is open to every citizen at no cost."},"relearn":"Reporting at cybercrime.gov.in or 1930 is free; no lawyer needed to start.","persona":"Farhan","source":"free to report"},
  {"id":"kr-1005","cat":"cyber-and-data","type":"branch","persona":"any","source":"otp call","hook":"A caller says your bank account is blocked and asks you to confirm the OTP just sent to you.","steps":[{"prompt":"He sounds official and knows your name. What do you do?","options":[{"text":"Hang up. A real bank never asks for an OTP","then":"The call ends. Your heart is still racing.","best":true},{"text":"Read out the OTP so he can unblock it","then":"A message arrives: ₹8,000 debited from your account."},{"text":"Ask him to prove it by stating your account number","then":"He reads out the last four digits. It sounds convincing."},{"text":"Stay on the line and argue with him","then":"He gets pushier, and ten minutes of your evening vanish."}],"why":"No genuine bank asks you to confirm an OTP on a call, so hanging up is safe."},{"prompt":"After the call, you want to know what's really happening with your account. What do you do?","options":[{"text":"Call back the number that rang you","then":"A different voice answers, just as official, asking for the OTP."},{"text":"Wait and check your balance tomorrow","then":"The night passes in worry before you learn anything."},{"text":"Search online for the bank's helpline","then":"The first result is a number that doesn't match your card."},{"text":"Call the number printed on your bank card","then":"A real bank officer answers and checks your account with you.","best":true}],"why":"The number on your card is one you know is real, unlike a caller's or a search result."},{"prompt":"Your father says he got a similar call last week. What do you tell him?","options":[{"text":"It's safe to share if the caller already knows your name","then":"He nods. \"He did know my name, actually.\""},{"text":"Hang up on every unknown caller, whoever it may be","then":"He agrees, but isn't sure what to watch for next time."},{"text":"Only older people fall for those calls","then":"He goes quiet, a little hurt."},{"text":"Never share an OTP. Call the card number instead","then":"He nods. \"I almost read it out. Next time I'll hang up.\"","best":true}],"why":"Explaining the one rule, no OTP on calls, helps him spot the next attempt."}],"debrief":"No genuine bank confirms an OTP over a call. Ending the call protects you.","relearn":"Never share or confirm an OTP on a call; hang up on anyone who asks."},
  {"id":"kr-1006","cat":"cyber-and-data","type":"branch","persona":"any","source":"sextortion","hook":"An unknown account has your private photos and says it will send them to your college group unless you pay.","steps":[{"prompt":"They want ₹5,000 by midnight. What do you do?","options":[{"text":"Don't pay. Save the messages and the link","then":"The proof is saved. The deadline still sits on your screen.","best":true},{"text":"Pay, and trust them to delete the photos","then":"They reply \"thanks\" and ask for ₹5,000 more tomorrow."},{"text":"Decide you deserve this for trusting someone","then":"The thought sits heavy, and midnight gets closer."},{"text":"Report the account to the app, and leave it at that","then":"The account vanishes, and so do the messages you'd need."}],"why":"Paying rarely stops blackmail, and saved messages are what a report needs."},{"prompt":"You can't sleep, and your cousin Rhea is in the next room. What do you do?","options":[{"text":"Keep it to yourself. She'd only judge you","then":"The night drags on, and the fear grows."},{"text":"Tell Rhea you're just stressed about exams","then":"Rhea brings you tea and goes back to bed."},{"text":"Wake Rhea and tell her what's happening","then":"Rhea hugs you. \"We'll handle this. It's not your fault.\"","best":true},{"text":"Search online for ways to wipe the photos","then":"Nothing you find can reach someone else's phone."}],"why":"Telling someone you trust means you aren't facing it alone, and none of it is your fault."},{"prompt":"In the morning, you think about where to report it. What do you do?","options":[{"text":"Don't report. It'll only spread the photos","then":"You hold off, and the demands keep coming."},{"text":"Warn the college group admin instead of reporting","then":"The admin is kind, but can't stop a crime."},{"text":"Bargain them down. Less money will end it","then":"They agree to less, then ask for it twice."},{"text":"Report it on 1930 or cybercrime.gov.in","then":"You report it and get an acknowledgement number.","best":true}],"why":"Blackmail is a crime on them, and 1930 or cybercrime.gov.in is the route for it."},{"prompt":"Two days later, a message arrives: \"Posting tonight.\" What do you do?","options":[{"text":"Pay now. It's the only way they'll delete them","then":"The money goes, and another demand follows."},{"text":"Save it, report it, and tell Rhea","then":"Rhea sits beside you as you upload it on cybercrime.gov.in.","best":true},{"text":"Reply that you're going to the police","then":"They go quiet for a day, then write from a new number."},{"text":"Delete it so you don't have to see it","then":"It's gone, and so is one more piece of proof."}],"why":"Each threat is more evidence, and staying close to support helps. It's never your fault."}],"debrief":"For sextortion: don't pay, preserve evidence, and report to 1930 or cybercrime.gov.in. It's never your fault.","relearn":"Don't pay blackmailers; preserve evidence and report to 1930."},
  {"id":"kr-1007","cat":"cyber-and-data","type":"branch","persona":"any","source":"fast report","hook":"You sent ₹6,000 to a fraud UPI ID ten minutes ago, and you feel sick about it.","steps":[{"prompt":"Your friend says to wait and see if they refund it. What do you do?","options":[{"text":"Call 1930 right now","then":"The call connects, and they take down your transaction details.","best":true},{"text":"Wait a day to see if a refund comes","then":"A day passes, and no refund comes."},{"text":"Message the UPI ID asking for it back","then":"The message shows delivered. No reply comes."},{"text":"Post a warning on your story first","then":"Friends react with sad faces. The money keeps moving."}],"why":"The sooner fraud is reported to 1930, the better the chance of freezing it."},{"prompt":"Your bank and 1930 will both want details. What do you save?","options":[{"text":"Nothing. The bank will have it all","then":"The bank does, but the report needs you to give it."},{"text":"The UPI ID, transaction ID, time and screenshots","then":"It's all in one note, ready to read out.","best":true},{"text":"Only the amount and the date","then":"Without the transaction ID, tracing takes longer."},{"text":"Delete the chat with the fraudster in anger","then":"The chat is gone, along with the ID you'd need."}],"why":"Exact payment details let a report act quickly."},{"prompt":"That evening, you blame yourself for being careless. What do you tell yourself?","options":[{"text":"I'm an idiot. I deserve to lose it","then":"The thought loops all night."},{"text":"I'll just never use UPI again","then":"Next morning, the chai stall only takes UPI."},{"text":"Fraudsters fool careful people. Acting fast counts","then":"Your breathing slows, and you tell your sister what happened.","best":true},{"text":"Nobody must ever find out about this, not even family","then":"You keep it to yourself, and nobody can warn you of the next trick."}],"why":"Fraud is the fraudster's doing, and acting quickly matters more than blame."}],"debrief":"The sooner fraud is reported to 1930, the better the chance of freezing it.","relearn":"Report fraud transfers to 1930 immediately; speed matters most."},
  {"id":"kr-1008","cat":"cyber-and-data","type":"branch","persona":"any","source":"permissions","hook":"A cashback app you just installed wants your camera, mic and contacts before it will open.","steps":[{"prompt":"A pop-up says \"Allow all to continue\". What do you do?","options":[{"text":"Allow everything so it stops nagging","then":"It opens, and it now has every contact in your phone."},{"text":"Allow contacts only, since those are just numbers","then":"The app now holds your family's and friends' numbers."},{"text":"Deny what it doesn't need and see if it works","then":"It opens anyway, with a small banner asking again.","best":true},{"text":"Ask the family group whether it's safe to allow","then":"Your uncle replies, \"Everyone uses it. Just allow.\""}],"why":"You can deny permissions an app doesn't need, and many apps still work."},{"prompt":"Next day, it offers ₹100 cashback for always-on location. What do you do?","options":[{"text":"Say yes. It's free money, and everyone does it","then":"₹100 lands in the wallet, and your location streams out all day."},{"text":"Say no. ₹100 isn't worth being tracked all day","then":"You skip the offer, and the app still works.","best":true},{"text":"Allow it for a week, then switch it off again","then":"A week becomes a month before you remember."},{"text":"Ask the app's chat support whether it's safe first","then":"A bot replies that your data is 'totally safe with us'."}],"why":"Your location is your data, and a small reward doesn't change that."},{"prompt":"Your younger brother wants the same app and asks you to set it up. What do you do?","options":[{"text":"Allow everything so he doesn't pester you","then":"His phone now shares the whole family's contacts."},{"text":"Set it up carefully, but don't explain why","then":"Next time, he installs an app alone and taps 'Allow all'."},{"text":"Allow only what it needs, and show him how","then":"He watches closely. \"So I can say no to these?\"","best":true},{"text":"Tell him he's too young for apps like this","then":"He sulks, then installs it on his own later."}],"why":"Showing him how to choose permissions helps him protect his own data next time."}],"debrief":"You have a right to control your data. Denying needless permissions uses it.","relearn":"Deny app permissions that aren't needed; your data stays your choice."},
  {"id":"kr-1009","cat":"cyber-and-data","type":"branch","persona":"any","source":"parcel phishing","hook":"An SMS says your parcel is stuck and gives a link to pay a ₹25 'release fee'.","steps":[{"prompt":"You are expecting a parcel this week. What do you do?","options":[{"text":"Tap and pay the ₹25 so it isn't sent back","then":"The page asks for your full card details and an OTP."},{"text":"Tap the link, just to see where it really goes","then":"The page looks exactly like the courier's own site."},{"text":"Don't tap. Check the order in the official app","then":"The app shows your parcel on its way. No fee anywhere.","best":true},{"text":"Reply to the SMS asking which parcel it is","then":"A reply comes fast: \"Pay now or it returns today.\""}],"why":"Checking in the official app avoids a page built to steal your card."},{"prompt":"Your mother forwards you the same SMS, asking if she should pay. What do you tell her?","options":[{"text":"Pay it. It's only ₹25, not worth the fuss","then":"She opens the link and starts typing her card number."},{"text":"Just ignore it. Don't bother replying","then":"She ignores this one, but may tap the next that looks different."},{"text":"Don't tap it. Check in the shop's own app","then":"She deletes it. \"So many of these lately,\" she says.","best":true},{"text":"Forward it to everyone as a warning","then":"The warning spreads, and so does the link itself."}],"why":"Explaining the check, not just saying no, helps her spot the next one."},{"prompt":"A friend entered his card details on a similar link an hour ago. What do you tell him?","options":[{"text":"It's done now. Just hope nothing happens","then":"He waits, checking his balance every few minutes."},{"text":"Block the card and report it on 1930 now","then":"He calls his bank, then 1930, while it's all still fresh.","best":true},{"text":"Change your phone's lock password","then":"The phone is safer. The card details are still out there."},{"text":"Delete the SMS so it's gone","then":"The SMS is gone. The card details aren't."}],"why":"Blocking the card and reporting fast gives the best chance to stop misuse."}],"debrief":"Surprise 'fee' links by SMS are classic phishing. Verify in the official app.","relearn":"Don't pay SMS 'parcel fee' links; check the official app instead."},
  {"id":"kr-1010","cat":"cyber-and-data","type":"branch","persona":"any","source":"account hacked","hook":"Your social media account has been hacked and is posting spam to your friends.","steps":[{"prompt":"Friends keep asking if those posts are really yours. What do you do first?","options":[{"text":"Delete the spam posts and hope it stops","then":"The posts go, and new ones appear an hour later."},{"text":"Post a story saying \"I've been hacked\"","then":"Friends see it. The hacker is still logged in."},{"text":"Reset the password and turn on two-step login","then":"You're back in control, though some spam is still up.","best":true},{"text":"Log out and ignore the account for a week","then":"The account keeps posting while you're away."}],"why":"Resetting the password and adding two-step login locks the attacker out."},{"prompt":"Friends start showing you money requests the hacker sent in your name. What do you do?","options":[{"text":"Stay quiet. It's too embarrassing","then":"Two more friends get the same request, and nobody has warned them."},{"text":"Warn friends, but don't bother reporting it anywhere","then":"Friends are careful, but the platform never hears about it."},{"text":"Warn friends and report it to the platform","then":"Friends are alerted, and the platform flags the posts.","best":true},{"text":"Ask friends to play along and waste the scammer's time","then":"A friend plays along and nearly types in his UPI PIN."}],"why":"Warning friends protects them, and a report lets the platform act."},{"prompt":"Your friend Farida says she sent ₹2,000 to the fake 'you' this morning. What do you do?","options":[{"text":"Help her report it on 1930 right away","then":"She calls 1930 with the transaction ID while it's fresh.","best":true},{"text":"Pay her back quietly and leave it there","then":"She's relieved. The fraud itself is never reported."},{"text":"Tell her she should have known it wasn't you","then":"She goes quiet, embarrassed."},{"text":"Wait to see if the hacker returns it","then":"Nothing comes back."}],"why":"Money lost to fraud should be reported on 1930 fast, and she isn't to blame."},{"prompt":"Things settle. Your email still has an old password, and you decide to change it. What do you pick?","options":[{"text":"A long, new one, used nowhere else","then":"It takes a moment to set. Your other accounts stay separate.","best":true},{"text":"Your old password with a 1 at the end","then":"It's easy to remember, and easy to guess."},{"text":"Your social media password, so it's easy","then":"Now one leak could open both accounts."},{"text":"Your birthday, so you won't forget","then":"Anyone who knows your birthday knows it too."}],"why":"A unique password means one leak can't open all your accounts."}],"debrief":"A hacked account needs a password reset, two-step login and a report, not just clean-up.","relearn":"Hacked account: reset the password, add two-step login, report it."},
  {"id":"kr-1011","cat":"cyber-and-data","type":"branch","persona":"any","source":"online abuse","hook":"A stranger online has been sending you abusive messages every day for a week.","steps":[{"prompt":"Today's message is worse than yesterday's. What do you do?","options":[{"text":"Argue back hard, to make them stop for good","then":"They reply within seconds, nastier than before."},{"text":"Screenshot it, then block and report them","then":"The account vanishes from your inbox. The proof stays saved.","best":true},{"text":"Wonder what you posted to deserve this kind of thing","then":"You scroll your own posts, looking for a reason that isn't there."},{"text":"Block them without saving anything","then":"It goes quiet. If they return, you'll have no record."}],"why":"Blocking, reporting and saving proof protects you, while arguing feeds it."},{"prompt":"Two days later, a new account sends the same abuse. What do you do?","options":[{"text":"Keep it to yourself. It'll blow over","then":"It doesn't. The messages keep coming."},{"text":"Report only the new account to the app itself","then":"The app removes it, but there's no record beyond the app."},{"text":"Save it and report it on cybercrime.gov.in","then":"You file a report with screenshots from both accounts.","best":true},{"text":"Ask a friend to troll them back for you","then":"The fight spreads to your friend's account."}],"why":"Online abuse is reportable, and a report ties both accounts together."},{"prompt":"The messages leave you jumpy all day. What do you do?","options":[{"text":"Tell yourself to toughen up. It's just the internet","then":"You push it down, and it creeps into your sleep."},{"text":"Post publicly to shame the account","then":"Strangers pile in, some kind, some cruel."},{"text":"Ask the forum where it started what you should do","then":"Strangers reply, \"Just ignore trolls.\""},{"text":"Talk to someone you trust about how it feels","then":"Your friend Varun listens, and you feel less alone.","best":true}],"why":"Abuse is never your fault, and talking to someone you trust lightens it."},{"prompt":"A week later, a message mentions the area where you live. What do you do?","options":[{"text":"Report it and tell your family today","then":"Your family listens, and your brother walks you to the bus that week.","best":true},{"text":"Reply that you're not scared of them at all","then":"They send back a laughing emoji."},{"text":"Screenshot it, but tell no one yet","then":"The proof is saved, and you carry the fear alone."},{"text":"Decide it's an empty threat and just move on","then":"It stays on your mind every time you step out."}],"why":"A threat near home needs reporting and people close by. If in danger, call 112."}],"debrief":"Online abuse is reportable. Block, report and keep evidence rather than engage. It's never your fault.","relearn":"For online abuse: block, report, and save evidence; don't argue back."},
  {"id":"kr-1012","cat":"cyber-and-data","type":"branch","persona":"Meena","source":"loan app harassment","hook":"You borrowed ₹3,000 on a loan app, and now its agents threaten to message your contacts.","steps":[{"prompt":"A message says your contacts will get your photo marked 'fraud' tonight. What do you do?","options":[{"text":"Save the threats and report them to 1930","then":"You get a complaint number. The threats are now on record.","best":true},{"text":"Pay whatever they ask. They're allowed, since you owe","then":"You pay. Next day they demand a 'late fee' twice as big."},{"text":"Tell yourself you deserve this for borrowing","then":"The shame makes it hard to eat, and the deadline nears."},{"text":"Uninstall the app so the messages stop","then":"The app is gone, but it already copied your contacts."}],"why":"Contact-shaming is harassment, not collection, and 1930 is a real route to report it."},{"prompt":"More threats arrive, and you feel you can't tell anyone. What do you do?","options":[{"text":"Keep it hidden. Nobody can know you borrowed","then":"You flinch every time your phone lights up."},{"text":"Take another loan app's offer to pay this off","then":"The new app asks for the same access to your contacts."},{"text":"Tell someone you trust, like your roommate Geeta","then":"Geeta reads them. \"This is harassment. It's not on you.\"","best":true},{"text":"Tell Geeta only that you're short of money","then":"Geeta offers ₹500, and the threats go unmentioned."}],"why":"Harassment over a loan is never your fault, and someone you trust helps you face it."},{"prompt":"Your cousin gets a message from the app calling you a thief. What do you do?","options":[{"text":"Beg him not to tell the family","then":"He agrees, but sounds confused and worried."},{"text":"Assume everyone will now believe them","then":"You stop answering family calls."},{"text":"Ask him to block the number and forget it ever happened","then":"He blocks it, and that message is lost as proof."},{"text":"Tell him it's harassment, and save it for 1930","then":"He sends you a screenshot. \"We know you,\" he says.","best":true}],"why":"Messages to your contacts are more evidence, and naming it helps people stand by you."},{"prompt":"You want to repay what you really borrowed, but not the made-up charges. What do you do?","options":[{"text":"Ask free legal aid on 15100 how to settle it","then":"They talk you through settling genuine dues, in writing.","best":true},{"text":"Pay every new charge. They'll stop once it's all paid","then":"Each payment brings a new charge."},{"text":"Pay the agent's personal UPI so it's settled fast","then":"He takes it. No receipt, and the app shows the same dues."},{"text":"Refuse to repay anything, ever","then":"The genuine loan sits unpaid and adds to your worry."}],"why":"Free advice keeps repayment fair and on record, while the harassment stays theirs to answer for."}],"debrief":"Loan-app contact-shaming is harassment, not collection. Save proof and report it. It's never your fault.","relearn":"Loan-app contact threats are harassment; save proof and report to 1930."},
  {"id":"kr-1013","cat":"cyber-and-data","type":"branch","persona":"any","source":"lottery scam","hook":"An email says you've won ₹25 lakh in a lucky draw and asks for a ₹1,500 'processing tax'.","steps":[{"prompt":"You never entered any lucky draw. What do you do?","options":[{"text":"Send the ₹1,500 to claim the prize","then":"A reply thanks you and asks for a ₹5,000 'transfer fee'."},{"text":"Ask them to take the tax out of the prize","then":"They insist it's paid first, and now know your email is active."},{"text":"Delete it. You can't win a draw you never entered","then":"It's gone. Your details and money stay with you.","best":true},{"text":"Share only your account number, never the PIN itself","then":"They send a 'verification' link asking for more."}],"why":"A prize for a draw you never entered, with a fee upfront, is always a scam."},{"prompt":"Next day, a WhatsApp call from the 'prize office' says the offer ends in an hour. What do you do?","options":[{"text":"Decline the call and block the number","then":"The calls from that number stop.","best":true},{"text":"Answer and hear them out, just in case","then":"A smooth voice explains the 'fee' again, very convincingly."},{"text":"Ask them to email an official letter first","then":"A letter arrives in minutes, with a stamp and a signature."},{"text":"Pay quickly before the hour runs out","then":"The money goes, and no prize ever comes."}],"why":"Urgency is a pressure trick, and documents from a scammer prove nothing."},{"prompt":"Your aunt excitedly forwards the same message to the family group. What do you do?","options":[{"text":"Reply in the group that it's a scam, and why","then":"Your aunt sends a sheepish emoji. Two cousins thank you.","best":true},{"text":"Say nothing. It's not your business","then":"Your uncle asks her how to pay the fee."},{"text":"Message your aunt privately, and leave the group be","then":"She deletes it, but a cousin has already replied 'interested'."},{"text":"Tease her in the group for falling for such a thing","then":"She goes quiet in the group, embarrassed."}],"why":"A kind, clear warning where everyone saw the message protects the whole family."}],"debrief":"A win for a lottery you never entered, plus an upfront fee, is always a scam.","relearn":"No real prize asks for a fee or your bank details first; delete it."},
  {"id":"kr-1014","cat":"cyber-and-data","type":"branch","persona":"any","source":"data breach","hook":"A site you shopped on had a data breach, and your email and phone number leaked.","steps":[{"prompt":"You used the same password there as for your email. What do you do?","options":[{"text":"Do nothing. The leak has already happened","then":"The leaked password still opens your email."},{"text":"Change that password everywhere you reused it","then":"It takes twenty minutes. The leaked password now opens nothing.","best":true},{"text":"Change it only on the shopping site","then":"The site is safe, but your email still uses the leaked password."},{"text":"Delete your account on that site, and then relax","then":"The account is gone. The same password still guards your email."}],"why":"A leaked password is only dangerous where it's still in use, so change it everywhere."},{"prompt":"A week later, an email 'from the site' offers a breach refund if you log in. What do you do?","options":[{"text":"Don't click. Open the site yourself to check","then":"The real site has no such refund.","best":true},{"text":"Click and log in quickly to claim the refund","then":"The page takes your password, then shows an error."},{"text":"Click the link to look around, but don't log in","then":"The page starts a download that you almost open."},{"text":"Reply to the email asking if the refund is real","then":"A reply comes: \"Yes, click fast before it expires.\""}],"why":"After a breach, expect targeted phishing, and check on the real site yourself."},{"prompt":"Your flatmate shopped there too and shrugs that nothing can be done now. What do you say?","options":[{"text":"Change reused passwords and watch for fake emails","then":"He opens his email settings. \"Okay, show me.\"","best":true},{"text":"You're right. Nothing can be done about it now","then":"He shrugs, and his old password stays everywhere."},{"text":"Just change your email password, nothing else","then":"He changes one, but keeps the old one on four other sites."},{"text":"Stop shopping online completely from now on","then":"He laughs. \"Not happening.\""}],"why":"Two simple steps limit the harm of a breach, so there's plenty that can be done."}],"debrief":"After a breach, reset reused passwords and expect targeted phishing for a while.","relearn":"After a breach, change reused passwords and watch for phishing."},
  {"id":"kr-1015","cat":"cyber-and-data","type":"branch","persona":"any","source":"investment scam","hook":"On a video call, an 'investment mentor' promises to double your money in a week.","steps":[{"prompt":"He shows other students' profit screenshots and asks you to start with ₹5,000. What do you do?","options":[{"text":"Start small to test if it's real","then":"You send ₹5,000, and 'profits' appear that you can't withdraw."},{"text":"Ask him for his registration details first","then":"He sends an official-looking certificate within seconds."},{"text":"Walk away. Guaranteed doubling means a scam","then":"You leave the call. The group keeps pinging you.","best":true},{"text":"Put in your savings. The screenshots look real","then":"Your savings go in, and the dashboard glows green."}],"why":"No genuine investment guarantees fast doubling, so the promise itself is the warning."},{"prompt":"The group's admin messages: \"Only three seats left. Pay today.\" What do you do?","options":[{"text":"Pay today so you don't miss out","then":"You pay, and the 'seat' leads to a request for more."},{"text":"Stay in the group to watch, without paying","then":"Others post big 'profits', and your resolve wobbles."},{"text":"Ask others in the group if it's real","then":"Every reply says yes. Some may be the scammers."},{"text":"Exit the group and block the admin","then":"The messages stop, and the pressure goes with them.","best":true}],"why":"Leaving removes the pressure, and a scam's own group can't vouch for it."},{"prompt":"Your friend Yash says he put in ₹20,000 and can't withdraw it. What do you do?","options":[{"text":"Tell him to pay the fee to unlock it","then":"He pays a 'release fee'. The balance stays locked."},{"text":"Tell him to wait a week. It might unlock","then":"A week later, the app has vanished."},{"text":"Help him report it on 1930 now","then":"He calls 1930 with his transaction details.","best":true},{"text":"Tell him he was greedy and deserves it","then":"Yash goes quiet and stops answering you."}],"why":"Reporting fast to 1930 gives the best chance, and he isn't to blame for being fooled."},{"prompt":"Your college WhatsApp group is buzzing about the same 'mentor'. What do you post?","options":[{"text":"It's a scam. If you've paid, call 1930","then":"A few people reply with thanks, and one asks for the number again.","best":true},{"text":"Nothing. People should learn for themselves","then":"Two classmates join the mentor's group that night."},{"text":"Say it's risky, without saying it's a scam","then":"People read 'risky' and decide to try small amounts."},{"text":"Post the mentor's number and insult him","then":"The post turns into a fight, and the warning gets lost."}],"why":"A clear warning with the report route protects classmates before they pay."}],"debrief":"No genuine investment guarantees fast doubling. That promise is the warning sign.","relearn":"Guaranteed quick-double returns are a scam; don't deposit anything."},
  {"id":"kr-1016","cat":"cyber-and-data","type":"spot","hook":"Lensy: spot the two red flags in this 'bank' call.","scene":[{"id":"a","text":"\"Don't visit the branch, I'll fix it on the phone now.\"","trick":true},{"id":"b","text":"\"Share the OTP I just sent to verify it's you.\"","trick":true},{"id":"c","text":"The bank's real number is on the back of your card","trick":false},{"id":"d","text":"You can hang up and call the bank yourself","trick":false},{"id":"e","text":"A bank never needs your OTP or PIN to help you","trick":false}],"why":"Rushing you off the branch and asking for an OTP are the scam moves; real banks never need your OTP.","relearn":"Real banks never ask for your OTP or rush you off the branch.","persona":"any","source":"bank call flags"},
  {"id":"kr-1017","cat":"cyber-and-data","type":"spot","hook":"Lensy: spot the two red flags in this 'job offer' message.","scene":[{"id":"a","text":"\"Pay a 2000 registration fee to lock your seat.\"","trick":true},{"id":"b","text":"\"Send your Aadhaar photo and bank login to onboard.\"","trick":true},{"id":"c","text":"A real offer letter states your pay, hours and role","trick":false},{"id":"d","text":"You can verify the company first","trick":false},{"id":"e","text":"Genuine employers pay you, not the reverse","trick":false}],"why":"The upfront fee and the bank-login demand are the scam moves; real jobs pay you.","relearn":"Real jobs don't charge a fee or need your bank login to hire you.","persona":"Meena","source":"job offer flags"},
  {"id":"kr-1018","cat":"cyber-and-data","type":"spot","hook":"Lensy: spot the two red flags in this 'KYC update' SMS.","scene":[{"id":"a","text":"\"Click this link in 2 hours or your account is blocked.\"","trick":true},{"id":"b","text":"\"Enter your card number and PIN to re-verify.\"","trick":true},{"id":"c","text":"Your bank handles KYC in its app or branch","trick":false},{"id":"d","text":"You can ignore the link and call the bank","trick":false},{"id":"e","text":"A bank never needs your PIN for KYC","trick":false}],"why":"The panic deadline and the PIN demand are the phishing moves; real KYC needs no PIN.","relearn":"KYC-update SMS links that demand your PIN are phishing; ignore them.","persona":"any","source":"kyc flags"},
  {"id":"kr-1019","cat":"cyber-and-data","type":"spot","hook":"Lensy: spot the two red flags in this app's sign-up screen.","scene":[{"id":"a","text":"A torch app demands access to your contacts and SMS","trick":true},{"id":"b","text":"\"Allow all permissions or you can't continue.\"","trick":true},{"id":"c","text":"You can deny permissions an app doesn't truly need","trick":false},{"id":"d","text":"The app lists why it wants each permission","trick":false},{"id":"e","text":"Your consent over your data is yours to give","trick":false}],"why":"Demanding needless data and forcing 'allow all' are the flags; you can deny what isn't needed.","relearn":"An app forcing needless permissions is a flag; deny what it doesn't need.","persona":"any","source":"permission flags"},
  {"id":"kr-1020","cat":"cyber-and-data","type":"spot","hook":"Lensy: spot the two red flags in this blackmail chat.","scene":[{"id":"a","text":"\"Pay by tonight or I send the photos to your family.\"","trick":true},{"id":"b","text":"\"Delete our chats so there's no proof.\"","trick":true},{"id":"c","text":"Saving screenshots helps a report","trick":false},{"id":"d","text":"You can report this to 1930","trick":false},{"id":"e","text":"The crime is on the blackmailer, never you","trick":false}],"why":"The pay-or-leak threat and 'delete the proof' are the abuser's moves; save evidence and report.","relearn":"Blackmail threats and 'delete the proof' are flags; save evidence and report.","persona":"any","source":"blackmail flags"},
  {"id":"kr-1021","cat":"cyber-and-data","type":"spot","hook":"Lensy: spot the two red flags in this 'refund' message.","scene":[{"id":"a","text":"\"Enter your UPI PIN to receive your refund.\"","trick":true},{"id":"b","text":"\"Install this remote-screen app so I can help.\"","trick":true},{"id":"c","text":"You never enter a PIN to receive money","trick":false},{"id":"d","text":"A real refund lands with no approval","trick":false},{"id":"e","text":"You can check the order in the app","trick":false}],"why":"A PIN-to-receive request and a remote-control app are the scam moves; receiving needs no PIN.","relearn":"You never enter a PIN to receive money, and never install a stranger's app.","persona":"any","source":"refund flags"},
  {"id":"kr-1022","cat":"cyber-and-data","type":"spot","hook":"Lensy: spot the two red flags in this 'electricity bill' SMS.","scene":[{"id":"a","text":"\"Power cut tonight unless you pay on this link.\"","trick":true},{"id":"b","text":"\"Call this personal number to update your meter.\"","trick":true},{"id":"c","text":"You can check dues in the board's app","trick":false},{"id":"d","text":"Real boards don't threaten an instant cut","trick":false},{"id":"e","text":"A personal number isn't an official line","trick":false}],"why":"The instant-cut threat and the personal-number 'helpline' are the scam moves; verify officially.","relearn":"Threats of an instant power cut by SMS link are a scam; verify officially.","persona":"any","source":"bill scam flags"},
  {"id":"kr-1023","cat":"cyber-and-data","type":"spot","hook":"Lensy: spot the two red flags in this stranger's friend request.","scene":[{"id":"a","text":"\"Send a private photo to prove you trust me.\"","trick":true},{"id":"b","text":"\"Move to a secret app, don't tell anyone.\"","trick":true},{"id":"c","text":"You can keep private photos private","trick":false},{"id":"d","text":"You can block and report a pushy stranger","trick":false},{"id":"e","text":"Real trust never demands a photo as a test","trick":false}],"why":"Pressuring for a private photo and pushing to a secret app are grooming moves; block and report.","relearn":"Pressure for private photos or secrecy is a flag; you can block and report.","persona":"any","source":"grooming flags"},
  {"id":"kr-1052","cat":"cyber-and-data","type":"match","hook":"Match each online harm to its first right move (India).","pairs":[{"left":"Money sent to a fraud UPI ID","right":"Report fast to 1930"},{"left":"Private images being shared","right":"Save proof, report at cybercrime.gov.in"},{"left":"Social account hacked","right":"Reset password, add two-step login"},{"left":"App misusing your data","right":"Exercise your DPDP Act rights"},{"left":"A child unsafe online","right":"Call Childline 1098"}],"relearn":"Fraud to 1930, image abuse to cybercrime.gov.in, hacks reset, data to DPDP, a child to 1098.","persona":"any","source":"harm to move"},
  {"id":"kr-1024","cat":"cyber-and-data","type":"match","hook":"Match each scam to the tell that gives it away.","pairs":[{"left":"\"Share the OTP to verify you\"","right":"A bank never needs your OTP"},{"left":"\"Pay a fee to start the job\"","right":"Real jobs pay you, not the reverse"},{"left":"\"Enter your PIN to get a refund\"","right":"Receiving money never needs a PIN"},{"left":"\"You won a prize, pay the tax\"","right":"No real prize charges a fee first"},{"left":"\"Doubling guaranteed in a week\"","right":"Guaranteed fast returns aren't real"}],"relearn":"Each tell is the giveaway: no OTP, no fee to be hired, no PIN to receive, no fee for a prize.","persona":"any","source":"scam tells"},
  {"id":"kr-1025","cat":"cyber-and-data","type":"match","hook":"Match each safe habit to what it protects you from.","pairs":[{"left":"Two-step login","right":"A stolen password alone getting in"},{"left":"A unique password per site","right":"One breach unlocking everything"},{"left":"Banking on mobile data","right":"Snooping on open Wi-Fi"},{"left":"Denying needless permissions","right":"Apps over-collecting your data"},{"left":"Checking links in the app","right":"Phishing pages that steal logins"}],"relearn":"Each habit blocks a real risk: stolen passwords, breaches, snooping, over-collection, phishing.","persona":"any","source":"habits protect"},
  {"id":"kr-1026","cat":"cyber-and-data","type":"match","hook":"Match each helpline or route to what it's for (India).","pairs":[{"left":"Cyber fraud or online harm","right":"1930 or cybercrime.gov.in"},{"left":"A woman in distress","right":"181 or 1091"},{"left":"Any life-threatening emergency","right":"Emergency 112"},{"left":"A child at risk","right":"Childline 1098"},{"left":"Free legal aid to follow up","right":"NALSA 15100"}],"relearn":"Cyber harm to 1930, a woman to 181 or 1091, emergency 112, a child 1098, legal aid 15100.","persona":"Farhan","source":"route card"},
  {"id":"kr-1027","cat":"cyber-and-data","type":"match","hook":"Match each privacy setting to what it does for you.","pairs":[{"left":"Private account","right":"Only approved people see your posts"},{"left":"Location off in photos","right":"Pictures don't reveal where you are"},{"left":"Reviewing tagged posts","right":"You choose what links to your name"},{"left":"Blocking and reporting","right":"You cut off someone harassing you"},{"left":"Clearing old saved logins","right":"A lost phone can't open your accounts"}],"relearn":"Privacy tools give you control: who sees you, where you are, what links to you, and who can reach you.","persona":"any","source":"privacy settings"},
  {"id":"kr-1028","cat":"cyber-and-data","type":"match","hook":"Match each myth to the truth that replaces it.","pairs":[{"left":"\"Nothing online can be reported\"","right":"cybercrime.gov.in and 1930 exist"},{"left":"\"A shared image is your fault\"","right":"The crime is on whoever shared it"},{"left":"\"My data belongs to the app\"","right":"Under DPDP your data stays yours"},{"left":"\"Scammed money can't return\"","right":"Fast reporting can help freeze it"},{"left":"\"Trust means sharing passwords\"","right":"Privacy and trust can coexist"}],"relearn":"Each myth has a true reply: it's reportable, not your fault, your data, recoverable, private.","persona":"any","source":"myth to truth"},
  {"id":"kr-1029","cat":"cyber-and-data","type":"match","hook":"Match each phishing lure to the calm check that defuses it.","pairs":[{"left":"\"Act in 2 hours or lose access\"","right":"Real services don't rush you"},{"left":"\"Click here to fix your KYC\"","right":"Do KYC only in the bank's app"},{"left":"\"Confirm card details to go on\"","right":"Never type card details in a link"},{"left":"\"Suspicious login, verify now\"","right":"Open the app, not the link"},{"left":"\"Download this support tool\"","right":"Never install a stranger's app"}],"relearn":"Slow down, ignore the link, open the official app; urgency is the lure, not a warning.","persona":"any","source":"phishing checks"},
  {"id":"kr-1030","cat":"cyber-and-data","type":"sort","hook":"Sort each move after a scam call: protects you, or a scam tactic?","items":[{"id":"a","text":"Hanging up and calling the number on your card"},{"id":"b","text":"Reading out the OTP they 'need to verify'"},{"id":"c","text":"Saving a screenshot of the caller's number"},{"id":"d","text":"Installing the screen-share app they sent"},{"id":"e","text":"Reporting the number to 1930"},{"id":"f","text":"Letting them rush you into deciding now"}],"bins":[{"id":"safe","label":"Protects you","valence":"pos"},{"id":"trap","label":"Scam tactic","valence":"neg"}],"key":{"a":"safe","b":"trap","c":"safe","d":"trap","e":"safe","f":"trap"},"relearn":"Hang up, save proof and report; never share an OTP, install their app, or let them rush you.","persona":"any","source":"scam call sort"},
  {"id":"kr-1031","cat":"cyber-and-data","type":"sort","hook":"Sort each password habit: keeps you safe, or leaves you exposed?","items":[{"id":"a","text":"A different password for each account"},{"id":"b","text":"Reusing one password everywhere"},{"id":"c","text":"Turning on two-step login"},{"id":"d","text":"Saving passwords in a plain notes file"},{"id":"e","text":"Using a long passphrase"},{"id":"f","text":"Telling a 'support' caller your password"}],"bins":[{"id":"safe","label":"Keeps you safe","valence":"pos"},{"id":"weak","label":"Leaves you exposed","valence":"neg"}],"key":{"a":"safe","b":"weak","c":"safe","d":"weak","e":"safe","f":"weak"},"relearn":"Unique passwords, two-step login and a long passphrase help; reuse, plain files and sharing don't.","persona":"any","source":"password sort"},
  {"id":"kr-1032","cat":"cyber-and-data","type":"sort","hook":"Sort each link or message: safe to open, or a phishing risk?","items":[{"id":"a","text":"An order update you open inside the app"},{"id":"b","text":"A 'KYC link' from an unknown SMS"},{"id":"c","text":"A statement you reach via the bank's app"},{"id":"d","text":"A 'free recharge' link a friend forwarded"},{"id":"e","text":"A 'parcel fee' link to pay a stranger"},{"id":"f","text":"A login page you reached by typing the site yourself"}],"bins":[{"id":"safe","label":"Safe to open","valence":"pos"},{"id":"phish","label":"Phishing risk","valence":"neg"}],"key":{"a":"safe","b":"phish","c":"safe","d":"phish","e":"phish","f":"safe"},"relearn":"Reach accounts through the official app or by typing the site; treat surprise SMS and forwards as risk.","persona":"any","source":"link sort"},
  {"id":"kr-1033","cat":"cyber-and-data","type":"sort","hook":"Sort each statement about your data rights: true, or a myth?","items":[{"id":"a","text":"Under DPDP your consent matters"},{"id":"b","text":"You can ask what data is held about you"},{"id":"c","text":"Apps own your data once you sign up"},{"id":"d","text":"You can deny needless permissions"},{"id":"e","text":"You have no say over your own data"},{"id":"f","text":"You can ask for wrong data to be corrected"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"myth","label":"Myth","valence":"neg"}],"key":{"a":"true","b":"true","c":"myth","d":"true","e":"myth","f":"true"},"relearn":"Your consent matters, you can see, correct and limit your data; 'apps own it, you have no say' is a myth.","persona":"any","source":"data rights sort"},
  {"id":"kr-1034","cat":"cyber-and-data","type":"sort","hook":"Sort each step after private images leak: helps, or makes it worse?","items":[{"id":"a","text":"Saving evidence before anything else"},{"id":"b","text":"Blaming yourself and staying silent"},{"id":"c","text":"Reporting at cybercrime.gov.in"},{"id":"d","text":"Asking the platform to take it down"},{"id":"e","text":"Paying whoever is threatening you"},{"id":"f","text":"Telling someone you trust for support"}],"bins":[{"id":"helps","label":"Helps","valence":"pos"},{"id":"worse","label":"Makes it worse","valence":"neg"}],"key":{"a":"helps","b":"worse","c":"helps","d":"helps","e":"worse","f":"helps"},"relearn":"Save proof, report, ask for take-down and lean on support; self-blame and paying only help the abuser.","persona":"Aarti","source":"image leak sort"},
  {"id":"kr-1035","cat":"cyber-and-data","type":"sort","hook":"Sort each claim about reporting cyber harm: true, or false?","items":[{"id":"a","text":"You can report for free at cybercrime.gov.in"},{"id":"b","text":"You need a lawyer just to file a report"},{"id":"c","text":"Helpline 1930 takes cyber-fraud reports"},{"id":"d","text":"Reporting is pointless once money is gone"},{"id":"e","text":"Fast reporting can help freeze a transfer"},{"id":"f","text":"Only rich people can report cyber crime"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"false","label":"False","valence":"neg"}],"key":{"a":"true","b":"false","c":"true","d":"false","e":"true","f":"false"},"relearn":"Anyone can report free at cybercrime.gov.in or 1930, and fast reporting helps; the rest are myths.","persona":"any","source":"reporting sort"},
  {"id":"kr-1036","cat":"cyber-and-data","type":"sort","hook":"Sort each habit: protects your privacy, or over-shares?","items":[{"id":"a","text":"Keeping your account private"},{"id":"b","text":"Posting your live location all day"},{"id":"c","text":"Reviewing what others tag you in"},{"id":"d","text":"Sharing your OTP 'just this once'"},{"id":"e","text":"Turning off location data in photos"},{"id":"f","text":"Putting your full address in your bio"}],"bins":[{"id":"private","label":"Protects privacy","valence":"pos"},{"id":"overshare","label":"Over-shares","valence":"neg"}],"key":{"a":"private","b":"overshare","c":"private","d":"overshare","e":"private","f":"overshare"},"relearn":"Private accounts, tag review and stripped location protect you; live location, OTPs and addresses don't.","persona":"any","source":"privacy habit sort"},
  {"id":"kr-1037","cat":"cyber-and-data","type":"role-play","persona":"any","source":"shame to report","hook":"Your friend Aakash lost ₹8,000 to a fake 'part-time task' job online.","setup":"He tells you in a low voice at the canteen.","steps":[{"prompt":"Aakash says: \"I'm so stupid. I can't tell anyone else.\"","options":[{"text":"\"You should've known better. Just forget about it.\"","then":"He shrinks into his chair. \"Yeah. I know.\""},{"text":"\"This happens to careful people. Let's call 1930 now.\"","then":"He looks up. \"Is that the cyber fraud number?\"","best":true},{"text":"\"I won't tell anyone. Let's just move on.\"","then":"He nods, relieved, and the money stays gone."},{"text":"\"How did you fall for something so obvious?\"","then":"His face goes red. \"It didn't feel obvious then.\""}],"why":"Taking the shame off him makes fast reporting possible, and speed matters."},{"prompt":"Later, Aakash finds that 1930 takes fraud reports, and asks: \"Won't they think I'm an idiot?\"","options":[{"text":"\"They hear this daily. What matters is speed.\"","then":"He picks up his phone. \"Okay. Stay while I call.\"","best":true},{"text":"\"Maybe. That's why it's better not to call.\"","then":"He puts the phone away. \"Right.\""},{"text":"\"Then let me call and pretend it was me instead.\"","then":"\"But it's my account and my money,\" he says."},{"text":"\"Who cares what they think? Just call.\"","then":"\"I care,\" he mutters, not moving."}],"why":"Online fraud is common and reportable, so there's nothing to be ashamed of."},{"prompt":"That evening, Aakash says: \"My cousin lost money the same way, but she's too embarrassed to say.\"","options":[{"text":"\"Tell her about 1930, and that it's not her fault.\"","then":"\"I'll call her tonight,\" he says.","best":true},{"text":"\"Leave her alone. Some things are better kept quiet.\"","then":"He nods slowly. \"I guess she'd prefer that.\""},{"text":"\"Report it for her without telling her.\"","then":"He frowns. \"I don't even have her details.\""},{"text":"\"Two in one family? That's embarrassing.\"","then":"He winces. \"Thanks. That helps a lot.\""}],"why":"Passing on the route without blame lets others report fast too."}],"relearn":"Online fraud is reportable; reassure a friend and help them call 1930 fast."},
  {"id":"kr-1038","cat":"cyber-and-data","type":"role-play","persona":"any","source":"blackmail support","hook":"Your friend Ishaan is being blackmailed over private photos and wants to just pay.","setup":"He calls you late at night, voice shaking.","steps":[{"prompt":"Ishaan says: \"They want ₹10,000. If I pay, it ends, right?\"","options":[{"text":"\"Paying rarely ends it. Let's save the messages first.\"","then":"He's quiet, then: \"Okay. I'll screenshot everything.\"","best":true},{"text":"\"Maybe just pay them, so it all goes away quietly tonight.\"","then":"\"I'll transfer it tonight,\" he says, sounding unsure."},{"text":"\"Block them right now, and delete the whole chat too.\"","then":"\"Done,\" he says. \"But now I can't see what they said.\""},{"text":"\"Why did you send those photos at all?\"","then":"The line goes silent. \"I don't know,\" he whispers."}],"why":"Paying rarely stops blackmail, and saved messages are the proof a report needs."},{"prompt":"Ishaan says: \"I feel so stupid. This is my fault.\"","options":[{"text":"\"It's not your fault. The crime is theirs.\"","then":"He exhales shakily. \"Nobody's said that to me.\"","best":true},{"text":"\"Well, you did trust a stranger.\"","then":"\"I know,\" he says, and his voice cracks."},{"text":"\"Let's not talk about fault. What's done is done.\"","then":"\"So it is my fault,\" he says quietly."},{"text":"\"Don't worry. I'll sort them out for you myself.\"","then":"\"How?\" he asks. \"You don't even know who they are.\""}],"why":"Blackmail is always the blackmailer's crime, never the fault of the person targeted."},{"prompt":"Ishaan asks: \"Where could I report this without everyone finding out?\"","options":[{"text":"\"You can't report it without the whole world knowing.\"","then":"\"Then I won't,\" he says flatly."},{"text":"\"Tell your parents first. They'll know how to handle it.\"","then":"\"I'm not ready for that,\" he says, panicking."},{"text":"\"1930 or cybercrime.gov.in. I'll sit with you.\"","then":"\"Tomorrow morning?\" he asks. \"Before I lose my nerve.\"","best":true},{"text":"\"Report it to the app. That's enough.\"","then":"\"And if they just make a new account?\" he asks."}],"why":"The cybercrime route is built for this, and your support makes it easier to use."},{"prompt":"Next day, Ishaan says: \"They sent a new message. 'Last warning.'\"","options":[{"text":"\"Maybe now you should just pay.\"","then":"\"So I give in after all?\" he asks, confused."},{"text":"\"Reply that you've already gone to the police.\"","then":"\"They'll just get angrier,\" he says, scared."},{"text":"\"Screenshot it for 1930. You're not alone.\"","then":"He sends you the screenshot. \"Okay. Saved.\"","best":true},{"text":"\"Ignore it. They're probably bluffing by now anyway.\"","then":"\"And if they're not?\" he asks."}],"why":"Each new threat is more evidence, and steady support helps him keep going."}],"relearn":"Don't pay blackmailers; preserve evidence and report to 1930 or cybercrime.gov.in."},
  {"id":"kr-1039","cat":"cyber-and-data","type":"role-play","persona":"any","source":"otp refusal","hook":"A caller says he's from your bank's fraud team.","setup":"Your phone buzzes with an OTP while he talks.","steps":[{"prompt":"The caller says: \"Read me that OTP now, or your account gets frozen.\"","options":[{"text":"\"Okay, one second. Let me find it.\"","then":"\"Quickly, please,\" he says. \"Time is running out.\""},{"text":"\"No bank needs my OTP. I'm hanging up now.\"","then":"\"Wait, wait!\" You end the call. He rings straight back.","best":true},{"text":"\"First tell me my account number.\"","then":"He reads out the last four digits. \"Now the OTP.\""},{"text":"\"Why is it being frozen? What did I do?\"","then":"\"Suspicious activity. Only the OTP can stop it.\""}],"why":"A real bank never asks for your OTP, so refusing and hanging up is safe."},{"prompt":"The caller insists: \"I'm trying to help you. You'll lose all your money.\"","options":[{"text":"\"Please don't let that happen. Here's the code.\"","then":"\"Go on,\" he says. A debit alert buzzes a minute later."},{"text":"\"Can you email me from the bank first?\"","then":"\"Sending now,\" he says. A lookalike email arrives."},{"text":"\"I'm recording this call, you know.\"","then":"\"Then record this: read the OTP.\""},{"text":"\"I'll call the number on my card myself.\"","then":"\"That line is busy today,\" he says quickly.","best":true}],"why":"Calling the number on your card reaches the real bank, whatever the caller says."},{"prompt":"Your flatmate Tanya asks: \"Who was that? You look rattled.\"","options":[{"text":"\"Just the bank. They're sorting out a problem.\"","then":"\"Banks call about problems now?\" she asks, frowning."},{"text":"\"A scam call. I'll check with my bank and report it.\"","then":"She nods. \"Use the card number, not his.\"","best":true},{"text":"\"A scammer, but I hung up on him, so it's all done.\"","then":"\"Did you check with the bank, though?\" she asks."},{"text":"\"Nobody. Forget it.\"","then":"She shrugs, and you stay unsure about your account."}],"why":"Checking with the real bank and reporting closes the loop after a scam call."}],"relearn":"A bank never asks for your OTP; refuse and hang up."},
  {"id":"kr-1040","cat":"cyber-and-data","type":"role-play","persona":"any","source":"private photo no","hook":"Your cousin Riya, 19, wants to send a private photo to a guy she met online.","setup":"She shows you his message on her phone.","steps":[{"prompt":"Riya says: \"He says if I trust him, I'll send it. It's just a test.\"","options":[{"text":"\"If he asked nicely, maybe one is fine.\"","then":"She starts scrolling for a picture, then pauses, unsure."},{"text":"\"Wait a few weeks. If he's still around, then send it.\"","then":"\"A few weeks? He wants it tonight,\" she says."},{"text":"\"You don't owe anyone a photo. Trust isn't a test.\"","then":"She frowns. \"But he'll think I don't like him.\"","best":true},{"text":"\"Are you mad? What will people say?\"","then":"She pulls the phone away. \"Forget I told you.\""}],"why":"No one owes a private photo, and real trust never makes it a test."},{"prompt":"A new message pops up. Riya says: \"He says everyone does this, and I'm being old-fashioned.\"","options":[{"text":"\"He's right. Everyone does it now.\"","then":"She nods slowly, thumb over the send button."},{"text":"\"Send one with your face hidden. Then it's totally safe.\"","then":"She hesitates. \"But he'd still have it. He could share it anywhere.\""},{"text":"\"Block him right now, or I'll tell your mother.\"","then":"Her face hardens. \"You wouldn't dare.\""},{"text":"\"Saying no isn't old-fashioned. It's your call.\"","then":"She looks at the screen again, less sure of him.","best":true}],"why":"Pressure to prove something is a warning, and the choice stays hers."},{"prompt":"Riya asks: \"What if he gets angry and stops talking to me?\"","options":[{"text":"\"Then send it, so you don't lose him.\"","then":"She sighs. \"I really don't want to lose him.\""},{"text":"\"Make up an excuse, like your phone broke or something.\"","then":"\"And next week, when he asks again?\" she says."},{"text":"\"Then he's shown you who he is. You'd be okay.\"","then":"She's quiet for a while. \"Yeah. Maybe I would.\"","best":true},{"text":"\"Good riddance. He's obviously some kind of creep.\"","then":"\"You don't even know him,\" she snaps."}],"why":"Someone who sulks at a no was testing control, not trust."},{"prompt":"A week later, Riya says: \"He's pressuring me again, and it's scaring me.\"","options":[{"text":"\"Maybe just send one, so he finally leaves you alone for good.\"","then":"She goes pale. \"That's what I'm afraid of.\""},{"text":"\"Just block him, and don't tell anyone about it.\"","then":"\"So if he finds me on a new account, I'm on my own?\" she asks."},{"text":"\"It's not your fault. Want to save it and report it together?\"","then":"She nods, relieved. \"Yes. Can we do it tonight?\"","best":true},{"text":"\"Why are you even still talking to him?\"","then":"She looks down. \"I thought it would stop.\""}],"why":"Pressure for images can be reported on 1930 or cybercrime.gov.in, and it's never her fault."}],"relearn":"Private images can be misused; you have every right to say no to a 'trust test'."},
  {"id":"kr-1041","cat":"cyber-and-data","type":"role-play","persona":"any","source":"forward refusal","hook":"Your uncle keeps forwarding 'win ₹5,000' links to the family group and urging you to click.","setup":"At Sunday lunch, he waves his phone at you.","steps":[{"prompt":"Your uncle says: \"Just click it! My friend already got his money.\"","options":[{"text":"\"Fine, I'll click it so you stop sending them.\"","then":"The page asks for your UPI PIN to 'receive' the money."},{"text":"\"Okay, Mamaji, I'll look at it later.\"","then":"He beams, and forwards two more that evening."},{"text":"\"Only fools fall for these, Mamaji.\"","then":"His face falls, and the table goes quiet."},{"text":"\"I don't open prize links. They steal your logins.\"","then":"He waves a hand. \"You young people worry too much.\"","best":true}],"why":"Declining calmly, with the reason, protects you without a fight."},{"prompt":"Your uncle says: \"My friend showed me a screenshot. He really got paid!\"","options":[{"text":"\"Maybe he did get it. I don't really know, Mamaji.\"","then":"\"See?\" he says, pleased, and forwards another."},{"text":"\"Receiving money never needs a PIN. That's the trick.\"","then":"He pauses. \"A PIN to receive? That is strange.\"","best":true},{"text":"\"Ask him to show you the money in his bank account.\"","then":"\"He won't show me his bank account,\" your uncle scoffs."},{"text":"\"Your friend must be lying to you.\"","then":"\"Don't insult my friend,\" he says stiffly."}],"why":"Naming the trick, a PIN to receive money, lets him see the scam for himself."},{"prompt":"Later, your uncle asks: \"Your Mami's sister lost money on one of these. Should I stop forwarding them?\"","options":[{"text":"\"Yes. Let's warn the group these are scams.\"","then":"He hands you his phone. \"You type it. I'll send.\"","best":true},{"text":"\"Just forward the ones that look genuine.\"","then":"He forwards a 'free recharge' link that evening."},{"text":"\"Just stop sending them to me.\"","then":"He shrugs. The rest of the family still gets them."},{"text":"\"Leave the group. It's full of junk anyway.\"","then":"\"And miss the wedding photos?\" he laughs."}],"why":"A warning in the group stops the link spreading to others who might click."}],"relearn":"Forwarded reward-bait links are scams; you can decline without guilt."},
  {"id":"kr-1042","cat":"cyber-and-data","type":"role-play","persona":"Meena","source":"loan app stand","hook":"You owe a loan app ₹4,000, and its agent is on the phone threatening you.","setup":"You've already had three calls from different numbers today.","steps":[{"prompt":"The agent says: \"Pay ₹6,000 today, or all your contacts hear you're a cheat.\"","options":[{"text":"\"I suppose you're allowed, since I owe money.\"","then":"\"Exactly. So pay today,\" he says."},{"text":"\"I know. It's my fault for borrowing.\"","then":"\"Right. So you'll pay,\" he says, pressing harder."},{"text":"\"That's harassment. I'm saving it and reporting it.\"","then":"\"Report? Go ahead,\" he sneers, but he sounds less sure.","best":true},{"text":"\"My friend says I should just change my phone number.\"","then":"\"We already have all your contacts,\" he says."}],"why":"Contact-shaming is harassment, not collection, and naming it is the first step."},{"prompt":"After the call, your roommate Pooja asks: \"You look shaken. What's wrong?\"","options":[{"text":"\"A loan app is threatening me. Help me report it?\"","then":"She sits down beside you. \"Show me the messages.\"","best":true},{"text":"\"Nothing. I'm just tired.\"","then":"She nods, not convinced, and goes to bed."},{"text":"\"Can you lend me ₹6,000 so I can pay them off tonight?\"","then":"She hesitates. \"I can, but will they stop?\""},{"text":"\"I'm so ashamed. I should never have borrowed at all.\"","then":"\"What happened?\" she asks gently."}],"why":"Telling someone you trust means you aren't alone, and the harassment is never your fault."},{"prompt":"The agent texts: \"Last chance. Your contacts get messages in one hour.\"","options":[{"text":"\"Sorry. I know I deserve this.\"","then":"\"Then pay,\" comes the reply."},{"text":"\"This is saved, and it's going to 1930.\"","then":"No reply for a while. Then: \"We'll see.\"","best":true},{"text":"\"My cousin says you're allowed to do this.\"","then":"\"He's right. Pay now.\""},{"text":"\"I'm changing my number, so it won't matter.\"","then":"\"Your contacts don't change,\" the reply says."}],"why":"Each threat is evidence for a 1930 report, and the crime is theirs, not yours."}],"relearn":"Contact-shaming is harassment, not collection; save proof and report to 1930."},
  {"id":"kr-1043","cat":"cyber-and-data","type":"role-play","persona":"any","source":"permission stand","hook":"Your friend Kabir is helping you install the college fest's ticket app, which wants every permission.","setup":"He's holding your phone, thumb over 'Allow all'.","steps":[{"prompt":"Kabir says: \"Just allow everything. It won't work otherwise.\"","options":[{"text":"\"Fine, allow everything so it actually works.\"","then":"He taps 'Allow all', and the app opens instantly."},{"text":"\"Allow only what it needs. Keep contacts off.\"","then":"He shrugs and taps 'Deny' twice. \"Let's see.\"","best":true},{"text":"\"Allow all for now. I'll fix it later.\"","then":"\"Sure,\" he says, and later never quite comes."},{"text":"\"Forget it. I'll skip the fest instead.\"","then":"\"Over an app?\" he laughs. \"Come on.\""}],"why":"You can deny permissions an app doesn't need, and it often still works."},{"prompt":"A week later, Kabir says: \"Honestly, I let every app have everything. Nothing's ever happened to me.\"","options":[{"text":"\"True. Nothing bad has happened to you.\"","then":"He grins. \"Told you.\""},{"text":"\"Maybe you're right. It's probably all fine.\"","then":"\"Totally,\" he says, and the moment passes."},{"text":"\"It's my data. I choose what it gets.\"","then":"He thinks. \"Huh. I never checked mine.\"","best":true},{"text":"\"You're careless. That's your problem.\"","then":"He frowns. \"Relax. It's just an app.\""}],"why":"Your consent is yours, whatever others choose for their own phones."},{"prompt":"The next day, a spam caller knows Kabir's name and college, and he asks: \"How do I check what my apps can see?\"","options":[{"text":"\"Don't bother. It's too late for your phone now.\"","then":"He shrugs and puts it away."},{"text":"\"Check permissions in settings. Switch off extras.\"","then":"He scrolls and whistles. \"The torch app has my contacts?\"","best":true},{"text":"\"Just delete the apps you don't use, and forget the rest.\"","then":"He deletes two. The rest keep their access."},{"text":"\"Reset your whole phone to be safe.\"","then":"\"And lose all my photos?\" he asks, horrified."}],"why":"Checking permissions app by app keeps control without losing what you use."}],"relearn":"You can deny permissions an app doesn't need; your consent is yours."},
  {"id":"kr-1044","cat":"cyber-and-data","type":"reflect","hook":"Lensy: which online safety habit feels most doable for you to start this week?","prompt":"There's no wrong pick; choose the one you'd actually keep up.","options":["Turn on two-step login somewhere","Make one account private","Stop reusing one password","Save the 1930 number in my phone"],"affirm":"Lensy: any of these makes you harder to scam. Starting small is still starting; your data, your call.","relearn":"One small safety habit at a time makes you harder to scam.","persona":"any","source":"habit reflect"},
  {"id":"kr-1045","cat":"cyber-and-data","type":"reflect","hook":"Lensy: a scam message just made you panic. What helps you slow down?","prompt":"Every answer is valid; notice what steadies you.","options":["Put the phone down for a minute","Tell someone what it said","Open the official app to check","Remember real services don't rush me"],"affirm":"Lensy: urgency is the trick, not the truth. A pause is your best defence; you don't owe a fast reply.","relearn":"Urgency is the scam's trick; a pause is your best defence.","persona":"any","source":"panic reflect"},
  {"id":"kr-1046","cat":"cyber-and-data","type":"reflect","hook":"Lensy: how much of your daily life feels comfortable to keep private online?","prompt":"There's no right amount; it's yours to decide.","options":["My location and address","Who I talk to","My photos","My account being public or not"],"affirm":"Lensy: privacy isn't hiding; it's choosing who gets in. Whatever you keep back is fully your right.","relearn":"Privacy is choosing who gets in; what you keep back is your right.","persona":"any","source":"privacy reflect"},
  {"id":"kr-1047","cat":"cyber-and-data","type":"reflect","hook":"Lensy: if you were scammed, what would help you report instead of staying silent?","prompt":"No answer is wrong; name what would lower the shame.","options":["Knowing it's common","Having the 1930 number ready","A friend doing it with me","Knowing it might recover money"],"affirm":"Lensy: being scammed is not a character flaw; it's a crime done to you. Reporting is strength, not shame.","relearn":"Being scammed is a crime done to you; reporting is strength, not shame.","persona":"any","source":"report reflect"},
  {"id":"kr-1048","cat":"cyber-and-data","type":"reflect","hook":"Lensy: which would make you most willing to help a friend in a cyber mess?","prompt":"Any of these counts; pick what fits you.","options":["Knowing the right helpline","Not judging how it happened","Sitting with them while they report","Reminding them it's not their fault"],"affirm":"Lensy: a calm friend who knows the route changes everything. Showing up matters more than having all the answers.","relearn":"A calm friend who knows the route helps; showing up matters most.","persona":"any","source":"helping reflect"},
  {"id":"kr-1049","cat":"cyber-and-data","type":"reflect","hook":"Lensy: when an app asks for a permission, what would you like to ask yourself first?","prompt":"There's no single right question; choose your default.","options":["Does it really need this?","What could it do with this?","Can I say no and still use it?","Who else gets this data?"],"affirm":"Lensy: pausing on a permission is you owning your data. Every 'no' you mean is a right you're using.","relearn":"Pausing on a permission is owning your data; 'no' is a right.","persona":"any","source":"permission reflect"},
  {"id":"kr-1050","cat":"cyber-and-data","type":"reflect","hook":"Lensy: what would make a 'too good to be true' offer easier for you to walk away from?","prompt":"All of these are fine; pick what would anchor you.","options":["Remembering no prize asks for a fee","Talking it over with someone","Knowing guaranteed returns aren't real","Just not replying at all"],"affirm":"Lensy: if it guarantees fast money, it's bait. Walking away costs you nothing and keeps your savings yours.","relearn":"Guaranteed fast money is bait; walking away keeps your savings safe.","persona":"any","source":"offer reflect"},
  {"id":"kr-1051","cat":"cyber-and-data","type":"reflect","hook":"Lensy: which part of your online life would you most like to feel more in control of?","prompt":"No wrong answer; this is just for you.","options":["My passwords","What I share publicly","The apps on my phone","Knowing where to report harm"],"affirm":"Lensy: control online grows one habit at a time. Wherever you start, the rights and routes are already yours.","relearn":"Control online grows one habit at a time; the rights are already yours.","persona":"any","source":"control reflect"},
  {"id":"kr-1053","cat":"cyber-and-data","type":"match","hook":"Match each data right under DPDP to what it lets you do.","pairs":[{"left":"Right to access","right":"Ask what data is held about you"},{"left":"Right to correction","right":"Get wrong details fixed"},{"left":"Right to erasure","right":"Ask for data no longer needed to go"},{"left":"Right to withdraw consent","right":"Take back a yes you gave before"},{"left":"Right to grievance","right":"Complain if your data is misused"}],"relearn":"Under DPDP you can access, correct, erase, withdraw consent and complain about your data.","persona":"Farhan","source":"dpdp rights"},
  {"id":"kr-1054","cat":"cyber-and-data","type":"sort","hook":"Sort each money move online: safe, or risky?","items":[{"id":"a","text":"Paying through the official app"},{"id":"b","text":"Scanning a stranger's 'collect' QR"},{"id":"c","text":"Checking the payee name before sending"},{"id":"d","text":"Sharing your card CVV on a call"},{"id":"e","text":"Using two-step login on your wallet"},{"id":"f","text":"Approving a request you didn't start"}],"bins":[{"id":"safe","label":"Safe","valence":"pos"},{"id":"risky","label":"Risky","valence":"neg"}],"key":{"a":"safe","b":"risky","c":"safe","d":"risky","e":"safe","f":"risky"},"relearn":"Pay in the official app, check the payee and use two-step login; never scan stranger QRs or share a CVV.","persona":"any","source":"money move sort"},
  {"id":"kr-1080","cat":"harassment-and-posh","type":"strike-rewrite","hook":"\"Only women in big companies are covered by the harassment law.\"","myth":{"un":"Only women in big companies are covered.","re":"The Act covers women everywhere they work, including small shops, homes as workplaces and unorganised work.","why":"It protects women at any workplace, not just large offices."},"relearn":"The harassment law covers women at any workplace, not only big companies.","persona":"Meena","source":"covers everywhere"},
  {"id":"kr-1081","cat":"harassment-and-posh","type":"strike-rewrite","hook":"\"An intern can't complain about harassment.\"","myth":{"un":"An intern can't complain about harassment.","re":"Interns, trainees and contract workers can complain; the law protects them, not only permanent staff.","why":"The Act names interns and contract women too."},"relearn":"Interns and contract workers can complain about harassment; the law protects them too.","persona":"Aarti","source":"interns covered"},
  {"id":"kr-1082","cat":"harassment-and-posh","type":"strike-rewrite","hook":"\"If there were no witnesses, there's no point complaining.\"","myth":{"un":"With no witnesses, there's no point complaining.","re":"A complaint can stand on your own account plus messages, emails and patterns; witnesses are not required.","why":"Your testimony and records are evidence."},"relearn":"You can complain without witnesses; your account plus messages and records are evidence.","persona":"any","source":"no witness needed"},
  {"id":"kr-1083","cat":"harassment-and-posh","type":"strike-rewrite","hook":"\"He's senior, so nothing will happen to him.\"","myth":{"un":"He's senior, so nothing will happen to him.","re":"The complaint process applies to everyone, including bosses and owners; rank does not put anyone above it.","why":"Seniority is not immunity from a harassment complaint."},"relearn":"The complaint process applies to everyone, including seniors and owners; rank is not immunity.","persona":"Aarti","source":"rank no shield"},
  {"id":"kr-1084","cat":"harassment-and-posh","type":"strike-rewrite","hook":"\"Reporting it will just get me labelled a troublemaker and sacked.\"","myth":{"un":"Reporting it gets you labelled and sacked.","re":"Punishing or sacking someone for a good-faith complaint is itself unlawful retaliation, not a normal consequence.","why":"The law forbids reprisal for complaining honestly."},"relearn":"Sacking or punishing you for a good-faith complaint is unlawful retaliation, not normal.","persona":"Meena","source":"retaliation unlawful"},
  {"id":"kr-1085","cat":"harassment-and-posh","type":"strike-rewrite","hook":"\"It was just a joke, so it doesn't count as harassment.\"","myth":{"un":"A 'joke' can't count as harassment.","re":"Unwelcome sexual jokes, comments or gestures can be harassment; what matters is that it's unwelcome, not that it's framed as fun.","why":"Harm isn't erased by calling it a joke."},"relearn":"Unwelcome sexual jokes and comments can be harassment; 'just a joke' doesn't erase it.","persona":"any","source":"a joke counts"},
  {"id":"kr-1086","cat":"harassment-and-posh","type":"strike-rewrite","hook":"\"You have to confront the harasser yourself first before anyone helps.\"","myth":{"un":"You must confront the harasser alone first.","re":"You can go straight to the Internal Committee; confronting the person yourself is never a required first step.","why":"The committee exists so you don't have to face it alone."},"relearn":"You can go straight to the Internal Committee; confronting them alone first is not required.","persona":"any","source":"no solo first"},
  {"id":"kr-1087","cat":"harassment-and-posh","type":"strike-rewrite","hook":"\"A creepy message at midnight isn't a work matter.\"","myth":{"un":"Off-hours messages aren't a work matter.","re":"Unwelcome sexual messages from a colleague or boss can be work harassment even after hours or off the premises.","why":"The work link, not the clock, is what matters."},"relearn":"Unwelcome sexual messages from a colleague count even after hours or off-site.","persona":"any","source":"off-hours counts"},
  {"id":"kr-1088","cat":"harassment-and-posh","type":"strike-rewrite","hook":"\"Quid pro quo, like 'sleep with me for the promotion', is just office politics.\"","myth":{"un":"'Favours for a promotion' is just office politics.","re":"Tying a job, promotion or marks to sexual favours is a clear, named form of harassment, not politics.","why":"Conditioning work on sex is harassment in law."},"relearn":"Tying a job, promotion or marks to sexual favours is harassment, not office politics.","persona":"Aarti","source":"quid pro quo"},
  {"id":"kr-1089","cat":"harassment-and-posh","type":"strike-rewrite","hook":"\"Harassment only happens to women, so men have no route at all.\"","myth":{"un":"Only women face harassment, so men have no route.","re":"Anyone harassed has routes; a man facing sexual harassment can use workplace policy, complaints and the law too.","why":"No one has to just endure harassment at work."},"relearn":"Anyone harassed has a route; men facing harassment can use workplace policy and the law too.","persona":"any","source":"routes for all"},
  {"id":"kr-1090","cat":"harassment-and-posh","type":"match","hook":"Match each part of a harassment complaint to what it does.","pairs":[{"left":"Internal Committee","right":"Hears and inquires into the complaint"},{"left":"Written complaint","right":"Starts the formal process"},{"left":"Dated notes and messages","right":"Build your evidence"},{"left":"Confidentiality rule","right":"Keeps your identity protected"},{"left":"NALSA 15100","right":"Free legal help if you need it"}],"relearn":"A committee, a written complaint, dated evidence, confidentiality and free legal aid each play a role.","persona":"any","source":"parts of a complaint"},
  {"id":"kr-1091","cat":"harassment-and-posh","type":"match","hook":"Match the situation to who can complain.","pairs":[{"left":"Intern, 3-month stint","right":"Yes, interns are covered"},{"left":"Contract housekeeping staff","right":"Yes, contract workers are covered"},{"left":"Part-time worker","right":"Yes, part-timers are covered"},{"left":"Trainee from another city","right":"Yes, location doesn't remove the right"},{"left":"Permanent employee","right":"Yes, permanent staff are covered"}],"relearn":"Interns, contract, part-time, trainee and permanent women workers are all covered.","persona":"Meena","source":"who can complain"},
  {"id":"kr-1092","cat":"harassment-and-posh","type":"match","hook":"Match each behaviour to what kind of conduct it is.","pairs":[{"left":"Unwelcome touching","right":"Physical harassment"},{"left":"Repeated sexual comments","right":"Verbal harassment"},{"left":"Showing porn at a desk","right":"Creating a hostile space"},{"left":"A fair, polite work review","right":"Normal, fair feedback"},{"left":"\"Favours for a promotion\"","right":"Demanding sexual favours"}],"relearn":"Unwelcome touching, sexual comments, porn and favour-demands are harassment; a fair review is normal feedback.","persona":"any","source":"is it harassment"},
  {"id":"kr-1093","cat":"harassment-and-posh","type":"match","hook":"Match each myth to the truth that breaks it.","pairs":[{"left":"\"You'll lose your job for complaining\"","right":"Retaliation is itself unlawful"},{"left":"\"Only seniors are protected\"","right":"Interns and contract staff count too"},{"left":"\"You must prove it with witnesses\"","right":"Your account and records are evidence"},{"left":"\"Nothing can touch the boss\"","right":"The process applies to everyone"},{"left":"\"It's the price of a job\"","right":"Safety and dignity are a right"}],"relearn":"Each common myth about harassment has a clear truth that breaks it.","persona":"any","source":"myth to truth"},
  {"id":"kr-1094","cat":"harassment-and-posh","type":"match","hook":"Match the helpline or route to when you'd use it.","pairs":[{"left":"Internal Committee","right":"Workplace or college harassment"},{"left":"Women in distress 181","right":"A woman needing urgent support"},{"left":"Women's helpline 1091","right":"Help for women facing harm"},{"left":"NALSA 15100","right":"Free legal aid if you can't pay"},{"left":"Emergency 112","right":"Immediate danger right now"}],"relearn":"Different routes fit different needs: the committee, 181, 1091, NALSA 15100 and 112.","persona":"Farhan","source":"route by need"},
  {"id":"kr-1095","cat":"harassment-and-posh","type":"match","hook":"Match the step to where it belongs in handling harassment.","pairs":[{"left":"Note dates and save messages","right":"First, build your record"},{"left":"Write to the Internal Committee","right":"Then file the complaint"},{"left":"Ask about confidentiality","right":"Protect your identity in the process"},{"left":"Ask about interim relief","right":"Stay safe while it's inquired into"},{"left":"Get free legal aid if needed","right":"Support if you can't afford a lawyer"}],"relearn":"Record, file, ask about confidentiality and interim relief, and use free legal aid if needed.","persona":"any","source":"steps in order"},
  {"id":"kr-1096","cat":"harassment-and-posh","type":"match","hook":"Match each false belief to why it's wrong.","pairs":[{"left":"\"A joke can't be harassment\"","right":"Unwelcome sexual jokes can be"},{"left":"\"Off-hours doesn't count\"","right":"The work link matters, not the clock"},{"left":"\"You can't complain about a boss\"","right":"Owners and bosses aren't above it"},{"left":"\"You needed to refuse on day one\"","right":"There's a window to file, extendable"},{"left":"\"Men have no route\"","right":"Anyone harassed has a route"}],"relearn":"Jokes, off-hours acts, bosses, timing and gender myths all have clear answers.","persona":"any","source":"false belief why"},
  {"id":"kr-1097","cat":"harassment-and-posh","type":"branch","persona":"Aarti","source":"start a record","hook":"Vikram, a senior at your internship, keeps making sexual comments, and you freeze each time.","steps":[{"prompt":"After another comment today, you sit at your desk, shaken. What do you do?","options":[{"text":"Tell yourself you must be imagining it","then":"The doubt sits heavy. The comments carry on, and you feel smaller each time."},{"text":"Note today's date, his words and who was near","then":"It takes two minutes. Seeing it written down, the blur starts to feel clearer.","best":true},{"text":"Decide you should have said something back","then":"You replay the moment all evening, blaming yourself for freezing."},{"text":"Wait until it gets worse before doing anything","then":"Days pass. By the time you want to act, the dates have run together."}],"why":"A dated note turns a blur into a record you can use later. Freezing is never your fault."},{"prompt":"A week later the comments continue, and a friend says to keep a record. Where do you keep it?","options":[{"text":"In a notebook in my desk at the office","then":"It's handy, but anyone tidying the desk could find it, Vikram included."},{"text":"In the team chat, so everyone sees what he does","then":"Two people react. Vikram hears of it, and the office turns tense."},{"text":"In a dated note I email to my personal address","then":"Each entry now has a timestamp, in an inbox nobody at work can open.","best":true},{"text":"Only in my head. I'll remember the big ones","then":"A month on, you recall the worst one clearly and the rest only vaguely."}],"why":"A private, timestamped record stays safe and is hard to dispute."},{"prompt":"Your friend Neha notices you're tense and asks what's going on. What do you do?","options":[{"text":"Say it's nothing, since it's only words","then":"Neha lets it go. You go home still carrying it alone."},{"text":"Tell her, but make her promise never to raise it","then":"She promises. Sharing feels lighter, but nothing at work changes."},{"text":"Ask her if you somehow brought it on yourself","then":"Neha says no at once. The question stays in your head anyway."},{"text":"Tell her, and look up the complaint committee together","then":"Neha says it isn't your fault and helps you find who sits on the committee.","best":true}],"why":"Telling someone you trust means you don't carry it alone, and they can help you find the route."}],"debrief":"A private, dated record turns a blur of incidents into something you can act on when ready. It's never your fault.","relearn":"Quietly note each incident with dates; a record helps you act when you're ready."},
  {"id":"kr-1098","cat":"harassment-and-posh","type":"branch","persona":"any","source":"refuse informal","hook":"You report a team lead's harassment. Rekha from HR says \"just sort it out between yourselves.\"","steps":[{"prompt":"She suggests a quick chat with him in her cabin tomorrow. What do you do?","options":[{"text":"Trust HR's advice, since they must know the process","then":"The chat happens. He apologises vaguely, and nothing is written down."},{"text":"Ask for the Internal Committee and complain in writing","then":"Rekha pauses, then shares the committee's email. It's on record now.","best":true},{"text":"Post about it online to force them to act","then":"The post spreads. HR calls you in about the post, not about him."},{"text":"Email HR asking them to handle it quietly","then":"Rekha replies that she'll speak to him informally. No inquiry starts."}],"why":"The committee must inquire into a written complaint. HR can't swap that for a private chat."},{"prompt":"Days later, the team lead passes your desk: \"Heard you've been talking about me.\" What do you do?","options":[{"text":"Tell yourself it was only a passing remark","then":"You let it go, but his remarks near your desk keep coming."},{"text":"Confront him loudly in front of the team","then":"Heads turn. He laughs it off and later calls you dramatic."},{"text":"Ask Rekha to have a quiet word with him","then":"Rekha says she'll try. A week later, nothing has changed or been written."},{"text":"Note it down and send it to the Internal Committee","then":"Your email reaches the committee with the date and his exact words.","best":true}],"why":"A remark aimed at your complaint belongs on record with the committee, dated and in his words."},{"prompt":"That evening your friend Sahil warns that a formal complaint will make you look difficult. What do you do?","options":[{"text":"Say it's my right, and call NALSA 15100","then":"Sahil listens in as a legal aid worker explains that complaining is protected.","best":true},{"text":"Believe him, since I don't want to look difficult","then":"You start doubting yourself, and the harassment still hasn't stopped."},{"text":"Accept that juniors never win against a team lead","then":"The thought sits heavy, and you stop asking what comes next."},{"text":"Leave it to HR. They'll sort it out eventually","then":"Sahil nods, and the matter drifts with nothing new on record."}],"why":"Complaining is protected, and free legal aid on 15100 can back you. The harassment is never your fault."}],"debrief":"Harassment has a formal committee route, so you needn't settle it informally. It's never your fault.","relearn":"If told to 'sort it out yourselves', ask for the committee and complain in writing."},
  {"id":"kr-1099","cat":"harassment-and-posh","type":"branch","persona":"Meena","source":"local committee","hook":"The owner's brother at your 8-person tailoring unit keeps brushing against you. There's no committee.","steps":[{"prompt":"Your co-worker Lata says small places like this have no route at all. What do you do?","options":[{"text":"Accept Lata's word, since she's worked there longer","then":"You stop looking. The brushing past continues, and you dread each shift."},{"text":"Complain to the owner about his own brother","then":"The owner waves it off and says his brother is just friendly."},{"text":"Find out about the district Local Committee","then":"You learn that workplaces under 10 people have a district committee.","best":true},{"text":"Ask Lata to keep it quiet and hope he stops","then":"Lata agrees. Nothing changes, and you feel alone with it."}],"why":"Workplaces too small for their own committee are served by a district Local Committee."},{"prompt":"A neighbour says a district office hears complaints from small workplaces. Who do you ask for help?","options":[{"text":"The owner, since he'd know the right office","then":"The owner asks why you want to know. Now he watches you closely."},{"text":"Free legal aid on NALSA 15100","then":"A legal aid worker explains how to reach the district committee.","best":true},{"text":"The workers' WhatsApp group, with the full story","then":"Advice pours in, some of it wrong. Word reaches the unit by evening."},{"text":"Nobody yet. I'll go when I get a day off","then":"Weeks pass without a free day, and the incidents keep adding up."}],"why":"Free legal aid on 15100 can guide you to the Local Committee and help with the complaint."},{"prompt":"He never says anything openly, and you wonder if it's serious enough. What do you tell yourself?","options":[{"text":"Maybe I'm overreacting because I'm new here","then":"You hold back, and the uneasy feeling follows you into every shift."},{"text":"It only counts if someone else saw it","then":"You look for a witness and give up when nobody noticed."},{"text":"Unwanted touching is harassment, and it counts","then":"You start writing each incident down with the date.","best":true},{"text":"It will count once he sends me a message","then":"You wait for proof that never comes, and nothing moves."}],"why":"Unwelcome touching is harassment, with or without a witness. It's never your fault."}],"debrief":"Workplaces too small for an internal committee use a district Local Committee. It's never your fault.","relearn":"A workplace too small for an internal committee has a district Local Committee."},
  {"id":"kr-1100","cat":"harassment-and-posh","type":"branch","persona":"any","source":"threat is retaliation","hook":"A harasser, Sunil, warns you: \"Complain and I'll make sure you never get hired here again.\"","steps":[{"prompt":"Your complaint to the Internal Committee is already drafted. What do you do with his threat?","options":[{"text":"Note his exact words and the time, and add them","then":"Your complaint now shows the harassment and the attempt to silence you.","best":true},{"text":"Believe his threat means I can't complain now","then":"You put the draft away, and Sunil starts telling people you're trouble."},{"text":"Send him a threat of my own","then":"Sunil screenshots your reply and shows it around as proof you're aggressive."},{"text":"Tell him I'll be reporting this too","then":"Sunil smirks and says it's your word against his. Nothing is written down."}],"why":"A threat to stop you complaining is retaliation. Recording it strengthens your complaint."},{"prompt":"Two days later, your manager says Sunil is valuable and tells you to stop 'creating drama'. What do you do?","options":[{"text":"Accept that a senior's word counts more than mine","then":"You go quiet in meetings, and Sunil's comments carry on."},{"text":"Argue it out with the manager in the open office","then":"Voices rise. The manager later warns you about your conduct."},{"text":"Ask the manager to speak to Sunil for me","then":"He says he'll 'handle it'. Nothing is written and nothing changes."},{"text":"Send the committee a dated note of what he said","then":"The committee logs it, with the date and the manager's words.","best":true}],"why":"Pressure to stay quiet is part of the story, and the committee needs to know about it."},{"prompt":"That evening your cousin Pooja asks why you look so drained. What do you do?","options":[{"text":"Say it's just work stress","then":"Pooja lets it go. You lie awake running through Sunil's words."},{"text":"Tell her, and call NALSA 15100 together","then":"Pooja sits beside you as a legal aid worker explains your options for free.","best":true},{"text":"Tell her, then ask if I'm making too much of it","then":"Pooja says no, but you still feel that it's somehow on you."},{"text":"Ask her to go and confront Sunil for me","then":"Pooja is ready to storm in, and you worry it will make work worse."}],"why":"Someone you trust and free legal aid mean you don't face this alone. It's never your fault."}],"debrief":"A threat meant to silence your complaint is retaliation, and it belongs in the complaint. It's never your fault.","relearn":"A threat for complaining is retaliation; note it and report it."},
  {"id":"kr-1101","cat":"harassment-and-posh","type":"branch","persona":"any","source":"window extendable","hook":"Your supervisor Arvind's harassment stopped four months ago. Fear kept you from filing in time.","steps":[{"prompt":"You feel ready now, but a colleague says the three-month limit has passed. What do you do?","options":[{"text":"Accept that it's simply too late now","then":"You close the matter in your head, but the memory doesn't close so easily."},{"text":"Ask the committee to extend the time, and say why","then":"A member says a delay can be excused for genuine reasons and asks for them in writing.","best":true},{"text":"Blame myself for not being braver sooner","then":"The guilt weighs on you, though fear was the reason you waited."},{"text":"Mention it to HR informally instead","then":"HR says they'll 'keep an eye out'. No inquiry begins."}],"why":"The time can be extended for genuine reasons like fear. Waiting doesn't make any of it your fault."},{"prompt":"Your friend Farah offers to help you write to the committee. What do you say about the delay?","options":[{"text":"That work deadlines kept me too busy","then":"It sounds thin, and it isn't the real reason you waited."},{"text":"Nothing. They shouldn't need a reason","then":"The letter goes in bare, giving the committee little to go on."},{"text":"That I wanted to be sure it was serious enough","then":"Farah nods, but it leaves out the fear that really held you back."},{"text":"The truth: I was scared of losing my job","then":"Farah helps you say it plainly. It reads as honest and human.","best":true}],"why":"Being honest about the fear gives the committee a genuine reason to extend the time."},{"prompt":"A week on there's no reply, and Arvind has turned cold towards you at work. What do you do?","options":[{"text":"Take the silence as a sign it's hopeless","then":"You stop checking your email, and the matter sits untouched."},{"text":"Follow up in writing, and note his behaviour","then":"The committee replies with a date to meet, and your notes are ready.","best":true},{"text":"Ask Arvind directly why he's being cold","then":"Arvind says he has no idea what you mean. You leave more rattled."},{"text":"Wait quietly. They'll get to it","then":"Two more weeks pass, and the cold treatment at work goes on."}],"why":"A written follow-up keeps things moving, and dated notes capture any new pressure."},{"prompt":"Later, the committee sets a date to hear you. What do you bring along?","options":[{"text":"Nothing. My word should be enough","then":"You tell it clearly, but a few dates blur when they ask."},{"text":"A friend to speak for me","then":"The committee asks to hear from you directly, and your friend waits outside."},{"text":"My dated notes and messages, and names of anyone who saw","then":"The member reads through them and asks clear, focused questions.","best":true},{"text":"A list of everything wrong with Arvind's work","then":"The member sets it aside. It isn't what they need to decide this."}],"why":"Dated notes and messages help the committee see the pattern clearly."}],"debrief":"The window can be extended for genuine reasons, so a delay doesn't end your right. It's never your fault.","relearn":"If you missed the window out of fear, ask the committee to extend it."},
  {"id":"kr-1102","cat":"harassment-and-posh","type":"branch","persona":"any","source":"customer harasser","hook":"Your friend Divya works at a phone shop, where a regular customer keeps making lewd remarks to her.","steps":[{"prompt":"She says nothing can be done because he isn't staff. What do you tell her?","options":[{"text":"Just ignore him. Customers come and go","then":"Divya nods, but she flinches every time the shop door opens."},{"text":"You should quit. That place isn't safe","then":"Divya goes quiet. She needs this job and now feels judged."},{"text":"Your employer still owes you a safe workplace","then":"Divya looks up. \"Even from customers? I didn't know that.\"","best":true},{"text":"Tell him off yourself the next time he comes in","then":"Divya looks worried. \"And if he makes a scene in front of my boss?\""}],"why":"An employer's duty to keep work safe covers harassment by customers too."},{"prompt":"Divya asks who she could even tell at work. What do you suggest?","options":[{"text":"The customer's family, so they can stop him","then":"Divya winces. She doesn't even know who they are."},{"text":"The complaint committee, whenever you feel ready","then":"Divya finds the committee notice by the staff room and saves the number.","best":true},{"text":"Your co-workers' chat group, to warn everyone","then":"Her co-workers are kind, but nothing formal reaches the employer."},{"text":"Your manager. I'll call him for you tomorrow","then":"Divya panics. \"Please don't. I haven't decided anything yet.\""}],"why":"The committee is the formal route, and the choice of when to use it stays hers."},{"prompt":"A few days later, Divya says he came back and she felt sick all shift. What do you say?","options":[{"text":"Why didn't you just leave the counter?","then":"Divya looks hurt. \"I couldn't. There were customers.\""},{"text":"It's only words, really. Try not to let it get to you","then":"Divya goes quiet and changes the subject."},{"text":"It's not your fault. Want to note down what happened?","then":"Divya exhales. \"Yes. Can you sit with me while I do it?\"","best":true},{"text":"You have to report it today. No more waiting","then":"Divya tenses. \"I said I'd think about it.\""}],"why":"Saying it isn't her fault and offering practical help supports her without taking over."}],"debrief":"Harassment by a customer is still a workplace safety issue the employer must address. It's never her fault.","relearn":"Harassment by a customer is still the employer's duty; she can raise it."},
  {"id":"kr-1103","cat":"harassment-and-posh","type":"branch","persona":"any","source":"settlement caution","hook":"Mr Kapoor from HR hands you a 'mutual settlement' that would quietly end your harassment complaint.","steps":[{"prompt":"He says you must sign today so everyone can move on. What do you do?","options":[{"text":"Agree to sign, since HR must know what's best","then":"Mr Kapoor smiles and says he'll send the final copy to sign tomorrow."},{"text":"Take it home and get free legal advice first","then":"Mr Kapoor frowns but agrees. The paper goes into your bag unsigned.","best":true},{"text":"Tear it up in front of him","then":"Mr Kapoor sighs and notes that you 'refused to cooperate'."},{"text":"Ask a colleague whether I should sign it","then":"She says she'd sign just to be done with it. You're still unsure."}],"why":"Taking time for free legal advice shows you what you'd be giving up before you sign."},{"prompt":"Next day, HR emails the final copy. One line says you won't raise this anywhere again. What do you do?","options":[{"text":"Assume it's standard wording and let it go","then":"You don't question it, and that line could limit what you can do later."},{"text":"Ask HR what the line means for me","then":"HR says it's 'just a formality'. You're none the wiser."},{"text":"Call NALSA 15100 and ask about that line","then":"A legal aid lawyer explains, free of charge, what the line would take away.","best":true},{"text":"Search online forums for what it means","then":"You find ten confident answers that all disagree."}],"why":"A free legal aid lawyer can explain the terms. HR's view is the company's view."},{"prompt":"A week later, HR hints that your complaint may affect your appraisal. What do you do?","options":[{"text":"Note the hint with the date and tell the committee","then":"The committee records it. The pressure is on paper now, not only in your head.","best":true},{"text":"Believe they can lawfully mark me down for this","then":"You start to feel cornered, and signing looks like the only way out."},{"text":"Threaten HR with a court case on the spot","then":"HR turns formal and cold, and every talk after that gets harder."},{"text":"Mention it casually to my team lead","then":"Your team lead says HR is 'just like that'. Nothing is recorded."}],"why":"Pressure linked to your complaint is retaliation and belongs with the committee. It's not your fault."}],"debrief":"Don't sign under pressure; free legal advice shows what you'd give up. The harassment is never your fault.","relearn":"Before signing any settlement, get free legal advice; NALSA 15100 is free."},
  {"id":"kr-1104","cat":"harassment-and-posh","type":"branch","persona":"Mehta","source":"support her pace","hook":"A junior colleague, Sneha, tells you a manager is harassing her and begs you to keep it secret.","steps":[{"prompt":"Sneha is shaking and asks you not to tell anyone. What do you do first?","options":[{"text":"Promise to report it to HR today for her","then":"Sneha's face falls. \"I asked you not to. Now I'm scared.\""},{"text":"Ask what she did before it all started","then":"Sneha pulls back. \"Are you saying it's on me?\""},{"text":"Say I believe her, and it's not her fault","then":"Sneha's shoulders drop a little, and she starts to tell you more.","best":true},{"text":"Tell her to keep her distance and it'll pass","then":"Sneha nods, but she looks more alone than before."}],"why":"Believing her first shows she's safe with you, and it's never her fault."},{"prompt":"Sneha asks what her options even are. What do you say?","options":[{"text":"The committee is the only real option","then":"Sneha looks overwhelmed. \"I'm not ready for anything that formal.\""},{"text":"She should find a safer job instead","then":"Sneha goes quiet. She needs this job, and now she feels judged."},{"text":"I'll work out the best option for her","then":"Sneha agrees, but she has handed you a choice that is hers."},{"text":"The committee, or helpline 181. It's her call","then":"Sneha notes both down. \"I'll think about which feels right.\"","best":true}],"why":"Sharing every route and leaving the choice to her keeps her in control."},{"prompt":"A week later, you see the manager stand too close to Sneha in the corridor. What do you do?","options":[{"text":"Report it over her head, since I saw it myself","then":"Sneha hears of it from HR and feels betrayed. It takes days before she talks to you again."},{"text":"Confront the manager right there","then":"He laughs it off, then corners Sneha about 'what she's been saying'."},{"text":"Check in with her privately and ask what she needs","then":"Sneha says it's getting worse and asks for help writing to the committee.","best":true},{"text":"Pretend not to notice, to respect her secret","then":"The manager carries on, and Sneha doesn't know you saw."}],"why":"Checking in keeps her in charge while making sure she knows you're there."},{"prompt":"Later, Sneha says she wants to complain but fears what people will say. What do you tell her?","options":[{"text":"Don't worry. Nobody will ever find out","then":"Sneha relaxes, but it's a promise nobody can fully keep."},{"text":"People will talk. Are you sure it's worth it?","then":"Sneha hesitates, and her fear grows."},{"text":"I'll come with you, and every step is your call","then":"Sneha nods slowly. \"Okay. Let's do it together.\"","best":true},{"text":"Just file it and stop worrying about others","then":"Sneha feels rushed and says she'll 'see'."}],"why":"Standing beside her while she stays in charge is real support, without false promises."}],"debrief":"Support a survivor at her pace: believe her and share routes, don't seize her choice. It's never her fault.","relearn":"Believe her, move at her pace, and share the committee and helpline options."},
  {"id":"kr-1105","cat":"harassment-and-posh","type":"branch","persona":"any","source":"ask interim relief","hook":"Your complaint against Karan is under inquiry, and you still share a small room with him every day.","steps":[{"prompt":"Each morning, walking in makes your chest tight. What do you do?","options":[{"text":"Tell myself it's only until the inquiry ends","then":"Weeks stretch on, and the tension in that room drains you daily."},{"text":"Ask my manager to shift my desk informally","then":"The manager agrees, then forgets. Nothing is on record."},{"text":"Write to the committee asking for interim relief","then":"The committee notes your request and asks what would help.","best":true},{"text":"Ask Karan to switch rooms with me himself","then":"Karan smirks and says he's comfortable where he is."}],"why":"The committee can recommend interim relief, like a transfer or leave, so you needn't face him."},{"prompt":"Ms Iyer from the committee calls to ask how you're managing during the inquiry. What do you tell her?","options":[{"text":"That I'm fine, so I don't seem difficult","then":"Ms Iyer thanks you and hangs up. Nothing in the room changes."},{"text":"That sharing a room with him is hard for me","then":"Ms Iyer says the committee can recommend moving one of you, or leave.","best":true},{"text":"That Karan should be fired right now","then":"Ms Iyer says the inquiry must finish first, and asks what would help you meanwhile."},{"text":"That I'll manage, but they should hurry up","then":"Ms Iyer says they're moving as fast as they can. The room stays the same."}],"why":"Saying plainly what's hard lets the committee use the protections it has."},{"prompt":"A week later, Karan starts leaving his unfinished work on your desk. What do you do?","options":[{"text":"Do it, since complaining again looks petty","then":"Your evenings vanish into his work, and the pattern keeps growing."},{"text":"Refuse loudly in front of the whole team","then":"The room goes silent. Karan tells people you're impossible to work with."},{"text":"Leave his work undone and say nothing","then":"Deadlines slip, and your manager asks you what went wrong."},{"text":"Note each time, and tell the committee","then":"Ms Iyer adds it to the file and says she'll take it up with your manager.","best":true}],"why":"New pressure during an inquiry belongs with the committee, dated and specific."},{"prompt":"That evening, your sister Nisha asks why you've seemed so tired lately. What do you do?","options":[{"text":"Say it's just a busy patch at work","then":"Nisha lets it go, and you carry the inquiry alone."},{"text":"Tell her, then ask if I'm making too much of it","then":"Nisha says no, but the doubt stays with you all night."},{"text":"Tell her about the inquiry, and lean on her","then":"Nisha hugs you. \"It's not your fault. Call me after every meeting.\"","best":true},{"text":"Ask her to go and have it out with Karan","then":"Nisha is furious, and you worry a scene could hurt the inquiry."}],"why":"Leaning on someone you trust helps you through the inquiry. None of this is your fault."}],"debrief":"While an inquiry runs you can ask for interim relief, like a transfer or leave. It's never your fault.","relearn":"Ask the committee for interim relief, like a transfer, during the inquiry."},
  {"id":"kr-1106","cat":"harassment-and-posh","type":"branch","persona":"Aarti","source":"college professor","hook":"Professor Menon hints that your internal marks depend on meeting him alone after class.","steps":[{"prompt":"He says it again as you leave the lab. What do you do once you're outside?","options":[{"text":"Believe that complaining will only cost me marks","then":"You keep it to yourself, and the worry follows you into every class."},{"text":"Write down his words, the date and the place","then":"The note is short and exact, and you feel steadier having it.","best":true},{"text":"Assume I must have misread what he meant","then":"You push it away, but his words keep coming back."},{"text":"Post about him on the college confessions page","then":"The post gets likes and guesses. Nothing reaches anyone who can act."}],"why":"A note of his exact words, time and place is the start of a clear complaint."},{"prompt":"In the canteen, your friend Rohit says students who complain about teachers only lose marks. What do you tell him?","options":[{"text":"Marks for favours is harassment. There's a committee","then":"Rohit pauses. \"Colleges have one too? I didn't know that.\"","best":true},{"text":"He's right. Teachers always win these things","then":"Rohit nods, and you start to feel stuck with it."},{"text":"It only counts as harassment if he touches me","then":"Rohit shrugs, and you start to doubt what you heard."},{"text":"I'll ask the head of department for a quiet word","then":"The HOD later promises to 'mention it', and nothing is written down."}],"why":"Tying marks to private meetings is harassment, and colleges must have a committee to hear it."},{"prompt":"The next week, you doubt the committee will take a student's word seriously. What do you do?","options":[{"text":"Ask Professor Menon to explain himself first","then":"He smiles and says you misunderstood. Now he knows you're thinking of it."},{"text":"Wait until another student complains too","then":"Weeks pass. If others are being targeted, they're waiting too."},{"text":"Hand in a written complaint of what he said","then":"A member confirms receipt and explains that the process is confidential.","best":true},{"text":"Talk to one member off the record only","then":"She listens kindly but says the committee needs a complaint to act."}],"why":"The committee hears students' complaints confidentially, and a written one starts the process."},{"prompt":"Your mother notices you've been quiet all week and asks what's wrong. What do you do?","options":[{"text":"Say nothing, since she would only worry","then":"She lets it go, and you carry it alone a little longer."},{"text":"Tell her, but say I shouldn't have stayed late","then":"She frowns and says no, but the thought lingers with you."},{"text":"Ask her to go to college and shout at him","then":"She's ready to march in, and you dread a scene on campus."},{"text":"Tell her, and ask her to back me through it","then":"She holds your hand. \"It's not your fault. We'll go through this together.\"","best":true}],"why":"Someone you trust can stand with you through the process. None of this is your fault."}],"debrief":"A teacher tying marks to private meetings is harassment, and colleges have a committee. It's never your fault.","relearn":"Tying marks to private meetings is harassment; use the college committee."},
  {"id":"kr-1107","cat":"harassment-and-posh","type":"branch","persona":"Meena","source":"own language ok","hook":"You want to complain about your supervisor's harassment, but you worry your English isn't good enough.","steps":[{"prompt":"The complaint notice at work is printed only in English. What do you do?","options":[{"text":"Give up, since I can't write it 'properly'","then":"The notice stays on the wall, and the remarks carry on."},{"text":"Pay a typist to write it in formal English","then":"The typist's version sounds grand, but parts of what happened get lost."},{"text":"Write it in my own language, in my own words","then":"Two pages in your own language, and they say exactly what happened.","best":true},{"text":"Copy a sample complaint from the internet","then":"It sounds official, but it doesn't describe what happened to you."}],"why":"A complaint needs your facts in your words. No legal English is needed."},{"prompt":"Your roommate Sunita says the committee only accepts complaints in proper English. What do you do?","options":[{"text":"Believe her, and drop the complaint for now","then":"Weeks pass, and the remarks carry on."},{"text":"Ask the committee if my own words will do","then":"A member says your own words and language are fine, and they'll help if you need it.","best":true},{"text":"Ask Sunita to put my complaint into English","then":"Sunita tries, but her version gets two of the dates wrong."},{"text":"Ask the supervisor's friend how it works","then":"He says he'll find out, and by evening the supervisor knows."}],"why":"Your own words and language are fine, and the committee can help you put a complaint in writing."},{"prompt":"You wonder if you'll need a lawyer, and you can't afford one. What do you do?","options":[{"text":"Decide lawyers are only for people with money","then":"You feel shut out and stop asking questions."},{"text":"Ask a relative who knows a lawyer to call him","then":"Your relative is busy, and weeks pass with no answer."},{"text":"Borrow money to hire a private lawyer","then":"You get help, along with a debt you worry about every month."},{"text":"Call NALSA 15100 for free legal aid","then":"A legal aid worker explains the next steps in plain words.","best":true}],"why":"Free legal aid on 15100 means you don't need money to get help."}],"debrief":"A complaint can be in your own words and language, with no legal English needed. It's never your fault.","relearn":"You can complain in your own language; free legal aid helps."},
  {"id":"kr-1108","cat":"harassment-and-posh","type":"branch","persona":"any","source":"appeal route","hook":"The committee dismisses your harassment complaint, and you feel it ignored key evidence.","steps":[{"prompt":"Colleagues say that's the end of it. What do you do?","options":[{"text":"Accept it as final, since the committee decided","then":"You try to move on, but the unfairness keeps nagging at you."},{"text":"Complain about the committee on social media","then":"The post spreads, and it muddies things if you appeal later."},{"text":"Confront the committee head in the corridor","then":"She says the decision is made and walks off. Nothing is recorded."},{"text":"Find out how an appeal works, and its deadline","then":"You learn an appeal is possible, within a time limit.","best":true}],"why":"A decision you feel is wrong can usually be appealed, and knowing the deadline keeps that door open."},{"prompt":"You're unsure if you can afford any help with an appeal. What do you do?","options":[{"text":"Call NALSA 15100 about free legal aid","then":"A legal aid lawyer offers to go through the committee's report with you.","best":true},{"text":"Assume appeals are only for people with money","then":"You let the idea go, and the time limit quietly runs down."},{"text":"Ask HR whether an appeal is worth it","then":"HR says it would 'just drag things out'. That's the company's view."},{"text":"Wait a few months until I've saved up","then":"By the time you've saved, the time to appeal may be gone."}],"why":"Free legal aid on 15100 can help you decide, without needing money."},{"prompt":"A friend asks what you'd need for an appeal. What do you start gathering?","options":[{"text":"Letters from friends about my character","then":"They're kind words, but they don't touch what the committee missed."},{"text":"The committee's report and my dated evidence","then":"It all sits in one folder, ready to show where the decision seems wrong.","best":true},{"text":"Only my memory of what happened","then":"Your account still counts, but without the report you can't show what the committee missed."},{"text":"Screenshots of people gossiping about the case","then":"They sting to read, but they aren't about the harassment itself."}],"why":"The report and your dated evidence show exactly where the decision went wrong."},{"prompt":"Your cousin Tanvi says appealing will make you look bitter. What do you tell her?","options":[{"text":"Maybe she's right, and I should let it go","then":"Tanvi nods. The appeal date passes, and so does your chance."},{"text":"It's my right to ask for a fair decision","then":"Tanvi pauses. \"Fair enough. I just don't want you hurt again.\"","best":true},{"text":"I'll appeal only if a lawyer promises I'll win","then":"No honest lawyer can promise that, so you stay stuck waiting."},{"text":"I'll appeal mainly to make them look bad","then":"Tanvi frowns, and you wonder if that's really why."}],"why":"An appeal is a normal way to seek a fair decision, even though nobody can promise the outcome."}],"debrief":"A decision you feel is wrong can usually be appealed, and free legal advice helps. It's never your fault.","relearn":"If a decision feels unfair, ask about appealing; NALSA 15100 advises for free."},
  {"id":"kr-1109","cat":"harassment-and-posh","type":"branch","persona":"Rohan","source":"no victim blame","hook":"At lunch during your internship, a colleague, Nikhil, says a harassment complaint happened because \"she led him on.\"","steps":[{"prompt":"Others at the table laugh along. What do you do?","options":[{"text":"Laugh along so it doesn't get awkward","then":"The chat moves on, and the idea sits there unchallenged."},{"text":"Say the fault is the harasser's, not hers","then":"The laughter stops. Nikhil shrugs. \"Just saying, yaar.\"","best":true},{"text":"Say we should all wait for the facts first","then":"It sounds fair, but 'she led him on' is left hanging in the air."},{"text":"Stay out of it, since it's not my business","then":"Nobody pushes back, and Nikhil keeps talking."}],"why":"Harassment is never caused by the person targeted. Saying so puts the fault where it belongs."},{"prompt":"Later, Nikhil adds, \"Some women use these complaints to get ahead.\" What do you say?","options":[{"text":"That's true sometimes, I suppose","then":"Nikhil nods, pleased, and the myth gets a little stronger."},{"text":"You're sexist, and I'm reporting you","then":"Nikhil gets defensive, and the table turns on you instead."},{"text":"A committee checks the facts of every complaint","then":"Nikhil pauses. \"Fine. But still...\" He trails off.","best":true},{"text":"Let's just change the subject","then":"The table moves on, and Nikhil's view goes unchallenged."}],"why":"Complaints are heard by a committee that checks the facts. Assuming they're fake silences real ones."},{"prompt":"A few days later, Priya, who made the complaint, sits alone at lunch. What do you do?","options":[{"text":"Ask her what really happened with him","then":"Priya stiffens. \"I'd rather not talk about that here.\""},{"text":"Keep my distance to stay out of the drama","then":"Priya eats alone again, and the silence says a lot."},{"text":"Tell her what Nikhil has been saying","then":"Priya's face falls. Now she's hurt, and nothing has changed."},{"text":"Join her and chat as I normally would","then":"Priya looks up, surprised, and makes room at the table.","best":true}],"why":"Ordinary kindness shows her she isn't shunned, without prying into her case."}],"debrief":"Harassment isn't caused by the target. The fault is always the harasser's, never hers.","relearn":"The fault is the harasser's, never the target's; push back on victim-blaming."},
  {"id":"kr-1110","cat":"harassment-and-posh","type":"branch","persona":"any","source":"preserve evidence","hook":"A colleague, Ajay, sent you harassing messages. You saved screenshots, and now he has deleted his.","steps":[{"prompt":"A friend says your proof is gone now that his side is deleted. What do you do?","options":[{"text":"Believe my copies are worthless now","then":"You stop saving new ones, even as his messages continue."},{"text":"Ask Ajay to admit that he sent them","then":"Ajay replies, \"What messages?\" and deletes that reply too."},{"text":"Back up my screenshots to email and a drive","then":"Copies now sit in two safe places, with the dates visible.","best":true},{"text":"Keep them safe on my phone, and only there","then":"It works, until the phone slips on the bus and the screen cracks."}],"why":"Your saved copies stay valid evidence after his are gone. Backups keep them safe."},{"prompt":"A week later, a new message from Ajay arrives late at night. What do you do?","options":[{"text":"Reply and tell him exactly what I think","then":"Ajay screenshots your reply and deletes his own message again."},{"text":"Screenshot it with the time showing, and back it up","then":"The new one joins the others, dated and safe.","best":true},{"text":"Tell myself that one more message doesn't really matter","then":"You leave it, and the pattern is harder to show later."},{"text":"Forward it to our common friends","then":"Friends are shocked, but the story spreads beyond your control."}],"why":"Capturing each message with its time builds a clear pattern."},{"prompt":"You decide it's time to complain. Where do you take the screenshots?","options":[{"text":"To my manager, and let him decide","then":"Your manager says he'll 'talk to Ajay'. Nothing formal starts."},{"text":"To the office group chat, so everyone sees who he is","then":"The chat explodes, and HR asks you to take it down."},{"text":"To the Internal Committee, with a written complaint","then":"The committee logs your complaint and your dated screenshots.","best":true},{"text":"To Ajay, to show him I have proof","then":"Ajay goes pale, then tells people you faked them."}],"why":"The committee is the formal route, and your saved screenshots count as evidence there."},{"prompt":"A few days on, your friend Mitali notices you jump every time your phone buzzes. What do you do?","options":[{"text":"Say it's nothing, just work stress","then":"Mitali lets it go, and you keep carrying it alone."},{"text":"Tell her, and ask her to stand by me","then":"Mitali says it's not your fault and offers to be with you through it.","best":true},{"text":"Tell her, then ask if I'm overreacting","then":"Mitali says no, but the doubt lingers anyway."},{"text":"Ask her to message Ajay and warn him off","then":"Mitali fires off a message, and Ajay screenshots it."}],"why":"Someone you trust means you don't face this alone. It's never your fault."}],"debrief":"Evidence you preserve stays valid even if the other person deletes theirs. It's never your fault.","relearn":"Your saved screenshots are still evidence even if his are deleted; back them up."},
  {"id":"kr-1111","cat":"harassment-and-posh","type":"sort","hook":"Sort: a behaviour that can be sexual harassment, or not?","items":[{"id":"a","text":"Unwelcome comments about your body"},{"id":"b","text":"Demanding sexual favours for a promotion"},{"id":"c","text":"A manager giving honest, fair feedback"},{"id":"d","text":"Repeatedly sending unwanted explicit messages"},{"id":"e","text":"Being assigned a normal work task"},{"id":"f","text":"Unwanted touching at the desk"}],"bins":[{"id":"is","label":"Can be harassment","valence":"neg"},{"id":"not","label":"Not harassment","valence":"pos"}],"key":{"a":"is","b":"is","c":"not","d":"is","e":"not","f":"is"},"relearn":"Unwelcome comments, demands, explicit messages and touching can be harassment; fair feedback and normal tasks are not.","persona":"any","source":"is it harassment sort"},
  {"id":"kr-1112","cat":"harassment-and-posh","type":"sort","hook":"Sort: does this remove your right to complain, or not?","items":[{"id":"a","text":"You're only an intern"},{"id":"b","text":"You're on a short contract"},{"id":"c","text":"You're part-time"},{"id":"d","text":"The conduct was genuinely welcome to you"},{"id":"e","text":"You're a trainee from another city"},{"id":"f","text":"There was no unwelcome conduct at all"}],"bins":[{"id":"still","label":"Still covered","valence":"pos"},{"id":"none","label":"Nothing to complain of","valence":"neutral"}],"key":{"a":"still","b":"still","c":"still","d":"none","e":"still","f":"none"},"relearn":"Being an intern, contract, part-time or a trainee leaves you covered; only genuinely welcome conduct means there's nothing to complain of.","persona":"Meena","source":"who is covered sort"},
  {"id":"kr-1113","cat":"harassment-and-posh","type":"sort","hook":"Sort: speak up about this, or wait and watch?","items":[{"id":"a","text":"A boss demanding a date for your appraisal"},{"id":"b","text":"Unwanted explicit messages from a colleague"},{"id":"c","text":"A vague feeling you can't yet name"},{"id":"d","text":"Repeated unwelcome touching"},{"id":"e","text":"A single ambiguous joke you're unsure about"},{"id":"f","text":"A threat to sack you if you report"}],"bins":[{"id":"speak","label":"Speak up","valence":"tell"},{"id":"watch","label":"Watch a bit","valence":"uhoh"}],"key":{"a":"speak","b":"speak","c":"watch","d":"speak","e":"watch","f":"speak"},"relearn":"Clear demands, explicit messages, touching and threats are speak-up; a vague feeling or one ambiguous joke you can watch.","persona":"any","source":"speak or watch"},
  {"id":"kr-1114","cat":"harassment-and-posh","type":"sort","hook":"Sort each into the right place in a harassment complaint.","items":[{"id":"a","text":"Save dated messages and emails"},{"id":"b","text":"Write to the Internal Committee"},{"id":"c","text":"Ask about confidentiality"},{"id":"d","text":"Delete everything to avoid trouble"},{"id":"e","text":"Get free legal aid if you can't pay"},{"id":"f","text":"Tell no one and wait for years"}],"bins":[{"id":"do","label":"Helps your case","valence":"pos"},{"id":"avoid","label":"Hurts your case","valence":"neg"}],"key":{"a":"do","b":"do","c":"do","d":"avoid","e":"do","f":"avoid"},"relearn":"Saving evidence, filing, asking about confidentiality and getting free aid help; deleting evidence or long silence hurt.","persona":"any","source":"complaint do or avoid"},
  {"id":"kr-1115","cat":"harassment-and-posh","type":"sort","hook":"Sort: a real protection in the complaint process, or a myth?","items":[{"id":"a","text":"The process is confidential"},{"id":"b","text":"You can ask for interim relief"},{"id":"c","text":"Retaliation for complaining is allowed"},{"id":"d","text":"Free legal aid is available if you can't pay"},{"id":"e","text":"You must face the harasser alone"},{"id":"f","text":"The filing window can be extended"}],"bins":[{"id":"real","label":"Real protection","valence":"pos"},{"id":"myth","label":"Myth","valence":"neg"}],"key":{"a":"real","b":"real","c":"myth","d":"real","e":"myth","f":"real"},"relearn":"Confidentiality, interim relief, free legal aid and an extendable window are real; allowed retaliation and forced solo confrontation are myths.","persona":"any","source":"protection or myth"},
  {"id":"kr-1116","cat":"harassment-and-posh","type":"sort","hook":"Sort each case to where it goes.","items":[{"id":"a","text":"Harassment by a coworker at the office"},{"id":"b","text":"Harassment by a teacher on campus"},{"id":"c","text":"A woman in immediate danger now"},{"id":"d","text":"Can't afford a lawyer"},{"id":"e","text":"Harassment at a 6-staff workplace"},{"id":"f","text":"A woman needing urgent support"}],"bins":[{"id":"committee","label":"A committee","valence":"neutral"},{"id":"helpline","label":"A helpline","valence":"tell"}],"key":{"a":"committee","b":"committee","c":"helpline","d":"helpline","e":"committee","f":"helpline"},"relearn":"Workplace and campus harassment go to a committee; danger, cost and urgent support go to helplines.","persona":"Farhan","source":"route sort"},
  {"id":"kr-1138","cat":"harassment-and-posh","type":"sort","hook":"Sort: is this on the harasser, or never the survivor's fault?","items":[{"id":"a","text":"Choosing to make unwelcome advances"},{"id":"b","text":"What the survivor was wearing"},{"id":"c","text":"Ignoring a clear 'no'"},{"id":"d","text":"The survivor smiling politely at work"},{"id":"e","text":"Sending the unwanted messages"},{"id":"f","text":"The survivor taking time to report"}],"bins":[{"id":"on-him","label":"On the harasser","valence":"neg"},{"id":"not-fault","label":"Never her fault","valence":"pos"}],"key":{"a":"on-him","b":"not-fault","c":"on-him","d":"not-fault","e":"on-him","f":"not-fault"},"relearn":"The advances, ignoring a 'no' and the messages are on the harasser; clothes, politeness and timing are never the survivor's fault.","persona":"any","source":"whose fault sort"},
  {"id":"kr-1117","cat":"harassment-and-posh","type":"role-play","persona":"Meena","source":"refuse favours-for-contract","hook":"Your contract at the garment unit ends next month, and the floor manager, Mr Rana, wants a word.","setup":"He stops you by the cutting table after the shift.","steps":[{"prompt":"Mr Rana says: \"Be nice to me and I'll renew your contract.\"","options":[{"text":"\"Maybe this is just how contracts work here.\"","then":"He nods slowly. \"Good. We'll talk again soon.\""},{"text":"\"My contract should depend on my work, not this.\"","then":"He leans back. \"Think it over. Contracts are hard to find.\"","best":true},{"text":"\"Did I do something to make you think that?\"","then":"He ignores the question. \"Just think about your contract.\""},{"text":"\"I'll tell the whole floor what you just said.\"","then":"His face hardens. \"Who'll believe a contract worker over me?\""}],"why":"Saying no clearly is your right. Your work, not favours, decides your contract. It's never your fault."},{"prompt":"Two days later, Mr Rana stops by your machine and asks: \"Decided yet? Plenty of girls would say yes.\"","options":[{"text":"\"No. And please don't ask me again.\"","then":"He frowns. \"Suit yourself.\" He walks off without another word.","best":true},{"text":"\"Maybe I'm overreacting. You were joking, right?\"","then":"He smiles. \"Of course. We'll talk later.\""},{"text":"\"Please keep this between us, whatever happens.\"","then":"\"Our secret, then,\" he says, and walks off."},{"text":"\"Say that again and your wife will hear of it.\"","then":"He laughs. \"Go ahead. Nobody will believe you.\""}],"why":"A clear, repeated no is your right. Write down his words and your no, with the date."},{"prompt":"That evening, your roommate Kamla asks: \"Why are you so upset? What happened?\"","options":[{"text":"\"Nothing. I must have misunderstood him.\"","then":"Kamla looks at you. \"Is it that manager? The girls at the unit talk about him.\""},{"text":"\"He wants favours for my contract. I'm writing it all down.\"","then":"\"That's harassment,\" Kamla says. \"Let's find out where to report it.\"","best":true},{"text":"\"I need that contract. I'll handle it myself.\"","then":"\"On your own? That doesn't sound safe,\" Kamla says."},{"text":"\"Maybe I dressed up too much for work.\"","then":"Kamla shakes her head. \"That's not why. Don't blame yourself.\""}],"why":"Telling someone you trust means you don't face this alone, and they can help you report it."},{"prompt":"Kamla asks: \"Does your unit even have a complaint committee?\"","options":[{"text":"\"No, so I guess there's nowhere to go.\"","then":"Kamla frowns. \"There must be somewhere.\""},{"text":"\"I'll ask the owner to have a word with him.\"","then":"Kamla hesitates. \"A word won't stop him or put it on record.\""},{"text":"\"If not, the district has one. NALSA 15100 can help.\"","then":"Kamla nods. \"Then let's call first thing tomorrow.\"","best":true},{"text":"\"Contract workers like me aren't covered anyway.\"","then":"Kamla shakes her head. \"Contract workers are covered too. Let's check.\""}],"why":"Contract workers are covered too. With no unit committee, a district one may hear it, and 15100 can guide you."}],"relearn":"Refuse a favours-for-contract demand clearly and put your refusal on record."},
  {"id":"kr-1118","cat":"harassment-and-posh","type":"role-play","persona":"any","source":"name the joke","hook":"At work, Deepesh keeps 'joking' about your body, and others laugh along.","setup":"It happens again as you walk into the canteen.","steps":[{"prompt":"Deepesh grins and says: \"Relax. It's just a joke. Why so serious?\"","options":[{"text":"\"I guess jokes like this are part of the job.\"","then":"Deepesh turns to the table. \"See? Just a bit of fun.\""},{"text":"\"Comments on my body aren't a joke to me. Stop.\"","then":"The table goes quiet. Deepesh shrugs. \"Okay, okay.\"","best":true},{"text":"\"You're disgusting, and everyone here knows it.\"","then":"Deepesh smirks. \"Wow. Someone's sensitive.\""},{"text":"\"Maybe I should just dress differently.\"","then":"Nobody answers, and the comments carry on."}],"why":"Naming it plainly, without apologising, makes it clear it's unwelcome. The fault is his, not yours."},{"prompt":"Later, your colleague Mansi says: \"He's like that with everyone. Just ignore him.\"","options":[{"text":"\"You're right. I'm probably too sensitive.\"","then":"Mansi changes the subject, and nothing about Deepesh changes."},{"text":"\"Then I'll embarrass him in front of the boss.\"","then":"\"That could backfire on you,\" Mansi warns."},{"text":"\"That doesn't make it okay. I'm keeping notes.\"","then":"Mansi pauses. \"Actually, he's said stuff to me too.\"","best":true},{"text":"\"Could you tell him to stop, for me?\"","then":"Mansi hesitates. \"I don't really want to get involved.\""}],"why":"You're not too sensitive. Doing it to everyone doesn't make it okay, and notes show the pattern."},{"prompt":"A week on, the comments haven't stopped. Your friend Ritika asks: \"What will you do?\"","options":[{"text":"\"Nothing. Complaints are for serious things, not jokes.\"","then":"Ritika shrugs. \"If you say so.\" The comments carry on."},{"text":"\"I'll ask my manager to have a quiet word with him.\"","then":"\"Maybe,\" Ritika says. \"But would a quiet word stop him?\""},{"text":"\"I'm taking it to the committee. Will you come?\"","then":"\"Of course,\" Ritika says. \"Let's write down what he's said first.\"","best":true},{"text":"\"Keep it between us. I don't want a fuss.\"","then":"Ritika agrees, looking worried, and you carry it on your own."}],"why":"A trusted friend and the committee mean you don't face this alone. His comments are never your fault."}],"relearn":"You can name an unwelcome 'joke' and ask for it to stop, without apologising."},
  {"id":"kr-1119","cat":"harassment-and-posh","type":"role-play","persona":"any","source":"ask at committee","hook":"You're at the Internal Committee to file your harassment complaint against a senior.","setup":"The committee's head, Ms Rao, pulls up a chair and opens a fresh file.","steps":[{"prompt":"Ms Rao asks: \"Before we begin, is there anything you need from us?\"","options":[{"text":"\"Sorry to bother you. Only if it's no trouble.\"","then":"\"It's no bother,\" she says, and moves straight on to the form."},{"text":"\"Nothing. I just want him punished.\"","then":"\"We'll inquire first,\" she says, and picks up her pen."},{"text":"\"I'd like this kept confidential, please.\"","then":"\"Of course,\" she says, and notes it at the top of the file.","best":true},{"text":"\"Could my friend tell it for me? I'm nervous.\"","then":"\"We'll need to hear it from you, but take your time.\""}],"why":"Asking for confidentiality at the start is your right, and it protects you."},{"prompt":"Ms Rao asks: \"Do you still work closely with him day to day?\"","options":[{"text":"\"Yes, but I'll manage. I don't want to cause trouble.\"","then":"She nods and writes 'no request'. The daily contact stays."},{"text":"\"Yes. I'd like interim relief while you inquire.\"","then":"\"We can recommend a transfer or leave,\" she says. \"Which would help?\"","best":true},{"text":"\"Yes. Can you just tell him to keep away?\"","then":"\"We don't pass messages,\" she says. \"What do you need from us?\""},{"text":"\"Yes, so please suspend him before anything else.\"","then":"\"We can't decide that before the inquiry,\" she says."}],"why":"Interim relief, like a transfer or leave, protects you while the inquiry runs."},{"prompt":"Ms Rao asks: \"Has anything changed at work since you decided to complain?\"","options":[{"text":"\"It's nothing. I'm probably imagining it.\"","then":"She pauses, then moves on. The pressure goes unrecorded."},{"text":"\"He's been awful, but I'll deal with him myself.\"","then":"She frowns. \"Please tell us what's happening instead.\""},{"text":"\"Yes, and I want you to warn him today.\"","then":"\"We'll follow the process,\" she says, and asks for details."},{"text":"\"He's been cold, and I've noted each time with dates.\"","then":"\"Thank you. That goes on the record,\" she says.","best":true}],"why":"Telling the committee about new pressure puts it on record. It's never your fault."},{"prompt":"Ms Rao asks: \"Do you have someone to talk to while this goes on?\"","options":[{"text":"\"No. I haven't told anyone, and I won't.\"","then":"She nods. \"That's your choice. It's a lot to carry alone, though.\""},{"text":"\"My cousin knows. I'll also call NALSA 15100.\"","then":"\"Good,\" she says. \"Lean on both. None of this is your fault.\"","best":true},{"text":"\"Only if you can promise this ends quickly.\"","then":"\"I can't promise how long it takes,\" she says gently."},{"text":"\"I'll tell my whole team, so they're on my side.\"","then":"She frowns. \"That could make it harder to keep this confidential.\""}],"why":"Someone you trust and free legal aid on 15100 mean you don't face this alone. It's never your fault."}],"relearn":"At the committee you can ask for confidentiality and interim relief while your complaint is heard."},
  {"id":"kr-1120","cat":"harassment-and-posh","type":"role-play","persona":"any","source":"fault is his","hook":"Your friend Ishita was harassed by a senior at her office, and she's struggling.","setup":"She calls you late at night, her voice unsteady.","steps":[{"prompt":"Ishita says: \"Maybe I caused it somehow. I did laugh at his jokes.\"","options":[{"text":"\"Maybe think about what you could do differently.\"","then":"Ishita goes silent. \"So it is my fault.\""},{"text":"\"Laughing is normal. Anyway, just forget him.\"","then":"\"I can't just forget him,\" she says."},{"text":"\"You didn't cause this. The fault is his.\"","then":"She breathes out. \"I needed to hear that.\"","best":true},{"text":"\"Tell me everything he did, from the start.\"","then":"Ishita hesitates. \"I'm not ready to go over all of it.\""}],"why":"Laughing at a joke never invites harassment. The fault is always his."},{"prompt":"Ishita says: \"I don't even know if I want to complain.\"","options":[{"text":"\"You have to, or he'll do it to someone else.\"","then":"Ishita tenses. \"So now that's on me too?\""},{"text":"\"That's your call. I'm with you either way.\"","then":"\"Thank you,\" she says quietly. \"I'll think about it.\"","best":true},{"text":"\"Don't. It'll only make your life harder.\"","then":"\"Maybe,\" she says, sounding more trapped."},{"text":"\"Let me call your manager and handle it.\"","then":"\"Please don't. I'm not ready.\""}],"why":"Leaving the choice to her respects her pace. Your support doesn't depend on what she decides."},{"prompt":"Ishita asks: \"If I do complain, will anyone take me seriously?\"","options":[{"text":"\"Honestly, these things rarely go anywhere.\"","then":"Ishita sighs. \"That's what I was afraid of.\""},{"text":"\"Of course. You'll definitely win.\"","then":"\"You can't promise that,\" she says."},{"text":"\"Only if you have videos or photos.\"","then":"\"I don't have any,\" she says, deflated."},{"text":"\"The law is on your side. There's a committee.\"","then":"\"At my office?\" she asks, curious now.","best":true}],"why":"The committee exists to hear her. Honest support gives no false promises."}],"relearn":"Tell a harassed friend they didn't cause it; the fault is the harasser's."},
  {"id":"kr-1121","cat":"harassment-and-posh","type":"role-play","persona":"Aarti","source":"hold your ground","hook":"During your internship you filed a harassment complaint, and now HR has called you in.","setup":"Mrs Bedi from HR closes her laptop as you sit down.","steps":[{"prompt":"Mrs Bedi says: \"Just drop it. It'll be easier for everyone.\"","options":[{"text":"\"Maybe it isn't serious enough for a committee.\"","then":"\"Exactly,\" she says, relieved. \"Let's keep it simple.\""},{"text":"\"Easier for whom? You're protecting him!\"","then":"She stiffens. \"I'd watch that tone.\""},{"text":"\"I'd like it placed before the committee, please.\"","then":"She pauses. \"Well, if you insist, I'll forward it.\"","best":true},{"text":"\"Could we sort it out, just the three of us?\"","then":"\"Good idea. I'll set up a chat with him,\" she says."}],"why":"You can politely insist on the committee. HR can't drop it for you, and none of this is your fault."},{"prompt":"Mrs Bedi adds: \"One more thing. He's senior, and he writes your certificate.\"","options":[{"text":"\"Maybe interns just can't complain about seniors.\"","then":"\"That's how it works,\" she says, and reaches for the file."},{"text":"\"I know. Punishing a complaint isn't allowed.\"","then":"She blinks. \"Nobody said anything about punishing.\"","best":true},{"text":"\"Are you threatening me? I'll go to the media.\"","then":"\"Nobody is threatening anyone,\" she says coldly."},{"text":"\"Then I guess complaining costs me my certificate.\"","then":"She doesn't correct you, and you leave dreading the certificate."}],"why":"Retaliation for a complaint isn't allowed, and saying so calmly shows you know it."},{"prompt":"Your classmate Payal asks later: \"How did the HR meeting go?\"","options":[{"text":"\"Fine. Maybe I'm making too much of it.\"","then":"Payal frowns. \"Are you sure? You were so upset.\""},{"text":"\"They pushed me to drop it. I've written it down.\"","then":"\"Send that to the committee too,\" Payal says. \"I'll help.\"","best":true},{"text":"\"Terrible. I'm posting the whole thing online.\"","then":"\"Wait,\" Payal says. \"Could that hurt your complaint?\""},{"text":"\"I'll just wait and see what HR does next.\"","then":"\"And if they do nothing?\" Payal asks."}],"why":"Recording HR's pressure and sharing it with someone you trust keeps you supported and on record."}],"relearn":"You can politely insist your complaint be placed before the committee, not dropped."},
  {"id":"kr-1122","cat":"harassment-and-posh","type":"role-play","persona":"Mehta","source":"intern reassure","hook":"Shruti, a new intern at your office, stops by your desk looking nervous.","setup":"She glances around before she speaks.","steps":[{"prompt":"Shruti asks quietly: \"Am I even allowed to complain? I'm only an intern.\"","options":[{"text":"\"Hmm, not sure interns count. Better not risk it.\"","then":"\"Oh,\" she says, and steps back from the desk."},{"text":"\"Depends. Is it serious enough to complain about?\"","then":"Shruti hesitates. \"I don't know. Maybe not.\""},{"text":"\"Yes. Interns are covered, and it's confidential.\"","then":"Her shoulders drop. \"Really? I thought it was only for staff.\"","best":true},{"text":"\"Tell me who it is and I'll deal with him.\"","then":"\"No, wait,\" she says. \"I don't want a fuss.\""}],"why":"Interns are covered, and complaints to the committee are confidential."},{"prompt":"Shruti adds: \"He's the one who signs my internship certificate.\"","options":[{"text":"\"Then maybe wait until you have the certificate.\"","then":"\"Two more months of this?\" she says quietly."},{"text":"\"That's how it works. Seniors hold the cards.\"","then":"Shruti looks down. \"So I'm stuck.\""},{"text":"\"The committee can ask for someone else to assess you.\"","then":"\"I didn't know that was possible,\" she says, thinking.","best":true},{"text":"\"I'll make sure he gives you a fair one.\"","then":"\"How would you do that?\" she asks, unsure."}],"why":"The committee can recommend that he doesn't assess her work, and punishing a complaint isn't allowed."},{"prompt":"Shruti says: \"I'm not sure I'm ready to decide anything yet.\"","options":[{"text":"\"Don't wait too long, or it could be too late to act.\"","then":"Shruti's face tightens with a new worry."},{"text":"\"It's not your fault. I'm here when you're ready.\"","then":"\"Thank you,\" she says. \"Can I ask you more later?\"","best":true},{"text":"\"If you won't complain, I can't really help.\"","then":"\"Oh. Okay,\" she says, and leaves quickly."},{"text":"\"Fine, but let me tell HR about it, just in case.\"","then":"\"Please don't. Not yet,\" she says."}],"why":"Respecting her pace keeps her trust, and she knows where to come back. It's never her fault."}],"relearn":"Tell a worried intern she is covered and can complain to the committee confidentially."},
  {"id":"kr-1123","cat":"harassment-and-posh","type":"role-play","persona":"any","source":"refuse silencing","hook":"You're about to report a colleague, Manav, for harassment, and he has found out.","setup":"He walks up to your desk while others are nearby.","steps":[{"prompt":"Manav says: \"Report me and I'll tell everyone about your personal life.\"","options":[{"text":"\"I shouldn't have told anyone personal things.\"","then":"He smiles. \"Exactly. So let's both stay quiet.\""},{"text":"\"Threatening me for reporting is wrong. I'm noting it.\"","then":"He hesitates, then shrugs. \"Do what you want.\"","best":true},{"text":"\"Go ahead. I'll spread worse things about you.\"","then":"\"Let's see who people believe,\" he says."},{"text":"\"Can we talk this through, off the record?\"","then":"\"Sure. Drop it and we're fine,\" he says."}],"why":"A threat to stop you reporting is itself wrong, and noting it adds to your complaint."},{"prompt":"That evening, your flatmate Rukhsar asks: \"You're quiet. Is it about work?\"","options":[{"text":"\"It's nothing. I'll handle it myself.\"","then":"Rukhsar lets it go, and you spend the night worrying alone."},{"text":"\"Maybe I brought all this on myself.\"","then":"\"No. He's the one making threats,\" Rukhsar says firmly."},{"text":"\"Yes. He's threatening me. Help me with the complaint?\"","then":"\"I'm with you,\" Rukhsar says. \"Let's write it all down.\"","best":true},{"text":"\"I'll tell you if you promise never to mention it.\"","then":"\"Okay,\" she says, \"but that makes it hard to help.\""}],"why":"Someone you trust means you don't face threats alone. It's never your fault."},{"prompt":"At the committee, Mr Joseph asks: \"Is there anything else we should know?\"","options":[{"text":"\"No. The threat isn't part of my complaint.\"","then":"He nods and closes the file. The threat goes unmentioned."},{"text":"\"He said things, but maybe he didn't mean them.\"","then":"\"Can you tell us exactly what he said?\" he asks."},{"text":"\"Yes. He threatened to spread rumours if I reported.\"","then":"\"Thank you. We'll record that,\" he says, writing it down.","best":true},{"text":"\"Only that he should be fired immediately.\"","then":"\"We'll inquire first,\" he says. \"Anything else?\""}],"why":"A threat for reporting is retaliation, and the committee needs to know about it."}],"relearn":"A threat for reporting is itself wrong; you can refuse to be silenced and note the threat."},
  {"id":"kr-1124","cat":"harassment-and-posh","type":"reflect","hook":"Lensy: realising harassment is the harasser's wrong, not your shame, can lift a real weight. Does it?","prompt":"What do you think?","options":["It does","Not my shame","A weight lifts"],"affirm":"The shame was never yours to carry; harassment is the harasser's wrong, and naming that frees you to act.","relearn":"Harassment is the harasser's wrong, not your shame.","persona":"any","source":"not your shame"},
  {"id":"kr-1125","cat":"harassment-and-posh","type":"reflect","hook":"Lensy: a safe, dignified workplace is something you're owed, not a favour you must earn. Sit with that?","prompt":"What do you think?","options":["Yes","I'm owed it","Not a favour"],"affirm":"Dignity at work isn't a perk handed to the lucky; it's owed to you, and the law backs that.","relearn":"A safe, dignified workplace is owed to you, not a favour you earn.","persona":"Meena","source":"owed not favour"},
  {"id":"kr-1126","cat":"harassment-and-posh","type":"reflect","hook":"Lensy: knowing there's a confidential committee can make speaking up feel less frightening. Does it for you?","prompt":"What do you think?","options":["Yes","Less scary","Good to know"],"affirm":"A confidential route means speaking up doesn't have to mean exposure; that can make the first step feel possible.","relearn":"A confidential committee can make speaking up feel less frightening.","persona":"any","source":"less frightening"},
  {"id":"kr-1127","cat":"harassment-and-posh","type":"reflect","hook":"Lensy: supporting a harassed colleague, even quietly, can change how alone they feel. Worth doing?","prompt":"What do you think?","options":["Yes","Worth it","I'd help"],"affirm":"One believing voice can break the isolation harassment creates; your support genuinely matters.","relearn":"Supporting a harassed colleague, even quietly, eases how alone they feel.","persona":"Rohan","source":"support matters"},
  {"id":"kr-1128","cat":"harassment-and-posh","type":"reflect","hook":"Lensy: you can take it at your own pace. There's no rule that you must report the instant it happens. Reassuring?","prompt":"What do you think?","options":["Yes","My pace","Reassuring"],"affirm":"There's a window, and it can extend; you get to choose when you're ready, not be rushed.","relearn":"You can report at your own pace; there's a window and it can be extended.","persona":"any","source":"your own pace"},
  {"id":"kr-1129","cat":"harassment-and-posh","type":"reflect","hook":"Lensy: even a small workplace or short internship doesn't put you outside these protections. Good to know?","prompt":"What do you think?","options":["Yes","I'm covered","Good to know"],"affirm":"Small employer, short stint, contract role: none of it places you outside the right to a safe workplace.","relearn":"A small workplace or short internship doesn't put you outside these protections.","persona":"Aarti","source":"still covered"},
  {"id":"kr-1130","cat":"harassment-and-posh","type":"reflect","hook":"Lensy: free legal aid means claiming this right never has to depend on how much money you have. Sit with that?","prompt":"What do you think?","options":["Yes","Money-free","Reassuring"],"affirm":"Your rights don't have a price tag; free legal aid exists so cost is never what stops you.","relearn":"Free legal aid means claiming this right doesn't depend on having money.","persona":"Farhan","source":"not about money"},
  {"id":"kr-1131","cat":"harassment-and-posh","type":"spot","hook":"Spot the two lines that are harassment myths, not facts.","scene":[{"id":"a","text":"You can complain even without witnesses","trick":false},{"id":"b","text":"Interns and contract staff aren't really covered","trick":true},{"id":"c","text":"The complaint process is confidential","trick":false},{"id":"d","text":"You must always confront the harasser alone first","trick":true},{"id":"e","text":"Retaliation for a good-faith complaint is unlawful","trick":false}],"why":"'Interns aren't covered' and 'you must confront them alone' are myths; the rest are true.","relearn":"Interns are covered and you needn't confront anyone alone first; those two are myths.","persona":"any","source":"spot the myths"},
  {"id":"kr-1132","cat":"harassment-and-posh","type":"spot","hook":"Spot the two things that are NOT how a fair process works.","scene":[{"id":"a","text":"Your identity is kept confidential","trick":false},{"id":"b","text":"You can ask for interim relief","trick":false},{"id":"c","text":"You get punished for complaining","trick":true},{"id":"d","text":"You're forced to settle privately with him","trick":true},{"id":"e","text":"Free legal aid is there if you can't pay","trick":false}],"why":"Punishment for complaining and a forced private settlement are both wrong; the rest are right.","relearn":"Punishment for complaining and a forced settlement are wrong; confidentiality and free aid are right.","persona":"any","source":"spot unfair"},
  {"id":"kr-1133","cat":"harassment-and-posh","type":"spot","hook":"Spot the two lines a harasser uses to silence you.","scene":[{"id":"a","text":"\"No one will believe an intern over me\"","trick":true},{"id":"b","text":"You have a right to a safe workplace","trick":false},{"id":"c","text":"\"Complain and your career is finished here\"","trick":true},{"id":"d","text":"The process is meant to protect your identity","trick":false},{"id":"e","text":"Retaliation for complaining is itself unlawful","trick":false}],"why":"'No one will believe an intern' and 'your career is finished' are silencing tactics; the rest are your real protections.","relearn":"Disbelief and career threats are silencing tactics; your protections are real.","persona":"any","source":"spot silencing"},
  {"id":"kr-1134","cat":"harassment-and-posh","type":"spot","hook":"Spot the two claims that are victim-blaming, not fact.","scene":[{"id":"a","text":"The fault for harassment is the harasser's","trick":false},{"id":"b","text":"\"She must have invited it somehow\"","trick":true},{"id":"c","text":"\"What was she wearing, anyway?\"","trick":true},{"id":"d","text":"You can complain confidentially","trick":false},{"id":"e","text":"Harassment is never the price of a job","trick":false}],"why":"'She invited it' and 'what was she wearing' shift blame to the target; the rest keep fault where it belongs.","relearn":"'She invited it' and 'what was she wearing' are victim-blaming; the fault is always the harasser's.","persona":"any","source":"spot victim-blaming"},
  {"id":"kr-1135","cat":"harassment-and-posh","type":"spot","hook":"Spot the two steps that would weaken a harassment complaint.","scene":[{"id":"a","text":"Saving dated messages and emails","trick":false},{"id":"b","text":"Deleting everything to avoid drama","trick":true},{"id":"c","text":"Writing to the Internal Committee","trick":false},{"id":"d","text":"Telling no one and waiting many years","trick":true},{"id":"e","text":"Asking about confidentiality","trick":false}],"why":"Deleting evidence and a long silence weaken a complaint; saving records, filing and asking about confidentiality strengthen it.","relearn":"Deleting evidence and long silence weaken a complaint; saving records and filing strengthen it.","persona":"any","source":"spot weakeners"},
  {"id":"kr-1136","cat":"harassment-and-posh","type":"spot","hook":"Spot the two things that do NOT remove your right to complain.","scene":[{"id":"a","text":"Being only an intern","trick":true},{"id":"b","text":"Genuinely giving your consent to the conduct","trick":false},{"id":"c","text":"Working at a tiny 5-person shop","trick":true},{"id":"d","text":"The conduct actually being welcome to you","trick":false},{"id":"e","text":"There being no harassment at all","trick":false}],"why":"Being an intern or at a tiny shop doesn't remove the right; genuine consent or welcome conduct means there's no harassment to complain of.","relearn":"Being an intern or at a tiny workplace doesn't remove your right to complain.","persona":"any","source":"spot non-barriers"},
  {"id":"kr-1137","cat":"harassment-and-posh","type":"spot","hook":"Spot the two replies that would shut a survivor down.","scene":[{"id":"a","text":"\"I believe you, and it's not your fault\"","trick":false},{"id":"b","text":"\"Are you sure you're not overreacting?\"","trick":true},{"id":"c","text":"\"You can complain confidentially, at your pace\"","trick":false},{"id":"d","text":"\"Maybe just don't make a fuss\"","trick":true},{"id":"e","text":"\"There's a committee that has to look into this\"","trick":false}],"why":"'Are you overreacting' and 'don't make a fuss' shut a survivor down; the others believe and inform them.","relearn":"'Are you overreacting' and 'don't make a fuss' shut a survivor down; believe and inform instead.","persona":"Mehta","source":"spot shutdowns"},
  {"id":"kr-1170","cat":"renting-and-consumer","type":"strike-rewrite","hook":"\"A verbal rent deal is enough; paper just slows things down.\"","myth":{"un":"A verbal rent deal is enough; paper just slows things down.","re":"A written rent agreement records terms and protects both tenant and landlord.","why":"If there's a dispute later, a verbal-only deal is very hard to prove."},"relearn":"Get the rent terms in writing; a written agreement protects both sides.","persona":"Meena","source":"written agreement"},
  {"id":"kr-1171","cat":"renting-and-consumer","type":"strike-rewrite","hook":"\"Tenants have no rights; the landlord can throw you out any day.\"","myth":{"un":"Tenants have no rights; the landlord can throw you out any day.","re":"'Instant eviction' is a myth; eviction has to follow the agreement and due process.","why":"A landlord can't lawfully turn you out overnight without proper notice."},"relearn":"'Instant eviction' and 'tenants have no rights' are myths.","persona":"Meena","source":"eviction myth"},
  {"id":"kr-1172","cat":"renting-and-consumer","type":"strike-rewrite","hook":"\"No bill means you can't complain about a faulty phone.\"","myth":{"un":"No bill means you can't complain about a faulty phone.","re":"You have consumer rights on defective goods, and a bill is the simplest proof, so always keep it.","why":"Without proof the complaint is harder, which is exactly why you save the bill."},"relearn":"Keep the bill; it's your simplest proof for a faulty-goods complaint.","persona":"any","source":"keep the bill"},
  {"id":"kr-1173","cat":"renting-and-consumer","type":"strike-rewrite","hook":"\"Once you've paid, a deal is final and can't be questioned.\"","myth":{"un":"Once you've paid, a deal is final and can't be questioned.","re":"Consumer law lets you seek refund or replacement for a defective good even after paying.","why":"Paying doesn't sign away your rights when the product is faulty."},"relearn":"Paying doesn't end your rights; defective goods can still be refunded or replaced.","persona":"any","source":"after paying"},
  {"id":"kr-1174","cat":"renting-and-consumer","type":"strike-rewrite","hook":"\"Brokerage and a year's rent up front are normal; just pay it.\"","myth":{"un":"Brokerage and a year's rent up front are normal; just pay it.","re":"You can ask what each charge is for and get a receipt; nothing has to be paid blindly.","why":"An itemised, receipted demand is how you tell a real charge from an inflated one."},"relearn":"Ask what each charge is for and get a receipt before you pay.","persona":"Meena","source":"upfront charges"},
  {"id":"kr-1175","cat":"renting-and-consumer","type":"strike-rewrite","hook":"\"A 'no refund, no exchange' board means you've no rights.\"","myth":{"un":"A 'no refund, no exchange' board means you've no rights.","re":"A shop notice can't cancel your consumer rights on a genuinely defective good.","why":"A store sign doesn't override the law on faulty products."},"relearn":"A 'no refund' sign can't take away your rights on a defective good.","persona":"any","source":"no refund sign"},
  {"id":"kr-1176","cat":"renting-and-consumer","type":"strike-rewrite","hook":"\"Asking for the deposit back will just get you a bad name.\"","myth":{"un":"Asking for the deposit back will just get you a bad name.","re":"Asking for your returnable deposit is a normal, fair request, not a quarrel.","why":"A deposit is your money held in trust, not a gift to the landlord."},"relearn":"Asking for your returnable deposit back is fair and normal.","persona":"any","source":"deposit is yours"},
  {"id":"kr-1177","cat":"renting-and-consumer","type":"strike-rewrite","hook":"\"An online order gone wrong is just bad luck; you can't do anything.\"","myth":{"un":"An online order gone wrong is just bad luck; you can't do anything.","re":"Online buyers have the same consumer rights, plus a complaint route for the defect or non-delivery.","why":"Buying online doesn't lower your protection on faulty or undelivered goods."},"relearn":"Online buyers have consumer rights too, with a real complaint route.","persona":"any","source":"online consumer"},
  {"id":"kr-1178","cat":"renting-and-consumer","type":"branch","persona":"Meena","source":"mid-lease change","hook":"Mid-lease, your landlord Mr Sethi raises the rent and threatens to lock you out if you refuse.","steps":[{"prompt":"He wants the higher rent from this month. What do you do?","options":[{"text":"Assume a landlord can change rent anytime","then":"You start cutting back to find the extra money."},{"text":"Point to the agreement and ask for any change in writing","then":"Mr Sethi grumbles, but says he'll 'think about it'.","best":true},{"text":"Refuse and stop speaking to him","then":"He sends an angry voice note, and nothing is settled."},{"text":"Ask the neighbours if he did this to them too","then":"They nod, but nobody knows what to do."}],"why":"A signed agreement binds both sides for its term. Any change belongs in writing."},{"prompt":"Days later, he says he'll change the lock if you don't pay by Sunday. What do you tell yourself?","options":[{"text":"He owns the room, so he can do what he likes","then":"You start packing, just in case."},{"text":"I must have done something to upset him","then":"You go over every chat, hunting for your mistake."},{"text":"A lock-out isn't a lawful way to evict me","then":"You feel steadier and start noting his threats with dates.","best":true},{"text":"It's just talk, so I'll ignore it","then":"You put it out of your mind, and Sunday creeps closer."}],"why":"Eviction needs a proper legal process, so locking you out isn't lawful. His threat is not your fault."},{"prompt":"On Sunday he messages: \"Pay or find a new place.\" What do you do?","options":[{"text":"Believe a lock-out is legal if he warns first","then":"You lie awake, sure he's within his rights."},{"text":"Threaten to break his things if he locks me out","then":"He screenshots it and shows it to the neighbours."},{"text":"Ask my uncle to phone him and deal with it","then":"Your uncle shouts at him, and things get worse."},{"text":"Save his messages and call NALSA 15100","then":"A legal aid worker explains how to reply to him in writing.","best":true}],"why":"Saving his threats and getting free legal advice gives you a real way to respond."},{"prompt":"Your co-worker Rani has the same trouble with her landlord. What do you tell her?","options":[{"text":"Keep the agreement handy, and get changes in writing","then":"Rani nods. \"I didn't know the signed terms bind him too.\"","best":true},{"text":"Just pay. Landlords always win these","then":"Rani sighs and hands over the extra money."},{"text":"Move out before he can lock you out","then":"Rani starts hunting for a room she can't afford."},{"text":"Hire a private lawyer before you speak to him","then":"Rani worries about the cost and does nothing."}],"why":"The signed terms bind both sides, and putting things in writing protects her."}],"debrief":"A signed lease binds both sides, and mid-lease changes belong in writing.","relearn":"Hold a landlord to the signed terms; any change should be in writing."},
  {"id":"kr-1179","cat":"renting-and-consumer","type":"branch","persona":"any","source":"deposit return","hook":"You left your rented flat spotless, but the owner, Mr Pillai, still hasn't returned your deposit.","steps":[{"prompt":"It's been three weeks, and he keeps saying 'next week'. What do you do?","options":[{"text":"Keep calling him angrily until he pays","then":"He picks up less and less, and you have nothing in writing."},{"text":"Send my photos and ask for it by a set date","then":"He reads it and replies, \"Will check and revert.\"","best":true},{"text":"Wait another month. He'll pay eventually","then":"Another month passes with the same promise."},{"text":"Post about him on the society WhatsApp group","then":"Neighbours take sides, and Mr Pillai turns curt and cold with you."}],"why":"Photos plus a dated, specific request make a clear case that's hard to ignore."},{"prompt":"Mr Pillai now says he'll keep a month's rent for 'repainting'. What do you ask for?","options":[{"text":"Nothing. Repainting sounds reasonable","then":"A month's rent quietly disappears from your deposit."},{"text":"A full refund, or I'll go to the police","then":"He shrugs and says the police don't deal with deposits."},{"text":"An itemised bill for the repainting cost","then":"He goes quiet, then says he'll 'look into the amount'.","best":true},{"text":"That he splits the cost with me","then":"He agrees fast, and you pay for something you may not owe."}],"why":"Deductions must be genuine and documented. An itemised bill shows whether they are."},{"prompt":"Your old flatmate says to take whatever Mr Pillai offers and move on. What do you do?","options":[{"text":"Take it, since arguing isn't worth it","then":"You settle for less than you may be owed."},{"text":"Check his claim against my move-out photos","then":"Your photos show clean walls, with nothing worth repainting.","best":true},{"text":"Refuse any deduction, whatever the facts","then":"It feels firm, but it leaves no room to settle what's fair."},{"text":"Let my flatmate negotiate for me","then":"Your flatmate agrees to a number without checking with you."}],"why":"Your own records show what's fair, instead of guessing or giving in."},{"prompt":"Two more weeks pass with no money and no reply. What do you do?","options":[{"text":"Assume owners can keep deposits if they like","then":"You stop chasing it, and the money is gone."},{"text":"Go to his house and refuse to leave","then":"Voices rise at his door, and you walk away rattled."},{"text":"Call NALSA 15100 for free legal advice","then":"A legal aid worker helps you draft a formal notice for the deposit.","best":true},{"text":"Keep texting him every day","then":"The messages pile up, unanswered."}],"why":"Free legal aid on 15100 can help you send a formal notice, without paying a lawyer."},{"prompt":"A friend about to rent asks how to avoid this. What do you tell her?","options":[{"text":"Choose an owner who seems friendly","then":"She nods, though friendly owners can dispute deposits too."},{"text":"Pay the smallest deposit and skip the papers","then":"She saves a little, but has nothing to show if it goes wrong."},{"text":"Expect to lose the deposit anyway","then":"She sighs, already resigned to it."},{"text":"Get a receipt, an agreement and move-in photos","then":"She notes it down. \"And send the photos to the owner?\"","best":true}],"why":"Receipts, a written agreement and photos protect a deposit from the very first day."}],"debrief":"Documented condition plus a dated, specific request is how you claim a returnable deposit.","relearn":"Use move-in photos and a dated request to claim a withheld deposit."},
  {"id":"kr-1180","cat":"renting-and-consumer","type":"branch","persona":"any","source":"warranty claim","hook":"Your washing machine breaks down within warranty, and the shop says 'company problem, not ours'.","steps":[{"prompt":"The shop owner waves you towards the brand's number. What do you do?","options":[{"text":"Post an angry video about the shop online","then":"The shop owner sees it and stops helping. Days later, the brand books a visit."},{"text":"Accept it's the brand's job, and call them myself","then":"An agent books a visit, but shares no complaint number."},{"text":"Show the bill and warranty, and ask him to act","then":"He looks at the bill and agrees to log a complaint with the brand.","best":true},{"text":"Keep going back to the shop until they act","then":"After three visits, he calls the brand just to get rid of you."}],"why":"Your bill and warranty are proof, and the seller can't simply pass you around."},{"prompt":"A technician checks the machine and says a part will take 'some time'. What do you ask for?","options":[{"text":"Nothing. I'll wait as long as it takes","then":"Weeks pass with no update."},{"text":"A complaint number and a date, in writing","then":"He writes both on the job sheet and hands you a copy.","best":true},{"text":"A cash discount so I can fix it myself","then":"He shrugs. Outside repairs may not be covered by the warranty."},{"text":"His personal number, to chase him directly","then":"He gives it, but stops answering after two calls."}],"why":"A complaint number and a written date make any delay traceable."},{"prompt":"Three weeks on, the machine is still broken. What do you do?","options":[{"text":"Pay a local mechanic and forget the warranty","then":"The mechanic can't find the part, and the warranty may no longer cover it."},{"text":"Leave furious reviews everywhere","then":"The reviews get likes, but the machine stays broken."},{"text":"Send a written complaint to the shop and brand","then":"Both reply within a week, each with a reference number.","best":true},{"text":"Keep calling customer care every day","then":"Each call gets a new agent and the same promise."}],"why":"A written complaint creates a record for the next step."},{"prompt":"A month later, it still isn't fixed. What's your next move?","options":[{"text":"Accept it's just bad luck with this brand","then":"The machine stays broken, and so does your budget."},{"text":"Go and threaten the shop owner in person","then":"He calls you a troublemaker and stops taking your calls."},{"text":"Wait another month, just in case","then":"Another month passes in silence."},{"text":"Use the consumer complaint route","then":"Your complaint is logged, with the bill, warranty and replies attached.","best":true}],"why":"The consumer route is the next step when the seller and brand don't act."}],"debrief":"A valid bill and warranty support repair, replacement or refund on a defective good.","relearn":"Use the bill and warranty to claim repair or replacement for a faulty good."},
  {"id":"kr-1181","cat":"renting-and-consumer","type":"branch","persona":"any","source":"silent seller","hook":"The ceiling fan you ordered online arrived with a bent blade, and the seller has stopped replying.","steps":[{"prompt":"Three messages to the seller have gone unanswered. What do you do?","options":[{"text":"Keep messaging the seller and hope","then":"Your fourth message shows 'seen'. Still no reply."},{"text":"Bend the blade back and use it anyway","then":"The fan wobbles loudly, and the defect is harder to show now."},{"text":"Send a written complaint with photos and order ID","then":"It goes in through the app's help page, with a timestamp.","best":true},{"text":"Post a video of the fan on social media","then":"It gets views, but the seller stays silent."}],"why":"A written complaint with photos and the order ID creates a clear record."},{"prompt":"You reach the app's support, and they say to 'contact the seller directly'. What do you do?","options":[{"text":"Go back to messaging the seller","then":"The chat stays silent, as before."},{"text":"Escalate to the app's grievance officer","then":"Support shares a ticket number and a date for a reply.","best":true},{"text":"Accept that the app isn't responsible","then":"You close the chat, and the fan goes back in its box."},{"text":"Leave a one-star rating and stop there","then":"The rating goes up, but nobody contacts you."}],"why":"Shopping apps must have a grievance officer, so you can escalate when a seller goes silent."},{"prompt":"A week later, the fan still hasn't been fixed or replaced. What do you do?","options":[{"text":"Assume small online buys aren't worth it","then":"You drop it, and the bent fan stays in its box."},{"text":"Call the cybercrime helpline 1930","then":"They listen, then point you to consumer routes for a faulty item."},{"text":"Use the consumer complaint route, with my records","then":"Your complaint is logged, with photos, order ID and chats attached.","best":true},{"text":"Keep chasing the app's chat every day","then":"Every chat ends with 'we're looking into it'."}],"why":"A defective item is a consumer matter, and your records back the complaint."},{"prompt":"Your roommate Arjun says online sellers can't be held to anything. What do you tell him?","options":[{"text":"He's right. That's the risk of ordering online","then":"Arjun nods, and neither of you complains again."},{"text":"Only if you paid by card, not UPI","then":"Arjun nods and checks how he paid last time."},{"text":"Consumer rights apply to online buys too","then":"Arjun frowns. \"So my broken headphones count too?\"","best":true},{"text":"Only if the seller has a real shop as well","then":"Arjun decides his online order doesn't count."}],"why":"Consumer rights cover what you buy online, just as in a shop."}],"debrief":"For a silent seller, a written complaint and the consumer route are the escalation.","relearn":"For a silent seller, file a written complaint and use the consumer route."},
  {"id":"kr-1182","cat":"renting-and-consumer","type":"branch","persona":"any","source":"unseen rental","hook":"A 'broker' on a housing group asks for a token deposit by UPI for a flat you've only seen in photos.","steps":[{"prompt":"He says three others want it, so pay now to hold it. What do you do?","options":[{"text":"Pay the token so I don't lose the flat","then":"He confirms receipt, then asks for the full deposit before any visit."},{"text":"Refuse to pay until I've seen it and met the owner","then":"He sends an annoyed voice note and says he'll 'try to hold it'.","best":true},{"text":"Pay half the token as a middle path","then":"He takes it and asks for the rest to 'confirm'."},{"text":"Ask him for more photos and a video first","then":"More photos arrive. They look great and prove nothing about ownership."}],"why":"Paying before viewing is a classic scam pattern. See the flat and meet the owner first."},{"prompt":"He says the owner lives abroad and can't meet anyone. What do you do?","options":[{"text":"Believe him, since many owners live abroad","then":"He sends a bank account in someone else's name for the deposit."},{"text":"Ask a friend to check the building from outside","then":"Your friend finds the building, but not who owns the flat."},{"text":"Send him my Aadhaar to speed things up","then":"He thanks you, and now a stranger has your ID."},{"text":"Insist on a visit and proof of ownership first","then":"He goes quiet, then stops replying.","best":true}],"why":"A real rental can be checked. A broker who dodges that is a warning sign."},{"prompt":"Your friend Kabir paid a similar 'broker', and the number is now switched off. What do you tell him?","options":[{"text":"Write it off. That money is gone","then":"Kabir sighs, and the broker's next ad goes up the same day."},{"text":"Keep calling until the number works","then":"It stays switched off, and days slip by."},{"text":"Report it fast on 1930 or cybercrime.gov.in","then":"Kabir files it that night and gets a complaint number.","best":true},{"text":"Post the broker's number in every group","then":"People thank him, but no report is filed."}],"why":"Fast reporting on 1930 or cybercrime.gov.in helps with payment fraud."}],"debrief":"Upfront money for an unseen rental is a classic scam pattern.","relearn":"Don't pay for an unseen rental; verify the flat and owner first."},
  {"id":"kr-1183","cat":"renting-and-consumer","type":"branch","persona":"Meena","source":"hostel terms","hook":"At your job-linked hostel, the warden wants to keep your ID and says rent rules can change anytime.","steps":[{"prompt":"The warden, Mrs Gill, holds out her hand for your original Aadhaar card. What do you do?","options":[{"text":"Hand it over, since everyone else did","then":"The card goes into her drawer, and getting it back won't be easy."},{"text":"Offer a photocopy and keep the original","then":"She frowns, then accepts the copy for her records.","best":true},{"text":"Refuse to show any ID at all","then":"She says she can't register you without one, and you're stuck."},{"text":"Hand it over, but ask for it back next month","then":"She nods vaguely, and next month she's 'too busy'."}],"why":"A copy is enough for their records. Your original ID should stay with you."},{"prompt":"Mrs Gill says rent and rules are 'as per management'. What do you ask for?","options":[{"text":"Nothing, since the hostel comes with my job","then":"You settle in without knowing what you've agreed to."},{"text":"A verbal promise that the rent won't change","then":"She promises, and nothing is written down."},{"text":"The rent, rules and notice terms in writing","then":"She sighs, then prints a sheet with the rent and rules.","best":true},{"text":"A lower rent than the others pay","then":"She laughs it off, and the terms stay unclear."}],"why":"Written terms mean the rules can't simply change at someone's whim."},{"prompt":"Two months later, a notice says rent goes up from tomorrow. What do you do?","options":[{"text":"Pay it, since the notice is already up","then":"You pay, and your savings for home shrink."},{"text":"Get everyone to refuse to pay anything","then":"A few join in, the office threatens fines, and tension grows."},{"text":"Ask my supervisor to sort it out with the warden","then":"Your supervisor says it's not his department."},{"text":"Ask for the change and its reasons in writing","then":"The office agrees to give written notice and a start date.","best":true}],"why":"Asking for changes in writing, with notice, keeps the stay on a fair footing."},{"prompt":"Your new roommate Pinky asks whether to hand over her ID too. What do you tell her?","options":[{"text":"Give a photocopy, and keep the original with you","then":"Pinky slips her card back into her bag.","best":true},{"text":"Just give it. The warden asks everyone","then":"Pinky hands it over, and later can't open a bank account without it."},{"text":"Don't show any ID at all","then":"Pinky gets stuck at registration for a whole day."},{"text":"Give it, but take a photo of it first","then":"Pinky has a photo, but the original stays in the drawer."}],"why":"A copy meets the record-keeping need while the original stays with her."}],"debrief":"Even in job-linked housing, you can ask for written terms and keep your ID.","relearn":"Ask for written terms and keep your own ID in any rented housing."},
  {"id":"kr-1184","cat":"renting-and-consumer","type":"branch","persona":"any","source":"hidden clause","hook":"Before signing a rent agreement, you spot a 'non-refundable maintenance' charge nobody mentioned.","steps":[{"prompt":"The landlord, Mr Rao, says it's standard and hands you a pen. What do you do?","options":[{"text":"Sign now and argue about it later","then":"The ink dries, and the clause now binds you."},{"text":"Walk out without saying anything","then":"You leave, but it's the best room you've seen, so you call him back that evening."},{"text":"Ask him to explain the clause or remove it","then":"Mr Rao sighs and says it covers 'general upkeep'.","best":true},{"text":"Cross the clause out with my pen, and then sign","then":"Mr Rao notices and refuses to accept the changed copy."}],"why":"Questioning a clause before you sign is far easier than undoing it afterwards."},{"prompt":"He says the charge is for 'general upkeep' but won't name an amount. What do you ask for?","options":[{"text":"Nothing more. Upkeep sounds fair enough","then":"The clause stays vague, and so does the bill to come."},{"text":"A fixed amount and what it covers, in writing","then":"He writes a figure and a short list beside the clause.","best":true},{"text":"A lower monthly rent to make up for the charge","then":"He shrugs, and the vague clause stays in."},{"text":"My friend's view on whether it's normal","then":"Your friend says hers had one too. The amount is still unknown."}],"why":"A clear amount and purpose in writing stops a vague charge from growing later."},{"prompt":"Later, your sister says questioning landlords only annoys them. What do you tell her?","options":[{"text":"Maybe she's right. I shouldn't make a fuss","then":"She shrugs, and you feel oddly guilty."},{"text":"Landlords always cheat, so I trust nobody","then":"She raises an eyebrow. \"Every single one?\""},{"text":"If anything goes wrong later, I'll just sue him","then":"She laughs. \"That sounds like a long way round.\""},{"text":"Terms are easier to fix before signing than after","then":"She nods. \"I wish I'd done that with my flat.\"","best":true}],"why":"Settling unclear terms before signing protects you from surprises."}],"debrief":"Question and settle unclear clauses before you sign, not after.","relearn":"Question unclear clauses before signing, not after."},
  {"id":"kr-1185","cat":"renting-and-consumer","type":"branch","persona":"any","source":"only repair","hook":"Your new mixer keeps failing, and the shopkeeper insists it can 'only be repaired', never replaced.","steps":[{"prompt":"It's back from its second repair and fails again the same day. What do you do?","options":[{"text":"Accept a third repair, as he insists","then":"The mixer comes back in a week and fails again."},{"text":"Ask for a replacement or refund, not a third repair","then":"The shopkeeper hesitates and says he'll 'ask the company'.","best":true},{"text":"Buy a pricier model from him, at a small discount","then":"You pay again, and the faulty mixer is still yours to sort out."},{"text":"Say loudly that I'll never shop there again","then":"He shrugs. You leave with the broken mixer and no plan."}],"why":"For a defective good, replacement or refund is on the table, not just endless repair."},{"prompt":"On your next visit, he says company policy is 'repair only'. What do you do?","options":[{"text":"Believe the company's policy beats my rights","then":"You go home and fill in another repair form."},{"text":"Ask him to at least waive the next repair fee","then":"He agrees, and you're back to square one."},{"text":"Put my request in writing, with the repair slips","then":"Your letter lists both repairs and the dates it failed.","best":true},{"text":"Post the mixer's failures in the family group","then":"Relatives sympathise, but nothing reaches the shop."}],"why":"A written request with the repair slips shows a pattern of defects and backs your claim."},{"prompt":"A week later, the shop still offers only repair. What do you do next?","options":[{"text":"Give up. It's only a mixer","then":"The broken mixer sits on the shelf as a reminder."},{"text":"Leave it at the shop until they replace it","then":"It sits in their back room, and nothing moves."},{"text":"Ask a lawyer friend to phone the shop","then":"The shop says it will 'see', and nothing is written."},{"text":"Take it to the consumer complaint route","then":"Your complaint is logged, with the bill and every repair slip.","best":true}],"why":"The consumer route can order a replacement or refund when a product stays defective."}],"debrief":"For a defective good, remedies can include refund or replacement.","relearn":"Defective goods can be refunded or replaced, not just repaired."},
  {"id":"kr-1186","cat":"renting-and-consumer","type":"branch","persona":"Meena","source":"cash deposit","hook":"You paid your room deposit to your landlord, Mr Bhatt, in cash, and never got a receipt.","steps":[{"prompt":"When you give notice, he says you never paid any deposit at all. What do you do?","options":[{"text":"Argue with him loudly, even without proof","then":"He shouts back, and it ends as your word against his."},{"text":"Accept the loss, since there's no receipt","then":"The money is gone, and he feels free to do it again."},{"text":"Gather any UPI, chat or witness proof I have","then":"You find a WhatsApp message where he wrote 'received, thanks'.","best":true},{"text":"Ask him to split the difference with me","then":"He offers a small amount 'as a favour' and calls it settled."}],"why":"Any UPI, chat or witness record helps rebuild the trail."},{"prompt":"Your cousin Ritu was with you when you paid. What do you ask her?","options":[{"text":"To come and shout at Mr Bhatt with me","then":"Ritu is willing, but it would just be two voices against one."},{"text":"To write a short, dated note of what she saw","then":"Ritu writes it that evening and signs it.","best":true},{"text":"To lend me money to cover the loss","then":"Ritu lends it, and the real problem stays unsolved."},{"text":"Nothing. She's family, so it won't count","then":"You leave out the one person who saw you pay."}],"why":"A dated note from someone who saw you pay adds to your proof."},{"prompt":"You want to raise the deposit formally, but can't afford a lawyer. What do you do?","options":[{"text":"Decide the law is only for people with money","then":"You let it go, and the deposit stays with him."},{"text":"Ask Mr Bhatt's neighbour to talk him round","then":"The neighbour tries, but Mr Bhatt won't budge."},{"text":"Post about him on the local WhatsApp group","then":"People react, but nothing formal happens."},{"text":"Call NALSA 15100 for free legal aid","then":"A legal aid worker explains how to send a notice with your proof.","best":true}],"why":"Free legal aid on 15100 means you don't need money to claim what's yours."},{"prompt":"You move to a new room next month. How do you pay the new deposit?","options":[{"text":"In cash, but with a friend watching","then":"Your friend sees it, but there's still no paper."},{"text":"In cash, since owners prefer it","then":"The owner smiles, and you're back where you started."},{"text":"By UPI, with a signed receipt","then":"The owner signs a receipt, and the UPI record backs it up.","best":true},{"text":"In small parts, so I never risk much","then":"By month three, half the payments have no record."}],"why":"A traceable payment plus a receipt means you never have to prove it from scratch."}],"debrief":"Cash with no receipt is the weak spot, and any UPI or chat record helps.","relearn":"Always get a receipt; collect any UPI or chat proof if you didn't."},
  {"id":"kr-1187","cat":"renting-and-consumer","type":"branch","persona":"any","source":"non-delivery","hook":"An app marks your shoes 'delivered', but they never came, and support keeps closing your ticket.","steps":[{"prompt":"Support closes your third ticket: 'delivered as per records'. What do you do?","options":[{"text":"Open a fourth ticket and hope for a new agent","then":"A new agent closes it with the same line."},{"text":"Assume the courier's record must be right","then":"You start doubting yourself, though your doorstep was empty."},{"text":"Ask the neighbours if someone took it","then":"Nobody saw anything, and the app's record stands."},{"text":"Save the tracking page, tickets and chat replies","then":"Screenshots of every closed ticket sit in one folder, with dates.","best":true}],"why":"Saved records show the pattern of closed tickets and back your non-delivery claim."},{"prompt":"The courier's delivery photo shows a door that isn't yours. What do you do?","options":[{"text":"Send it to the app's grievance officer in writing","then":"You get an acknowledgement and a date for a reply.","best":true},{"text":"Post the photo and tag the brand publicly","then":"It gets a canned 'DM us' reply, and nothing else."},{"text":"Go door to door looking for the parcel","then":"You spend an evening searching and find nothing."},{"text":"Let it go, since the photo 'proves' delivery","then":"The app keeps the order marked as delivered."}],"why":"The wrong-door photo is evidence, and the grievance officer is the next step up."},{"prompt":"A week later, the app sends a coupon 'for the inconvenience', and nothing else. What do you do?","options":[{"text":"Take the coupon and let it go","then":"You get a discount on your next order, and lose the shoes."},{"text":"Dispute it with my bank, and nothing else","then":"The bank asks for proof you've raised it formally with the seller."},{"text":"Decline, and use the consumer complaint route","then":"Your complaint is logged, with the photo and ticket history attached.","best":true},{"text":"Keep reopening tickets every day","then":"Each one closes within the hour."}],"why":"A false 'delivered' is a non-delivery dispute the consumer route can hear."},{"prompt":"Your flatmate says it isn't worth the effort for one pair of shoes. What do you say?","options":[{"text":"Maybe he's right. It's only shoes","then":"You drop it, and the app never hears from you again."},{"text":"I'll make sure that courier gets fired","then":"He raises an eyebrow. \"That's not really up to you.\""},{"text":"It's my money, and there's a route for this","then":"He shrugs. \"Fair. Tell me how it goes.\"","best":true},{"text":"I'll never order from any app again","then":"He laughs. \"By next week you will.\""}],"why":"Small amounts still carry your rights, and the route is there for them."}],"debrief":"A false 'delivered' is a non-delivery dispute, and records plus the consumer route help.","relearn":"For a false 'delivered', keep records and use the consumer route."},
  {"id":"kr-1188","cat":"renting-and-consumer","type":"branch","persona":"any","source":"shared deposit","hook":"Your two flatmates moved out, and the landlord, Mr Kulkarni, wants you to forfeit the whole shared deposit.","steps":[{"prompt":"He says their early exit broke the agreement for everyone. What do you do?","options":[{"text":"Accept that one early exit breaks it for all","then":"You start writing off your share without checking the agreement."},{"text":"Check the agreement and ask what's actually owed","then":"He reluctantly pulls it out. It asks for a month's notice.","best":true},{"text":"Tell him to chase my flatmates, not me","then":"He says he doesn't care who pays, and the standoff drags on."},{"text":"Stop paying rent until he backs down","then":"He says he'll take that out of the deposit too."}],"why":"Deductions should match the agreement and what's genuinely owed."},{"prompt":"Your flatmates gave two weeks' notice, not the month the agreement asks. What do you propose?","options":[{"text":"Letting him keep their shares, since they left early","then":"He agrees at once. You've given up far more than the notice gap."},{"text":"An itemised account, with the rest paid back","then":"He works out half a month's rent for the missing notice.","best":true},{"text":"Paying nothing, since it wasn't my fault","then":"He digs in, and nothing gets settled."},{"text":"Whatever amount he thinks is fair","then":"He names a big number, and you have nothing to compare it with."}],"why":"An itemised account ties any deduction to documented facts."},{"prompt":"You message your old flatmates, Tara and Imran, about the shortfall. What do you ask?","options":[{"text":"That we split it three ways, no questions","then":"It's quick, but you pay for a gap you didn't cause."},{"text":"That we settle who owes what by the agreement","then":"Tara agrees at once, and Imran asks to see the numbers.","best":true},{"text":"Nothing. I'll just cover it quietly","then":"You pay their share, and resentment builds."},{"text":"That they sort it out with him directly","then":"They ignore it, and he still comes to you."}],"why":"Settling shares by the agreement is fair and keeps everyone on the same terms."},{"prompt":"Mr Kulkarni says he'll return what's left 'someday'. What do you do?","options":[{"text":"Wait patiently. He'll get round to it","then":"Months pass, and 'someday' never arrives."},{"text":"Threaten to damage the flat if he doesn't pay","then":"He screenshots it, and now you're the one in trouble."},{"text":"Keep reminding him by phone","then":"He says 'yes, yes' each time, and nothing is written."},{"text":"Ask for the balance by a set date, in writing","then":"He replies with a date two weeks away.","best":true}],"why":"A written request with a date turns 'someday' into a clear deadline."}],"debrief":"A deposit is forfeited only for genuine, documented dues.","relearn":"Deductions must be genuine and documented; ask for an itemised account."},
  {"id":"kr-1189","cat":"renting-and-consumer","type":"branch","persona":"any","source":"pressure sale","hook":"A salesman at your door pushes a costly water-purifier EMI, saying the 'limited offer' ends today.","steps":[{"prompt":"He holds out a tablet and says to just sign here. What do you do?","options":[{"text":"Say yes, and sign when he comes back tonight","then":"He grins and says he'll bring the final form after dinner."},{"text":"Ask him to explain it all out loud instead","then":"He talks fast about 'low monthly amounts' and skips the fees."},{"text":"Decline today and ask for the full terms","then":"He frowns, then leaves a brochure and his card.","best":true},{"text":"Ask him to lower the price first","then":"He knocks off a little and pushes the tablet closer."}],"why":"'Offer ends today' pressure is a tactic. Reading the terms first protects you."},{"prompt":"Later, you look up the offer online. It lists a 'processing fee' with no amount. What do you do?","options":[{"text":"Assume it's a small fee, like most are","then":"You stop asking, and the real cost stays hidden from you."},{"text":"Ask the company in writing for the total cost","then":"They reply with the full cost, well above what he said.","best":true},{"text":"Ask my cousin, who bought a purifier","then":"Your cousin's plan was different, so it doesn't help."},{"text":"Ask the salesman, and take his word for it","then":"He says it's 'nothing much', and gives no figure."}],"why":"Getting the total cost in writing shows what you'd really be paying."},{"prompt":"The salesman calls back: \"Last chance. Sign now or lose it.\" What do you say?","options":[{"text":"Okay, fine. I'll sign now","then":"You sign under pressure, and the EMI starts next month."},{"text":"Never call me again, or I'll report you","then":"He hangs up, and you're no closer to a decision."},{"text":"I'll sign if you add free servicing","then":"He agrees, and you've signed an EMI you still haven't read."},{"text":"I'll decide in my own time, after comparing","then":"He hangs up. Next week, the same 'last chance' offer is back.","best":true}],"why":"Taking your own time is your right. A fair deal doesn't vanish because you read first."}],"debrief":"'Offer ends today' pressure is a red flag, so read before you sign an EMI.","relearn":"Don't sign under on-the-spot pressure; read the full terms first."},
  {"id":"kr-1190","cat":"renting-and-consumer","type":"branch","persona":"any","source":"bad service","hook":"A repair shop returns your laptop in worse shape and refuses to fix it or refund the fee.","steps":[{"prompt":"The shop insists the laptop was already old and it's not their fault. What do you do?","options":[{"text":"Pay another shop to fix it, and forget this one","then":"The second shop quotes double, and the first one still keeps your fee."},{"text":"Keep the job card and bill, and note what's worse","then":"You list the new faults beside the job card's notes.","best":true},{"text":"Argue at the counter until they give in","then":"They ask you to leave, and nothing is written."},{"text":"Accept that old laptops just break","then":"You carry it home, unsure what went wrong."}],"why":"The job card and bill show what you handed in and what you paid for."},{"prompt":"The job card says 'screen flicker only', but now the keyboard is dead too. What do you do?","options":[{"text":"Try to fix the keyboard myself","then":"You loosen a cable, and now it's harder to show what they did."},{"text":"Send the shop a written complaint with photos","then":"They reply that they'll 'check', and it's now in writing.","best":true},{"text":"Post the job card online to shame them","then":"People comment, but the shop ignores it."},{"text":"Ask the technician to redo it free, verbally","then":"He agrees, then says his boss said no."}],"why":"A written complaint with photos puts the poor service on record."},{"prompt":"When you next contact the shop, the owner says 'services aren't covered like products'. What do you tell yourself?","options":[{"text":"They're right. Services are a gamble","then":"You drop it, and the shop keeps your fee."},{"text":"Only big companies must fix bad service","then":"You let it go and budget for a new keyboard."},{"text":"Poor service is covered, not just faulty goods","then":"You start filling in the consumer complaint form.","best":true},{"text":"It only counts if I filmed the repair","then":"You can't film it now, so you stop."}],"why":"Consumer law covers deficient service, not only defective goods."},{"prompt":"A friend asks what to keep when giving a phone for repair. What do you tell him?","options":[{"text":"Nothing. Repair shops are all the same","then":"He hands it over with no record at all."},{"text":"Just the bill, since that's enough","then":"The bill shows the fee, but not the phone's condition."},{"text":"Pick the cheapest shop and just hope for the best","then":"He saves a little, with nothing to fall back on."},{"text":"The job card, the bill, and photos from before","then":"He snaps photos of his phone at the counter.","best":true}],"why":"Records from before and after a repair make any complaint easy to back up."}],"debrief":"Deficient service, not just faulty goods, is covered, and the job-card and bill are proof.","relearn":"Deficient service is covered too; keep the job-card and bill."},
  {"id":"kr-1191","cat":"renting-and-consumer","type":"branch","persona":"Meena","source":"blank agreement","hook":"Your new landlord, Mr Chawla, asks you to sign a rent agreement with the rent and deposit boxes blank.","steps":[{"prompt":"He says he'll fill them in 'correctly' later. What do you do?","options":[{"text":"Sign now, since he seems honest enough","then":"He takes the paper, and you have no copy of what he writes later."},{"text":"Sign, but pencil in the amounts myself","then":"Pencil can be rubbed out, and he smiles at the idea."},{"text":"Refuse to sign until every amount is filled in","then":"He grumbles, then fills in the rent and deposit in front of you.","best":true},{"text":"Ask him to text me the amounts instead","then":"He texts rough figures, but the signed paper stays blank."}],"why":"Blank boxes can be filled against you later. Every amount should be written before you sign."},{"prompt":"He puts the agreement in his drawer and says one copy is enough. What do you do?","options":[{"text":"Trust him to keep it safe","then":"Months later, he 'can't find it'."},{"text":"Ask a neighbour to remember the terms","then":"Your neighbour agrees, then forgets the amounts within a week."},{"text":"Write the terms from memory in my diary","then":"Your notes are close, but nobody has signed them."},{"text":"Ask for a signed copy of every page","then":"He hands you a photocopy, and you photograph it too.","best":true}],"why":"Your own signed copy is proof of what you both agreed."},{"prompt":"Your friend Seema signs a lease tomorrow and asks for one tip. What do you say?","options":[{"text":"Owners know best, so sign what they give","then":"Seema signs the next day without reading it."},{"text":"Never sign with blank amounts. Fill them first","then":"Seema writes it down. \"Rent, deposit, notice. Got it.\"","best":true},{"text":"Only sign agreements on stamp paper","then":"Seema checks the stamp paper and misses the blank deposit box."},{"text":"Skip agreements. They're just formalities","then":"Seema goes without one, and has nothing to show later."}],"why":"Filled-in amounts protect a tenant from terms being changed later."}],"debrief":"Never sign a part-blank agreement, and have every amount filled first.","relearn":"Never sign an agreement with blank amounts; get them filled first."},
  {"id":"kr-1192","cat":"renting-and-consumer","type":"branch","persona":"any","source":"defect window","hook":"Your new phone overheats every day, and the seller says 'use it a month, then we'll see'.","steps":[{"prompt":"It's only been five days since you bought it. What do you do?","options":[{"text":"Wait a month as told, recording nothing","then":"A month later, he calls it damage from 'normal use'."},{"text":"Report the defect in writing now, with the bill","then":"The seller's email reply confirms the date of your complaint.","best":true},{"text":"Reset the phone and hope it stops","then":"It still overheats, and five more days have passed."},{"text":"Ask a friend whether their phone overheats too","then":"Your friend's phone is fine, and you're none the wiser."}],"why":"Logging the defect in writing now keeps it inside the warranty."},{"prompt":"When you raise it again, the seller says 'all phones get warm'. What do you do?","options":[{"text":"Believe him and stop worrying","then":"The phone keeps shutting down in the afternoons."},{"text":"Argue by phone until he agrees","then":"He hangs up, and there's nothing new in writing."},{"text":"Ask online forums if mine is normal","then":"Strangers disagree, and nothing reaches the seller."},{"text":"Record dated videos of it overheating","then":"Three short videos show the heat warning on three days.","best":true}],"why":"Dated videos show the defect clearly, beyond 'all phones get warm'."},{"prompt":"The seller still won't act, and the warranty card lists a service centre. What do you do?","options":[{"text":"Wait until the warranty is nearly over","then":"The clock runs down, and your claim gets harder."},{"text":"Get it fixed at a local shop instead, to save time","then":"It's cheaper, but the warranty stops covering it."},{"text":"Take it to the centre with the bill and my proof","then":"They log it under warranty and give you a job number.","best":true},{"text":"Give up, since the seller has said no","then":"The phone keeps overheating in your pocket."}],"why":"Your bill and dated proof let the warranty do its job."}],"debrief":"Report a defect in writing early and keep your bill and warranty.","relearn":"Report a defect in writing early; keep the bill and warranty."},
  {"id":"kr-1193","cat":"renting-and-consumer","type":"branch","persona":"Meena","source":"pg exit","hook":"As you leave your PG, the owner, Mrs Grewal, holds back your bag until you pay a surprise 'cleaning charge'.","steps":[{"prompt":"You have a bus to catch in an hour. What do you do?","options":[{"text":"Assume she can keep my bag until I pay","then":"You hesitate, and she tucks the bag behind her chair."},{"text":"Shout at her in front of the other residents","then":"Heads turn, and she holds the bag even tighter."},{"text":"Calmly ask for the charge in writing, with a receipt","then":"She hesitates, then writes an amount and 'cleaning' on a slip.","best":true},{"text":"Leave the bag and come back another day","then":"You reach the gate without your things, and Mrs Grewal calls you back to explain the charge."}],"why":"A fair charge comes in writing with a receipt. Holding your things isn't how it's settled."},{"prompt":"She says it's for 'deep cleaning', though you cleaned the room yourself. What do you do?","options":[{"text":"Accept it, since owners decide these things","then":"You say you'll pay, and she asks for it in cash."},{"text":"Show my move-out photos and the stay terms","then":"She looks through the photos and lowers the amount.","best":true},{"text":"Refuse to discuss it at all","then":"She digs in, and nothing moves."},{"text":"Ask the other residents to back me up","then":"Two agree, but they weren't there when you moved out."}],"why":"Photos and the stay terms show whether a charge is genuine."},{"prompt":"She wants the money in cash, with no receipt. What do you do?","options":[{"text":"Pay cash, since a receipt hardly matters now","then":"The bag is yours, and there's no record of what you paid."},{"text":"Refuse to pay anything at all now","then":"The standoff starts again, and the bag stays."},{"text":"Pay by UPI, or in cash with a receipt","then":"She sighs and writes a receipt for the amount.","best":true},{"text":"Pay, and ask her to sign a receipt later","then":"She says she'll sign it 'next time', and never does."}],"why":"A UPI record or written receipt shows what you paid, so you can still question the charge later."},{"prompt":"Your friend Geeta moves into a PG next week. What do you tell her?","options":[{"text":"Avoid PGs. They're all like this","then":"Geeta worries, but she has no other option near work."},{"text":"Keep your valuables with you when leaving","then":"Geeta nods, though that won't stop a surprise charge."},{"text":"Get the stay terms and all charges in writing","then":"Geeta asks the owner for the terms before paying anything.","best":true},{"text":"Pay whatever they ask. It's easier","then":"Geeta heads in expecting to be charged at will."}],"why":"Written terms and charges protect her from surprises when she leaves."}],"debrief":"A fair charge comes in writing with a receipt, and a hostage move doesn't.","relearn":"Ask for any charge in writing with a receipt; your things shouldn't be held hostage."},
  {"id":"kr-1194","cat":"renting-and-consumer","type":"branch","persona":"any","source":"prepaid service","hook":"You paid a gym a year's fee up front, and it shut down within two months with no refund.","steps":[{"prompt":"The gym door is locked, with a note saying 'closed for renovation'. What do you do?","options":[{"text":"Shrug it off as money gone","then":"You stop thinking about it, and ten months of fees go with it."},{"text":"Wait for them to reopen someday","then":"Weeks pass, and the note curls in the sun."},{"text":"Gather my receipt, card and a photo of the note","then":"Everything sits in one folder, with dates.","best":true},{"text":"Join a new gym and forget this one","then":"You pay again, and the first gym keeps your money."}],"why":"Your receipt and dated photos prove what you paid for and didn't get."},{"prompt":"The owner's number is switched off, but the gym's social page is active. What do you do?","options":[{"text":"Comment angrily under every post","then":"Your comments vanish, and you're blocked."},{"text":"Assume gyms never give refunds","then":"You drop it, though other members are still asking."},{"text":"Turn up at the owner's home address","then":"He says he'll pay 'soon', and nothing is written."},{"text":"Message the page asking for a refund","then":"The page replies, \"Refunds will be processed soon.\"","best":true}],"why":"A written request gives you a dated record of what you asked for."},{"prompt":"Other members start a WhatsApp group about the gym. What do you do?","options":[{"text":"Join, and share how to file a consumer complaint","then":"Several members start gathering their receipts too.","best":true},{"text":"Stay out of it, since it's their problem too","then":"The group plans without you, and you miss updates."},{"text":"Use the group only to vent","then":"It fills with anger, and nobody files anything."},{"text":"Suggest we all go and shout at the owner","then":"A few agree, and the plan turns into a confrontation."}],"why":"Sharing the route helps everyone claim, not just vent."},{"prompt":"Weeks pass, and there's still no refund. What do you do?","options":[{"text":"Accept the loss, since the gym has closed","then":"The fee is gone, and so is the chance to claim it."},{"text":"Post the owner's photo everywhere","then":"It spreads, but it doesn't bring your fee back."},{"text":"Wait a little longer for the refund","then":"The locked door stays locked."},{"text":"File a consumer complaint for the unused months","then":"Your complaint is logged, with the receipt and messages attached.","best":true}],"why":"A prepaid service cut short is a consumer claim, and your receipt is the proof."}],"debrief":"A prepaid service cut short is a consumer matter, and the receipt is proof.","relearn":"A prepaid service that stops can be a consumer claim; keep the receipt."},
  {"id":"kr-1195","cat":"renting-and-consumer","type":"sort","hook":"Sort: a fair deposit deduction, or an unfair one?","items":[{"id":"a","text":"Cost of a wall you actually damaged, with a bill"},{"id":"b","text":"'Just because' with no reason given"},{"id":"c","text":"A documented unpaid utility bill"},{"id":"d","text":"Normal wear like faded paint over years"},{"id":"e","text":"A broken window you caused, with a quote"},{"id":"f","text":"A round figure cut to keep some of it"}],"bins":[{"id":"fair","label":"Fair, documented","valence":"pos"},{"id":"unfair","label":"Unfair","valence":"neg"}],"key":{"a":"fair","b":"unfair","c":"fair","d":"unfair","e":"fair","f":"unfair"},"relearn":"Deductions must be genuine and documented; 'just because' and normal wear aren't fair.","persona":"any","source":"fair deductions"},
  {"id":"kr-1196","cat":"renting-and-consumer","type":"sort","hook":"Sort: covered by consumer law, or not a consumer issue?","items":[{"id":"a","text":"A defective good you bought"},{"id":"b","text":"A service that was clearly deficient"},{"id":"c","text":"A gift someone freely gave you"},{"id":"d","text":"Misleading false advertising"},{"id":"e","text":"A fee you paid for a service"},{"id":"f","text":"A casual favour from a friend"}],"bins":[{"id":"covered","label":"Consumer law covers it","valence":"pos"},{"id":"not","label":"Not a consumer issue","valence":"neutral"}],"key":{"a":"covered","b":"covered","c":"not","d":"covered","e":"covered","f":"not"},"relearn":"Consumer law covers paid goods, services and misleading ads; free gifts and favours aren't consumer deals.","persona":"any","source":"what counts"},
  {"id":"kr-1197","cat":"renting-and-consumer","type":"sort","hook":"Sort: smart before paying a deposit, or risky?","items":[{"id":"a","text":"Seeing the actual room first"},{"id":"b","text":"Paying a stranger before any viewing"},{"id":"c","text":"Getting a receipt for the money"},{"id":"d","text":"Paying instantly under pressure"},{"id":"e","text":"Meeting the real owner"},{"id":"f","text":"Sending UPI to a 'broker' you can't verify"}],"bins":[{"id":"smart","label":"Smart","valence":"pos"},{"id":"risky","label":"Risky","valence":"neg"}],"key":{"a":"smart","b":"risky","c":"smart","d":"risky","e":"smart","f":"risky"},"relearn":"See the place, meet the owner and get a receipt; pre-viewing pay and pressure are risky.","persona":"any","source":"before deposit"},
  {"id":"kr-1198","cat":"renting-and-consumer","type":"sort","hook":"Sort: belongs in a rent agreement, or doesn't belong at all?","items":[{"id":"a","text":"Rent amount and due date"},{"id":"b","text":"A clause taking your ID forever"},{"id":"c","text":"Deposit amount and return terms"},{"id":"d","text":"'Landlord may keep deposit for any reason'"},{"id":"e","text":"Notice period for leaving"},{"id":"f","text":"'Tenant waives all rights'"}],"bins":[{"id":"belongs","label":"Fair to include","valence":"pos"},{"id":"nope","label":"Should not be there","valence":"neg"}],"key":{"a":"belongs","b":"nope","c":"belongs","d":"nope","e":"belongs","f":"nope"},"relearn":"Rent, deposit terms and notice belong; clauses seizing your ID or waiving all rights don't.","persona":"any","source":"agreement clauses"},
  {"id":"kr-1199","cat":"renting-and-consumer","type":"sort","hook":"Sort: strong proof in a dispute, or weak proof?","items":[{"id":"a","text":"A signed, stamped rent agreement"},{"id":"b","text":"'He said it was fine over chai'"},{"id":"c","text":"A dated UPI payment record"},{"id":"d","text":"A vague memory of the amount"},{"id":"e","text":"Move-in photos with a timestamp"},{"id":"f","text":"A friend's second-hand account"}],"bins":[{"id":"strong","label":"Strong proof","valence":"pos"},{"id":"weak","label":"Weak proof","valence":"uhoh"}],"key":{"a":"strong","b":"weak","c":"strong","d":"weak","e":"strong","f":"weak"},"relearn":"Signed papers, dated payments and timestamped photos are strong proof; hearsay and memory are weak.","persona":"any","source":"proof strength"},
  {"id":"kr-1200","cat":"renting-and-consumer","type":"sort","hook":"Sort: a real consumer remedy, or a myth about your options?","items":[{"id":"a","text":"Refund for a defective good"},{"id":"b","text":"'A no-refund sign ends your rights'"},{"id":"c","text":"Replacement of a faulty product"},{"id":"d","text":"'Once paid, nothing can be done'"},{"id":"e","text":"A complaint route for bad service"},{"id":"f","text":"'Online buys have no protection'"}],"bins":[{"id":"real","label":"Real remedy","valence":"pos"},{"id":"myth","label":"Myth","valence":"neg"}],"key":{"a":"real","b":"myth","c":"real","d":"myth","e":"real","f":"myth"},"relearn":"Refund, replacement and complaint routes are real; no-refund signs and 'nothing can be done' are myths.","persona":"any","source":"remedy or myth"},
  {"id":"kr-1201","cat":"renting-and-consumer","type":"match","hook":"Match each rental record to what it proves.","pairs":[{"left":"Signed rent agreement","right":"The agreed terms"},{"left":"Timestamped move-in photos","right":"The room's condition"},{"left":"Deposit UPI record","right":"What you paid as deposit"},{"left":"Itemised exit account","right":"Why any amount was cut"},{"left":"Notice you sent in writing","right":"That you gave proper notice"}],"relearn":"Each rental record proves one thing; together they protect you in a deposit or rent dispute.","persona":"any","source":"record to proof"},
  {"id":"kr-1202","cat":"renting-and-consumer","type":"match","hook":"Match each consumer problem to its remedy.","pairs":[{"left":"A defective product","right":"Refund or replacement"},{"left":"A deficient paid service","right":"A consumer complaint"},{"left":"A non-delivered online order","right":"Records plus the consumer route"},{"left":"A misleading advertisement","right":"A complaint about false claims"},{"left":"A faulty good under warranty","right":"Repair using bill and warranty"}],"relearn":"Each consumer problem has a matching route; the remedy depends on the kind of harm.","persona":"any","source":"problem to remedy"},
  {"id":"kr-1203","cat":"renting-and-consumer","type":"match","hook":"Match the rental myth to the truth that corrects it.","pairs":[{"left":"'Instant eviction anytime'","right":"Eviction needs notice and process"},{"left":"'Tenants have no rights'","right":"A rent agreement protects you"},{"left":"'Deposit kept for any reason'","right":"Returnable minus documented dues"},{"left":"'Verbal deals are enough'","right":"Put the terms in writing"},{"left":"'Cash with no receipt is fine'","right":"Always get a receipt"}],"relearn":"Each common rental myth has a plain, factual correction.","persona":"any","source":"myth to truth"},
  {"id":"kr-1204","cat":"renting-and-consumer","type":"match","hook":"Match the consumer claim to the proof that supports it.","pairs":[{"left":"A faulty appliance","right":"The bill and warranty"},{"left":"A non-delivery","right":"The order and 'delivered' screenshot"},{"left":"A deficient repair","right":"The job-card and receipt"},{"left":"A false-ad purchase","right":"The advert and the actual product"},{"left":"An overcharge","right":"The price tag and the bill"}],"relearn":"Every consumer claim is stronger with the right proof kept and shown.","persona":"any","source":"claim to proof"},
  {"id":"kr-1205","cat":"renting-and-consumer","type":"match","hook":"Match each rent-agreement term to what it does for you.","pairs":[{"left":"Notice period","right":"Time to plan a move"},{"left":"Deposit return clause","right":"How your money comes back"},{"left":"Maintenance responsibility","right":"Who fixes what"},{"left":"Rent and due date","right":"What you owe and when"},{"left":"Lock-in or exit terms","right":"How either side can end it"}],"relearn":"A good rent agreement spells out money, notice, repairs and exit, so nothing is left to guesswork.","persona":"Meena","source":"agreement terms"},
  {"id":"kr-1206","cat":"renting-and-consumer","type":"spot","hook":"Spot the two red flags in this rental listing chat.","relearn":"Pre-payment for an unseen flat and a refusal to meet are classic rental-scam signs.","persona":"any","source":"listing red flags","scene":[{"id":"a","text":"'Send the token now or I give it to someone else'","trick":true},{"id":"b","text":"'Come see the flat this weekend'","trick":false},{"id":"c","text":"'I'm abroad, just pay; I can't meet you'","trick":true},{"id":"d","text":"'I'll give a receipt for the deposit'","trick":false},{"id":"e","text":"'Here's the owner's number, please verify'","trick":false}],"why":"Instant-pay pressure and a seller who won't meet you are classic rental-scam red flags."},
  {"id":"kr-1207","cat":"renting-and-consumer","type":"spot","hook":"Spot the two unfair terms in this rent agreement.","relearn":"Clauses seizing your ID or letting a landlord keep the deposit for any reason are unfair.","persona":"any","source":"unfair terms","scene":[{"id":"a","text":"'Tenant must surrender ID card to landlord'","trick":true},{"id":"b","text":"'Rent is due by the 5th each month'","trick":false},{"id":"c","text":"'Landlord may keep the deposit for any reason'","trick":true},{"id":"d","text":"'One month's notice to leave'","trick":false},{"id":"e","text":"'Deposit returns minus documented damage'","trick":false}],"why":"Surrendering your ID and 'keep the deposit for any reason' are the unfair clauses to catch."},
  {"id":"kr-1208","cat":"renting-and-consumer","type":"spot","hook":"Spot the two warning signs in this online deal.","relearn":"Deals that block proof, like no bill and prepaid-only with no returns, are warning signs.","persona":"any","source":"online warning","scene":[{"id":"a","text":"'No bill or invoice will be given'","trick":true},{"id":"b","text":"'You'll get a GST invoice by email'","trick":false},{"id":"c","text":"'Prepaid only, and absolutely no returns'","trick":true},{"id":"d","text":"'Cash on delivery is available'","trick":false},{"id":"e","text":"'There's a clear return window'","trick":false}],"why":"No bill and 'prepaid only, no returns' strip away your proof and remedies; those are the warning signs."},
  {"id":"kr-1209","cat":"renting-and-consumer","type":"spot","hook":"Spot the two risky moves when paying a deposit.","relearn":"Paying cash with no receipt, or to an unverified person, leaves you with no proof.","persona":"Meena","source":"deposit risks","scene":[{"id":"a","text":"Handing over cash and taking no receipt","trick":true},{"id":"b","text":"Paying by UPI and saving the record","trick":false},{"id":"c","text":"Paying a 'broker' you couldn't verify","trick":true},{"id":"d","text":"Getting a signed deposit slip","trick":false},{"id":"e","text":"Noting the amount and date together","trick":false}],"why":"Cash with no receipt and paying an unverified person leave you no proof; those are the risky moves."},
  {"id":"kr-1210","cat":"renting-and-consumer","type":"spot","hook":"Spot the two pressure tactics in this salesman's pitch.","relearn":"'Offer ends today' urgency and 'sign first, read later' are pressure tactics to resist.","persona":"any","source":"sales pressure","scene":[{"id":"a","text":"'This price is only for the next ten minutes'","trick":true},{"id":"b","text":"'Take your time to read the terms'","trick":false},{"id":"c","text":"'Just sign here; you can read it later'","trick":true},{"id":"d","text":"'Here's a copy to keep for yourself'","trick":false},{"id":"e","text":"'Ask me anything before you decide'","trick":false}],"why":"Fake ten-minute urgency and 'sign first, read later' are the pressure tactics to catch and resist."},
  {"id":"kr-1211","cat":"renting-and-consumer","type":"spot","hook":"Spot the two myths in this 'advice' about deposits.","relearn":"'Deposits are the landlord's once paid' and 'you can't ask for it back' are myths.","persona":"any","source":"deposit myths","scene":[{"id":"a","text":"'Once paid, the deposit is the landlord's money'","trick":true},{"id":"b","text":"'A deposit is returnable minus real damage'","trick":false},{"id":"c","text":"'Asking for it back will only get you trouble'","trick":true},{"id":"d","text":"'Move-in photos help you get it back'","trick":false},{"id":"e","text":"'An itemised reason is fair to ask for'","trick":false}],"why":"'The deposit is the landlord's' and 'don't dare ask' are the myths; a deposit is returnable and you can ask."},
  {"id":"kr-1212","cat":"renting-and-consumer","type":"reflect","hook":"Lensy: a deposit is your money held in trust, not a parting gift. Sit with that?","prompt":"What feels true for you?","options":["It's still mine","I can ask for it back","Worth keeping proof"],"affirm":"A returnable deposit stays yours; documented condition and a fair ask are how you protect it.","relearn":"A deposit is your money held in trust, returnable minus documented damage.","persona":"any","source":"deposit mindset"},
  {"id":"kr-1213","cat":"renting-and-consumer","type":"reflect","hook":"Lensy: keeping a bill or chat takes seconds but can settle a whole dispute later. Worth the habit?","prompt":"How do you see it?","options":["Worth it","I'll save proof","Small effort, big help"],"affirm":"A saved bill, photo or chat is quiet insurance; the habit costs little and protects a lot.","relearn":"Keeping receipts, photos and chats is a small habit with big protection.","persona":"any","source":"proof habit"},
  {"id":"kr-1214","cat":"renting-and-consumer","type":"reflect","hook":"Lensy: asking 'what is this charge for?' isn't rude, it's how fair deals work. Agree?","prompt":"What do you think?","options":["It's fair to ask","I'll ask next time","Good deals welcome questions"],"affirm":"Honest sellers and landlords can explain their charges; asking is normal, not a fight.","relearn":"Asking what a charge is for is normal and fair, not rude.","persona":"any","source":"asking is fair"},
  {"id":"kr-1215","cat":"renting-and-consumer","type":"reflect","hook":"Lensy: 'I'll read it before I sign' is a small line that saves a lot of trouble. Make it a habit?","prompt":"Where do you stand?","options":["Always read first","I can take my time","No rush to sign"],"affirm":"Reading before signing is yours to insist on; a fair deal can always wait for you to read.","relearn":"Reading before you sign is a habit worth keeping; a fair deal can wait.","persona":"any","source":"read first"},
  {"id":"kr-1216","cat":"renting-and-consumer","type":"reflect","hook":"Lensy: knowing one consumer right makes you harder to brush off with 'your bad luck'. Feel that?","prompt":"What lands for you?","options":["I have rights","Harder to brush off","Knowing helps"],"affirm":"Even one known right shifts the conversation; 'your bad luck' loses its power when you know the route.","relearn":"Knowing your consumer rights makes 'your bad luck' easy to refuse.","persona":"any","source":"knowing helps"},
  {"id":"kr-1217","cat":"renting-and-consumer","type":"reflect","hook":"Lensy: renting alone in a new city is hard, and asking for written terms is strength, not trouble. Agree?","prompt":"What feels right?","options":["It's strength","I can ask","Written is safer"],"affirm":"Asking for written terms protects you and the landlord; it's a fair, steady move, not making trouble.","relearn":"Asking for written terms when you rent is strength, not trouble.","persona":"Meena","source":"renting alone"},
  {"id":"kr-1218","cat":"renting-and-consumer","type":"reflect","hook":"Lensy: 'no refund' boards are everywhere, but a sign can't outrank the law on a faulty good. Sit with that?","prompt":"How do you read it?","options":["A sign isn't the law","I still have rights","Good to know"],"affirm":"A store notice can't cancel your rights on a genuinely defective good; the law still stands behind you.","relearn":"A 'no refund' sign can't override your rights on a defective good.","persona":"any","source":"sign vs law"},
  {"id":"kr-1219","cat":"renting-and-consumer","type":"role-play","persona":"any","source":"ask deposit","hook":"You moved out of your rented room clean, and your landlord, Mr Nair, has gone quiet about the deposit.","setup":"You finally get him on the phone.","steps":[{"prompt":"Mr Nair says: \"Deposit? I'll see. Maybe next month.\"","options":[{"text":"\"It's fine if you keep some. I don't want trouble.\"","then":"\"Good, good,\" he says. \"I'll send what I can.\""},{"text":"\"I left it as it was. Please return it by the 10th.\"","then":"\"The 10th? Hmm. I'll check the room first,\" he says.","best":true},{"text":"\"If it's not back tomorrow, I'll ruin your name.\"","then":"\"Don't threaten me,\" he snaps, and goes quiet for a moment."},{"text":"\"Okay, whenever it suits you is fine.\"","then":"\"Fine,\" he says. \"I'll call you.\""}],"why":"A clear date turns 'maybe next month' into a real request."},{"prompt":"Mr Nair says: \"The walls need painting. I'll have to cut something.\"","options":[{"text":"\"Sure, cut whatever you think is right.\"","then":"\"I'll decide, then,\" he says, sounding pleased."},{"text":"\"No cuts at all, whatever you say.\"","then":"\"Then we have a problem,\" he says."},{"text":"\"Then please share an itemised list for any cut.\"","then":"\"Itemised?\" He pauses. \"Let me see what it costs.\"","best":true},{"text":"\"Can we just split the painting cost between us?\"","then":"\"Half, then,\" he says quickly, and names a big figure."}],"why":"Asking for an itemised reason ties any deduction to real, documented costs."},{"prompt":"Mr Nair says: \"I'm busy these days. The deposit will have to wait.\"","options":[{"text":"\"Then just keep it all. It's not worth it.\"","then":"\"Okay,\" he says, and the line goes quiet."},{"text":"\"Then I'll send some people to your house.\"","then":"\"Is that a threat?\" he says, now angry."},{"text":"\"No problem. I'll call you every day till then.\"","then":"\"Please don't,\" he says, and stops picking up."},{"text":"\"Then message me the amount and any cuts by Friday.\"","then":"He sighs. \"Fine. You'll have it in writing by Friday.\"","best":true}],"why":"A written amount with a date keeps it simple and gives you a clear record."}],"relearn":"Ask clearly for your deposit by a date, or for an itemised reason."},
  {"id":"kr-1220","cat":"renting-and-consumer","type":"role-play","persona":"any","source":"faulty product","hook":"The blender you bought last week won't start, and the shop says 'not our problem'.","setup":"You're back at the counter with the box and the bill.","steps":[{"prompt":"The shopkeeper says: \"Take it to the company. We only sell.\"","options":[{"text":"\"Okay, maybe I used it wrong. I'll manage.\"","then":"\"Read the manual first,\" he says, then picks the box up anyway."},{"text":"\"You people cheat everyone who comes here.\"","then":"\"Mind your words,\" he says, and folds his arms."},{"text":"\"Could you at least give me the company's number, then?\"","then":"He writes a number on a scrap, then glances at the box again."},{"text":"\"It's defective and under warranty. Here's the bill.\"","then":"He glances at the bill. \"Hmm. So what do you want?\"","best":true}],"why":"Naming the defect and showing the bill makes clear the seller must help."},{"prompt":"He says: \"If it's faulty, I can send it for repair. It takes a month or so.\"","options":[{"text":"\"Repair's fine with a written date. Or a replacement.\"","then":"He pauses. \"A date? Let me ask the distributor.\"","best":true},{"text":"\"Okay, whenever it's done. I'll wait.\"","then":"He nods and hands you a slip with no date."},{"text":"\"A month? Then I'll just go and buy one somewhere else.\"","then":"\"Your choice,\" he says. \"This one stays faulty, though.\""},{"text":"\"Could I get a discount on another one instead?\"","then":"\"A small one,\" he says. You'd still be paying twice."}],"why":"A faulty item can be repaired or replaced, and a written date stops a repair dragging on."},{"prompt":"He puts down the phone and says: \"The distributor says it's misuse. Nothing I can do.\"","options":[{"text":"\"Okay. I guess that's that, then.\"","then":"He nods, relieved, and serves the next customer."},{"text":"\"Please note my complaint. There's a consumer route.\"","then":"\"Consumer route?\" He pauses. \"Wait. Let me try once more.\"","best":true},{"text":"\"I'll post a video of this shop online.\"","then":"\"Do what you like,\" he says, unbothered."},{"text":"\"Fine. I'll keep coming back here until you fix it.\"","then":"\"Come any time,\" he says. \"The answer will be the same.\""}],"why":"Naming the consumer route shows you know there's a real next step."}],"relearn":"State the defect, show the bill, and ask for repair or replacement."},
  {"id":"kr-1221","cat":"renting-and-consumer","type":"role-play","persona":"any","source":"token deposit","hook":"A 'broker' called Vicky has sent you photos of a flat and wants a token deposit by UPI.","setup":"He calls you back within minutes.","steps":[{"prompt":"Vicky says: \"Send the token now, or someone else takes it.\"","options":[{"text":"\"Alright, I'll send it now so I don't lose it.\"","then":"\"Done. Sending my UPI ID,\" he says quickly."},{"text":"\"I'll pay once I've seen it and met the owner.\"","then":"\"Owner is busy,\" he says. \"Photos are enough, no?\"","best":true},{"text":"\"Can I send half now and half after the visit?\"","then":"\"Okay, half now,\" he says, a little too fast."},{"text":"\"Send me a video of the flat first, then.\"","then":"\"Video coming,\" he says. \"Then you pay, okay?\""}],"why":"Seeing the flat and meeting the owner before paying is how you avoid the classic trap."},{"prompt":"Vicky says: \"The owner lives abroad. I handle everything for him.\"","options":[{"text":"\"Oh, okay. Lots of owners live abroad.\"","then":"\"Exactly. So send the token,\" he says."},{"text":"\"Can you send me the owner's number, then?\"","then":"\"He doesn't take calls,\" he says smoothly."},{"text":"\"Then I need to see his papers and the flat.\"","then":"\"Papers? Why so much doubt?\" he says, irritated.","best":true},{"text":"\"Send me a receipt first. Then I'll think about it.\"","then":"\"Receipts come after payment only,\" he says."}],"why":"A real rental can be checked, and someone who dodges that is a warning sign."},{"prompt":"Vicky says: \"Last chance. Two people are ready to pay today.\"","options":[{"text":"\"Okay, okay. I'm sending it now.\"","then":"\"Done,\" he says. By evening, his number is switched off."},{"text":"\"Please just hold it one more day for me.\"","then":"\"Only if you send something now,\" he says."},{"text":"\"You're a fraud. I'll make sure you regret this.\"","then":"He hangs up at once, and the flat photos vanish from your chat."},{"text":"\"Then I'll pass. I don't pay for unseen flats.\"","then":"\"Your loss,\" he says, and hangs up.","best":true}],"why":"Walking away from pressure protects your money. A genuine rental lets you visit and meet the owner first."}],"relearn":"Don't pay for an unseen rental; see the flat and meet the owner first."},
  {"id":"kr-1222","cat":"renting-and-consumer","type":"role-play","persona":"any","source":"on-the-spot","hook":"At a phone store, a salesman insists you sign a costly EMI now because 'the offer ends today'.","setup":"He slides the form and a pen across the counter.","steps":[{"prompt":"The salesman says: \"Just sign here. I'll explain the details later.\"","options":[{"text":"\"If it's standard, I suppose I can sign it.\"","then":"\"Exactly,\" he says, tapping the line for your signature."},{"text":"\"Can you just tell me the monthly amount?\"","then":"\"Only a small amount each month,\" he says, without a number."},{"text":"\"I don't sign what I haven't read. I'll take the terms.\"","then":"\"All the terms are standard,\" he says, holding the form.","best":true},{"text":"\"Sign? You people always cheat customers.\"","then":"\"No need to insult me,\" he says, stiffening."}],"why":"Reading the terms before signing is your right, however standard they're said to be."},{"prompt":"He says: \"The offer ends at 8. After that, the price goes up.\"","options":[{"text":"\"Then I'll come back before 8 to sign it.\"","then":"\"Good,\" he says. \"Don't be late.\""},{"text":"\"Then I'll decide tomorrow, after reading it.\"","then":"\"Your choice,\" he says, and hands over a copy of the terms.","best":true},{"text":"\"Can I call my brother to decide for me?\"","then":"\"Quickly, please,\" he says, tapping the counter."},{"text":"\"If it goes up, that's your trick, not my problem.\"","then":"\"No trick, just the offer,\" he says coldly."}],"why":"A deadline is a pressure tactic. A fair offer can wait while you read it."},{"prompt":"At home, your brother asks: \"So, are you signing up for that phone?\"","options":[{"text":"\"No, and I'm never buying anything on EMI again.\"","then":"\"Never? That seems a bit much,\" he says."},{"text":"\"Not yet. I'm comparing the total cost first.\"","then":"\"Show me the numbers,\" he says, pulling up a chair.","best":true},{"text":"\"Almost. I'll rush back before the offer ends.\"","then":"\"Those offers never really end,\" he says, smiling."},{"text":"\"I felt bad saying no, so I'll probably sign.\"","then":"\"Because you felt bad?\" he asks, frowning."}],"why":"Comparing the total cost in your own time is how you decide well."}],"relearn":"Don't sign under pressure; read the terms and decide in your own time."},
  {"id":"kr-1223","cat":"renting-and-consumer","type":"role-play","persona":"Meena","source":"blank sign","hook":"Your landlord, Mr Pillai, hands you a rent agreement with the rent and deposit boxes left empty.","setup":"He holds out a pen at the door.","steps":[{"prompt":"Mr Pillai says: \"I'll fill those in later. Just sign here.\"","options":[{"text":"\"Let's write the rent and deposit in now. Then I'll sign.\"","then":"He sighs. \"Fine. Eight thousand rent, twenty deposit. Write it.\"","best":true},{"text":"\"Okay. I trust you to fill it in correctly later.\"","then":"He smiles and pockets the signed sheet. \"I'll send a copy sometime.\""},{"text":"\"I'll sign, but send me a photo once it's filled.\"","then":"\"Sure, sure,\" he says, folding the signed page into his bag."},{"text":"\"Everyone signs these blank here, right? Okay.\"","then":"\"Exactly,\" he says, and takes the page without filling anything."}],"why":"Anything left blank can be filled in later with numbers you never agreed to."},{"prompt":"A week later, Mr Pillai says: \"Maintenance is extra. I'll tell you the amount each month.\"","options":[{"text":"\"Please add the maintenance amount to the agreement in writing.\"","then":"He grumbles, then writes \"Maintenance: 500 a month\" and signs beside it.","best":true},{"text":"\"Okay. Just tell me whenever it's due, and I'll pay it.\"","then":"\"Sure,\" he says. Next month's maintenance comes to 1,800 with no breakdown."},{"text":"\"Can you WhatsApp me a rough figure for now?\"","then":"He sends \"somewhere between 500 and 1,000\" and the amount stays loose."},{"text":"\"Maintenance was never mentioned. I won't pay a rupee of it.\"","then":"He raises his voice about finding another tenant, and nothing gets settled."}],"why":"A charge that isn't written down can grow each month with nothing to check it against."},{"prompt":"At renewal time, Mr Pillai says: \"Same as last year. I'll fill the new rent after I check the market.\"","options":[{"text":"\"Let's agree the new rent now and write it in before I sign.\"","then":"He names a figure. You settle on it, and it goes on the page in ink.","best":true},{"text":"\"It's just a renewal. Here, I'll sign it now and save us time.\"","then":"He takes it with a nod. The rent box is still empty."},{"text":"\"I'll sign if you promise it won't go up much.\"","then":"\"Of course, of course,\" he says. There's nothing on paper to hold him to."},{"text":"\"Let me ask my flatmate what she signed first.\"","then":"Your flatmate signed hers blank too, and isn't sure what it says now."}],"why":"Every renewal is a new agreement, so the amounts go in before your signature."}],"relearn":"Never sign blank boxes; get every amount written in first."},
  {"id":"kr-1224","cat":"renting-and-consumer","type":"role-play","persona":"any","source":"broken order","hook":"Your new mixer grinder arrived with a cracked jar, and support has closed your ticket twice.","setup":"A chat agent, Priya, finally replies.","steps":[{"prompt":"Priya types: \"What's the issue with your order?\"","options":[{"text":"\"The jar came cracked. Photos and order ID attached. I want a replacement.\"","then":"\"Thank you. I can see the photos. Let me check.\"","best":true},{"text":"\"It's only a bit damaged. Just forget it.\"","then":"\"Are you sure? I can still check,\" she types."},{"text":"\"You sell junk. This is my third time writing to you!\"","then":"\"I understand you're upset. Can you share the order ID?\""},{"text":"\"The jar has a crack. Can you see what can be done?\"","then":"\"Please share photos and your order ID so I can raise it.\""}],"why":"Naming the defect, showing proof and saying what you want leaves nothing to stall on."},{"prompt":"Priya types: \"Our policy only covers damage reported within 48 hours.\"","options":[{"text":"\"I reported it the day it came. Here are my old ticket numbers.\"","then":"\"I see both tickets now. Let me check what I can offer.\"","best":true},{"text":"\"Oh. Then I suppose there's nothing more to be done.\"","then":"\"Let me see if anything else is possible,\" she types."},{"text":"\"That's illegal, and I'm taking you to court right now.\"","then":"\"I'll note your concern,\" she types, and sends a standard reply."},{"text":"\"Could you make an exception, just this once, as a favour?\"","then":"\"I'm not able to make exceptions, sorry,\" she types."}],"why":"Your earlier tickets prove you reported it on time. Point to them."},{"prompt":"Priya types: \"I can offer a 200-rupee coupon instead.\"","options":[{"text":"\"Thanks, but I'd like a replacement or a full refund, please.\"","then":"\"Noted. I'm raising a replacement request. You'll get an email.\"","best":true},{"text":"\"Fine. A coupon is better than nothing, I suppose.\"","then":"\"Done! It's in your account.\" The cracked jar stays on your shelf."},{"text":"\"Give me your manager's number. I'm done talking to you.\"","then":"\"I'll request a callback,\" she types, with no time given."},{"text":"\"Let me think about it and come back to you later.\"","then":"\"Sure. This chat will close after five minutes of no reply.\""}],"why":"A faulty product gives you a right to a refund or replacement, not a token."},{"prompt":"A week later, a new agent, Arun, says: \"I can't see any open request on this order.\"","options":[{"text":"\"Here's my old ticket number and the photos. Please reopen it.\"","then":"\"Got it. Reopened under the same number. Pickup is Thursday.\"","best":true},{"text":"\"Oh. Then maybe it's not worth chasing anymore. Leave it.\"","then":"\"Okay. Anything else I can help with?\" he asks."},{"text":"\"Unbelievable. You people are all completely useless.\"","then":"\"I'm trying to help,\" he says, and his replies get shorter."},{"text":"\"Can you just make a note and call me back sometime later?\"","then":"\"Sure,\" he says, but gives no reference number."}],"why":"Your saved ticket and photos let anyone pick up the claim without starting over."}],"relearn":"State the defect, attach proof, and clearly ask for a refund or replacement."},
  {"id":"kr-1225","cat":"renting-and-consumer","type":"role-play","persona":"Meena","source":"surprise charge","hook":"On your last day at the PG, the owner, Mrs Kaur, adds a surprise 'cleaning charge'.","setup":"Your bag is packed and an auto is waiting.","steps":[{"prompt":"Mrs Kaur says: \"Two thousand cash for cleaning. Everyone pays.\"","options":[{"text":"\"Please put it in writing with a receipt. Then I'll look.\"","then":"She frowns. \"Receipt? Fine. It'll be on the deposit sheet.\"","best":true},{"text":"\"Okay, here's the cash. I just want to leave quietly.\"","then":"She counts the notes and waves you off. No slip, no record."},{"text":"\"I'm not paying anything. I'm leaving right now.\"","then":"\"Then don't expect your deposit soon,\" she calls after you."},{"text":"\"Can you just take it out of my deposit instead?\"","then":"\"Done,\" she says, and writes nothing down."}],"why":"A charge with no receipt has no record, so ask for it in writing before money changes hands."},{"prompt":"A day later, Mrs Kaur messages: \"Your deposit refund will be less. The room needed repairs.\"","options":[{"text":"\"Could you list each repair and its cost? I have move-in photos.\"","then":"An hour later she replies: \"Fan regulator, 300. That's all.\"","best":true},{"text":"\"Okay. Please just send whatever is left of the deposit.\"","then":"She sends back half the deposit with no explanation."},{"text":"\"I left that room spotless. You're just cheating me.\"","then":"\"Watch your tone,\" she replies, and stops answering."},{"text":"\"How much less? Just tell me the final number.\"","then":"\"Four thousand less,\" she replies, with no breakdown."}],"why":"Deductions should be itemised against real damage, and your photos let you check them."},{"prompt":"Your friend Jyoti, moving into the same PG next month, asks: \"Anything I should do differently?\"","options":[{"text":"\"Get every charge and the deposit in writing, with receipts.\"","then":"Jyoti notes it down. \"Receipts for everything. Got it.\"","best":true},{"text":"\"Nothing. Just pay whatever she asks. It's easier that way.\"","then":"Jyoti nods. \"Okay. I'll keep some extra cash ready.\""},{"text":"\"Don't move there at all. She's a thief.\"","then":"Jyoti looks worried. \"But it's the only place near my college.\""},{"text":"\"Just keep your cash payments to her small.\"","then":"\"Small how?\" she asks. \"The rent alone is eight thousand.\""}],"why":"Receipts for every charge give anyone a record to check against."}],"relearn":"Ask for any surprise charge in writing with a receipt before paying."},
  {"id":"kr-1226","cat":"renting-and-consumer","type":"role-play","persona":"any","source":"wear and tear","hook":"You're moving out, and your landlord, Mr Reddy, wants half your deposit for 'wear and tear'.","setup":"You're doing the final walk-through.","steps":[{"prompt":"Mr Reddy says: \"Walls, floor, fittings. It all wears out.\"","options":[{"text":"\"Could you tell me which items, and what each one costs?\"","then":"He hesitates. \"The wall paint, mainly. And the geyser.\"","best":true},{"text":"\"Okay. Keep whatever you think is fair.\"","then":"He nods, pleased. \"Good. Come, I'll show you the walls.\""},{"text":"\"Half? That's robbery. I want every rupee back.\"","then":"His face hardens. \"Then we'll see who waits longer.\""},{"text":"\"Can we split the difference and call it a quarter?\"","then":"\"Fine, a quarter,\" he says quickly, as if he'd expected less."}],"why":"An itemised list turns a vague cut into something you can check."},{"prompt":"Mr Reddy points at the wall and says: \"See these marks? The whole room needs painting.\"","options":[{"text":"\"Here are my move-in photos. Those marks were already there.\"","then":"He studies the dated photos. \"Hm. Maybe not the whole room.\"","best":true},{"text":"\"I guess a year of living here leaves marks. Fine.\"","then":"He smiles and makes a note on his phone."},{"text":"\"I'll repaint that wall myself before I hand over the keys.\"","then":"\"Fine,\" he says. You spend a weekend and 1,500 on marks you didn't make."},{"text":"\"Send me a painter's quote and I'll pay it.\"","then":"The next day he sends a quote for painting the whole flat."}],"why":"Dated move-in photos show what was already there, which any deduction must be checked against."},{"prompt":"Mr Reddy says: \"I'll return the rest once the new tenant pays me.\"","options":[{"text":"\"Could we write down the amount and a return date today?\"","then":"He writes the amount and \"by the 10th\" on a paper and signs it.","best":true},{"text":"\"No problem. Whenever it's convenient for you.\"","then":"\"Good,\" he says, and walks you to the gate."},{"text":"\"No. I want it right now, in cash, or I'm not leaving.\"","then":"He folds his arms. \"I don't keep that much at home.\""},{"text":"\"Can you at least give me a rough idea of when?\"","then":"\"Soon, soon,\" he says, and picks up his keys."}],"why":"A written amount and date turns 'later' into a promise you can point to."},{"prompt":"Two weeks later, Mr Reddy says on the phone: \"The new tenant hasn't paid yet. It'll take time.\"","options":[{"text":"\"My deposit doesn't depend on the new tenant. When will you pay it?\"","then":"He's quiet, then says, \"Fine. Saturday. I'll transfer it.\"","best":true},{"text":"\"Okay. I'll wait until the new tenant pays, then.\"","then":"\"Good,\" he says. Another month goes by with nothing."},{"text":"\"If it's not here tomorrow, I'll tell everyone you're a cheat.\"","then":"\"Threats won't help you,\" he says, and hangs up."},{"text":"\"Could you send some of it now, at least?\"","then":"He sends 2,000 and says the rest will \"follow\"."}],"why":"Your deposit is yours to get back. It shouldn't wait on someone else's rent."}],"relearn":"Ask for an itemised reason and compare it against your move-in photos."},
  {"id":"kr-1227","cat":"renting-and-consumer","type":"match","hook":"Match each unfair move to the fair alternative.","pairs":[{"left":"Sign a blank agreement","right":"Fill every amount first"},{"left":"Pay cash, take no receipt","right":"Get a receipt or pay by UPI"},{"left":"Deposit kept for any reason","right":"Itemised, documented deductions"},{"left":"Pay for an unseen flat","right":"View it and meet the owner"},{"left":"Sign under instant pressure","right":"Read the terms in your own time"}],"relearn":"Every pressured or risky move has a fair, safer alternative you can ask for.","persona":"any","source":"unfair to fair"},
  {"id":"kr-1260","cat":"rights-at-work","type":"strike-rewrite","hook":"\"A probation period means the company can pay you nothing.\"","myth":{"un":"On probation the company can pay you nothing.","re":"Probation sets a review window, not free labour; work done during it still earns the agreed pay.","why":"A trial period tests fit, it doesn't cancel your wage."},"relearn":"Probation is a review window, not unpaid time; work done still earns your agreed pay.","persona":"Meena","source":"probation pay"},
  {"id":"kr-1261","cat":"rights-at-work","type":"strike-rewrite","hook":"\"If there's no written contract, the company owes you nothing.\"","myth":{"un":"No written contract means the company owes you nothing.","re":"Wages are owed for work actually done, with or without paper; a missing contract is their risk too.","why":"Pay follows the work, not just the paperwork."},"relearn":"Wages are owed for work done even without a written contract; a missing contract is a warning sign.","persona":"Meena","source":"no contract"},
  {"id":"kr-1262","cat":"rights-at-work","type":"strike-rewrite","hook":"\"Asking for a payslip will mark you as a troublemaker.\"","myth":{"un":"Asking for a payslip marks you as a troublemaker.","re":"A payslip is a normal record of pay and deductions; asking for one is routine, not a complaint.","why":"A simple proof-of-pay request is your right, not rebellion."},"relearn":"Asking for a payslip is routine; it records your pay and deductions and protects you.","persona":"any","source":"payslip"},
  {"id":"kr-1263","cat":"rights-at-work","type":"strike-rewrite","hook":"\"Gig and delivery workers are 'partners', so they have no rights at all.\"","myth":{"un":"Gig and delivery 'partners' have no rights at all.","re":"A label like 'partner' doesn't erase your earnings, agreed terms, or safety; those still stand.","why":"Renaming a worker doesn't delete what's owed to them."},"relearn":"Calling a gig worker a 'partner' doesn't erase agreed pay, terms or safety.","persona":"any","source":"gig partner label"},
  {"id":"kr-1264","cat":"rights-at-work","type":"strike-rewrite","hook":"\"A company can hold your original certificates until you 'prove loyalty'.\"","myth":{"un":"A company can keep your original certificates to ensure loyalty.","re":"Your original documents are yours; holding them to trap you in a job is coercion, not policy.","why":"Your degree and ID belong to you, never to an employer."},"relearn":"Your original certificates are yours; an employer holding them to trap you is coercion.","persona":"Meena","source":"document holding"},
  {"id":"kr-1265","cat":"rights-at-work","type":"strike-rewrite","hook":"\"Overtime is just part of the job; you can never expect to be paid for it.\"","myth":{"un":"Overtime is part of the job and is never paid extra.","re":"Hours beyond your agreed terms are extra work; agreed overtime should be counted and paid.","why":"Time worked is time owed, not a free gift."},"relearn":"Hours beyond your agreed terms are extra work and agreed overtime should be paid.","persona":"any","source":"overtime"},
  {"id":"kr-1266","cat":"rights-at-work","type":"strike-rewrite","hook":"\"Women can be paid less than men for the very same job.\"","myth":{"un":"Women can be paid less than men for the same job.","re":"Equal work earns equal pay; paying a woman less for the same role and output is unfair and not allowed.","why":"The wage follows the work, not the worker's gender."},"relearn":"Equal work earns equal pay; paying a woman less for the same job is not allowed.","persona":"Aarti","source":"equal pay"},
  {"id":"kr-1267","cat":"rights-at-work","type":"strike-rewrite","hook":"\"A resignation 'penalty' can take your last month's full salary.\"","myth":{"un":"Resigning lets them keep your full last salary as penalty.","re":"You're still owed pay for days actually worked; a vague 'penalty' can't swallow earned wages whole.","why":"Leaving a job doesn't cancel pay you already earned."},"relearn":"You're owed pay for days actually worked; a vague exit 'penalty' can't take earned wages.","persona":"any","source":"exit penalty"},
  {"id":"kr-1268","cat":"rights-at-work","type":"strike-rewrite","hook":"\"A 'training bond' lets them keep your stipend if you ever ask questions.\"","myth":{"un":"A training bond means they keep your stipend if you question anything.","re":"A bond has set terms; it can't be stretched to grab your stipend just for asking fair questions.","why":"A bond is a written deal, not a gag on your voice."},"relearn":"A training bond has set terms; it can't be stretched to take your stipend for asking questions.","persona":"Deepak","source":"training bond"},
  {"id":"kr-1269","cat":"rights-at-work","type":"strike-rewrite","hook":"\"A weekly day off is a favour the boss can cancel anytime.\"","myth":{"un":"A weekly day off is a favour the boss can cancel anytime.","re":"Rest and a weekly off are part of fair, safe work, not a gift handed out at someone's mood.","why":"Reasonable rest keeps work safe; it isn't charity."},"relearn":"A weekly day off and rest are part of fair, safe work, not a favour to cancel at whim.","persona":"Meena","source":"weekly off"},
  {"id":"kr-1270","cat":"rights-at-work","type":"sort","hook":"Sort: okay at work, or not okay?","items":[{"id":"a","text":"An offer letter stating pay, hours and role"},{"id":"b","text":"Wages held back to 'punish' a mistake"},{"id":"c","text":"A payslip each month"},{"id":"d","text":"Doing months of real work unpaid"},{"id":"e","text":"Agreed overtime that gets paid"},{"id":"f","text":"Originals kept so you can't leave"}],"bins":[{"id":"ok","label":"Okay","valence":"pos"},{"id":"not","label":"Not okay","valence":"neg"}],"key":{"a":"ok","b":"not","c":"ok","d":"not","e":"ok","f":"not"},"relearn":"Clear terms, a payslip and paid overtime are okay; withheld wages, unpaid real work and held originals are not.","persona":"any","source":"okay at work"},
  {"id":"kr-1271","cat":"rights-at-work","type":"sort","hook":"Sort: a real labour-rights fact, or a myth?","items":[{"id":"a","text":"Interns doing real work can be paid"},{"id":"b","text":"Juniors legally get zero rights"},{"id":"c","text":"A contract should state your role"},{"id":"d","text":"Cash-in-hand pay erases all rights"},{"id":"e","text":"Gig workers still have agreed terms"},{"id":"f","text":"Probation means you work for free"}],"bins":[{"id":"real","label":"Real fact","valence":"pos"},{"id":"myth","label":"Myth","valence":"neg"}],"key":{"a":"real","b":"myth","c":"real","d":"myth","e":"real","f":"myth"},"relearn":"Interns and gig workers have terms and a contract states your role; 'no rights for juniors, cash, or probation' are myths.","persona":"any","source":"labour facts"},
  {"id":"kr-1272","cat":"rights-at-work","type":"sort","hook":"Sort: belongs in a fair offer letter, or a red flag?","items":[{"id":"a","text":"Your monthly pay in figures"},{"id":"b","text":"'Salary: we'll decide later'"},{"id":"c","text":"Working hours and weekly off"},{"id":"d","text":"'No leaving for two years or pay us'"},{"id":"e","text":"Your job title and duties"},{"id":"f","text":"'Pay only if the client is happy'"}],"bins":[{"id":"fair","label":"Fair term","valence":"pos"},{"id":"flag","label":"Red flag","valence":"neg"}],"key":{"a":"fair","b":"flag","c":"fair","d":"flag","e":"fair","f":"flag"},"relearn":"A fair offer states pay, hours and role; vague pay, lock-in threats and 'pay only if client's happy' are red flags.","persona":"any","source":"offer letter terms"},
  {"id":"kr-1273","cat":"rights-at-work","type":"sort","hook":"Sort: which step protects you, or leaves you exposed?","items":[{"id":"a","text":"Get the offer in writing first"},{"id":"b","text":"Start on a verbal promise only"},{"id":"c","text":"Keep your own record of hours"},{"id":"d","text":"Trust 'we'll sort pay later'"},{"id":"e","text":"Save messages about your pay"},{"id":"f","text":"Hand over your only ID copy"}],"bins":[{"id":"safe","label":"Protects you","valence":"pos"},{"id":"risk","label":"Leaves you exposed","valence":"neg"}],"key":{"a":"safe","b":"risk","c":"safe","d":"risk","e":"safe","f":"risk"},"relearn":"Written terms, your own hour log and saved pay messages protect you; verbal-only deals and handing over IDs expose you.","persona":"Meena","source":"protect yourself at work"},
  {"id":"kr-1274","cat":"rights-at-work","type":"sort","hook":"Sort: who is still a protected worker?","items":[{"id":"a","text":"A paid intern doing real tasks"},{"id":"b","text":"A contract housekeeping worker"},{"id":"c","text":"A part-time evening shift worker"},{"id":"d","text":"A delivery rider called a 'partner'"},{"id":"e","text":"A trainee on a stipend"},{"id":"f","text":"A daily-wage site worker"}],"bins":[{"id":"yes","label":"Has rights","valence":"pos"},{"id":"also","label":"Also has rights","valence":"neutral"}],"key":{"a":"yes","b":"also","c":"yes","d":"also","e":"yes","f":"also"},"relearn":"Interns, contract, part-time, gig, trainee and daily-wage workers all have basic labour rights.","persona":"any","source":"who is protected"},
  {"id":"kr-1275","cat":"rights-at-work","type":"sort","hook":"Sort: fair internship, or exploitation in disguise?","items":[{"id":"a","text":"A set stipend paid on time"},{"id":"b","text":"Full unpaid work for many months"},{"id":"c","text":"Real learning and a mentor"},{"id":"d","text":"'Stipend' that never arrives"},{"id":"e","text":"Agreed hours in writing"},{"id":"f","text":"Doing a paid staff member's whole job free"}],"bins":[{"id":"fair","label":"Fair internship","valence":"pos"},{"id":"exploit","label":"Exploitation","valence":"neg"}],"key":{"a":"fair","b":"exploit","c":"fair","d":"exploit","e":"fair","f":"exploit"},"relearn":"A paid stipend, real learning and written hours make a fair internship; endless unpaid work or vanishing pay is exploitation.","persona":"Deepak","source":"internship vs exploitation"},
  {"id":"kr-1276","cat":"rights-at-work","type":"sort","hook":"Sort: a deduction that's fair, or one to question?","items":[{"id":"a","text":"Tax shown clearly on your payslip"},{"id":"b","text":"'Fine' for asking about late pay"},{"id":"c","text":"Provident fund you agreed to"},{"id":"d","text":"Cut for a 'uniform' you never got"},{"id":"e","text":"An advance you actually took"},{"id":"f","text":"Pay 'held' until you train a replacement"}],"bins":[{"id":"fair","label":"Fair deduction","valence":"pos"},{"id":"question","label":"Question it","valence":"uhoh"}],"key":{"a":"fair","b":"question","c":"fair","d":"question","e":"fair","f":"question"},"relearn":"Clear tax, agreed PF and a real advance are fair cuts; surprise 'fines', phantom charges and held pay are worth questioning.","persona":"any","source":"deductions"},
  {"id":"kr-1277","cat":"rights-at-work","type":"sort","hook":"Sort: counts as 'real work that deserves pay', or genuine free learning?","items":[{"id":"a","text":"Handling live customer orders alone"},{"id":"b","text":"A one-day shadowing visit"},{"id":"c","text":"Running the shop's daily accounts"},{"id":"d","text":"Watching a senior do a task once"},{"id":"e","text":"Filling staff shifts they're short on"},{"id":"f","text":"A short guided practice exercise"}],"bins":[{"id":"work","label":"Real work, pay owed","valence":"tell"},{"id":"learn","label":"Genuine learning","valence":"pos"}],"key":{"a":"work","b":"learn","c":"work","d":"learn","e":"work","f":"learn"},"relearn":"Doing the real job, accounts or covering shifts is paid work; shadowing or guided practice can be genuine learning.","persona":"any","source":"work vs learning"},
  {"id":"kr-1278","cat":"rights-at-work","type":"sort","hook":"Sort: a safe-conditions right, or just a nice-to-have?","items":[{"id":"a","text":"Clean drinking water on site"},{"id":"b","text":"A free luxury coffee machine"},{"id":"c","text":"Basic safety gear for risky work"},{"id":"d","text":"A bean-bag lounge"},{"id":"e","text":"A reasonable rest break"},{"id":"f","text":"Branded company hoodies"}],"bins":[{"id":"right","label":"Safety right","valence":"pos"},{"id":"perk","label":"Just a perk","valence":"neutral"}],"key":{"a":"right","b":"perk","c":"right","d":"perk","e":"right","f":"perk"},"relearn":"Water, safety gear and reasonable rest are part of safe work; lounges and freebies are just perks.","persona":"Meena","source":"safe conditions vs perks"},
  {"id":"kr-1279","cat":"rights-at-work","type":"sort","hook":"Sort: a worker myth to drop, or a fact to keep?","items":[{"id":"a","text":"Wages are owed for work done"},{"id":"b","text":"'Junior means no rights'"},{"id":"c","text":"Written terms protect both sides"},{"id":"d","text":"'Complaining always gets you fired'"},{"id":"e","text":"Equal work earns equal pay"},{"id":"f","text":"'Off-the-books pay erases rights'"}],"bins":[{"id":"keep","label":"Keep, it's a fact","valence":"pos"},{"id":"drop","label":"Drop, it's a myth","valence":"neg"}],"key":{"a":"keep","b":"drop","c":"keep","d":"drop","e":"keep","f":"drop"},"relearn":"Wages owed, written terms and equal pay are facts; 'juniors have no rights' and 'complaining gets you fired' are myths.","persona":"any","source":"myths vs facts"},
  {"id":"kr-1280","cat":"rights-at-work","type":"branch","persona":"any","source":"trial became job","hook":"Your 'two-week unpaid trial' at a coaching centre is now month three of full-time teaching.","steps":[{"prompt":"The owner, Mr Bhatia, says pay will start \"very soon\". What do you do?","options":[{"text":"Ask him to put the pay start date and amount in writing","then":"He frowns, then says he'll \"think about a date\" by Monday.","best":true},{"text":"Keep waiting quietly so you don't seem ungrateful","then":"Another month of classes passes. \"Very soon\" is still the answer."},{"text":"Ask a senior teacher when she thinks pay will start","then":"She shrugs. \"He told me the same thing last year.\""},{"text":"Take on extra batches to prove you're worth paying","then":"Your timetable fills up. Pay still isn't mentioned."}],"why":"A dated, written pay start turns a vague promise into something you can hold him to."},{"prompt":"At the staff meeting, Mr Bhatia says pay \"will be reviewed after exams\". What do you do?","options":[{"text":"Email him your start date and ask for a pay start date","then":"Your email now shows, in dated writing, three months of unpaid work.","best":true},{"text":"Accept that exams are a busy time, and wait","then":"Exams end. The review never happens."},{"text":"Complain about him to the students' parents","then":"A parent mentions it to Mr Bhatia, who is furious with you."},{"text":"Ask him again after class, just the two of you","then":"\"Trust me,\" he says. Nothing is written down."}],"why":"An email creates a dated record of your work and your ask."},{"prompt":"A friend says, \"At least you're getting experience.\" What do you think?","options":[{"text":"Experience is nice, but three months of teaching is a job","then":"She nods slowly. \"I hadn't thought of it as a job.\"","best":true},{"text":"She's right. Experience matters more than pay right now","then":"You feel grateful, and the unpaid months keep adding up."},{"text":"Maybe I'm just not good enough to be paid yet","then":"You start doubting the classes you've been running alone."},{"text":"True. I'll give it just one more month and see","then":"One more month begins with the same promise."}],"why":"Once a trial becomes your regular work, it deserves pay. Calling it experience doesn't change that."}],"debrief":"A full job done for months unpaid is exploitation; pin the pay-start in writing.","relearn":"Pin the pay-start in writing when an unpaid 'trial' has become your real job."},
  {"id":"kr-1281","cat":"rights-at-work","type":"branch","persona":"Meena","source":"held originals","hook":"HR at your packaging job kept your original mark-sheets and says you'll get them back in two years.","steps":[{"prompt":"A better job has offered you a place, but it needs the originals. What do you do?","options":[{"text":"Write to HR asking for your originals back by a date","then":"HR replies, \"Company policy,\" but your request is now on record with a date.","best":true},{"text":"Leave them there for now. It's not worth the fight","then":"The new job's joining date creeps closer without your papers."},{"text":"Tell the new job you've lost your originals","then":"The new HR asks for duplicates, which take months to get."},{"text":"Ask your supervisor to have a quiet word with HR for you","then":"He says he'll try. A week passes with no news."}],"why":"A dated written request puts on record that the documents are yours and you want them."},{"prompt":"With the joining date close, you go to HR in person. She says papers are kept \"so people don't run away\". What do you say?","options":[{"text":"Say they're yours, and offer copies in place of the originals","then":"There's a pause. \"Let me check with the manager,\" she says.","best":true},{"text":"Say you understand, and you'll just stay the two years","then":"\"Good,\" she says, and turns back to her screen."},{"text":"Call it blackmail and say everyone will hear about it","then":"\"Don't threaten us,\" she says, and asks you to leave her desk."},{"text":"Ask if you could borrow them for just one week","then":"\"Only if you sign a bond,\" she says."}],"why":"Offering copies meets any fair need while keeping what's yours in your hands."},{"prompt":"Days later, a notice goes up: staff can have their papers back for a 10,000 \"release fee\". What do you do?","options":[{"text":"Refuse to pay for your own papers, and tell HR in writing","then":"HR goes quiet, then replies that the fee is \"only a suggestion\".","best":true},{"text":"Pay it. Getting them back quickly is all that matters now","then":"You pay from your savings, and HR says they'll \"process it\" next month."},{"text":"Try to bargain the fee down to 5,000","then":"They agree to 7,000, and you're still paying for what's yours."},{"text":"Say you'll go to the newspapers about this","then":"HR laughs and says, \"Go ahead,\" and the papers stay locked up."}],"why":"Your documents are yours. Paying to get them back isn't something you owe."},{"prompt":"Your new job says it can hold your place for one more week. What do you do?","options":[{"text":"Write to HR for your papers, and call NALSA 15100","then":"A legal-aid volunteer helps you word a clear, firm letter to the firm.","best":true},{"text":"Give up the new job and stay where you are","then":"The better job goes to someone else."},{"text":"Ask the new job to accept photocopies for now","then":"They agree for now, but want the originals within a month."},{"text":"Ask a local politician you know to lean on your employer","then":"He promises to \"see\", and doesn't return your calls."}],"why":"Holding your papers to trap you isn't okay or your fault. Free legal aid can help you get them back."}],"debrief":"Your certificates belong to you; a written request to return them is fair.","relearn":"Your original certificates are yours; ask in writing for them back."},
  {"id":"kr-1282","cat":"rights-at-work","type":"branch","persona":"any","source":"job fee scam","hook":"A recruiter on WhatsApp offers you a data-entry job from home at 25,000 a month.","steps":[{"prompt":"She asks for a 1,500 \"registration fee\" today to hold your seat. What do you do?","options":[{"text":"Stop and check the company before paying anything","then":"You search the name. There's no website, only other people's complaints.","best":true},{"text":"Pay quickly before the seat goes to someone else","then":"The payment goes through. She says a \"training kit fee\" is next."},{"text":"Pay half now and the other half after joining","then":"She accepts 750 happily and asks for the rest by tonight."},{"text":"Ask for an offer letter first, and then pay","then":"A glossy PDF arrives within minutes, with a payment QR code at the bottom."}],"why":"A genuine employer pays you. An up-front fee to be hired is a classic scam sign."},{"prompt":"She messages: \"Only 3 seats left! Pay within the hour or lose your place.\" What do you do?","options":[{"text":"Pay nothing more, and stop replying to the rush","then":"Three more messages arrive overnight, each more urgent than the last.","best":true},{"text":"Pay now. You can't miss a 25,000 job","then":"A new request arrives: 2,000 for \"verification\"."},{"text":"Ask her for a video call to prove she's real","then":"She agrees, then cancels at the last minute and asks for payment first."},{"text":"Try to bargain the fee down to 500","then":"\"Okay, 500 only for you,\" she says, and sends a fresh QR code."}],"why":"Pressure to pay fast is how scams stop you checking. Paying nothing more keeps your money safe."},{"prompt":"Next morning, she sends a \"joining letter\" asking for your Aadhaar and bank details. What do you do?","options":[{"text":"Don't send them, and report the number at 1930","then":"The helpline logs the number and tells you what to watch for.","best":true},{"text":"Send them. Every real job needs ID anyway","then":"Your details are now with someone you've never met."},{"text":"Send only the Aadhaar, and keep the bank details back","then":"She thanks you, then asks for the bank details \"for salary\"."},{"text":"Reply with insults to scare her off for good","then":"She blocks you, and the number moves on to someone else."}],"why":"Sharing ID with an unverified recruiter is risky. Reporting at 1930 helps stop the scam."},{"prompt":"Your friend Kabir got the same offer and is about to pay. What do you tell him?","options":[{"text":"A real job pays you. Don't pay any fee to be hired","then":"Kabir cancels the payment and warns his hostel group too.","best":true},{"text":"Pay only if the company has a nice website","then":"He finds a slick site made last week, and pays."},{"text":"It's his choice. Better not to interfere","then":"He pays, then asks you why the recruiter stopped answering."},{"text":"Pay by card, so he can always get it back","then":"He pays by card, and the refund request goes nowhere."}],"why":"Warning a friend plainly helps stop a scam before it reaches them."}],"debrief":"You should never pay to be hired; up-front 'job fees' are a red flag.","relearn":"A real job pays you; never pay an up-front fee to start work."},
  {"id":"kr-1283","cat":"rights-at-work","type":"branch","persona":"any","source":"blank sheet","hook":"On your first day at a warehouse, the supervisor, Manoj, hands you a salary register with the amount column empty.","steps":[{"prompt":"He says, \"Sign for records. Salary gets filled in later.\" What do you do?","options":[{"text":"Politely decline until the amount is filled in","then":"Manoj clicks his tongue. \"Fine. I'll ask the office for the figure.\"","best":true},{"text":"Sign it to keep things smooth on your first day","then":"He takes the register back. The empty column stays empty."},{"text":"Sign it, and take a photo of the blank page","then":"He frowns at your phone, but your signature is already on it."},{"text":"Ask the worker next to you whether he signed","then":"\"Everyone signs,\" he says, and hands you the pen."}],"why":"A blank signed sheet can be filled with any number, so the amount must go in first."},{"prompt":"At month end, you're paid 11,000, not the 14,000 you were told at the interview. What do you do?","options":[{"text":"Ask Manoj to show you what's written against your name","then":"The register shows 11,000 against your name, in someone else's writing.","best":true},{"text":"Assume the office knows better, and accept it","then":"You take the 11,000 home, wondering what else is written there."},{"text":"Shout at Manoj in front of the whole floor","then":"The floor goes quiet, and Manoj walks away."},{"text":"Say nothing, and quietly start looking for another job","then":"You send a few applications, and the missing 3,000 stays missing."}],"why":"Seeing what's written against your name tells you exactly what you're dealing with."},{"prompt":"Next day, Manoj tells the floor the office has fixed everyone's pay, and it's \"final\". What do you do?","options":[{"text":"Write to the office with the promised and paid amounts","then":"The office replies that they'll \"look into it\". Now it's in writing.","best":true},{"text":"Accept it. Arguing will only cost you the job","then":"Next month's slip shows 11,000 again."},{"text":"Refuse to sign anything else ever again at this place","then":"Manoj marks you as \"difficult\", and nothing changes."},{"text":"Ask Manoj to \"adjust it\" for you next month","then":"\"Let's see,\" he says, and next month is the same."}],"why":"A written note with both numbers puts the gap on record, where it can be raised."}],"debrief":"Never sign a blank pay document; the figure must be filled in first.","relearn":"Don't sign a blank salary sheet; insist the amount is written in before you sign."},
  {"id":"kr-1284","cat":"rights-at-work","type":"branch","persona":"Meena","source":"final settlement","hook":"You resigned from a hotel kitchen job a month ago, and your last salary is still 'pending'.","steps":[{"prompt":"Your calls to the manager, Mr Fernandes, go unanswered. What do you do?","options":[{"text":"Send one message listing days worked and pay owed","then":"The message shows two blue ticks. It's now dated and on record.","best":true},{"text":"Assume the money is gone, and give up on it","then":"You stop calling. The money stays with the hotel, and it still stings."},{"text":"Keep calling him, ten times a day if needed","then":"By evening, your calls stop going through."},{"text":"Ask your old coworker Joseph to remind him for you","then":"Joseph mentions it. Mr Fernandes tells him it's \"processing\"."}],"why":"One clear written request with days and amount creates a dated record of the claim."},{"prompt":"A week later, the accounts clerk calls about your uniform and adds, \"Settlement takes 90 days here.\" What do you do?","options":[{"text":"Ask for that rule and a pay date in writing","then":"The clerk hesitates. \"I'll ask sir and email you.\"","best":true},{"text":"Say okay, and wait the 90 days quietly","then":"The 90 days pass, and then there's a new reason."},{"text":"Say you'll sit in the lobby until you're paid","then":"You go and sit there, and security walks you out by evening. Nothing is paid."},{"text":"Ask if they could pay just half of it now","then":"\"Can't split it,\" the clerk says, and hangs up."}],"why":"Asking for the rule and a pay date in writing puts the stalling on record."},{"prompt":"Mr Fernandes finally texts: \"You didn't serve full notice. Nothing is due.\" What do you do?","options":[{"text":"Say worked days are owed, and ask for any cut in writing","then":"He replies with one line: \"Will check with accounts.\"","best":true},{"text":"Accept it. Maybe you did leave too soon","then":"You feel guilty, and a month's pay quietly disappears."},{"text":"Call and argue with him until he hangs up","then":"He hangs up, and later texts, \"Don't call again.\""},{"text":"Offer to come back and work one more week to earn it","then":"\"Come Monday,\" he says, and your old pay is still not mentioned."}],"why":"Pay for days already worked stays owed. Any deduction should be explained in writing."},{"prompt":"Another month passes with no pay. What do you do?","options":[{"text":"Take your records to free legal aid on NALSA 15100","then":"A legal-aid volunteer looks at his texts and your days worked, and explains the next step.","best":true},{"text":"Write the money off as a lesson learnt","then":"You move on, and the hotel keeps your month's pay."},{"text":"Post the hotel's name with angry reviews everywhere","then":"A few people like the posts. The money doesn't move."},{"text":"Turn up at the hotel and argue with the manager","then":"Mr Fernandes repeats that nothing is due and leaves for a meeting."}],"why":"Earned wages are owed, and free legal aid means you don't need money to chase them."},{"prompt":"Your old coworker Joseph leaves the hotel next month and asks how to avoid this. What do you tell him?","options":[{"text":"Resign in writing, and log days worked and pay due","then":"Joseph starts a note on his phone that same night.","best":true},{"text":"Just leave quietly and hope they pay him","then":"He nods. \"Maybe they'll be nicer to me.\""},{"text":"Skip his last week, since they won't pay anyway","then":"He skips it, and now they have a reason to cut his pay."},{"text":"Get the manager to promise on the phone to pay on time","then":"He gets the promise. There's no record of it anywhere."}],"why":"Written records from day one make final pay much easier to claim."}],"debrief":"Earned final wages are owed; a dated written request starts the claim.","relearn":"Send a clear written request for your earned final wages; you're owed them."},
  {"id":"kr-1285","cat":"rights-at-work","type":"branch","persona":"any","source":"surprise shifts","hook":"Your call-centre offer letter says day shifts, but your manager, Vikram, has put you on nights.","steps":[{"prompt":"The new roster has three night shifts a week, with no extra pay. What do you do?","options":[{"text":"Point to your agreed hours and ask how nights are paid","then":"Vikram frowns. \"Everyone's doing nights. I'll check about pay.\"","best":true},{"text":"Do the shifts to stay on his good side","then":"He thanks you. By week two, it's four nights."},{"text":"Swap your night shifts with a colleague on the quiet","then":"Your colleague agrees once, then needs a favour back."},{"text":"Report sick on your night-shift days","then":"HR notices the pattern and asks for medical notes."}],"why":"Your agreed hours are the anchor. Extra shifts should be agreed and paid."},{"prompt":"In a team meeting, Vikram says, \"Nights are just part of the job now.\" What do you do?","options":[{"text":"Ask for any change in hours to be agreed in writing","then":"Two colleagues nod. Vikram says he'll \"send something in writing\".","best":true},{"text":"Keep quiet, since nobody else is objecting","then":"The meeting moves on. The roster stays."},{"text":"Say loudly that he's exploiting all of you","then":"The room goes stiff, and Vikram cuts the meeting short."},{"text":"Ask if you can do the nights just for this month","then":"\"Sure,\" he says, and next month's roster looks the same."}],"why":"Asking for changes in writing protects you and everyone else on the roster."},{"prompt":"Your friend says, \"Push back and they'll just fire you.\" What do you think?","options":[{"text":"Holding to my agreed terms is fair, not difficult","then":"She thinks. \"Fair. My letter says nights are paid extra.\"","best":true},{"text":"She's right. Better tired than jobless","then":"You keep doing nights, and your sleep falls apart."},{"text":"I'll push back, but only after I find a new job","then":"The job search drags on, and so do the nights."},{"text":"Maybe I shouldn't have expected day shifts at all","then":"You feel small for having asked for anything."}],"why":"Asking an employer to stick to agreed terms is your right, not trouble-making."}],"debrief":"Shifts beyond your agreed hours should be agreed and paid; your terms are the anchor.","relearn":"Extra shifts beyond your agreed hours should be agreed and paid."},
  {"id":"kr-1286","cat":"rights-at-work","type":"branch","persona":"Aarti","source":"pay gap","hook":"At your marketing internship, you overhear that the male interns get 3,000 more a month for the same work.","steps":[{"prompt":"Your fellow intern Sana says, \"Let it go. We're just interns.\" What do you do?","options":[{"text":"Check the facts, then raise it with your manager","then":"A male intern confirms his stipend, and you note down both amounts.","best":true},{"text":"Let it go. Interns shouldn't make waves","then":"Sana looks relieved. The gap stays where it was."},{"text":"Post about it on the team's WhatsApp group","then":"The group goes silent, and your manager calls you in, annoyed."},{"text":"Ask the male interns to complain on your behalf","then":"They shrug. \"It's not our issue,\" one says."}],"why":"Checking the facts first makes your case clear and hard to wave away."},{"prompt":"A week later, the gap is office gossip. Your manager, Mr Kapoor, tells the interns the men \"negotiated better\". What do you do?","options":[{"text":"Say it's the same role and output, so the same pay","then":"He pauses. \"Put it in an email. I'll take it to HR.\"","best":true},{"text":"Ask him how you could negotiate better next time","then":"He gives you tips, and your stipend stays the same."},{"text":"Accept it. Maybe you should have pushed harder","then":"You leave feeling it was somehow your fault."},{"text":"Tell him the company is sexist, and walk out","then":"He calls you \"emotional\", and the talk ends there."}],"why":"The same role and output should earn the same pay. Bargaining skills don't change that."},{"prompt":"HR emails all interns: \"Stipends are confidential and not for discussion.\" What do you do?","options":[{"text":"Reply that you're asking for equal pay for equal work","then":"HR asks you and Mr Kapoor to meet next week.","best":true},{"text":"Drop it. You don't want a bad reference","then":"You stay quiet, and the gap carries on into your last month."},{"text":"Reply to all, calling the email a cover-up","then":"HR calls you in about your tone, not the gap."},{"text":"Reply with an apology, and promise not to discuss it","then":"HR thanks you, and the matter is closed."}],"why":"Equal pay for equal work is a fair ask, and saying so plainly keeps it on track."},{"prompt":"Sana wants to ask HR about her own stipend, but worries it'll look like stirring trouble. What do you say?","options":[{"text":"Say equal pay is a fair ask, and hers to make","then":"Sana drafts her own email to HR that evening.","best":true},{"text":"Tell her to wait until her final review to ask","then":"Sana waits, and her internship clock keeps running."},{"text":"Tell her to ask for more without mentioning the gap","then":"HR offers her a little more, but still less than the men."},{"text":"Tell her to accept it, since it's only an internship","then":"Sana shrugs. \"I thought so,\" she says quietly."}],"why":"Equal pay is her right too. Asking about it plainly isn't stirring trouble."}],"debrief":"Same role and output should earn the same pay; the gap is fair to question.","relearn":"Equal work earns equal pay; you can raise an unfair pay gap."},
  {"id":"kr-1287","cat":"rights-at-work","type":"branch","persona":"any","source":"cash job","hook":"Your friend Irfan says a catering firm pays 800 a day, cash in hand, no contract.","steps":[{"prompt":"The owner wants you this weekend. What do you do?","options":[{"text":"Take it, and ask for the rate and hours in a text","then":"The owner texts back: \"800 a day, 4 pm to midnight.\" You save it.","best":true},{"text":"Take it with nothing written. Cash is simpler","then":"He says, \"See you Saturday,\" and that's all."},{"text":"Take it, and ask Irfan to be your witness","then":"Irfan agrees, though he'll be at another event on Sunday."},{"text":"Ask for the whole weekend's pay in advance","then":"He laughs. \"Pay is after the event.\" You take the job anyway."}],"why":"Cash pay is fine, and a quick text with the rate and hours gives you proof."},{"prompt":"After the weekend, the owner offers you every Saturday this month. What do you do?","options":[{"text":"Say yes, and ask for the dates, rate and hours in a text","then":"He sends a message listing four Saturdays at 800 a day. You screenshot it.","best":true},{"text":"Say yes. He paid last time, so trust is already built","then":"He nods, and the month begins on a handshake."},{"text":"Say yes, and keep your own diary of hours","then":"Your diary fills with hours. The rate lives only in his head."},{"text":"Say yes if he pays the whole month up front","then":"\"Nobody pays before the work,\" he says, and you agree anyway."}],"why":"Written dates, rate and hours protect you when memories 'change'."},{"prompt":"Irfan was paid less than agreed and has nothing in writing. What do you tell him?","options":[{"text":"Text the owner the dates, hours and rate, and save the reply","then":"Irfan sends it. The owner replies, \"Will settle the rest next week.\"","best":true},{"text":"Say cash jobs don't come with rights, so he should let it go","then":"Irfan lets it go, and so does the money."},{"text":"Tell him to post the owner's name online to shame him","then":"The owner stops calling Irfan for any events."},{"text":"Tell him to ask the owner nicely in person one more time","then":"\"Next time,\" the owner tells him. There's no record of it."}],"why":"Cash work still carries rights, and a written message creates the record to claim them."}],"debrief":"Cash work still carries rights; get written proof of pay and terms.","relearn":"Even for cash work, keep written proof of your pay and terms."},
  {"id":"kr-1288","cat":"rights-at-work","type":"branch","persona":"any","source":"confusing clause","hook":"Your first job contract at a startup has a clause about 'recovery of training costs at the company's discretion'.","steps":[{"prompt":"HR, Rhea, says, \"Just sign. Everyone does.\" What do you do?","options":[{"text":"Ask Rhea what the clause means in plain words","then":"Rhea reads it twice. \"If you leave early, they can charge you. I think.\"","best":true},{"text":"Sign it, since everyone else in your batch did","then":"Rhea smiles and files it. You're not sure what you agreed to."},{"text":"Sign now, and look up what it means tonight","then":"You find out that night. The contract is already signed."},{"text":"Strike the clause out with a pen, then sign","then":"Rhea frowns. \"You can't just edit it. I'll need a fresh copy.\""}],"why":"You're entitled to understand every clause you sign. 'Everyone does' isn't an explanation."},{"prompt":"That evening, a senior tells you the training cost can be \"up to 2 lakh\". What do you do?","options":[{"text":"Ask HR in writing what training costs and for how long","then":"Rhea replies: the cost drops to zero after one year. Now it's in writing.","best":true},{"text":"Assume they'd never actually charge anyone that","then":"You put it out of mind. The clause sits in the contract, unexplained."},{"text":"Decide you'll just never leave before a year is up","then":"You feel calmer, and a little boxed in."},{"text":"Ask a few seniors how often it has been charged","then":"\"Never heard of it happening,\" one says. Another isn't sure."}],"why":"Written answers from HR tell you exactly what you're agreeing to."},{"prompt":"Next week, Rhea emails all new joiners: the clause is \"standard\" and can't be changed. What do you do?","options":[{"text":"Ask a legal-aid clinic what the clause allows","then":"The clinic explains what the clause can and can't do, so you know where you stand.","best":true},{"text":"Accept it. If it's standard, it must be fine","then":"You accept, and \"standard\" is the only explanation you have."},{"text":"Argue with Rhea until she agrees to change it","then":"Rhea gets curt. \"I don't make these rules.\""},{"text":"Ask her to promise it will never be used on you","then":"\"Of course,\" she says. The clause stays exactly as written."}],"why":"Proper advice shows what the clause really means, so you know where you stand."}],"debrief":"Understand each clause before signing; 'everyone does' is not a reason.","relearn":"Ask what a clause means and get advice before signing a contract."},
  {"id":"kr-1289","cat":"rights-at-work","type":"branch","persona":"Meena","source":"unsafe site","hook":"You cut your hand badly on a building site where no one was given gloves.","steps":[{"prompt":"The contractor, Ramesh, says, \"Bandage it and keep working.\" What do you do?","options":[{"text":"Get it treated first, and note down how it happened","then":"A clinic stitches it. That night you write down the time, place and missing gloves.","best":true},{"text":"Bandage it and carry on so you're not blamed","then":"You keep working. Nothing is written down, and no one asks about the gloves."},{"text":"Say nothing, since injuries come with site work","then":"Ramesh nods. The next day, everyone works without gloves again."},{"text":"Borrow a coworker's old gloves and carry on","then":"He shares one torn pair. The rest of the crew still has none."}],"why":"Treatment comes first, and a written note of what happened is your record."},{"prompt":"Two days later, another worker slips near an open pit with no barrier. What do you do?","options":[{"text":"Report the hazards to the site in-charge in writing","then":"The in-charge reads it, frowns, and has the pit covered the next morning.","best":true},{"text":"Stay quiet so nobody blames you for trouble","then":"Work goes on around the open pit."},{"text":"Warn the others to be careful, and leave it there","then":"Everyone watches their step, and the pit stays open."},{"text":"Stop coming to work without telling anyone why","then":"Ramesh marks you absent and hires someone else for the week."}],"why":"Safe conditions are owed to every worker. A written report makes the hazard official."},{"prompt":"Ramesh says any treatment cost is \"your own problem\". What do you do?","options":[{"text":"Write down what happened, and call NALSA 15100","then":"A legal-aid volunteer reads what you wrote and explains your options.","best":true},{"text":"Pay it yourself. You should have been more careful","then":"You pay from your rent money and start blaming yourself."},{"text":"Threaten to shame Ramesh all over social media","then":"Ramesh laughs it off, and you're dropped from the next site list."},{"text":"Ask the in-charge for a small favour, off the record","then":"He gives you 500 and asks you to keep it quiet."}],"why":"An injury from missing safety gear isn't your fault. Records and free legal aid help you claim."},{"prompt":"A new worker, Sunita, asks if it's worth reporting a loose ladder. What do you tell her?","options":[{"text":"Report it in writing. Safety is owed to everyone","then":"Sunita writes a note to the in-charge before lunch.","best":true},{"text":"Don't. She'll be marked as a troublemaker","then":"Sunita keeps quiet and climbs carefully around it."},{"text":"Tie it up with some rope herself for now","then":"The rope holds for a day, then slips."},{"text":"Mention it to Ramesh casually and leave it there","then":"Ramesh says, \"Will see,\" and the ladder stays loose."}],"why":"Reporting a hazard in writing protects everyone on the site, not just you."}],"debrief":"Safe conditions are owed to every worker; record and report a hazard.","relearn":"Report unsafe conditions and keep a record; safety is owed to every worker."},
  {"id":"kr-1290","cat":"rights-at-work","type":"branch","persona":"any","source":"platform terms change","hook":"You deliver food through an app, and overnight your pay per order dropped from 40 to 25.","steps":[{"prompt":"A new \"partner terms\" pop-up appears with an Accept button. What do you do?","options":[{"text":"Screenshot the new terms and last week's pay first","then":"Your gallery now holds the new terms and last week's pay summary, dated.","best":true},{"text":"Tap Accept so you don't lose today's orders","then":"The pop-up vanishes, and so does any trace of the old rate."},{"text":"Uninstall the app in anger and walk away","then":"You lose a day's earnings, and when you reinstall, the new terms are waiting."},{"text":"Tap Accept now, and complain to support later","then":"Orders start coming. The old rate isn't shown anywhere now."}],"why":"Saving the before-and-after first keeps your evidence of what changed."},{"prompt":"Riders in your WhatsApp group are angry and want to do something. What do you suggest?","options":[{"text":"Everyone saves before-and-after screenshots first","then":"Screenshots flood the group. Now there's a shared record of the change.","best":true},{"text":"Just accept it. The apps always win in the end","then":"The group goes quiet. A few riders switch apps."},{"text":"Leave one-star reviews on the app store together","then":"The reviews pile up. The rate stays at 25."},{"text":"Wait for someone else in the group to sort it out","then":"Days pass. Nobody sorts anything out."}],"why":"Shared, dated screenshots give everyone a record to raise the change with."},{"prompt":"A new rider asks what to do if the app changes pay again. What do you tell him?","options":[{"text":"Screenshot the terms and pay before tapping Accept","then":"He makes a folder called \"Pay proof\" on his phone that night.","best":true},{"text":"Accept fast, or you'll miss out on orders","then":"He nods and taps Accept on everything without reading."},{"text":"Just switch to another app when it happens","then":"He switches once, and the new app cuts its rate too."},{"text":"Complain on social media and hope it goes viral","then":"He posts. A few likes, and the rate stays the same."}],"why":"Your screenshots are your evidence, and they only exist if you save them first."}],"debrief":"When platform terms change, save the before-and-after as evidence first.","relearn":"Save screenshots of changed gig-app terms before acting; it's your evidence."},
  {"id":"kr-1291","cat":"rights-at-work","type":"branch","persona":"Aarti","source":"role denied to woman","hook":"You've done the field sales role well as a stand-in, but your manager, Mr Sethi, says it's 'not for women'.","steps":[{"prompt":"He says it needs night travel and gives it to a new male hire. What do you do?","options":[{"text":"Ask him for the job's actual criteria, in writing","then":"Mr Sethi hesitates. \"Targets, travel, client handling. I'll send it.\"","best":true},{"text":"Accept that some roles just aren't for women","then":"You go back to your desk, and the role goes to the new hire."},{"text":"Promise never to complain about travel if he reconsiders","then":"\"It's not about complaining,\" he says, not moving."},{"text":"Tell the whole team that he's a sexist","then":"The team goes awkward, and Mr Sethi stops talking to you."}],"why":"Job-based criteria show whether the bar is the work or your gender."},{"prompt":"Your record shows you met every target, including two late client visits. What do you do?","options":[{"text":"Email him your record against the job's demands","then":"Your email lines up targets, travel and client visits with your results.","best":true},{"text":"Hope he notices your numbers on his own someday","then":"Weeks pass. He doesn't bring it up."},{"text":"Ask HR to move you to a desk role instead","then":"HR moves you, and the field role closes quietly behind you."},{"text":"Ask your father to call Mr Sethi and explain","then":"Mr Sethi is polite to your father and changes nothing."}],"why":"Your record set against what the job needs makes the case in plain facts."},{"prompt":"At a team meeting, Mr Sethi says women aren't sent on field visits \"for their own safety\". What do you do?","options":[{"text":"Ask what safety support the job gives to everyone","then":"He pauses. \"Company cabs for late visits, I suppose. For everyone.\"","best":true},{"text":"Thank him. Maybe he's only protecting you","then":"He smiles, and the role stays with the new hire."},{"text":"Tell him your safety is none of his business","then":"He goes stiff and moves on to the next item."},{"text":"Offer to do the role with daytime visits only","then":"He agrees, and your pay stays below the full role's."}],"why":"Safety support belongs in the job for everyone. It's not a reason to shut women out."},{"prompt":"A month later, a junior, Pooja, is told the same about a field role. What do you tell her?","options":[{"text":"Get the real criteria in writing, and show her record","then":"Pooja drafts her email that evening and asks you to read it.","best":true},{"text":"Tell her some roles just aren't meant for women","then":"Pooja looks crushed and applies for a desk role."},{"text":"Tell her to take a desk role and stay safe for now","then":"She takes it, and wonders what the field role would have been."},{"text":"Tell her to prove herself for a year first, then ask","then":"She waits, and a year later the role has gone to someone else."}],"why":"Asking for job-based criteria helps any woman shut out of a role she can do."}],"debrief":"A role shouldn't be closed off for being a woman; ask for job-based criteria.","relearn":"Ask for job-based criteria when a role is denied for being a woman."},
  {"id":"kr-1292","cat":"rights-at-work","type":"branch","persona":"Deepak","source":"late stipend","hook":"Your research internship stipend of 6,000 a month is now two months late.","steps":[{"prompt":"The office clerk says \"next week\" for the fourth time. What do you do?","options":[{"text":"Email the owed amount and dates to the clerk and your guide","then":"Your guide replies within a day: \"Forwarding to accounts.\"","best":true},{"text":"Keep accepting \"next week\". They'll pay eventually","then":"You skip meals to stretch your last 500 rupees."},{"text":"Catch your guide in the corridor and ask him to look into it","then":"He nods, distracted. \"I'll mention it.\" You're not sure he will."},{"text":"Borrow from friends and stop asking about it","then":"Your friends help, and the stipend stays stuck."}],"why":"An email with amount and dates creates a record that reaches the right people."},{"prompt":"Days later, a note from accounts says your stipend is held for a \"missing\" form. It doesn't say which. What do you do?","options":[{"text":"Ask in writing for the exact form and who must sign it","then":"They reply naming one form. Your guide signs it the same day.","best":true},{"text":"Resubmit every form you've ever filled in","then":"You lose a day to paperwork. The missing one still isn't clear."},{"text":"Give up. The system is just too slow for students","then":"The file sits on someone's desk."},{"text":"Lose your temper with the staff at the counter","then":"The staff shut the window early."}],"why":"A precise written question gets a precise answer instead of a runaround."},{"prompt":"A junior intern, Meher, asks how to deal with a late stipend. What do you tell her?","options":[{"text":"Put the amount and dates in writing, and follow up by email","then":"She drafts the email in the canteen and sends it before lunch ends.","best":true},{"text":"Just wait. Complaining makes you look greedy","then":"She nods and waits, and her month's rent comes due."},{"text":"Get her parents to call the head of department","then":"Her father calls. The office is polite, and nothing moves."},{"text":"Keep chasing people in person until someone helps","then":"She chases for days. No one remembers what they promised."}],"why":"A stipend for work is owed, and a written, dated follow-up moves it forward."}],"debrief":"A promised stipend for work is owed; a written, dated follow-up moves it forward.","relearn":"Put owed stipend amounts and dates in a written follow-up."},
  {"id":"kr-1293","cat":"rights-at-work","type":"branch","persona":"any","source":"reference threat","hook":"You've got a better offer, but your boss at the travel agency, Mr Arora, hints he'll 'ruin your reference' if you go.","steps":[{"prompt":"You want to take the new job. What do you do first?","options":[{"text":"Resign in writing, with your notice period and last day","then":"Your email goes out with a clear last date. Mr Arora doesn't reply.","best":true},{"text":"Stay on for now. A bad reference could follow you","then":"You ask the new firm for more time, and the fear stays with you."},{"text":"Just stop coming in, without a word to anyone","then":"Mr Arora calls eleven times, then sends an angry message."},{"text":"Tell him in person and hope he takes it well","then":"He goes red. \"We'll see,\" he says. Nothing is written anywhere."}],"why":"A written resignation with dates gives you a clean, provable exit."},{"prompt":"Mr Arora warns that nobody will hire you once he's done. What do you do?","options":[{"text":"Gather your own records: emails, targets, client praise","then":"Your folder fills with client thank-yous and your sales figures.","best":true},{"text":"Apologise to him, and ask if you can stay on after all","then":"He smiles. That evening, the new firm emails that your offer is still open."},{"text":"Threaten to expose him online if he tries it","then":"He forwards your message to the owner as \"misconduct\"."},{"text":"Ask your colleagues to talk him down for you","then":"They try, but he only gets angrier."}],"why":"Your own records of good work stand on their own, whatever he says."},{"prompt":"The new firm asks for a reference. What do you do?","options":[{"text":"Offer another senior who knew your work, plus your records","then":"The new firm calls your old team lead, sees your figures, and is satisfied.","best":true},{"text":"Give only Mr Arora's name and hope for the best","then":"Mr Arora gives a cold, vague answer on the phone."},{"text":"Leave the travel agency off your CV entirely","then":"The gap in your CV raises more questions than it answers."},{"text":"Offer Mr Arora a week of unpaid work for a good reference","then":"You work a week for free, and the reference is still lukewarm."}],"why":"Other references and your records mean one person can't hold your career hostage."}],"debrief":"A clean written resignation and your own work records protect your exit.","relearn":"Resign in writing and keep records of your work; a vague threat shouldn't trap you."},
  {"id":"kr-1294","cat":"rights-at-work","type":"match","hook":"Match the work document to what it does for you.","pairs":[{"left":"An offer letter","right":"States your pay, hours and role"},{"left":"A monthly payslip","right":"Records pay and any deductions"},{"left":"Your own hours log","right":"Backs up an overtime claim"},{"left":"A signed contract copy","right":"Holds both sides to agreed terms"},{"left":"Saved pay messages","right":"Evidence if pay is disputed"}],"relearn":"Offer letter, payslip, hours log, contract copy and saved messages each give you a different layer of proof.","persona":"any","source":"work documents"},
  {"id":"kr-1295","cat":"rights-at-work","type":"match","hook":"Match the work problem to a sensible first step.","pairs":[{"left":"Unpaid final salary","right":"Written request listing days owed"},{"left":"No contract given","right":"Ask for terms in writing"},{"left":"Originals held back","right":"Written request to return them"},{"left":"Unsafe site","right":"Report and record the hazard"},{"left":"Surprise unpaid overtime","right":"Point to your agreed hours"}],"relearn":"Each work problem has a calm first step, mostly a written request or pointing back to agreed terms.","persona":"any","source":"first steps"},
  {"id":"kr-1296","cat":"rights-at-work","type":"match","hook":"Match the worker to the rights they still hold.","pairs":[{"left":"A paid intern","right":"Fair stipend and agreed hours"},{"left":"A contract cleaner","right":"Pay for work and safe conditions"},{"left":"A gig 'partner' rider","right":"Agreed terms and earnings owed"},{"left":"A part-time worker","right":"Pay for the hours worked"},{"left":"A daily-wage worker","right":"Wages for the day's work done"}],"relearn":"Interns, contract, gig, part-time and daily-wage workers each keep real rights to pay and fair terms.","persona":"any","source":"who holds rights"},
  {"id":"kr-1297","cat":"rights-at-work","type":"match","hook":"Match the red-flag phrase to what it really signals.","pairs":[{"left":"'Pay a fee to start'","right":"Likely a job scam"},{"left":"'Salary decided later'","right":"Vague, unenforceable pay"},{"left":"'Sign this blank sheet'","right":"They could fill in any figure"},{"left":"'Give us your originals'","right":"An attempt to trap you"},{"left":"'Work free to prove yourself'","right":"Unpaid real work"}],"relearn":"Up-front fees, vague pay, blank sheets, held originals and 'work free to prove yourself' are all warning signs.","persona":"any","source":"red-flag phrases"},
  {"id":"kr-1298","cat":"rights-at-work","type":"match","hook":"Match the fair internship feature to why it matters.","pairs":[{"left":"A set stipend","right":"Pays you for real work done"},{"left":"Written hours","right":"Stops endless unpaid time"},{"left":"A named mentor","right":"Means real learning, not just labour"},{"left":"A clear end date","right":"It won't drag on forever"},{"left":"Defined tasks","right":"You're not just free staff cover"}],"relearn":"A stipend, written hours, a mentor, an end date and defined tasks are what make an internship fair, not free labour.","persona":"Deepak","source":"fair internship features"},
  {"id":"kr-1299","cat":"rights-at-work","type":"match","hook":"Match each pay term to its plain meaning.","pairs":[{"left":"Stipend","right":"Set pay for a trainee or intern"},{"left":"Deduction","right":"An amount cut from your pay"},{"left":"In-hand pay","right":"What lands after deductions"},{"left":"Overtime","right":"Hours beyond your agreed time"},{"left":"Notice period","right":"Agreed time before you can leave"}],"relearn":"Knowing stipend, deduction, in-hand pay, overtime and notice period helps you read any pay deal clearly.","persona":"any","source":"pay terms"},
  {"id":"kr-1300","cat":"rights-at-work","type":"match","hook":"Match the worker right to a true statement about it.","pairs":[{"left":"Right to be paid","right":"Owed for work actually done"},{"left":"Right to written terms","right":"Protects both you and the employer"},{"left":"Right to safe conditions","right":"Owed to every worker on site"},{"left":"Right to equal pay","right":"Same work earns the same pay"},{"left":"Right to your documents","right":"Originals always belong to you"}],"relearn":"Pay for work, written terms, safe conditions, equal pay and your own documents are rights that hold at any level.","persona":"any","source":"rights at a glance"},
  {"id":"kr-1301","cat":"rights-at-work","type":"reflect","hook":"Lensy: a junior who knows what an offer letter must say is hard to trick. Sit with that.","prompt":"What do you think?","options":["Yes","Hard to trick","I'd read it"],"affirm":"Knowing your terms should be in writing makes a vague verbal promise much easier to spot and refuse.","relearn":"Knowing what your terms should say in writing makes you harder to trick.","persona":"any","source":"knowing terms"},
  {"id":"kr-1302","cat":"rights-at-work","type":"reflect","hook":"Lensy: your time and work have real value, even on your first job. Feel that?","prompt":"What do you think?","options":["Yes","They have value","Always"],"affirm":"Your hours and effort are worth pay from day one; being new never means your work is free.","relearn":"Your time and work have real value, even on your very first job.","persona":"Deepak","source":"your work has value"},
  {"id":"kr-1303","cat":"rights-at-work","type":"reflect","hook":"Lensy: asking 'what's the pay, hours and role?' is a sign of self-respect, not rudeness. Agree?","prompt":"What do you think?","options":["Yes","Self-respect","Fair to ask"],"affirm":"Clear questions about pay, hours and role are normal and grown-up; a fair employer expects them.","relearn":"Asking about pay, hours and role is self-respect, not rudeness.","persona":"Aarti","source":"asking is okay"},
  {"id":"kr-1304","cat":"rights-at-work","type":"reflect","hook":"Lensy: you can be grateful for a chance and still expect to be paid for it. Hold both?","prompt":"What do you think?","options":["Yes","Both can be true","Paid and grateful"],"affirm":"Gratitude and fair pay aren't opposites; you can value an opportunity and still be paid for real work.","relearn":"You can be grateful for a chance and still expect fair pay for real work.","persona":"any","source":"grateful and paid"},
  {"id":"kr-1305","cat":"rights-at-work","type":"reflect","hook":"Lensy: keeping your own simple record of hours and pay is quiet power. Notice that?","prompt":"What do you think?","options":["Yes","Quiet power","I'll keep notes"],"affirm":"A plain log of your hours and pay turns 'he said, she said' into evidence whenever you need it.","relearn":"Keeping your own simple record of hours and pay is quiet power.","persona":"Meena","source":"keep records"},
  {"id":"kr-1306","cat":"rights-at-work","type":"reflect","hook":"Lensy: walking away from an offer that pays you nothing for real work is allowed. Believe it?","prompt":"What do you think?","options":["Yes","I can say no","It's allowed"],"affirm":"You're allowed to refuse a 'role' that wants your real work for free; saying no to exploitation is strength.","relearn":"You're allowed to walk away from an offer that wants real work for no pay.","persona":"any","source":"you can refuse"},
  {"id":"kr-1307","cat":"rights-at-work","type":"reflect","hook":"Lensy: being new doesn't mean being silent; you can ask a fair question on day one. True for you?","prompt":"What do you think?","options":["Yes","I can ask","From day one"],"affirm":"A first job still comes with a voice; a calm question about your terms is yours to ask from the start.","relearn":"Being new doesn't mean being silent; you can ask fair questions on day one.","persona":"any","source":"new but not silent"},
  {"id":"kr-1308","cat":"rights-at-work","type":"role-play","persona":"Deepak","source":"unpaid trial pushback","hook":"Founder Aditi offers to 'mentor' you through three months of full-time, unpaid work.","setup":"It's a video call after your interview.","steps":[{"prompt":"Aditi says: \"You'll learn loads. Pay can come later.\"","options":[{"text":"\"I'd love to learn. Real work needs a stipend from day one.\"","then":"She pauses. \"We're a bit tight this year, you know.\"","best":true},{"text":"\"Okay. Learning matters more than money right now.\"","then":"She beams. \"Great attitude! You'll fit right in.\""},{"text":"\"Three months of free work? That's exploitation.\"","then":"Her smile drops. \"It's a mentorship, not a job.\""},{"text":"\"Could we agree on pay after the first month or so, then?\"","then":"\"Sure, we'll revisit then,\" she says, without a number."}],"why":"Warm and clear together: you want the role, and real work needs pay."},{"prompt":"Aditi says: \"Most interns here work just for the experience.\"","options":[{"text":"\"The experience is great. But the work is real, and so is my rent.\"","then":"She laughs a little. \"Fair. That's fair.\"","best":true},{"text":"\"Sorry. I really don't want to seem greedy about it.\"","then":"\"Don't worry about it,\" she says, and changes the subject."},{"text":"\"My parents are the ones insisting on pay, not me.\"","then":"\"Tell them it's an investment in you,\" she says."},{"text":"\"Fine. Forget the money. I'll do it.\"","then":"\"Great,\" she says, and starts listing your first tasks."}],"why":"Real work deserves pay, whatever others did before you."},{"prompt":"Aditi asks: \"I'm drafting your offer letter tonight. Anything you want in it?\"","options":[{"text":"\"A fixed monthly stipend, with the amount written in.\"","then":"She thinks. \"We can do 8,000. I'll put it in.\"","best":true},{"text":"\"Nothing, really. Just the start date is fine.\"","then":"\"Perfect,\" she says, and notes down only your start date."},{"text":"\"Just put in whatever you think is fair for an intern.\"","then":"\"Okay,\" she says, and types \"pay: as discussed\" into her draft."},{"text":"\"Maybe a certificate and a nice LinkedIn post?\"","then":"\"Definitely!\" she says, sounding relieved."}],"why":"A fixed amount in writing is something you can both count on."},{"prompt":"Aditi asks: \"Can you start before the offer letter is ready? We're in a rush.\"","options":[{"text":"\"I'll start once I have the letter, with a stipend in it.\"","then":"\"Fair,\" she says. \"I'll put a figure in and send it tonight.\"","best":true},{"text":"\"Sure. I'll start Monday, and we'll sort the letter later.\"","then":"\"Brilliant!\" she says. The letter slips to next week, then next month."},{"text":"\"No letter, no work. Please don't ask again.\"","then":"She pauses. \"Okay. Noted.\" Her tone cools."},{"text":"\"Okay, if you promise it'll come in the first week.\"","then":"\"Promise,\" she says. The first week ends without it."}],"why":"Starting once pay is in writing means the promise is real before the work begins."}],"relearn":"You can warmly insist that ongoing real work needs an agreed stipend from the start."},
  {"id":"kr-1309","cat":"rights-at-work","type":"role-play","persona":"any","source":"ask for written terms","hook":"A store manager, Mr Iyer, offers you a sales job, but nothing about salary is in writing.","setup":"He's shaking your hand across the counter.","steps":[{"prompt":"Mr Iyer says: \"Welcome aboard. You start Monday.\"","options":[{"text":"\"Thanks. Could we put the pay, hours and role in writing first?\"","then":"\"Sure,\" he says. \"I'll print an offer letter by Saturday.\"","best":true},{"text":"\"Thank you so much! See you on Monday, then.\"","then":"He smiles. Salary never comes up."},{"text":"\"What's the salary? I'll decide once I hear it.\"","then":"\"Fifteen thousand,\" he says. There's nothing on paper."},{"text":"\"Great. I'm sure HR will send all the paperwork later on.\"","then":"He nods. No paperwork arrives."}],"why":"Asking plainly and politely before you start is the easiest time to get it in writing."},{"prompt":"On Saturday, a senior salesperson, Kiran, says: \"Mr Iyer doesn't like staff who want paperwork.\"","options":[{"text":"\"Written terms are normal. They protect us both.\"","then":"Kiran shrugs. \"True. I never got mine, actually.\"","best":true},{"text":"\"Then I'd better not ask him for anything.\"","then":"Kiran nods. \"Smart. Keep your head down.\""},{"text":"\"Then he must be hiding something shady.\"","then":"Kiran looks uneasy. \"Don't say that out loud here.\""},{"text":"\"I'll ask for it after my first salary, then.\"","then":"\"People say that,\" Kiran says. \"Then they forget.\""}],"why":"Written terms protect both sides, so asking is normal, not distrust."},{"prompt":"On Monday, Mr Iyer hands you a joining letter and says: \"Hours are as per company norms. Standard.\"","options":[{"text":"\"Could it say the actual hours and weekly off?\"","then":"He writes \"10 to 7, Tuesday off\" by hand and initials it.","best":true},{"text":"\"Sure. Norms are norms, I suppose.\"","then":"He nods. You'll learn the norms one long shift at a time."},{"text":"\"Can you just tell me what the norms are, then?\"","then":"\"Ten to seven, roughly,\" he says. The letter doesn't change."},{"text":"\"No problem. I'll figure the hours out once I start.\"","then":"\"Good,\" he says. The first week has two late closings."}],"why":"Vague words like 'norms' can mean anything. Actual hours in writing protect you."}],"relearn":"You can plainly ask for pay, hours and role in writing before you start."},
  {"id":"kr-1310","cat":"rights-at-work","type":"role-play","persona":"Meena","source":"ask for originals","hook":"Three months ago, HR at your new job kept your original diploma 'for safekeeping'.","setup":"You're at the HR desk during your lunch break.","steps":[{"prompt":"The HR executive, Pooja, asks: \"Yes? What do you need?\"","options":[{"text":"\"I'd like my original diploma back. I can give you a copy.\"","then":"Pooja frowns. \"Originals stay with us. Company policy.\"","best":true},{"text":"\"Just checking that my diploma is safe with you.\"","then":"\"Very safe. It's locked in the cupboard,\" she says."},{"text":"\"You've no right to keep my diploma. Give it back now.\"","then":"\"Lower your voice,\" she says. \"This is policy.\""},{"text":"\"Could I borrow it for a day and bring it back?\"","then":"\"Only with a manager's signature,\" she says, sliding a form over."}],"why":"A calm ask plus an offer of a copy shows you're reasonable, and the document is yours."},{"prompt":"Pooja adds: \"We keep originals so people don't leave suddenly. You understand.\"","options":[{"text":"\"I understand. But it's mine, and a copy covers you.\"","then":"She hesitates. \"Let me ask the manager. Come back tomorrow.\"","best":true},{"text":"\"Okay. I'm not planning to leave anyway.\"","then":"\"Exactly,\" she says. \"So there's no problem.\""},{"text":"\"So you're holding my diploma hostage, then?\"","then":"\"That's not what I said,\" she snaps."},{"text":"\"Can you at least give me a receipt saying you have it?\"","then":"She writes one out. The diploma stays in the cupboard."}],"why":"Your document is yours, and a copy meets any fair need they have."},{"prompt":"Later, Pooja says: \"Manager's rule. Originals go back after two years of service.\"","options":[{"text":"\"Please note my request in the register. I'll get advice.\"","then":"Pooja pauses, then writes the date and \"asked for original\" in the register.","best":true},{"text":"\"Fine. Two years isn't that long, really.\"","then":"She nods. Your diploma stays in the cupboard."},{"text":"\"Then I'm quitting today. Give it to me.\"","then":"\"Then you'll need to serve notice first,\" she says flatly."},{"text":"\"Can you ask him again? Maybe he'll change his mind.\"","then":"\"He's decided,\" she says. \"There's nothing more I can do.\""}],"why":"A written record of your request helps if you need free legal help to get it back."}],"relearn":"You can calmly ask for your original documents back and offer a copy instead."},
  {"id":"kr-1311","cat":"rights-at-work","type":"role-play","persona":"any","source":"blank form refusal","hook":"On day one at a courier office, accountant Mr Gupta hands you a salary form with the amount blank.","setup":"A queue of new staff waits behind you.","steps":[{"prompt":"Mr Gupta says: \"Sign quickly. The amount goes in after approval.\"","options":[{"text":"\"I'm glad to sign once the salary figure is filled in.\"","then":"Mr Gupta sighs. \"Wait here. I'll get the approved number.\"","best":true},{"text":"\"Okay, sure. Just show me where to sign.\"","then":"He points. You sign, and he slides the form into a file."},{"text":"\"I'll sign now if you tell me the figure out loud.\"","then":"\"Twelve thousand,\" he says, and hands you the pen."},{"text":"\"I won't sign anything blank. This looks like a scam.\"","then":"\"Scam? It's a courier office,\" he says, loudly."}],"why":"A blank signed pay form can be filled with any figure, so the amount goes in first."},{"prompt":"Later, Mr Gupta says: \"Here's your offer copy. The salary is written in now.\"","options":[{"text":"\"Thanks. Could I get a signed copy of this to keep?\"","then":"He stamps a photocopy and hands it over. You fold it into your bag.","best":true},{"text":"\"Thanks. No need to read it. I trust you.\"","then":"Later you notice it says 11,000, less than you were told."},{"text":"\"I don't need a copy. I'll remember the number.\"","then":"He files it away. Only the office has the figure on paper now."},{"text":"\"Can you email a copy to me sometime?\"","then":"\"Sure,\" he says. No email arrives."}],"why":"Your own signed copy is proof of the agreed figure if it's ever questioned."},{"prompt":"A week later, Mr Gupta says: \"Sign the monthly pay sheet too. Amount's blank as usual.\"","options":[{"text":"\"I'll sign once this month's amount is written in.\"","then":"He grumbles, then fills in the figure and hands it back.","best":true},{"text":"\"Sure. As usual, then. Where do I sign?\"","then":"He takes it back. You don't see what goes in the box."},{"text":"\"Why is it always blank? What are you hiding?\"","then":"\"Nothing,\" he snaps. \"It's just how accounts works.\""},{"text":"\"I'll sign, but I'll write today's date beside it.\"","then":"He shrugs. The amount box stays empty beside your date."}],"why":"Every pay document needs its figure written in before you sign, not just the first one."}],"relearn":"You can politely refuse to sign a blank pay form until the figure is filled in."},
  {"id":"kr-1312","cat":"rights-at-work","type":"role-play","persona":"Meena","source":"chase final pay","hook":"You left a salon job on the 20th of last month, and your final pay still hasn't come.","setup":"The salon's accountant, Mr Dsouza, finally answers.","steps":[{"prompt":"Mr Dsouza says: \"Ah, yes. It's in process. Don't worry.\"","options":[{"text":"\"I worked till the 20th. When will that pay clear?\"","then":"He pauses. \"Let me see. Maybe by the 10th.\"","best":true},{"text":"\"Okay. Thank you. I'll just wait, then.\"","then":"\"Good, good,\" he says, sounding relieved."},{"text":"\"In process for a month? Do you think I'm a fool?\"","then":"\"No need for that tone,\" he says stiffly."},{"text":"\"Could you please try to speed it up a little?\"","then":"\"I'll try,\" he says. There's no date attached."}],"why":"Naming your last day and asking for a date is specific without being rude."},{"prompt":"Mr Dsouza adds: \"There'll be a deduction, though. Uniform and all.\"","options":[{"text":"\"Could you send each deduction in writing?\"","then":"\"I'll WhatsApp the breakup,\" he says, and you hear him typing.","best":true},{"text":"\"Okay, whatever's fair. Just send the rest.\"","then":"\"Right,\" he says. You'll learn the total when it lands."},{"text":"\"I returned everything. You're making this up.\"","then":"\"I'm only telling you what I'm told,\" he says curtly."},{"text":"\"How much, roughly? Just tell me the total.\"","then":"\"Two thousand, maybe more,\" he says vaguely."}],"why":"Deductions should be itemised, so you can check each one."},{"prompt":"Mr Dsouza says: \"Just be patient. These things take time.\"","options":[{"text":"\"Okay. I'll text you the amount owed and today's date.\"","then":"\"Okay, send it,\" he says. \"I'll show it to Madam.\"","best":true},{"text":"\"Sure. Just call me when it's done.\"","then":"\"Will do,\" he says. The phone doesn't ring."},{"text":"\"I'll post about this salon everywhere, then.\"","then":"\"Do what you like,\" he says, and hangs up."},{"text":"\"Then I'll call you every single day until it's paid.\"","then":"He sighs. By day three, he stops picking up."}],"why":"A dated written message keeps a record of what you're owed."},{"prompt":"A week later, Mr Dsouza says: \"Madam will pay when she's back from her trip.\"","options":[{"text":"\"I'd like a date, or I'll ask free legal aid what to do.\"","then":"He pauses. \"Let me call Madam now,\" he says.","best":true},{"text":"\"Okay. I'll wait until she's back, then.\"","then":"\"Good,\" he says. Nobody tells you when she's back."},{"text":"\"Tell Madam I'll come to the salon and make a scene.\"","then":"\"Please don't,\" he says, and the line goes cold."},{"text":"\"Could you pay me from the till for now, as a favour?\"","then":"\"I can't touch the till,\" he says, sounding tired."}],"why":"Calmly naming a real next step shows you know your route, without threats."}],"relearn":"You can politely ask for a clear date on your owed final pay."},
  {"id":"kr-1313","cat":"rights-at-work","type":"role-play","persona":"Aarti","source":"raise pay gap","hook":"You're a woman analyst, and you learn Rohit, who joined with you, earns 4,000 more a month.","setup":"Your manager, Ms Menon, has made time for you.","steps":[{"prompt":"Ms Menon asks: \"So, what did you want to talk about?\"","options":[{"text":"\"Rohit and I do the same job equally well. I'd like equal pay.\"","then":"She sits back. \"I see. Tell me more.\"","best":true},{"text":"\"I heard Rohit earns more. Is that normal here?\"","then":"She hesitates. \"Every salary is different.\""},{"text":"\"Match Rohit's pay, or I'll start looking elsewhere.\"","then":"Her face tightens. \"Let's not start with ultimatums.\""},{"text":"\"Could I get closer to Rohit's pay? Whatever's fair.\"","then":"\"Let's discuss it at appraisal time,\" she says."}],"why":"Naming the same role and output keeps it about the work, calmly and clearly."},{"prompt":"Ms Menon says: \"Salaries are personal. You shouldn't compare.\"","options":[{"text":"\"I understand. But equal work should get equal pay.\"","then":"She's quiet for a moment, then opens both files.","best":true},{"text":"\"Sorry. You're right. I shouldn't have compared.\"","then":"\"It's fine,\" she says. \"And for what it's worth, there's a reason.\""},{"text":"\"Then why hide them, unless something's wrong?\"","then":"\"I'm not hiding anything,\" she says sharply."},{"text":"\"Rohit told me himself, so I know I'm not wrong.\"","then":"\"That's between you and Rohit,\" she says."}],"why":"Comparing equal work is fair. Equal work earns equal pay."},{"prompt":"Ms Menon says: \"Rohit negotiated harder when he joined.\"","options":[{"text":"\"Our work is the same now, so our pay should be too.\"","then":"She nods slowly. \"I'll raise it with HR this week.\"","best":true},{"text":"\"Okay. I'll negotiate harder at my next job.\"","then":"She smiles, relieved. The gap is still there."},{"text":"\"So I'm punished for being polite at my interview?\"","then":"\"That's not how I'd put it,\" she says, defensive."},{"text":"\"Could you match it from next year, maybe?\"","then":"\"We'll see,\" she says, without writing anything down."}],"why":"Pay should match the work being done now, not how hard someone bargained."},{"prompt":"A week later, Ms Menon says: \"HR is reviewing all analysts' pay in the next cycle.\"","options":[{"text":"\"Could you confirm by email that my pay gap is part of it?\"","then":"\"Sure,\" she says. An email naming your case and a date arrives that afternoon.","best":true},{"text":"\"Okay. I'll just wait for the cycle, then.\"","then":"She nods. The cycle comes and goes without a word."},{"text":"\"The next cycle? That's months away. It's so unfair.\"","then":"\"I'm doing what I can,\" she says stiffly."},{"text":"\"Could I get a small bonus until then, at least?\"","then":"\"I'll see,\" she says, and nothing more is said."}],"why":"Getting your case and a date in writing keeps equal pay from slipping off the list."}],"relearn":"You can steadily ask for equal pay when you do equal work."},
  {"id":"kr-1314","cat":"rights-at-work","type":"role-play","persona":"any","source":"extra hours line","hook":"For weeks, your team lead, Sneha, has handed you tasks at 6 that run till 9, unpaid.","setup":"It's 5:50, and she's walking over with a file.","steps":[{"prompt":"Sneha says: \"One more thing before you go. Should take a couple of hours.\"","options":[{"text":"\"I can do extra when it's agreed and paid. Can we talk?\"","then":"Sneha stops. \"Paid? I never thought about it. Let me check.\"","best":true},{"text":"\"Sure, no problem. Leave it on my desk.\"","then":"She drops the file. You leave at 9:10."},{"text":"\"Again? You do this to me every single day.\"","then":"\"Everyone's stretched,\" she says, and puts the file down anyway."},{"text":"\"I'll do it tonight, but I really can't tomorrow.\"","then":"\"Thanks. You're a star,\" she says. Tomorrow there's another file."}],"why":"Kind and clear together: you're willing to help on fair terms."},{"prompt":"Next morning, Sneha tells the team: \"Everyone stays late here. It shows commitment.\"","options":[{"text":"\"I'm committed in my hours. Extra needs agreeing.\"","then":"She thinks. \"Okay. Let's list what can wait a day.\"","best":true},{"text":"\"You're right. I'll stay whenever you need me.\"","then":"She smiles. Your evenings are no longer yours."},{"text":"\"Commitment doesn't pay my rent, though.\"","then":"She raises her eyebrows. \"Noted,\" she says coldly."},{"text":"\"Maybe I could stay late just on Fridays?\"","then":"\"Great,\" she says. By next week, Fridays have spread to Wednesdays."}],"why":"Commitment within your hours is enough. Extra time is extra, and agreed."},{"prompt":"Sneha asks: \"The client wants weekend work too. Can I count on you?\"","options":[{"text":"\"Yes, if it's agreed ahead and paid as overtime.\"","then":"\"Deal,\" she says. \"I'll set up an overtime sheet.\"","best":true},{"text":"\"Of course. The client always comes first, right?\"","then":"She nods. Your weekends start filling up too."},{"text":"\"Weekends? Absolutely not. Find someone else.\"","then":"\"There isn't anyone else,\" she says, frowning."},{"text":"\"Ask me on the Friday, and I'll see if I'm free.\"","then":"She agrees, but every ask arrives late on Friday night."}],"why":"Planning real exceptions as paid overtime keeps the agreement fair and lasting."}],"relearn":"You can kindly hold the line that extra hours should be agreed and paid."},
  {"id":"kr-1315","cat":"rights-at-work","type":"spot","hook":"Spot the two red-flag lines in this 'job offer'.","scene":[{"id":"a","text":"'Your salary is 18,000 a month, paid by the 7th.'","trick":false},{"id":"b","text":"'Pay a 2,000 registration fee before you can join.'","trick":true},{"id":"c","text":"'Your hours are 9 to 6, with a weekly off.'","trick":false},{"id":"d","text":"'We'll hold your original degree till you finish a year.'","trick":true},{"id":"e","text":"'Here's your offer letter with the role written in.'","trick":false}],"why":"A join 'fee' and handing over your originals are the red flags; a real job pays you and your documents stay yours.","relearn":"Join fees and held originals are red flags.","persona":"any","source":"offer red flags"},
  {"id":"kr-1316","cat":"rights-at-work","type":"spot","hook":"Spot the two lines that signal exploitation, not a fair internship.","scene":[{"id":"a","text":"'You'll get a set stipend each month.'","trick":false},{"id":"b","text":"'Work full days unpaid for six months to prove it.'","trick":true},{"id":"c","text":"'A mentor will guide your real learning.'","trick":false},{"id":"d","text":"'You'll cover a staff member's whole job for free.'","trick":true},{"id":"e","text":"'Your hours and end date are written down.'","trick":false}],"why":"Months of full unpaid work and covering a paid job free are the exploitation signs; a stipend and mentor are fair.","relearn":"Long unpaid work or free job-cover is exploitation.","persona":"Deepak","source":"internship red flags"},
  {"id":"kr-1317","cat":"rights-at-work","type":"spot","hook":"Spot the two unfair things hidden in this contract pitch.","scene":[{"id":"a","text":"'It lists your pay, hours and role clearly.'","trick":false},{"id":"b","text":"'Sign this blank page now; we'll add terms later.'","trick":true},{"id":"c","text":"'You get a copy of the signed contract.'","trick":false},{"id":"d","text":"'A penalty lets us keep your full last salary.'","trick":true},{"id":"e","text":"'Notice period is one month, stated upfront.'","trick":false}],"why":"A blank page to sign and a penalty that grabs your earned salary are the unfair parts; clear terms are fine.","relearn":"Blank pages and salary-grabbing penalties are unfair.","persona":"any","source":"contract red flags"},
  {"id":"kr-1318","cat":"rights-at-work","type":"spot","hook":"Spot the two lines that wrongly deny a worker their rights.","scene":[{"id":"a","text":"'Interns doing real work can be paid a stipend.'","trick":false},{"id":"b","text":"'You're junior, so you simply have no rights.'","trick":true},{"id":"c","text":"'Wages are owed for the work you did.'","trick":false},{"id":"d","text":"'Cash-in-hand means you've got no rights at all.'","trick":true},{"id":"e","text":"'A contract protects both you and the company.'","trick":false}],"why":"'Juniors have no rights' and 'cash pay erases rights' are false; pay and contracts are real protections.","relearn":"'Juniors have no rights' and 'cash erases rights' are false.","persona":"any","source":"rights-denial flags"},
  {"id":"kr-1319","cat":"rights-at-work","type":"spot","hook":"Spot the two warning signs in this gig 'partner' offer.","scene":[{"id":"a","text":"'Your per-trip rate is shown before you accept.'","trick":false},{"id":"b","text":"'We can change your pay anytime with no notice.'","trick":true},{"id":"c","text":"'You'll get a weekly summary of earnings.'","trick":false},{"id":"d","text":"'Buy your own safety gear or you can't work; that's on you.'","trick":true},{"id":"e","text":"'You choose your own shift hours.'","trick":false}],"why":"Changing pay with no notice and dumping all safety costs on you are the warning signs; clear rates are fair.","relearn":"No-notice pay changes are a gig warning sign.","persona":"any","source":"gig offer flags"},
  {"id":"kr-1320","cat":"rights-at-work","type":"spot","hook":"Spot the two lines that are exploitation dressed as 'opportunity'.","scene":[{"id":"a","text":"'You'll be paid for every hour you work here.'","trick":false},{"id":"b","text":"'Do this real client project free; exposure is your pay.'","trick":true},{"id":"c","text":"'We agree your role and hours in writing.'","trick":false},{"id":"d","text":"'Keep working unpaid; payment starts someday, maybe.'","trick":true},{"id":"e","text":"'Your stipend lands on a fixed date.'","trick":false}],"why":"'Exposure as pay' and endless 'someday' payment are exploitation; real work earns real pay.","relearn":"'Exposure' and 'someday' pay are exploitation.","persona":"any","source":"exposure pay flags"},
  {"id":"kr-1321","cat":"rights-at-work","type":"spot","hook":"Spot the two unfair lines aimed at a woman worker.","scene":[{"id":"a","text":"'You'll be judged on the same targets as everyone.'","trick":false},{"id":"b","text":"'We pay women a bit less for the same role.'","trick":true},{"id":"c","text":"'Your shift and duties are written in your letter.'","trick":false},{"id":"d","text":"'This promotion isn't for women, whatever the results.'","trick":true},{"id":"e","text":"'Safe conditions apply to every worker here.'","trick":false}],"why":"Paying women less and barring a promotion for being a woman are the unfair lines.","relearn":"Lower pay or a barred promotion for being a woman is unfair.","persona":"Aarti","source":"gender-at-work flags"},
  {"id":"kr-1322","cat":"rights-at-work","type":"spot","hook":"Spot the two lines that try to trap you in the job.","scene":[{"id":"a","text":"'Your notice period is one month, as agreed.'","trick":false},{"id":"b","text":"'We keep your originals until you give two years.'","trick":true},{"id":"c","text":"'You'll get a relieving letter when you leave.'","trick":false},{"id":"d","text":"'Quit early and we keep all your pending salary.'","trick":true},{"id":"e","text":"'Your pay clears on a fixed monthly date.'","trick":false}],"why":"Holding your originals and seizing all pending salary to stop you leaving are the traps.","relearn":"Held originals and seized salary to stop you leaving are traps.","persona":"any","source":"lock-in flags"},
  {"id":"kr-1350","type":"match","persona":"Farhan","source":"need to helpline","relearn":"181/1091 women in distress, 112 danger, 1930 cyber harm, 15100 legal aid, 1098 child at risk.","hook":"Match each need to the right helpline (India).","pairs":[{"left":"A woman in distress","right":"181 / 1091"},{"left":"Immediate danger","right":"112"},{"left":"Online fraud or abuse","right":"1930"},{"left":"Can't afford a lawyer","right":"NALSA 15100"},{"left":"A child at risk","right":"Childline 1098"}],"cat":"tools-and-help"},
  {"id":"kr-1351","type":"match","persona":"any","source":"need to route","relearn":"Each rights problem has a real route: an IC, the cyber portal, legal aid, or a consumer forum.","hook":"Match the problem to where its route begins.","pairs":[{"left":"Workplace harassment","right":"The Internal Committee"},{"left":"A scam message online","right":"cybercrime.gov.in"},{"left":"No money for a lawyer","right":"Free legal aid"},{"left":"A faulty product","right":"A consumer forum"},{"left":"Withheld wages","right":"The labour authority"}],"cat":"tools-and-help"},
  {"id":"kr-1352","type":"match","persona":"any","source":"resource to use","relearn":"Reliable rights resources: legal-aid clinics, the cyber portal, an IC, official sites, qualified help.","hook":"Match the situation to a reliable resource (not a forward).","pairs":[{"left":"Want free legal help","right":"A legal-aid clinic"},{"left":"Want to report cyber harm","right":"The official cyber portal"},{"left":"Harassed at college","right":"The campus IC"},{"left":"Unsure of the law","right":"A qualified lawyer"},{"left":"Need rights basics","right":"An official government site"}],"cat":"tools-and-help"},
  {"id":"kr-1353","type":"match","persona":"Farhan","source":"toolkit phrase","relearn":"A shareable card carries the route AND the helpline so a friend isn't left guessing.","hook":"Match each line on the rights card to what it gives a friend.","pairs":[{"left":"\"Harassment? Go to the IC\"","right":"A route to redress"},{"left":"\"Can't pay? NALSA 15100\"","right":"Free legal help"},{"left":"\"Scammed? 1930\"","right":"A cyber report line"},{"left":"\"In danger? 112\"","right":"Emergency help"},{"left":"\"This isn't legal advice\"","right":"An honest limit"}],"cat":"tools-and-help"},
  {"id":"kr-1354","type":"match","persona":"any","source":"myth to truth","relearn":"Junior staff have rights, harassment has redress, justice isn't only for the rich, scams are reportable.","hook":"Match each myth to the truth that replaces it.","pairs":[{"left":"\"Interns have no rights\"","right":"Basic labour rights apply"},{"left":"\"Just endure harassment\"","right":"There's a formal complaint route"},{"left":"\"Justice needs money\"","right":"Free legal aid exists"},{"left":"\"Scams can't be reported\"","right":"1930 and the cyber portal exist"},{"left":"\"You can't fight the system\"","right":"Real routes shift the odds"}],"cat":"tools-and-help"},
  {"id":"kr-1355","type":"match","persona":"Meena","source":"who can help","relearn":"Different helpers do different jobs: an IC, a legal-aid clinic, a consumer forum, a labour office, a counsellor.","hook":"Match each helper to what they handle.","pairs":[{"left":"Internal Committee","right":"Harassment complaints"},{"left":"Legal-aid clinic","right":"A free lawyer"},{"left":"Consumer forum","right":"A faulty-goods claim"},{"left":"Labour office","right":"Unpaid wages"},{"left":"Campus counsellor","right":"Support and pointing the way"}],"cat":"tools-and-help"},
  {"id":"kr-1356","type":"match","persona":"any","source":"first step","relearn":"A good first step is small: save proof, note dates, find the route, call a helpline, ask for legal aid.","hook":"Match each situation to a sensible first step.","pairs":[{"left":"Got blackmailed online","right":"Save proof, don't pay"},{"left":"Wages not paid","right":"Keep a record of work done"},{"left":"Deposit being withheld","right":"Show the written agreement"},{"left":"Unsure who to call","right":"Ring a helpline to be directed"},{"left":"Can't afford a lawyer","right":"Ask for free legal aid"}],"cat":"tools-and-help"},
  {"id":"kr-1357","type":"match","persona":"Farhan","source":"plain language","relearn":"A toolkit works only if it's plain: short lines, a number, no jargon, in the reader's language.","hook":"Match each toolkit habit to why it helps a working friend.","pairs":[{"left":"Short, plain lines","right":"Anyone can read it fast"},{"left":"A number on each line","right":"Help is one call away"},{"left":"No legal jargon","right":"It doesn't intimidate"},{"left":"In their own language","right":"It actually reaches them"},{"left":"\"Not legal advice\" noted","right":"It stays honest"}],"cat":"tools-and-help"},
  {"id":"kr-1358","type":"match","persona":"any","source":"reliable vs not","relearn":"Trust official portals, clinics and qualified help; not forwards, rumours or a stranger's guess.","hook":"Match each source to whether it's a reliable rights source.","pairs":[{"left":"The official cyber portal","right":"Reliable"},{"left":"A legal-aid clinic","right":"Trustworthy"},{"left":"A viral WhatsApp forward","right":"Not a source"},{"left":"A stranger's confident guess","right":"Unreliable"},{"left":"A qualified lawyer","right":"Worth asking"}],"cat":"tools-and-help"},
  {"id":"kr-1359","type":"sort","persona":"any","source":"reliable resources","relearn":"Official portals, clinics and an IC are reliable; forwards, rumours and guesses are not.","hook":"Sort: a reliable rights resource, or not?","items":[{"id":"a","text":"A legal-aid clinic"},{"id":"b","text":"A random WhatsApp forward"},{"id":"c","text":"The official cyber portal"},{"id":"d","text":"A stranger's confident guess"},{"id":"e","text":"The campus Internal Committee"},{"id":"f","text":"A rumour someone repeated"}],"bins":[{"id":"reliable","label":"Reliable","valence":"pos"},{"id":"not","label":"Not a source","valence":"neg"}],"key":{"a":"reliable","b":"not","c":"reliable","d":"not","e":"reliable","f":"not"},"cat":"tools-and-help"},
  {"id":"kr-1360","type":"sort","persona":"any","source":"on the card","relearn":"The rights card carries real routes and helplines; not 'put up with it' or 'you have no options'.","hook":"Sort: belongs on the rights & helpline card, or not?","items":[{"id":"a","text":"The Internal Committee route"},{"id":"b","text":"\"Just put up with it\""},{"id":"c","text":"Free legal aid: NALSA 15100"},{"id":"d","text":"\"You have no options\""},{"id":"e","text":"Cyber harm: 1930"},{"id":"f","text":"\"Don't bother, you'll lose\""}],"bins":[{"id":"card","label":"On the card","valence":"pos"},{"id":"not","label":"Off the card","valence":"neg"}],"key":{"a":"card","b":"not","c":"card","d":"not","e":"card","f":"not"},"cat":"tools-and-help"},
  {"id":"kr-1361","type":"sort","persona":"Farhan","source":"helpline matching","relearn":"Match the harm to its line: danger 112, women 181/1091, cyber 1930, child 1098, legal aid 15100.","hook":"Sort each line into the kind of help it gives.","items":[{"id":"a","text":"112"},{"id":"b","text":"1930"},{"id":"c","text":"181 / 1091"},{"id":"d","text":"Childline 1098"},{"id":"e","text":"NALSA 15100"},{"id":"f","text":"The Internal Committee"}],"bins":[{"id":"danger","label":"Immediate danger","valence":"uhoh"},{"id":"report","label":"Report a harm","valence":"tell"},{"id":"support","label":"Get support/advice","valence":"pos"}],"key":{"a":"danger","b":"report","c":"report","d":"support","e":"support","f":"report"},"cat":"tools-and-help"},
  {"id":"kr-1362","type":"sort","persona":"any","source":"honest frame","relearn":"Honest framing: this is education, routes are real, no promises of a specific outcome.","hook":"Sort: an honest thing the toolkit says, or an overclaim to drop?","items":[{"id":"a","text":"\"Here are real routes you can use\""},{"id":"b","text":"\"You'll definitely win your case\""},{"id":"c","text":"\"This is education, not legal advice\""},{"id":"d","text":"\"You're guaranteed your money back\""},{"id":"e","text":"\"Free legal aid can help you\""},{"id":"f","text":"\"They'll surely be fired\""}],"bins":[{"id":"honest","label":"Honest","valence":"pos"},{"id":"overclaim","label":"Overclaim","valence":"neg"}],"key":{"a":"honest","b":"overclaim","c":"honest","d":"overclaim","e":"honest","f":"overclaim"},"cat":"tools-and-help"},
  {"id":"kr-1363","type":"sort","persona":"any","source":"good toolkit","relearn":"A good rights card is plain, has a number per line, names the route, and stays honest.","hook":"Sort: makes the rights card more useful, or less?","items":[{"id":"a","text":"Short, plain lines"},{"id":"b","text":"Heavy legal jargon"},{"id":"c","text":"A helpline on each line"},{"id":"d","text":"Vague 'go ask someone'"},{"id":"e","text":"Written in the reader's language"},{"id":"f","text":"A promise it can't keep"}],"bins":[{"id":"better","label":"More useful","valence":"pos"},{"id":"worse","label":"Less useful","valence":"neg"}],"key":{"a":"better","b":"worse","c":"better","d":"worse","e":"better","f":"worse"},"cat":"tools-and-help"},
  {"id":"kr-1364","type":"sort","persona":"Meena","source":"who to call","relearn":"Pick the line by need: danger 112, cyber harm 1930, free lawyer 15100, woman in distress 181.","hook":"Sort each situation to the line you'd reach for.","items":[{"id":"a","text":"A man is following you right now"},{"id":"b","text":"Someone is blackmailing you online"},{"id":"c","text":"You can't afford a lawyer"},{"id":"d","text":"You feel unsafe and alone as a woman"},{"id":"e","text":"A scam took your money online"},{"id":"f","text":"You're in real, present danger"}],"bins":[{"id":"emerg","label":"112 / 181","valence":"uhoh"},{"id":"cyber","label":"Cyber 1930","valence":"tell"},{"id":"aid","label":"Legal aid 15100","valence":"pos"}],"key":{"a":"emerg","b":"cyber","c":"aid","d":"emerg","e":"cyber","f":"emerg"},"cat":"tools-and-help"},
  {"id":"kr-1365","type":"sort","persona":"any","source":"share or skip","relearn":"Share verified routes and helplines; never forward unverified rumours or scary half-truths.","hook":"Sort: safe to share with a friend, or check first?","items":[{"id":"a","text":"The verified helpline list"},{"id":"b","text":"A forwarded 'new law' rumour"},{"id":"c","text":"The official cyber portal link"},{"id":"d","text":"A scary unverified screenshot"},{"id":"e","text":"A legal-aid clinic's address"},{"id":"f","text":"\"Someone said the rule changed\""}],"bins":[{"id":"share","label":"Safe to share","valence":"pos"},{"id":"check","label":"Check first","valence":"uhoh"}],"key":{"a":"share","b":"check","c":"share","d":"check","e":"share","f":"check"},"cat":"tools-and-help"},
  {"id":"kr-1366","type":"sort","persona":"any","source":"first move","relearn":"First moves that help: save proof, note dates, find the route, call a helpline, ask for legal aid.","hook":"Sort: a helpful first move, or a dead end?","items":[{"id":"a","text":"Save proof and note dates"},{"id":"b","text":"\"Just give up\""},{"id":"c","text":"Call a helpline to be directed"},{"id":"d","text":"\"Stay silent and hope\""},{"id":"e","text":"Ask a legal-aid clinic"},{"id":"f","text":"Pay the blackmailer to make it stop"}],"bins":[{"id":"helps","label":"Helps","valence":"pos"},{"id":"deadend","label":"Dead end","valence":"neg"}],"key":{"a":"helps","b":"deadend","c":"helps","d":"deadend","e":"helps","f":"deadend"},"cat":"tools-and-help"},
  {"id":"kr-1367","type":"sort","persona":"Farhan","source":"toolkit pieces","relearn":"A working-youth toolkit needs the route, a helpline, plain words and the honest 'not legal advice' line.","hook":"Sort each piece: core to the toolkit, or clutter?","items":[{"id":"a","text":"The route to redress"},{"id":"b","text":"Long disclaimers nobody reads"},{"id":"c","text":"A helpline number"},{"id":"d","text":"Fancy legal Latin"},{"id":"e","text":"The honest 'not legal advice' note"},{"id":"f","text":"A wall of dense text"}],"bins":[{"id":"core","label":"Core","valence":"pos"},{"id":"clutter","label":"Clutter","valence":"neg"}],"key":{"a":"core","b":"clutter","c":"core","d":"clutter","e":"core","f":"clutter"},"cat":"tools-and-help"},
  {"id":"kr-1368","type":"reflect","persona":"any","source":"save it before you need it","relearn":"Save a helpline or legal-aid number now, so it's ready before any crisis hits.","hook":"Lensy: the time to find a helpline number is before you need it. Worth saving one today?","prompt":"What do you think?","options":["Yes","I'll save one","Good idea"],"affirm":"Having a helpline or legal-aid contact saved in advance means you're never scrambling in a crisis.","cat":"tools-and-help"},
  {"id":"kr-1369","type":"reflect","persona":"any","source":"the point","relearn":"Rights you know are rights you can use; that knowledge is real protection.","hook":"Lensy: rights you know are rights you can use. Worth carrying?","prompt":"What do you think?","options":["Yes","Know to use","Carry it"],"affirm":"Rights you know are rights you can use; that knowledge is one of the strongest protections you have.","cat":"tools-and-help"},
  {"id":"kr-1370","type":"reflect","persona":"any","source":"keep one","relearn":"Keep one route or line ready, and you have a real protection when you or a friend needs it.","hook":"Lensy: which helpline do you most want to keep in your head?","prompt":"Pick one.","options":["112 for danger","1930 for cyber harm","15100 for legal aid","181 for women in distress"],"affirm":"Keep that one ready, and you've got a real route the moment you, or someone near you, needs it.","cat":"tools-and-help"},
  {"id":"kr-1371","type":"reflect","persona":"Farhan","source":"who to share with","relearn":"A rights card helps most where help feels far; think of who could use yours.","hook":"Lensy: who in your life would the rights card help most?","prompt":"Picture one person.","options":["A younger sibling","A new colleague","A friend renting alone","A neighbour"],"affirm":"Holding a real person in mind is how a toolkit stops being a leaflet and starts being help.","cat":"tools-and-help"},
  {"id":"kr-1372","type":"reflect","persona":"any","source":"first instinct","relearn":"Your first instinct doesn't have to be perfect; finding the route is the win.","hook":"Lensy: if a rights problem hit tomorrow, what's your honest first instinct?","prompt":"No wrong answer.","options":["Freeze a moment","Call someone","Look it up","Save proof"],"affirm":"Whatever your first instinct, the win is finding the route next; you don't have to have it all figured out.","cat":"tools-and-help"},
  {"id":"kr-1373","type":"reflect","persona":"any","source":"asking is strength","relearn":"Asking for help is a skill, not a weakness; the toolkit exists so you don't go it alone.","hook":"Lensy: how does asking for help land for you, honestly?","prompt":"Sit with it.","options":["Hard for me","Getting easier","Fine by me","Depends"],"affirm":"However it lands, asking is a skill worth growing; the routes exist so nobody has to do this alone.","cat":"tools-and-help"},
  {"id":"kr-1374","type":"reflect","persona":"Meena","source":"rights as survival","relearn":"Knowing your rights when you're on your own is power; you carry it with you.","hook":"Lensy: working far from home, which protection means most to you?","prompt":"Pick what fits.","options":["Being paid fairly","A safe workplace","A roof I can keep","Knowing who to call"],"affirm":"Whatever you chose, knowing the right that protects it is yours to carry, wherever the work takes you.","cat":"tools-and-help"},
  {"id":"kr-1375","type":"reflect","persona":"any","source":"belief shift","relearn":"\"You can't fight the system\" is a belief, not a fact; real routes shift the odds.","hook":"Lensy: \"ordinary people just lose\", does that belief still hold for you?","prompt":"Be honest.","options":["Less than before","I'm not sure","No, there are routes","Old habit"],"affirm":"Loosening that belief is the real shift here; routes don't promise wins, but they genuinely change the odds.","cat":"tools-and-help"},
  {"id":"kr-1376","type":"reflect","persona":"Farhan","source":"plain language","relearn":"A toolkit only helps if people can read it; plain language is the whole game.","hook":"Lensy: what would make a rights card actually reach the people you work with?","prompt":"Think practically.","options":["Their language","Shorter lines","A number to call","Less jargon"],"affirm":"Whatever you picked, you're thinking like a toolkit-builder: reach first, polish later.","cat":"tools-and-help"},
  {"id":"kr-1377","type":"reflect","persona":"any","source":"trust a source","relearn":"You can choose what you trust: official portals and clinics over forwards and guesses.","hook":"Lensy: when a 'new rule' lands in your chats, what do you tend to do?","prompt":"No judgement.","options":["Forward it on","Check it first","Ignore it","Ask someone"],"affirm":"Whatever your habit, choosing to check a claim against an official source before acting is always solid.","cat":"tools-and-help"},
  {"id":"kr-1378","type":"reflect","persona":"any","source":"calm first step","relearn":"You don't have to solve it all at once; one calm first step is enough.","hook":"Lensy: facing a rights mess, what helps you take just the first step?","prompt":"What works for you?","options":["A list","One phone call","A friend with me","A deep breath"],"affirm":"Whatever steadies you, remember the bar is one step, not the whole battle; the route reveals itself as you go.","cat":"tools-and-help"},
  {"id":"kr-1379","type":"reflect","persona":"any","source":"helping others","relearn":"Knowing a route means you can point a friend to it; that's protection multiplied.","hook":"Lensy: which friend might you be the one to point toward help?","prompt":"Hold them in mind.","options":["Someone renting alone","A new joinee","Someone scammed","Not sure yet"],"affirm":"Being the person who knows the route is quiet power; what you've learned can protect more than just you.","cat":"tools-and-help"},
  {"id":"kr-1380","type":"reflect","persona":"any","source":"no false promise","relearn":"Honest help names real routes without promising a win; that honesty is a feature.","hook":"Lensy: does it bother you that the toolkit won't promise you'll win?","prompt":"Be honest.","options":["A little","No, I prefer honest","I get why","Mixed"],"affirm":"That honesty is the point: real routes, named plainly, with no false guarantee; that's help you can actually trust.","cat":"tools-and-help"},
  {"id":"kr-1381","type":"reflect","persona":"Aarti","source":"a say in your life","relearn":"Wanting a say in your own life is reason enough to learn your rights.","hook":"Lensy: what's the right you most want at your back as you start out?","prompt":"Pick one.","options":["A safe workplace","To be heard","To say no","To be paid fairly"],"affirm":"Whatever you chose, wanting a real say in your own life is exactly why these rights are worth knowing.","cat":"tools-and-help"},
  {"id":"kr-1382","type":"reflect","persona":"any","source":"keep it handy","relearn":"A toolkit only works if it's reachable; decide now where yours will live.","hook":"Lensy: where would you actually keep a rights & helpline card so it's there when needed?","prompt":"Make it real.","options":["Phone notes","Saved chat","On paper","Memorised"],"affirm":"Wherever it lives, the point is reachable-in-the-moment; a card you can find beats one you forgot you had.","cat":"tools-and-help"},
  {"id":"kr-1383","type":"reflect","persona":"any","source":"confidence","relearn":"Knowing the route lowers the fear; you're harder to exploit when you know where help is.","hook":"Lensy: knowing these routes now, does anything feel a bit less scary?","prompt":"Notice it.","options":["Yes, a bit","Not yet","A lot","Hard to say"],"affirm":"However it sits, knowing where help lives tends to shrink the fear; that's exactly what a toolkit is for.","cat":"tools-and-help"},
  {"id":"kr-1384","type":"reflect","persona":"any","source":"one to teach","relearn":"You remember what you teach; passing on one route locks it in for you too.","hook":"Lensy: if you taught one person one thing from this, what would it be?","prompt":"Choose one.","options":["A helpline","The IC route","Free legal aid","Save-your-proof"],"affirm":"Teaching it is how you keep it; the thing you'd pass on is probably the thing you'll never forget yourself.","cat":"tools-and-help"},
  {"id":"kr-1385","type":"reflect","persona":"any","source":"carry forward","relearn":"Work, harassment, renting, online: you know the rights and routes now. Carry one forward.","hook":"Lensy: across work, renting, harassment and online, which route do you most want to carry forward?","prompt":"Pick one.","options":["Rights at work","Harassment redress","Consumer & cyber routes","Free legal aid"],"affirm":"Carry that one forward and you step into adult life genuinely harder to exploit, and ready to help others too.","cat":"tools-and-help"},
  {"id":"kr-1386","cat":"tools-and-help","type":"role-play","persona":"Farhan","source":"point a friend","hook":"Your friend Ankit's landlord won't return his 20,000 deposit, and Ankit doesn't know where to start.","setup":"You're having chai outside his PG.","steps":[{"prompt":"Ankit says: \"He's rich and I'm a student. What can I even do?\"","options":[{"text":"\"There's a route: free legal aid on NALSA 15100.\"","then":"Ankit looks up. \"Free? I thought lawyers cost lakhs.\"","best":true},{"text":"\"Just let it go. It's not worth the trouble.\"","then":"Ankit nods slowly, and his shoulders drop."},{"text":"\"I'll go and shout at your landlord for you.\"","then":"\"Please don't,\" Ankit says. \"He'll just get angrier.\""},{"text":"\"Maybe ask him nicely one more time?\"","then":"\"I've asked four times,\" he says quietly."}],"why":"Naming the route and the helpline turns 'what can I do' into a first step."},{"prompt":"Ankit says: \"Say I do try. What should I have ready?\"","options":[{"text":"\"The agreement, deposit receipt and his messages.\"","then":"Ankit starts scrolling through old chats and saving screenshots.","best":true},{"text":"\"Nothing. They'll figure it all out for you.\"","then":"\"Okay,\" he says, and doesn't look for anything."},{"text":"\"Just your story. Papers don't matter much.\"","then":"He practises the story in his head, with nothing to back it up."},{"text":"\"Only the agreement. The rest is just extra.\"","then":"He finds the agreement, but not the deposit receipt."}],"why":"Papers and messages are the proof that makes a deposit claim clear."},{"prompt":"Ankit asks: \"Will you come with me when I call?\"","options":[{"text":"\"Yes. I'll sit with you, and you do the talking.\"","then":"Ankit smiles for the first time today. \"Tomorrow at ten, then.\"","best":true},{"text":"\"No. It's your problem to sort out, really.\"","then":"Ankit goes quiet. The call doesn't happen that week."},{"text":"\"Better still, let me do all the talking.\"","then":"Ankit agrees, then looks lost when the helpline asks him things."},{"text":"\"Maybe. Let me see if I'm free sometime.\"","then":"\"Okay,\" Ankit says. The plan stays vague."}],"why":"Being there without taking over helps him act for himself."}],"relearn":"Point a friend to the route and a helpline so they don't face it alone."},
  {"id":"kr-1387","cat":"tools-and-help","type":"role-play","persona":"any","source":"share the card","hook":"Farida, new at your factory, seems unsure what she's owed after her first month.","setup":"You're eating lunch together on the steps outside.","steps":[{"prompt":"Farida asks: \"Is it normal that they didn't give me a pay slip?\"","options":[{"text":"\"You can ask for one. Want my rights card? No pressure.\"","then":"Farida nods. \"Yes, please. I didn't know who to ask.\"","best":true},{"text":"\"You really should know all this stuff already.\"","then":"Farida goes red and looks down at her food."},{"text":"\"It's normal here. Don't make a fuss about it.\"","then":"\"Oh,\" she says, and puts the question away."},{"text":"\"Let me explain every labour right to you, right now.\"","then":"Farida's eyes glaze over by the third point."}],"why":"Offering the card plainly, with no pressure, is kind and useful."},{"prompt":"Farida asks: \"Won't I look like a troublemaker if I ask for things?\"","options":[{"text":"\"Asking for what's owed isn't trouble. It's normal.\"","then":"She thinks. \"Okay. Just the pay slip, then.\"","best":true},{"text":"\"Maybe. Better to wait a year before you ask.\"","then":"She nods, and months of unrecorded pay stretch ahead."},{"text":"\"Who cares what they think? Demand it loudly.\"","then":"She looks alarmed. \"I can't do that.\""},{"text":"\"I'll ask the supervisor for you, so you're safe.\"","then":"The supervisor asks why Farida can't ask herself."}],"why":"Asking for what you're owed is normal. Saying so helps her feel steady."},{"prompt":"Farida asks: \"Is there anything I could send my cousin? She works at a hotel.\"","options":[{"text":"\"Sure. Here's my rights card. Tell her to pass it on.\"","then":"Farida forwards it straight away. \"She'll be so relieved.\"","best":true},{"text":"\"Only if she's really in trouble. Otherwise, no need.\"","then":"Farida isn't sure, and doesn't send anything."},{"text":"\"She should look all this up herself, really.\"","then":"\"Oh. Okay,\" Farida says, a little hurt."},{"text":"\"Sure, with a long note on what she's doing wrong.\"","then":"Her cousin reads the first line and feels judged."}],"why":"Sharing the route freely helps more people know where to turn."}],"relearn":"Offer the rights card plainly; sharing the route is a kindness, not a lecture."},
  {"id":"kr-1388","cat":"tools-and-help","type":"role-play","persona":"any","source":"check a forward","hook":"Cousin Dhruv posts a forward in the family group: 'All calls recorded from tomorrow!'","setup":"Relatives are reacting with worried faces.","steps":[{"prompt":"Dhruv writes: \"Share this fast! Don't say I didn't warn you.\"","options":[{"text":"\"Let's check that on an official site before we share it.\"","then":"Dhruv replies: \"Okay, but it came from a reliable group.\"","best":true},{"text":"\"Thanks for the warning, Dhruv! Forwarding it now.\"","then":"Your aunt thanks you and forwards it to three more groups."},{"text":"\"This is obviously fake. Why do you post such rubbish?\"","then":"Dhruv leaves the chat for an hour, embarrassed."},{"text":"\"Scary. Does anyone know if this is real?\"","then":"Five relatives reply \"Yes, true!\" without checking."}],"why":"Suggesting a check together slows the panic without making anyone feel foolish."},{"prompt":"When your uncle asks if it's true, your aunt writes: \"It came from a doctors' group. Doctors don't lie.\"","options":[{"text":"\"They may not lie, but forwards change as they travel.\"","then":"Your aunt sends a thumbs up. \"Okay beta, you check.\"","best":true},{"text":"\"Oh. If doctors sent it, it must be right.\"","then":"The group goes quiet, and the forward stands."},{"text":"\"Aunty, doctors aren't lawyers. Please stop forwarding.\"","then":"Your aunt replies, \"Very rude,\" and the group goes silent."},{"text":"\"Maybe. Let's just be careful on calls for now.\"","then":"Everyone agrees to \"be careful\", and the rumour stays alive."}],"why":"Even trusted forwards can be wrong. Checking the source settles it."},{"prompt":"That evening, Dhruv messages you alone: \"Be honest. Is this forward real or not?\"","options":[{"text":"\"There's no such rule. Here's the official link.\"","then":"Dhruv reads it and posts, \"Sorry, all. Please ignore my forward.\"","best":true},{"text":"\"Not sure. I never looked it up properly.\"","then":"\"Then maybe it is true,\" he replies."},{"text":"\"It's fake, obviously. You never check anything.\"","then":"Dhruv sends an angry emoji and goes offline."},{"text":"\"No idea, honestly. But better safe than sorry, right?\"","then":"Dhruv posts in the group, \"Even my cousin says better safe than sorry.\""}],"why":"Sharing the official link lets everyone see the truth for themselves."}],"relearn":"Slow a scary forward down: check it against an official source before passing it on."},
  {"id":"kr-1389","cat":"tools-and-help","type":"role-play","persona":"Meena","source":"ask for legal aid","hook":"Your old boss threatens a case over 'missing stock', and you can't afford a lawyer.","setup":"You're at the front desk of the legal services office.","steps":[{"prompt":"The clerk, Mrs Joshi, asks: \"Yes, what can we do for you?\"","options":[{"text":"\"I can't afford a lawyer. Could I ask about free legal aid?\"","then":"Mrs Joshi nods and pulls out a form. \"That's what we're here for.\"","best":true},{"text":"\"Sorry, never mind. I'll just manage somehow.\"","then":"\"Are you sure? Take a seat if you change your mind.\""},{"text":"\"I'm only asking for a friend, not for myself.\"","then":"\"Many people say that,\" she says gently. \"Sit down.\""},{"text":"\"How much does a lawyer here cost, roughly?\"","then":"\"Legal aid is free if you're eligible,\" she says. \"Let's check.\""}],"why":"Saying it plainly is enough. Not affording a lawyer is exactly what legal aid is for."},{"prompt":"Mrs Joshi asks: \"What's your monthly income, roughly?\"","options":[{"text":"\"About 9,000 a month. Sometimes less.\"","then":"She writes it down. \"That helps. Now tell me what happened.\"","best":true},{"text":"\"I'd rather not say, if that's okay.\"","then":"\"I understand. But I need it to check if we can help,\" she says."},{"text":"\"Why does that matter? I just need some help.\"","then":"\"It helps decide who gets free help,\" she says patiently."},{"text":"\"Maybe around 20,000? I'm not really sure.\"","then":"She notes it, and says she'll need to check if you qualify."}],"why":"Honest details let them check quickly whether you qualify for free help."},{"prompt":"Mrs Joshi says: \"Bring any papers about the job and the stock by Friday.\"","options":[{"text":"\"I'll bring my pay records and his messages on Friday.\"","then":"She writes your name in the diary for Friday at eleven.","best":true},{"text":"\"I don't have much. Is it even worth coming back?\"","then":"\"Bring whatever you have,\" she says kindly. \"We'll start there.\""},{"text":"\"Can't you just call my old boss and sort it out?\"","then":"\"We'll advise you first,\" she says. \"Then decide next steps.\""},{"text":"\"I'll come once I've found everything, maybe next month.\"","then":"\"That's a long time,\" she says. \"Try for Friday.\""}],"why":"Bringing your records on time helps the legal-aid lawyer build your case."}],"relearn":"You can ask plainly for free legal aid; not affording a lawyer is exactly what NALSA is for."},
  {"id":"kr-1390","cat":"tools-and-help","type":"role-play","persona":"any","source":"honest limit","hook":"You told your friend Nikhil what you know about deposit rights, and now he thinks his case is won.","setup":"He's sent you a voice note, sounding thrilled.","steps":[{"prompt":"Nikhil says: \"You said it's the law. So I've definitely won, right?\"","options":[{"text":"\"I'm not a lawyer. It's a route, not a ruling.\"","then":"\"Oh,\" he says. \"Okay. So where do I get proper help?\"","best":true},{"text":"\"Yes, trust me. You've definitely won already.\"","then":"\"Great! I'll tell my landlord I'm suing,\" he says."},{"text":"\"Honestly, I don't know anything. Forget what I said.\"","then":"\"Then why say it? Still, you write better than me.\""},{"text":"\"Probably. I read it on a really good website.\"","then":"\"Probably is good enough for me!\" he laughs."}],"why":"Sharing the route is helpful. Saying it's not legal advice keeps it honest."},{"prompt":"Nikhil asks: \"Can't you just write the letter to my landlord for me?\"","options":[{"text":"\"I'll help, but let legal aid check the letter.\"","then":"He sighs, then laughs. \"Fine. Give me the number.\"","best":true},{"text":"\"Sure. I'll write it and sign it for you.\"","then":"He's delighted, and your name is now on his dispute."},{"text":"\"No. I'm not getting involved in this at all.\"","then":"\"Wow. Okay,\" he says, and goes quiet."},{"text":"\"I'll copy a letter from the internet for you.\"","then":"The letter you find mentions laws from another country."}],"why":"Helping him think is kind, and a legal-aid check keeps his case on firm ground."},{"prompt":"Nikhil asks: \"Is there a number for free legal aid?\"","options":[{"text":"\"NALSA 15100. Keep your deposit receipt handy.\"","then":"He saves it. \"Calling tomorrow at lunch.\"","best":true},{"text":"\"I don't remember. Just search for it online.\"","then":"He finds three numbers online, and one is a private firm."},{"text":"\"You don't need it. Just threaten him with court.\"","then":"He sends the message, and his landlord stops replying."},{"text":"\"Just walk into any police station and ask them.\"","then":"The officer says it's a civil matter and he should get legal advice."}],"why":"The right number and his papers make his first call count."}],"relearn":"Be honest about limits: share the route, but say it's not legal advice."},
  {"id":"kr-1391","cat":"tools-and-help","type":"role-play","persona":"Aarti","source":"name the route","hook":"Tanya, a junior on your team, says a manager keeps touching her shoulder and making remarks.","setup":"She tells you in the pantry, watching the door.","steps":[{"prompt":"Tanya says: \"Maybe I'm overreacting. Nothing can be done.\"","options":[{"text":"\"I believe you. It's not your fault. There's an Internal Committee.\"","then":"Her shoulders drop. \"For complaints like this?\"","best":true},{"text":"\"Are you sure he meant it that way?\"","then":"She looks down. \"Maybe not. But it keeps happening.\""},{"text":"\"That's just how jobs are, sadly. Try to ignore him.\"","then":"She nods, but her eyes fill up."},{"text":"\"You must report him today. I'll take you right now.\"","then":"She steps back. \"No, please. I'm not ready.\""}],"why":"Believing her, saying it's not her fault and naming the Committee opens the door to help."},{"prompt":"Tanya asks: \"Won't everyone find out if I complain?\"","options":[{"text":"\"It's confidential. Punishing you for it isn't allowed.\"","then":"She's quiet. \"I didn't know that. It feels a little less scary.\"","best":true},{"text":"\"Probably. Offices love gossip, sadly.\"","then":"She flinches. \"Then I'll just stay quiet.\""},{"text":"\"Who cares if they find out? You did nothing wrong.\"","then":"\"I care,\" she says softly."},{"text":"\"Just post about him anonymously online instead.\"","then":"\"That feels even scarier,\" she says."}],"why":"Knowing it's confidential and protected helps her choose without fear."},{"prompt":"Tanya asks: \"What if I'm not ready to do anything yet?\"","options":[{"text":"\"Your call. I'm here, and 181 is there to talk to.\"","then":"Tanya nods slowly. \"Thanks. Can we talk again next week?\"","best":true},{"text":"\"Then nothing will change. You have to act.\"","then":"She looks overwhelmed and goes back to her desk."},{"text":"\"Then I'll report it for you, without your name.\"","then":"\"Please don't,\" she says, alarmed. \"He'll know it's me.\""},{"text":"\"Okay. Let's not talk about it again, then.\"","then":"She nods, and carries it alone again."}],"why":"Respecting her pace, with support like Women 181 on hand, keeps her in charge."},{"prompt":"A week later, Tanya says: \"He did it again. I want to go to the Internal Committee.\"","options":[{"text":"\"Okay. Want help writing down the dates first?\"","then":"She nods, and you sit together listing dates in her notes app.","best":true},{"text":"\"Finally! You should have gone straight away.\"","then":"She flinches. \"I needed time. That's all.\""},{"text":"\"Are you sure? It could get really messy.\"","then":"Her face falls, and she puts her phone away."},{"text":"\"Great. I'll go and tell them everything for you.\"","then":"\"No,\" she says firmly. \"I want to do it myself.\""}],"why":"Helping her record what happened supports her own choice, at her own pace."}],"relearn":"Name the formal route out loud; harassment has a complaint process, not just silence."},
  {"id":"kr-1392","cat":"tools-and-help","type":"role-play","persona":"any","source":"first call","hook":"Your employer cut a month's pay as a 'penalty', and you don't know which office handles that.","setup":"You finally dial the legal-aid line, NALSA 15100.","steps":[{"prompt":"The operator asks: \"Hello, legal aid. How can I help you today?\"","options":[{"text":"\"My pay was cut unfairly. Who handles that?\"","then":"\"That's what we're here for,\" she says. \"Tell me what happened.\"","best":true},{"text":"\"Sorry, it's probably nothing. Wrong number.\"","then":"\"Please don't hang up,\" she says. \"Just tell me what happened.\""},{"text":"\"I need a lawyer to sue my boss today.\"","then":"\"Let's start with what happened,\" she says calmly."},{"text":"\"Can you tell me if I'll get my money back?\"","then":"\"I can't promise that, but I can explain your options,\" she says."}],"why":"You don't need the perfect answer to call. Saying what happened is enough."},{"prompt":"The operator says: \"I'll give you some details to note. Do you have a pen?\"","options":[{"text":"\"Yes. Go ahead. I'm writing it down.\"","then":"She gives you the office's name and the papers to take.","best":true},{"text":"\"No need. I'll just remember it all.\"","then":"By evening, you remember the office but not the papers."},{"text":"\"Can't you just sort it all out for me?\"","then":"\"We guide you, and a legal-aid lawyer can help if needed,\" she says."},{"text":"\"Could you send it on WhatsApp? I'm in a rush.\"","then":"\"We can't send messages, sorry. I'll wait a minute,\" she says."}],"why":"Writing down the details turns the call into a real next step."},{"prompt":"Your flatmate Ravi asks: \"So, was calling even worth it?\"","options":[{"text":"\"Yes. I know where to go now. That's a start.\"","then":"Ravi grins. \"Then I'll come with you on Monday.\"","best":true},{"text":"\"Not really. They didn't fix it on the phone.\"","then":"Ravi shrugs. \"Told you it's a waste of time.\""},{"text":"\"I don't know. Maybe I should just drop it.\"","then":"\"Your call,\" Ravi says, and the pay slip sits on the table."},{"text":"\"Yes! They said I'll definitely win the case.\"","then":"Ravi looks doubtful. \"Did they actually say that?\""}],"why":"A first call that points you somewhere is progress, even before anything is fixed."}],"relearn":"When unsure who handles it, a helpline can direct you; you don't need the perfect answer first."},
  {"id":"kr-1393","type":"spot","persona":"any","source":"accurate rights","relearn":"Junior staff have rights and free legal aid is real; 'no rights' and 'justice needs money' are false.","hook":"Spot the two FALSE lines on the rights card (tap the wrong ones).","scene":[{"id":"a","text":"\"Harassment has a formal complaint route\"","trick":false},{"id":"b","text":"\"You have no rights as a junior\"","trick":true},{"id":"c","text":"\"Free legal aid exists if you can't pay\"","trick":false},{"id":"d","text":"\"You need money and connections to be heard\"","trick":true},{"id":"e","text":"\"Online scams can be reported\"","trick":false}],"why":"'No rights as a junior' and 'you need money' are the myths; the rest are real routes.","cat":"tools-and-help"},
  {"id":"kr-1394","type":"spot","persona":"Farhan","source":"overclaim","relearn":"An honest toolkit names routes without promising wins; guarantees are the red flags.","hook":"Spot the two OVERCLAIMS a rights card should never make.","scene":[{"id":"a","text":"\"Here are real routes you can use\"","trick":false},{"id":"b","text":"\"You'll definitely win your case\"","trick":true},{"id":"c","text":"\"This is education, not legal advice\"","trick":false},{"id":"d","text":"\"You're guaranteed your money back\"","trick":true},{"id":"e","text":"\"Free legal aid can help if you can't pay\"","trick":false}],"why":"'You'll definitely win' and 'guaranteed your money back' promise outcomes nobody can; drop them.","cat":"tools-and-help"},
  {"id":"kr-1395","type":"spot","persona":"any","source":"bad source","relearn":"Trust official portals, clinics and qualified help; forwards and guesses are the red flags.","hook":"Spot the two UNRELIABLE sources to never trust for your rights.","scene":[{"id":"a","text":"The official cyber portal","trick":false},{"id":"b","text":"A viral WhatsApp forward","trick":true},{"id":"c","text":"A legal-aid clinic","trick":false},{"id":"d","text":"A stranger's confident guess","trick":true},{"id":"e","text":"A qualified lawyer","trick":false}],"why":"A viral forward and a stranger's guess aren't sources; the portal, clinic and lawyer are.","cat":"tools-and-help"},
  {"id":"kr-1396","type":"spot","persona":"any","source":"wrong helpline use","relearn":"Use the line that fits: danger 112, cyber 1930, legal aid 15100; mismatches waste precious time.","hook":"Spot the two lines that MISMATCH the need (tap the wrong pairings).","scene":[{"id":"a","text":"In danger right now → 112","trick":false},{"id":"b","text":"Online scam → ignore it","trick":true},{"id":"c","text":"Can't afford a lawyer → NALSA 15100","trick":false},{"id":"d","text":"Blackmailed online → pay them off","trick":true},{"id":"e","text":"Cyber harm → report at 1930","trick":false}],"why":"Ignoring a scam and paying a blackmailer are wrong moves; report online harm at 1930 instead.","cat":"tools-and-help"},
  {"id":"kr-1397","type":"spot","persona":"Meena","source":"bad first move","relearn":"Save proof, note dates, call a helpline; staying silent or paying off the abuser are the wrong moves.","hook":"Spot the two WRONG first moves in a rights problem.","scene":[{"id":"a","text":"Save proof and note the dates","trick":false},{"id":"b","text":"Stay silent and just hope","trick":true},{"id":"c","text":"Call a helpline to be directed","trick":false},{"id":"d","text":"Pay the blackmailer to make it stop","trick":true},{"id":"e","text":"Ask a legal-aid clinic","trick":false}],"why":"Silence and paying off a blackmailer trap you; saving proof and calling for help open the route.","cat":"tools-and-help"},
  {"id":"kr-1398","type":"spot","persona":"Farhan","source":"toolkit flaws","relearn":"A useful card is plain with a number per line; jargon and false promises are the flaws to cut.","hook":"Spot the two lines that WEAKEN the rights card.","scene":[{"id":"a","text":"Short, plain wording","trick":false},{"id":"b","text":"A wall of legal jargon","trick":true},{"id":"c","text":"A helpline on every line","trick":false},{"id":"d","text":"\"We guarantee you'll win\"","trick":true},{"id":"e","text":"Written in the reader's language","trick":false}],"why":"Jargon and a false guarantee make the card useless and dishonest; the rest make it work.","cat":"tools-and-help"},
  {"id":"kr-1399","type":"spot","persona":"any","source":"myth on the card","relearn":"Routes and helplines belong on the card; 'just endure it' and 'nothing can be done' are myths to cut.","hook":"Spot the two MYTHS that don't belong on a rights card.","scene":[{"id":"a","text":"\"Harassment? Go to the IC\"","trick":false},{"id":"b","text":"\"Just endure it, that's the job\"","trick":true},{"id":"c","text":"\"Can't pay? NALSA 15100\"","trick":false},{"id":"d","text":"\"Nothing can really be done\"","trick":true},{"id":"e","text":"\"Scammed? Report at 1930\"","trick":false}],"why":"'Just endure it' and 'nothing can be done' are the myths the card exists to replace.","cat":"tools-and-help"},
  {"id":"kr-1400","type":"spot","persona":"any","source":"share or not","relearn":"Share verified routes and official links; scary forwards and unverified screenshots get checked first.","hook":"Spot the two things you should NOT forward without checking.","scene":[{"id":"a","text":"The verified helpline list","trick":false},{"id":"b","text":"A 'the law just changed' rumour","trick":true},{"id":"c","text":"The official cyber portal link","trick":false},{"id":"d","text":"A scary unverified screenshot","trick":true},{"id":"e","text":"A legal-aid clinic's address","trick":false}],"why":"The rumour and the unverified screenshot could be false; check them before sharing.","cat":"tools-and-help"},
  {"id":"kr-1401","type":"spot","persona":"any","source":"honest helper","relearn":"A good helper names the route honestly; pretending to be a lawyer or promising a win is the red flag.","hook":"Spot the two things an honest rights-helper would never say.","scene":[{"id":"a","text":"\"Here's the route to start with\"","trick":false},{"id":"b","text":"\"Trust me, you've already won\"","trick":true},{"id":"c","text":"\"I'm not a lawyer: get proper help too\"","trick":false},{"id":"d","text":"\"Skip the helpline, just pay them\"","trick":true},{"id":"e","text":"\"A helpline can point you the right way\"","trick":false}],"why":"Promising a win and saying 'just pay them' are the dishonest, harmful lines; cut them.","cat":"tools-and-help"},
  {"id":"kr-1402","cat":"tools-and-help","type":"branch","persona":"any","source":"where to start","hook":"A coaching institute cancelled your course and won't refund the fee, and you don't know who handles that.","steps":[{"prompt":"Your classmates are all guessing different offices. What do you do?","options":[{"text":"Ring a helpline and ask them to point you the right way","then":"The legal-aid helpline says it's a consumer complaint and explains how to start.","best":true},{"text":"Give up. It's too confusing to be worth it","then":"The fee stays with the institute, and the course never restarts."},{"text":"Follow a WhatsApp tip about a paid \"refund agent\"","then":"The \"agent\" asks for 2,000 up front to \"process\" your refund."},{"text":"Wait for someone in the group to figure it out first","then":"The group chat argues for a week. Nobody files anything."}],"why":"A helpline can direct you, so confusion doesn't have to be a dead end."},{"prompt":"The institute emails offering \"credit for a future course\" instead. What do you do?","options":[{"text":"Reply that you want a refund, and save their email","then":"They reply that refunds \"take time\". Now it's all in writing.","best":true},{"text":"Take the credit. Something is better than nothing","then":"The credit comes with a catch: use it within a month."},{"text":"Ignore the email, since replying drags it out","then":"They later say you \"accepted\" the credit by not replying."},{"text":"Reply angrily, threatening to shut them down","then":"They stop replying altogether."}],"why":"Asking clearly for a refund in writing keeps your claim on record."},{"prompt":"A classmate forwards: \"Consumer cases take ten years. Don't bother.\" What do you do?","options":[{"text":"Check it with the legal-aid helpline first","then":"The helpline says many complaints are simpler than that forward suggests.","best":true},{"text":"Believe it, and drop the whole thing","then":"You drop it, and so do three classmates who were watching you."},{"text":"Forward it on to warn the rest of the class","then":"The whole group gives up that afternoon."},{"text":"Ask your uncle, who once had a court case","then":"He tells you about his land case, which has nothing to do with yours."}],"why":"Forwards often get the law wrong. A proper source tells you where you really stand."}],"debrief":"Unsure of the route? A helpline or legal-aid clinic can point you the right way.","relearn":"Unsure of the route? A helpline or legal-aid clinic will direct you."},
  {"id":"kr-1403","cat":"tools-and-help","type":"branch","persona":"any","source":"can't afford a lawyer","hook":"A legal notice says you owe 40,000 on a phone loan you never took, and you can't afford a lawyer.","steps":[{"prompt":"The notice gives you 15 days to respond. What do you do?","options":[{"text":"Call NALSA 15100 and ask about free legal aid","then":"The helpline explains how to apply and where the nearest office is.","best":true},{"text":"Ignore it, since justice costs money you don't have","then":"The days tick by, and the notice sits on your table."},{"text":"Borrow heavily from a cousin to hire a private lawyer","then":"Your cousin lends you 20,000 at interest, and the fees eat it fast."},{"text":"Pay a small amount to make the problem go away","then":"The lender treats your payment as proof you owe the loan."}],"why":"Free legal aid exists for exactly this, so money isn't what stands between you and a defence."},{"prompt":"A friend takes you to the legal services office, and you feel embarrassed to talk about money. What do you do?","options":[{"text":"Say plainly you can't pay a lawyer, and show the notice","then":"The officer nods and hands you a short form. \"This is what we're for.\"","best":true},{"text":"Pretend you're only asking on behalf of a friend","then":"The officer answers in general terms, and your notice stays in your bag."},{"text":"Leave quietly before your turn comes","then":"You're home again with the deadline closer. The office opens again tomorrow."},{"text":"Ask for help, but hide how little you really earn","then":"The officer can't tell if you qualify and asks you to come back."}],"why":"A loan taken in your name isn't your fault. Being plain about money gets you the help you're entitled to."},{"prompt":"Back home, a neighbour says free legal-aid lawyers \"don't really try\". What do you do?","options":[{"text":"Use legal aid, and bring every paper the lawyer asks for","then":"Your lawyer drafts a reply showing the loan was taken in your name by someone else.","best":true},{"text":"Believe your neighbour and hunt for a paid lawyer anyway","then":"You spend days searching and can't find one you can afford."},{"text":"Get legal aid, then leave everything to the lawyer","then":"Weeks pass without your papers, and the lawyer has less to work with."},{"text":"Skip lawyers and reply to the notice yourself","then":"Your reply misses key points, and the lender writes back sharply."}],"why":"A legal-aid lawyer is a real lawyer, and your papers help them help you."},{"prompt":"The lender's agent calls, offering to \"settle\" if you pay 10,000 today. What do you do?","options":[{"text":"Refuse to pay, note the call, and tell legal aid","then":"Legal aid writes down the call details and explains your next step.","best":true},{"text":"Pay the 10,000 just to make the stress stop","then":"The agent thanks you, and a week later the rest is \"still due\"."},{"text":"Argue with the agent until one of you hangs up","then":"Voices rise on both sides, and nothing is written down."},{"text":"Promise to pay a little next month to buy time","then":"He writes down your \"promise\" as proof you accept the loan."}],"why":"Paying a debt you never took can look like admitting it. Let legal aid guide you."}],"debrief":"Free legal aid (NALSA 15100) means a real case isn't only for those who can pay.","relearn":"Can't afford a lawyer? Free legal aid (NALSA 15100) exists."},
  {"id":"kr-1404","cat":"tools-and-help","type":"branch","persona":"any","source":"scary forward","hook":"A forward says a new rule lets landlords evict tenants without notice from next month.","steps":[{"prompt":"You rent a room, and the forward has three red sirens on it. What do you do?","options":[{"text":"Check it on an official government site first","then":"You search the official site. There's no such rule anywhere.","best":true},{"text":"Panic and forward it to everyone you know","then":"Your family group fills with worried replies within minutes."},{"text":"Start hunting for a new room just in case","then":"You spend the weekend visiting rooms you didn't need."},{"text":"Ask your landlord whether it's true","then":"He grins. \"Maybe. So don't give me trouble.\""}],"why":"An official source tells you the real position before you react."},{"prompt":"Your flatmate Tanvi insists it must be true because it's everywhere. What do you say?","options":[{"text":"Shares aren't proof. Let's look at the official site","then":"Tanvi reads the official site with you and finds no such rule.","best":true},{"text":"True. So many people can't all be wrong","then":"Tanvi forwards it to her college group too."},{"text":"Who cares? We can't do anything about it anyway","then":"Tanvi looks worried, and the topic hangs in the air."},{"text":"Let's wait and see whether the news covers it","then":"Days pass. The forward keeps spreading."}],"why":"Checking the source beats counting how many people shared it."},{"prompt":"Your aunt sends the same forward and asks whether she should move out. What do you do?","options":[{"text":"Check the official site, and send her the link","then":"She reads the official page and replies with a relieved emoji.","best":true},{"text":"Tell her to move anyway, just to be safe","then":"She starts calling packers the next morning."},{"text":"Leave her message unread so you don't get involved","then":"She stays worried for a week and asks someone else."},{"text":"Tell her it's probably fake, without explaining why","then":"\"Probably?\" she replies. \"How do you know?\""}],"why":"Sending the official source helps her trust the truth, not just your word."}],"debrief":"Forwards get the law wrong often; verify against an official source first.","relearn":"Check a scary 'new rule' against an official source before you act or share."},
  {"id":"kr-1405","cat":"tools-and-help","type":"branch","persona":"Meena","source":"blackmail online","hook":"Someone you met online threatens to share a private photo of you unless you pay 10,000.","steps":[{"prompt":"The messages say you have one hour. What do you do?","options":[{"text":"Don't pay. Screenshot everything and report at 1930","then":"The helpline takes your report and tells you what to save and how to block.","best":true},{"text":"Tell yourself paying once will make them go away","then":"You open your bank app, and the fear gets louder."},{"text":"Tell yourself this is your fault for sending the photo","then":"The shame makes it harder to think about who could help."},{"text":"Delete the whole chat so nobody can ever see it","then":"The chat is gone, and so are the usernames a report would need."}],"why":"Not paying and saving proof starts the real route. None of this is your fault."},{"prompt":"Your hands are shaking and you feel very alone. What do you do?","options":[{"text":"Tell one person you trust what's happening","then":"Your cousin Lata listens, holds your hand, and sits with you.","best":true},{"text":"Keep it a secret. Nobody can ever know","then":"You sit alone with it all night, and the panic grows."},{"text":"Follow a friend's advice to just pay and forget it","then":"Your friend means well. You still feel sick, and nothing is safer yet."},{"text":"Pay an online \"hacker\" who says he can delete it","then":"The \"hacker\" wants 3,000 up front. Something about it feels wrong."}],"why":"Someone you trust helps you stay steady and think clearly. You don't have to face this alone."},{"prompt":"The blackmailer messages again from a new number. What do you do?","options":[{"text":"Save it, report it at 1930, and block the number","then":"The new number goes into a report at 1930, and then it's blocked.","best":true},{"text":"Believe a polite reply might make them stop","then":"You send a polite plea. The reply is the same threat, with a new deadline."},{"text":"Believe no one can catch someone hiding online","then":"You stare at the screen, feeling stuck, as the messages keep coming."},{"text":"Keep the new messages to yourself this time","then":"The new messages sit unreported, and you carry them alone."}],"why":"Each new message is more evidence. Reporting it at 1930 keeps the case strong."},{"prompt":"Days later, the shame comes back at night. What do you do?","options":[{"text":"Remember it's their crime, and talk to someone you trust","then":"Your friend Anu sits with you and says it three times: \"Not your fault.\"","best":true},{"text":"Tell yourself you deserved it for trusting someone online","then":"The thought sits heavy, even though the fault is theirs."},{"text":"Promise yourself you'll never tell anyone else","then":"The secret feels heavier each night."},{"text":"Believe everyone would judge you if they knew","then":"You pull away from friends, and feel more alone."}],"why":"The crime is theirs, never yours. Leaning on people you trust helps you heal."}],"debrief":"Image blackmail is on the abuser: don't pay, keep proof, report at 1930.","relearn":"For online blackmail: don't pay, preserve proof, report at 1930."},
  {"id":"kr-1406","cat":"tools-and-help","type":"branch","persona":"any","source":"friend in trouble","hook":"Your friend Salman's employer has held back two months of his wages, and he feels stuck.","steps":[{"prompt":"Salman says, \"People like us can't fight bosses.\" What do you do?","options":[{"text":"Tell him about free legal aid on NALSA 15100","then":"Salman writes the number on his hand. \"Free? Really?\"","best":true},{"text":"Say \"You'll figure it out\" and change the subject","then":"He goes quiet, and the talk drifts to cricket."},{"text":"Promise you'll get him justice yourself","then":"His face lights up, and now he's waiting on you."},{"text":"Agree it's hopeless, but lend him some money","then":"He takes 2,000 gratefully. His wages stay unpaid."}],"why":"A real route and a helpline give him a first step, not just sympathy."},{"prompt":"A week later, Salman wants help but fears his boss will find out. What do you do?","options":[{"text":"Listen, and offer to sit with him while he calls","then":"Salman breathes out. \"Okay. Sunday, with you there.\"","best":true},{"text":"Tell him to stop being scared and just call","then":"He bristles. \"Easy for you to say.\""},{"text":"Call his boss yourself to sort it all out","then":"His boss is furious that Salman \"spread stories\"."},{"text":"Say maybe it's safer to let the money go","then":"He nods, relieved and defeated at once."}],"why":"Support at his pace helps him act without taking the choice away from him."},{"prompt":"Salman's cousin asks if legal aid will \"definitely get the money back\". What do you say?","options":[{"text":"No one can promise that, but it's a real route to try","then":"The cousin nods. \"Then it's worth a go.\"","best":true},{"text":"Yes, definitely. They'll win for sure","then":"The cousin tells Salman it's \"guaranteed\", and he stops preparing."},{"text":"Probably not. These things rarely work","then":"The cousin tells Salman not to bother."},{"text":"You don't know. They should really ask someone else","then":"The cousin looks for answers in a WhatsApp group instead."}],"why":"Honest hope beats false promises. The route is real, and the outcome isn't guaranteed."}],"debrief":"Point a friend to the route and a helpline; false promises aren't help.","relearn":"A friend in a rights mess needs the route and a helpline, not silence."},
  {"id":"kr-1407","cat":"tools-and-help","type":"branch","persona":"Aarti","source":"harassment route","hook":"At your internship, a senior, Mr Khanna, keeps commenting on your body and texting you late at night.","steps":[{"prompt":"You're unsure anything can be done about it. What do you do?","options":[{"text":"Note dates, save the texts, and find the Internal Committee","then":"Your notes list the dates, and the notice board names the Committee members.","best":true},{"text":"Tell yourself it's just the price of getting a first job","then":"The words sit badly, and you start dreading each morning."},{"text":"Wonder if your clothes gave him the wrong idea","then":"You change what you wear. The comments don't change."},{"text":"Keep it to yourself so nobody starts gossiping","then":"You carry it alone, and the office starts to feel smaller."}],"why":"Dated notes and saved texts give the Committee what it needs. None of this is your fault."},{"prompt":"A colleague, Mitali, warns that complaining will \"finish your career\". What do you do?","options":[{"text":"Ask the Committee, in confidence, how it works","then":"A member explains it's confidential, and that punishing a complaint isn't allowed.","best":true},{"text":"Believe her. Careers need you to stay quiet","then":"You feel more alone with it, and her words keep playing in your head."},{"text":"Wonder if you're overreacting to a few texts","then":"You scroll back through them, and they still make you feel sick."},{"text":"Ask Mitali to quietly handle it for you","then":"Mitali says it's not her place, and you're back where you started."}],"why":"Knowing the process is confidential and protected helps you choose freely."},{"prompt":"One evening, it feels too heavy to carry alone. What do you do?","options":[{"text":"Lean on a trusted friend, and go to the Committee","then":"Your friend Rhea waits outside while you hand in your written complaint.","best":true},{"text":"Believe no one takes an intern's word seriously","then":"You close your notes, and the weight stays with you."},{"text":"Ask Mr Khanna's friend to have a word with him","then":"Mr Khanna hears about it second-hand and brushes it off."},{"text":"Spend hours reading forum stories before you decide anything","then":"You read dozens of stories, some hopeful, some not, and feel no closer."}],"why":"Support and the formal route together mean you don't have to carry it alone."},{"prompt":"Soon after, Mr Khanna starts leaving you out of meetings. What do you do?","options":[{"text":"Note each time, and tell the Committee about it","then":"A Committee member notes it down and follows up that week.","best":true},{"text":"Believe you brought this on yourself somehow","then":"The thought weighs on you, though none of this is on you."},{"text":"Take a colleague's advice to apologise to him","then":"The apology sits wrong with you, and nothing changes in the meetings."},{"text":"Believe telling the Committee will only make him worse","then":"The meetings go on without you, and no one knows why."}],"why":"Being shut out after harassment is something the Committee can act on. It's never your fault."}],"debrief":"Harassment is never the price of a job; the route is confidential and protected.","relearn":"Workplace or college harassment has a confidential complaint route; you needn't just endure it."},
  {"id":"kr-1408","cat":"tools-and-help","type":"branch","persona":"any","source":"faulty goods","hook":"The pressure cooker you bought last week leaks steam from the lid, and the shopkeeper shrugs.","steps":[{"prompt":"He says, \"Once sold, no return. Your bad luck.\" What do you do?","options":[{"text":"Keep the bill, and ask for a replacement in writing","then":"He reads your note, then says he'll \"talk to the company\".","best":true},{"text":"Accept it's bad luck, and throw the cooker out","then":"You bag it for the rubbish, and it sits by the door for days."},{"text":"Warn your friends about the shop and leave it at that","then":"Your friends avoid the shop. You still have a leaking cooker."},{"text":"Try to seal the lid yourself with some tape","then":"The tape melts the first time you use it."}],"why":"A defective product gives you a right to a replacement or refund. The bill is your proof."},{"prompt":"A week later, the shop still refuses to take the cooker back. What do you do?","options":[{"text":"Contact the company yourself, with the bill and photos","then":"The company's service line logs a complaint number and asks for a video.","best":true},{"text":"Give up. If the shop won't budge, nothing can be done","then":"The leaky cooker sits in a corner of the kitchen."},{"text":"Leave a one-star review and hope someone notices","then":"The review gets two likes. The lid still leaks."},{"text":"Buy a new cooker from the same shop and move on","then":"The new one works, and the 2,200 is simply lost."}],"why":"Going to the maker with proof keeps your claim moving when the shop stalls."},{"prompt":"Days later, the maker calls: the shop passed on your complaint, and they offer a coupon, not a fix. What do you do?","options":[{"text":"Ask for a replacement or refund, or file a consumer complaint","then":"The agent pauses, then says a replacement can be arranged.","best":true},{"text":"Take the coupon. It's better than nothing","then":"The coupon arrives. The cooker still leaks."},{"text":"Argue on the phone until they hang up on you","then":"The line goes dead mid-sentence."},{"text":"Accept the coupon, but ask for a bigger one","then":"They offer a slightly bigger coupon, and the cooker still leaks."}],"why":"A coupon isn't a fix. The consumer complaint route exists for exactly this."}],"debrief":"Consumer law gives a real route for faulty goods; 'bad luck' is a myth.","relearn":"A defective product has a real consumer route to refund or replacement."},
  {"id":"kr-1409","type":"strike-rewrite","persona":"any","source":"junior myth","relearn":"Rights apply at any level; being junior doesn't switch them off.","hook":"\"You're too junior to have any rights.\"","myth":{"un":"\"You're too junior to have any rights.\"","re":"Basic rights apply at every level: even interns and new joiners are protected.","why":"Rights attach to the person and the work, not to seniority; juniors are covered too."},"cat":"tools-and-help"},
  {"id":"kr-1410","type":"strike-rewrite","persona":"any","source":"money myth","relearn":"Free legal aid exists, so justice isn't only for those who can pay.","hook":"\"You need money and connections to claim anything.\"","myth":{"un":"\"You need money and connections to claim anything.\"","re":"Free legal aid is available through NALSA (15100) if you can't afford a lawyer.","why":"The right to free legal aid exists so cost isn't a wall; you can start without money or contacts."},"cat":"tools-and-help"},
  {"id":"kr-1411","type":"strike-rewrite","persona":"any","source":"reporting myth","relearn":"Online scams and abuse can be reported at 1930 and the cyber portal.","hook":"\"Nothing online can really be reported.\"","myth":{"un":"\"Nothing online can really be reported.\"","re":"Online fraud, abuse and blackmail can be reported at 1930 or cybercrime.gov.in.","why":"There's a real national route for cyber harm; fast reporting genuinely helps your case."},"cat":"tools-and-help"},
  {"id":"kr-1412","type":"strike-rewrite","persona":"any","source":"forward myth","relearn":"A confident forward isn't a source; verify rights claims against official sites.","hook":"\"If it's forwarded confidently, it must be the real rule.\"","myth":{"un":"\"If it's forwarded confidently, it must be the real rule.\"","re":"Forwards get the law wrong often: check the claim on an official source first.","why":"Confidence isn't accuracy; only official portals and qualified help are reliable for your rights."},"cat":"tools-and-help"},
  {"id":"kr-1413","type":"strike-rewrite","persona":"Aarti","source":"endure myth","relearn":"Harassment is never the price of a job; there's a real complaint route.","hook":"\"Harassment is just part of working life: endure it.\"","myth":{"un":"\"Harassment is just part of working life: endure it.\"","re":"Harassment has a formal, confidential complaint route; you don't have to endure it.","why":"A safe, dignified workplace is your right, and complaining in good faith is protected."},"cat":"tools-and-help"},
  {"id":"kr-1414","type":"strike-rewrite","persona":"any","source":"advice myth","relearn":"This is education, not legal advice; a real case needs qualified or free legal help.","hook":"\"A rights tip from a friend settles your case.\"","myth":{"un":"\"A rights tip from a friend settles your case.\"","re":"Tips point you to the route, but a real case needs qualified or free legal help.","why":"Only a lawyer can advise on your facts; the toolkit gives direction, not a ruling."},"cat":"tools-and-help"},
  {"id":"kr-1415","type":"strike-rewrite","persona":"any","source":"cost myth","relearn":"Asserting a right needn't be costly: free legal aid, helplines, and consumer forums keep fees low.","hook":"\"Standing up for a right always costs a fortune in lawyers and years in court.\"","myth":{"un":"\"Asserting a right always means expensive lawyers and years of court.\"","re":"Free legal aid, helplines, and low-cost forums like consumer commissions make many routes affordable and quick.","why":"Many first steps are free or cheap; cost is rarely the real barrier."},"cat":"tools-and-help"},
  {"id":"kr-1416","type":"strike-rewrite","persona":"Farhan","source":"toolkit myth","relearn":"A rights card helps only if it's plain and honest, with a real route and number.","hook":"\"A rights card must be long and full of legal terms to be useful.\"","myth":{"un":"\"A rights card has to be long and full of legal terms to be useful.\"","re":"The best card is short and plain, with a real route and a helpline on each line.","why":"People act on what they can read fast; jargon and length make a toolkit useless."},"cat":"tools-and-help"},
];

